(window.JCPA_DATA=window.JCPA_DATA||{})["companies"]={"id":"companies","name":"قانون الشركات","full":"قانون الشركات رقم (22) لسنة 1997 وتعديلاته حتى القانون المعدل رقم (20) لسنة 2023","icon":"🏢","articles":[{"n":"1","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يسمى هذا القانون ( قانون الشركات لسنة ١٩٩٧ ) ويعمل به بعد مرور ثلاثين يوما على تاريخ نشره في الجريدة الرسمية .","title":"التسمية وبدء العمل","memo":"⭐ يعمل بقانون الشركات لسنة ١٩٩٧ بعد مرور ثلاثين يوماً على تاريخ نشره في الجريدة الرسمية","qs":[{"q":"متى يعمل بقانون الشركات لسنة ١٩٩٧؟","o":["بعد مرور ثلاثين يوماً على تاريخ نشره في الجريدة الرسمية","من تاريخ نشره في الجريدة الرسمية","بعد مرور ستين يوماً على تاريخ نشره في الجريدة الرسمية","بعد مرور خمسة عشر يوماً على تاريخ نشره في الجريدة الرسمية"],"a":0}]},{"n":"2","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ . يكون للكلمات التالية حيثما وردت في هذا القانون المعاني المخصصة لها ادناه ما لم تدل القرينة على غير ذلك:\nالوزارة: وزارة الصناعة والتجارة والتموين.\nالوزير: وزير الصناعة والتجارة والتموين.\nالمراقب: مراقب عام الشركات.\nالدائرة: دائرة مراقبة الشركات وترتبط بالوزير.\nالبنك:الشركة المرخصة لممارسة الاعمال المصرفية وفق احكام قانون البنوك النافذ المفعول.\nالمحكمة: محكمة البداية التي يقع المركز الرئيسي للشركة الاردنية او مركز الفرع الرئيسي للشركة الاجنبية ضمن اختصاصها المكاني.\nب- يقصد بكلمات وعبارات (الهيئة) و(السوق المالي) و(المركز) و (مدير الإصدار) و(أمين الإصدار) حيثما وردت في هذا القانون المعاني المخصصة لها بمقتضى قانون الأوراق المالية والانظمة الصادرة بمقتضاه.","title":"تعريفات","memo":"⭐ المراقب: مراقب عام الشركات، والدائرة: دائرة مراقبة الشركات وترتبط بالوزير\n⭐ الوزير: وزير الصناعة والتجارة والتموين\n⭐ المحكمة: محكمة البداية التي يقع ضمن اختصاصها المكاني المركز الرئيسي للشركة الأردنية أو مركز الفرع الرئيسي للشركة الأجنبية\n⭐ الهيئة والسوق المالي والمركز ومدير الإصدار وأمين الإصدار: معانيها وفق قانون الأوراق المالية","qs":[{"q":"ترتبط دائرة مراقبة الشركات وفق قانون الشركات بـ:","o":["الوزير","رئيس الوزراء","مجلس الوزراء","هيئة الأوراق المالية"],"a":0},{"q":"يقصد بـ(المحكمة) في قانون الشركات:","o":["محكمة البداية التي يقع المركز الرئيسي للشركة الأردنية أو مركز الفرع الرئيسي للشركة الأجنبية ضمن اختصاصها المكاني","محكمة الاستئناف التي يقع المركز الرئيسي للشركة ضمن اختصاصها","المحكمة الإدارية","محكمة الصلح التي يقع المركز الرئيسي للشركة ضمن اختصاصها"],"a":0},{"q":"يرجع في تحديد معنى عبارة (مدير الإصدار) الواردة في قانون الشركات إلى:","o":["قانون الأوراق المالية والأنظمة الصادرة بمقتضاه","قانون البنوك","قانون التجارة","تعليمات يصدرها مراقب عام الشركات"],"a":0},{"q":"يقصد بـ(المراقب) في قانون الشركات:","o":["مراقب عام الشركات","مدير عام دائرة الأراضي","مدقق الحسابات القانوني","رئيس مجلس مفوضي هيئة الأوراق المالية"],"a":0}]},{"n":"3","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"تسري احكام هذا القانون على الشركات التي تمارس الاعمال التجارية وعلى المسائل التي تناولتها نصوصه، فاذا لم يكن فيها ما ينطبق على اي مسالة فيرجع الى قانون التجارة فان لم يوجد فيه حكم يتناول هذا الامر يرجع الى القانون المدني والا فتطبق احكام العرف التجاري والاسترشاد بالاجتهادات القضائية والفقهية وقواعد العدالة.","title":"نطاق تطبيق القانون","memo":"⭐ يسري القانون على الشركات التي تمارس الأعمال التجارية وعلى المسائل التي تناولتها نصوصه\n⭐ ترتيب المرجعية عند عدم وجود نص: قانون التجارة ← القانون المدني ← العرف التجاري والاجتهادات القضائية والفقهية وقواعد العدالة","qs":[{"q":"إذا لم يوجد في قانون الشركات نص ينطبق على مسألة معينة، فيرجع أولاً إلى:","o":["قانون التجارة","القانون المدني","العرف التجاري","الاجتهادات القضائية"],"a":0},{"q":"إذا لم يوجد حكم لمسألة في قانون الشركات ولا في قانون التجارة، فيرجع إلى:","o":["القانون المدني","العرف التجاري","قواعد العدالة","قانون الأوراق المالية"],"a":0},{"q":"تسري أحكام قانون الشركات على:","o":["الشركات التي تمارس الأعمال التجارية","الشركات المدنية فقط","الجمعيات الخيرية","المؤسسات العامة الرسمية"],"a":0}]},{"n":"4","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يتم تأسيس الشركة في المملكة وتسجيلها فيها بمقتضى هذا القانون وتعتبر كل شركة بعد تأسيسها وتسجيلها على ذلك الوجه شخصاً اعتبارياً اردني الجنسية ويكون مركزها الرئيسي في المملكة .","title":"تأسيس الشركة وجنسيتها","memo":"⭐ تؤسس الشركة وتسجل في المملكة بمقتضى هذا القانون\n⭐ تعتبر بعد تأسيسها وتسجيلها شخصاً اعتبارياً أردني الجنسية ومركزها الرئيسي في المملكة","qs":[{"q":"تعتبر الشركة بعد تأسيسها وتسجيلها في المملكة وفق قانون الشركات:","o":["شخصاً اعتبارياً أردني الجنسية مركزه الرئيسي في المملكة","شخصاً اعتبارياً يحمل جنسية أغلبية الشركاء","شخصاً اعتبارياً بعد نشر عقدها فقط دون تسجيل","شخصاً اعتبارياً يجوز أن يكون مركزه الرئيسي خارج المملكة"],"a":0},{"q":"يكون المركز الرئيسي للشركة المسجلة وفق قانون الشركات:","o":["في المملكة","في المكان الذي يحدده الشركاء داخل المملكة أو خارجها","في بلد جنسية الشريك الأكبر","في مكان تسجيل الفرع الرئيسي"],"a":0}]},{"n":"5","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - لا يجوز تسجيل شركة باسم اتخذ لغاية احتيالية او غير قانونية كما لا يجوز تسجيل اي شركة باسم سبق وسجلت به شركة اخرى في المملكة ، او باسم يشبهه الى درجة قد تؤدي الى اللبس او الغش. وللمراقب رفض تسجيل الشركة بمثل ذلك الاسم في اي حالة من تلك الحالات .\nب - يجوز لاي شركة ان تعترض خطياً لدى الوزير خلال ستين يوماً من تاريخ نشر القرار بتسجيل شركة اخرى في الجريدة الرسمية لالغاء تسجيل تلك الشركة الأخرى اذا كان الاسم الذي سجلت به مماثلاً لاسمها او يشبهه الى درجة قد تؤدي الى اللبس او الغش ، وللوزير بعد السماح للشركة المعترض على تسجيلها تقديم دفاعها خلال المدة التي يحددها ، ان يصدر قراره بالغاء تسجيل الشركة الأخرى اذا اقتنع باسباب الاعتراض على تسجيلها ولم تقم بتعديل اسمها وازالة اسباب الاعتراض ، وللمتضرر من قراره ، الطعن فيه لدى المحكمة الإدارية خلال ثلاثين يوماً من الاعلان عنه في احدى الصحف اليومية المحلية .","title":"موانع التسجيل والاعتراض عليه","memo":"⭐ لا يجوز تسجيل شركة باسم احتيالي أو غير قانوني أو باسم مسجل سابقاً أو يشبهه لدرجة اللبس أو الغش، وللمراقب رفض التسجيل\n⭐ الاعتراض خطياً لدى الوزير خلال ستين يوماً من نشر قرار التسجيل في الجريدة الرسمية\n⭐ الطعن في قرار الوزير لدى المحكمة الإدارية خلال ثلاثين يوماً من الإعلان عنه في إحدى الصحف اليومية المحلية","qs":[{"q":"يجوز لأي شركة الاعتراض على تسجيل شركة أخرى باسم مماثل لاسمها خلال:","o":["ستين يوماً من تاريخ نشر قرار التسجيل في الجريدة الرسمية","ثلاثين يوماً من تاريخ نشر قرار التسجيل في الجريدة الرسمية","تسعين يوماً من تاريخ تقديم طلب التسجيل","خمسة عشر يوماً من تاريخ نشر قرار التسجيل"],"a":0},{"q":"يقدم الاعتراض على تسجيل شركة باسم يشبه اسم شركة أخرى إلى درجة قد تؤدي إلى اللبس إلى:","o":["الوزير","المراقب","المحكمة الإدارية","محكمة البداية"],"a":0},{"q":"يطعن المتضرر من قرار الوزير بإلغاء تسجيل شركة بسبب تشابه الاسم لدى:","o":["المحكمة الإدارية خلال ثلاثين يوماً من الإعلان عن القرار في إحدى الصحف اليومية المحلية","محكمة البداية خلال ستين يوماً من صدور القرار","المحكمة الإدارية خلال ستين يوماً من نشر القرار في الجريدة الرسمية","مجلس الوزراء خلال ثلاثين يوماً من تبليغه القرار"],"a":0}]},{"n":"6","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- مع مراعاة احكام المادتين ( ٧ ) و ( ٨ ) من هذا القانون تقسم الشركات التي يتم تسجيلها بمقتضى هذا القانون الى الأنواع التالية :\n١ - شركة التضامن .\n٢- شركة التوصية البسيطة .\n٣ - الشركات ذات المسؤولية المحدودة .\n٤ - شركة رأس المال المغامر.\n٥ـ الشركة المساهمة الخاصة .\n٦ - الشركة المساهمة العامة .\nب- لا يشترط لتسجيل أي شركة الحصول على موافقة مسبقة من أي جهة اخرى الا اذا اقتضى تشريع نافذ غير ذلك .\nج- يجوز الافصاح ، بمقتضى تعليمات يصدرها الوزير ، عن أي بيانات او معلومات لدى الدائرة لا تتعلق بحسابات الشركة وبياناتها المالية .\nد- يجوز للدائرة ان تحتفظ بصور الكترونية او مصغرة لاصول أي من الوثائق والمستندات المحفوظة او المودعة لديها ، كما يجوز لها ان تحتفظ بالبيانات والمعلومات والسجلات والمعاملات المتعلقة باعمالها بوسائل الكترونية، ويكون لتلك الصور والبيانات والسجلات المستخرجة بعد ختمها بخاتم الدائرة وتوقيعها من الموظف المختص الاثار القانونية للمستندات الخطية الاصلية ذاتها بما في ذلك حجيتها في الاثبات .\nهـ - للمراقب اعتماد الوسائل الإلكترونية لتقديم الطلبات وايداع المحاضر والوثائق للدائرة واصدار شهادات ونسخ عنها واعتماد التواقيع والاجراءات التي يتطلبها القانون.\nو- للشركات الدعوة إلى اجتماعات الهيئات العامة ومجالس الادارة وهيئات المديرين وعقدها بالوسائل الالكترونية على ان تتم ادارة الاجتماعات من داخل المملكة.\nز - على المراقب أن يعلن على الموقع الإلكتروني للدائرة عن تسجيل أي شركة وعن أي تعديل يطرأ على بيانات الشركة المسجلة.\nح- يصدر الوزير التعليمات اللازمة لتنفيذ احكام الفقرات (د) و (هـ) و (و) من هذه المادة بما يتوافق مع قانون المعاملات الالكترونية النافذ.","title":"أنواع الشركات وأحكام عامة","memo":"⭐ أنواع الشركات: التضامن، التوصية البسيطة، ذات المسؤولية المحدودة، رأس المال المغامر، المساهمة الخاصة، المساهمة العامة\n⭐ لا يشترط موافقة مسبقة من أي جهة أخرى للتسجيل إلا إذا اقتضى تشريع نافذ غير ذلك\n⭐ يجوز الإفصاح بتعليمات الوزير عن بيانات لدى الدائرة لا تتعلق بحسابات الشركة وبياناتها المالية\n⭐ الاجتماعات الإلكترونية جائزة على أن تدار من داخل المملكة","qs":[{"q":"أي مما يلي ليس من أنواع الشركات التي يتم تسجيلها بمقتضى قانون الشركات وفق المادة (٦)؟","o":["شركة المحاصة","شركة رأس المال المغامر","الشركة المساهمة الخاصة","شركة التوصية البسيطة"],"a":0},{"q":"يجوز للدائرة، بمقتضى تعليمات يصدرها الوزير، الإفصاح عن أي بيانات أو معلومات لديها باستثناء:","o":["البيانات المتعلقة بحسابات الشركة وبياناتها المالية","أسماء الشركاء","عنوان المركز الرئيسي للشركة","غايات الشركة"],"a":0},{"q":"عقدت شركة اجتماع هيئتها العامة بالوسائل الإلكترونية، فإن ذلك جائز بشرط:","o":["أن تتم إدارة الاجتماع من داخل المملكة","موافقة الوزير المسبقة على الاجتماع","حضور مندوب المراقب شخصياً","أن يكون جميع المساهمين داخل المملكة"],"a":0},{"q":"يكون للصور الإلكترونية للوثائق المستخرجة من الدائرة الآثار القانونية للمستندات الخطية الأصلية بما فيها حجيتها في الإثبات بعد:","o":["ختمها بخاتم الدائرة وتوقيعها من الموظف المختص","تصديقها من الكاتب العدل","موافقة الوزير عليها","نشرها في الجريدة الرسمية"],"a":0}]},{"n":"7","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - تسجل الشركات التي تؤسس في المملكة بموجب اتفاقيات تبرمها الحكومة مع اي دولةاخرى ، والشركات العربية المشتركة المنبثقة عن الجامعة العربية او المؤسسات او المنظمات التابعة لها لدى المراقب في سجل خاص يعد لهذه الغاية ، و تخضع هذه الشركات للأحكام والشروط المنصوص عليها في هذا القانون وذلك في الحالات وعلى المسائل التي لم ينص عليها في الاتفاقيات والعقود التي تم تأسيسها بموجبها والأنظمة التأسيسية الخاصة بها .\nب - تسـجل الشـركات التـي تـعمـل فـي المنـاطق الحـرة لدى دائرة مراقبة الشركات من خلال الخدمة الاستثمارية الشـاملة الموجـودة فـي وزارة الاستثمار وفـي السـجلات التي تعدها لهذه الغاية.\nج - الشركات المدنية :\n١ - تسجل الشركات المدنية لدى المراقب بسجل خاص يسمى \"سجل الشركات المدنية \" وهي الشركات التي تؤسس بين شركاء من ذوي الاختصاص والمهن وتخضع لأحكام القانون المدني واحكام القوانين الخاصة بها وعقودها وانظمتها الداخلية .\n٢ - يجوز دخول شركاء جدد من نفس المهنة او خروج شركاء منها.\n٣ - يسري على تسجيلها والتغيرات عليها الأحكام المنصوص عليها في هذا القانون بالقدر الذي لا يتعارض مع أحكام القوانين والأنظمة الخاصة بها .\n٤. اذا كان جميع الشركاء في الشركة من اصحاب مهنة واحدة ، وكانت غايات الشركة تقتصر على ممارسة الاعمال والانشطة المتعلقة بتلك المهنة ، فيجوز للشركاء ان يتفقوا في عقد تاسيس الشركة او في نظامها الداخلي على أي احكام خاصة لادارة الشركة او توزيع ارباحها او تنظيم انتقال ملكية الحصص فيها ووضع القيود اللازمة لذلك او وضع احكام خاصة لاي مسائل اخرى متعلقة بالشركة .\nد- الشركات التي لا تهدف إلى تحقيق الربح :-\nعلى الرغم مما ورد في قانون الجمعيات النافذ:-\n١- يجوز تسجيل شركات لا تهدف إلى تحقيق الربح وفق أي من الأنواع المنصوص عليها في هذا القانون في سجل خاص يسمى ( سجل الشركات التي لا تهدف إلى تحقيق الربح ).\n٢ - يحدد نظام خاص الغايات التي يحق للشركات المسجلة وفق أحكام البند (١) من هذه الفقرة ممارستها، كما يحدد النظام أحكام تأسيسها وشروط قيامها بأعمالها وسائر الأمور المتعلقة بها وسبل الإشراف والرقابة عليها وأسلوب وطريقة حصولها على المساعدات والتبرعات ومصادر تمويلها وأسلوب إنفاقها وتصفيتها وأيلولة أموالها عند التصفية والبيانات التي يجب ان تقوم بتقديمها للمراقب ، وشروط وإجراءات تحولها إلى شركات تهدف إلى تحقيق الربح .\n٣ - مع مراعاة أحكام البند (٤) من هذه الفقرة ، على الشركة التي لا تهدف الى تحقيق الربح ان تعلن في تقريرها السنوي عن أي تبرع أو تمويل حصلت عليه ، على أن تقيد الشركة في سجلاتها المالية اسم الجهة المقدمة للتبرع أو التمويل ومقداره والغاية التي سينفق عليها وأي شروط خاصة بذلك .\n٤ - أـ إذا رغبت الشركة التي لا تهدف الى تحقيق الربح الحصول على تبرع أو تمويل من شخص غير اردني فعليها الحصول على موافقة مجلس الوزراء بناء على تنسيب الوزير ووفق إشعار يبين هذا التبرع او التمويل ومقداره وطريقة استلامه والغاية التي سينفق عليها واي شروط خاصة به.\nب - يرفع الإشعار مع تنسيب الوزير إلى مجلس الوزراء خلال ثلاثين يوما من تاريخ تقديمه ، وفي حال عدم صدور قرار عن مجلس الوزراء خلال مدة ثلاثين يوما من تاريخ تنسيب الوزير يعتبر التبرع او التمويل موافقا عليه حكما .\n٥ - أ- تعتبر الشركات التي لا تهدف إلى تحقيق الربح المسجلة لدى المراقب قبل نفاذ قانون الجمعيات رقم (٥١) لسنة ٢٠٠٨ والتي تدخل غاياتها ضمن الغايات التي يحددها النظام الخاص الصادر وفق أحكام البند (٢) من هذه الفقرة كأنها قائمة ومسجلة وفق أحكام هذه المادة ، إلا إذا قررت الشركة الاستمرار في تسجيلها جمعية خاصة .\nب - على الشركات التي لا تهدف الى تحقيق الربح القائمة عند نفاذ احكام هذا القانون المعدل توفيق أوضاعها وفقا لأحكام النظام الصادر بمقتضى البند (٢) من الفقرة (د) من هذه المادة خلال ستة اشهر من تاريخ نفاذه وذلك تحت طائلة المسؤولية القانونية .\nهـ- تسجل شركة الاستثمار المشترك شركة مساهمة عامة لدى المراقب في سجل خاص وتسري على تسجيلها وادارتها والتغييرات التي تطرا عليها احكام هذا القانون وفيما عدا ذلك تخضع لاحكام قانون الاوراق المالية .\nو- يتم امام المراقب او من يفوضه خطيا توقيع طلب تسجيل الشركة وعقد تاسيسها ونظامها الاساسي او أي بيان او أي تعديل يطرا على أي منها او توقيع أي وثيقة يتطلب القانون تقديمها للمراقب او الدائرة لاي من انواع الشركات المنصوص عليها في هذا القانون ويجوز توقيع هذه الوثائق امام الكاتب العدل او احد المحامين المزاولين .","title":"الشركات الخاصة والمدنية وغير الربحية","memo":"⭐ شركات الاتفاقيات الحكومية والشركات العربية المشتركة تسجل لدى المراقب في سجل خاص\n⭐ الشركات المدنية: بين شركاء من ذوي الاختصاص والمهن وتخضع للقانون المدني\n⭐ تمويل الشركة غير الربحية من شخص غير أردني يحتاج موافقة مجلس الوزراء بتنسيب الوزير؛ يرفع الإشعار خلال ٣٠ يوماً، وعدم صدور قرار خلال ٣٠ يوماً من التنسيب = موافقة حكماً\n⭐ شركة الاستثمار المشترك تسجل شركة مساهمة عامة في سجل خاص؛ يجوز توقيع الوثائق أمام المراقب أو من يفوضه خطياً أو الكاتب العدل أو أحد المحامين المزاولين","qs":[{"q":"إذا رغبت شركة لا تهدف إلى تحقيق الربح بالحصول على تمويل من شخص غير أردني، فعليها الحصول على موافقة:","o":["مجلس الوزراء بناءً على تنسيب الوزير","الوزير بناءً على تنسيب المراقب","المراقب","وزير التخطيط"],"a":0},{"q":"رفع الوزير إشعار تمويل أجنبي لشركة غير ربحية مع تنسيبه إلى مجلس الوزراء، ولم يصدر مجلس الوزراء قراراً خلال ثلاثين يوماً من تاريخ التنسيب، فإن التمويل:","o":["يعتبر موافقاً عليه حكماً","يعتبر مرفوضاً حكماً","يحال إلى المراقب للبت فيه","يعاد إلى الوزير لإعادة التنسيب"],"a":0},{"q":"تسجل شركة الاستثمار المشترك لدى المراقب بوصفها:","o":["شركة مساهمة عامة في سجل خاص","شركة ذات مسؤولية محدودة","شركة مساهمة خاصة","شركة مدنية"],"a":0},{"q":"أي مما يلي لا يجوز توقيع طلب تسجيل الشركة وعقد تأسيسها أمامه وفق المادة (٧)؟","o":["مدقق الحسابات القانوني","المراقب أو من يفوضه خطياً","الكاتب العدل","أحد المحامين المزاولين"],"a":0}]},{"n":"8","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"على الرغم مما هو منصوص عليه في هذا القانون :\nأ - يجوز ، بقرار من مجلس الوزراء ، بناء على تنسيب الوزير ووزير المالية والوزير المختص تحويل أي مؤسسة او سلطة او هيئة رسمية عامة او مرفق عام او أي جزء منه الى شركة مساهمة عامة او خاصة او شركة ذات مسؤولية محدودة تعمل وفق الاسس التجارية وتمتلك الحكومة كامل اسهمها باستثناء المؤسسة او السلطة او الهيئة العامة التي انشئت بموجب قانون خاص بها فيقتضي تعديل القانون الخاص بها قبل تحويلها الى أي نوع من تلك الشركات بموجب احكام هذه المادة .\nب - يحدد رأسمال تلك الشركة باعادة تقدير موجودات المؤسسة او السلطة او الهيئة المنقولة وغير المنقولة وفقاً لأحكام القانون على ان يكون من بين أعضاء لجنة اعادة التقدير مدقق حسابات قانوني واحد على الأقل وتعتبر قيمة هذه الموجودات اسهما نقدية في رأسمال الشركة .\nج - يعين مجلس الوزراء لجنة خاصة تتولى اعداد عقد التأسيس والنظام الأساسي للشركة متضمناً اسلوب بيع وتداول أسهمهما واتمام الاجراءات الخاصة بتحويل المؤسسة او السلطة او الهيئة الرسمية العامة الى شركة مساهمة عامة وتسجيلها بهذه الصفة وفقاً لأحكام هذا القانون .\nد - لدى تحويل المؤسسة او السلطة او الهيئة الرسمية العامة الى شركة وتسجيلها بهذه الصفة يعين مجلس الوزراء مجلس ادارة لها يتولى تصريف شؤونها ويمارس جميع الصلاحيات المخولة له بموجب هذا القانون .\nهـ - تخضع الشركة المؤسسة على الوجه المتقدم للأحكام والشروط المنصوص عليها في هذا القانون وذلك في الحالات وعلى المسائل التي لم تنص عليها عقود تأسيسها وأنظمتها الأساسية وتنتخب مدقق حسابات مستقل لها .\nو - تعتبر الشركة المؤسسة على هذا الوجه خلفاً عاماً للمؤسسة او السلطة او الهيئة الرسمية العامة التي تم تحويلها وتحل محلها حلولاً قانونياً وواقعياً في كل ما لها من حقوق وما عليها من التزامات .","title":"تحويل المؤسسات العامة إلى شركات","memo":"⭐ التحويل بقرار من مجلس الوزراء بتنسيب الوزير ووزير المالية والوزير المختص، والحكومة تمتلك كامل الأسهم\n⭐ المؤسسة المنشأة بقانون خاص يقتضي تعديل قانونها قبل التحويل\n⭐ لجنة إعادة التقدير تضم مدقق حسابات قانونياً واحداً على الأقل، وتعتبر قيمة الموجودات أسهماً نقدية\n⭐ الشركة خلف عام للمؤسسة المحولة","qs":[{"q":"يتم تحويل مؤسسة رسمية عامة إلى شركة مساهمة عامة بقرار من:","o":["مجلس الوزراء بناءً على تنسيب الوزير ووزير المالية والوزير المختص","الوزير بناءً على تنسيب المراقب","مجلس الأمة","وزير المالية بناءً على تنسيب الوزير المختص"],"a":0},{"q":"يشترط في لجنة إعادة تقدير موجودات المؤسسة العامة المحولة إلى شركة أن يكون من بين أعضائها:","o":["مدقق حسابات قانوني واحد على الأقل","مندوب عن هيئة الأوراق المالية","محامٍ مزاول واحد على الأقل","مدقق حسابات قانونيان اثنان على الأقل"],"a":0},{"q":"تعتبر قيمة موجودات المؤسسة العامة بعد إعادة تقديرها في رأسمال الشركة المحولة:","o":["أسهماً نقدية","أسهماً عينية","قرضاً للحكومة","احتياطياً إجبارياً"],"a":0},{"q":"المؤسسة العامة التي أنشئت بموجب قانون خاص بها يشترط لتحويلها إلى شركة:","o":["تعديل القانون الخاص بها قبل تحويلها","موافقة المراقب على التحويل","موافقة الهيئة العامة للمساهمين","طرح أسهمها للاكتتاب العام أولاً"],"a":0}]},{"n":"9","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تتألف شركة التضامن من عدد من الأشخاص الطبيعيين لا يقل عن اثنين ولا يزيد على عشرين ، الا اذا طرأت الزيادة على ذلك نتيجة للارث ، على ان تراعى في هذه الزيادة احكام المادتين ( ١٠ ) و ( ٣٠ ) من هذا القانون .\nب - لا يقبل اي شخص شريكاً في شركة التضامن الا اذا كان قد أكمل الثامنة عشرة من عمره على الأقل .\nج - يكتسب الشريك في شركة التضامن صفة التاجر ، ويعتبر ممارساً لأعمال التجارة باسم الشركة .","title":"تأليف شركة التضامن","memo":"⭐ تتألف من أشخاص طبيعيين لا يقل عددهم عن ٢ ولا يزيد على ٢٠ إلا إذا طرأت الزيادة نتيجة الإرث\n⭐ لا يقبل الشريك إلا إذا أكمل الثامنة عشرة من عمره\n⭐ يكتسب الشريك المتضامن صفة التاجر","qs":[{"q":"الحد الأقصى لعدد الشركاء في شركة التضامن عند التأسيس هو:","o":["عشرون شريكاً","خمسون شريكاً","عشرة شركاء","ثلاثون شريكاً"],"a":0},{"q":"يجوز أن يزيد عدد الشركاء في شركة التضامن على الحد الأقصى المقرر في حالة:","o":["الزيادة الناتجة عن الإرث","موافقة المراقب","موافقة جميع الشركاء","زيادة رأس مال الشركة"],"a":0},{"q":"الحد الأدنى لعمر الشريك في شركة التضامن هو:","o":["ثماني عشرة سنة مكتملة","إحدى وعشرون سنة","ست عشرة سنة","خمس وعشرون سنة"],"a":0}]},{"n":"10","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يتألف عنوان شركة التضامن من أسماء جميع الشركاء فيها ، او من لقب او كنية كل منهم ، او من اسم واحد او اكثر منهم او لقبه على ان تضاف في هذه الحالة الى اسمه او أسمائهم عبارة ( وشركاه ) او ( وشركاهم ) حسب مقتضى الحال ، او ما يفيد معنى هذه العبارة ، ويجب ان يكون عنوان الشركة متفقا دائماً مع هيئتها القائمة .\nب - لشركة التضامن ان تتخذ لها اسماً تجارياً خاصاً على ان يقترن هذا الاسم التجاري بالعنوان الذي سجلت به الشركة وان يدرج في الوثائق والمستندات التي تصدر عنها او تتعامل بها وفي مراسلاتها .\nج - اذا توفي جميع الشركاء في شركة التضامن او بعضهم وكان عنوان الشركة مسجلاً باسمائهم فلورثتهم والشركاء الباقين بموافقة المراقب الاحتفاظ بعنوان الشركة واستعماله اذا تبين له بان عنوان الشركة قد اكتسب شهرة تجارية .","title":"عنوان شركة التضامن","memo":"⭐ يتألف من أسماء جميع الشركاء أو ألقابهم أو اسم واحد أو أكثر مع عبارة (وشركاه/وشركاهم)، ويجب أن يتفق دائماً مع هيئتها القائمة\n⭐ يجوز اتخاذ اسم تجاري خاص مقترن بالعنوان المسجل\n⭐ عند وفاة الشركاء يجوز للورثة والباقين الاحتفاظ بالعنوان بموافقة المراقب إذا اكتسب شهرة تجارية","qs":[{"q":"إذا تألف عنوان شركة التضامن من اسم أحد الشركاء فقط، فيجب أن:","o":["تضاف إليه عبارة (وشركاه) أو ما يفيد معناها","يقترن به الاسم التجاري للشركة","يكون الشريك صاحب أكبر حصة","يوافق الوزير على ذلك"],"a":0},{"q":"توفي الشركاء الذين سجل عنوان شركة التضامن بأسمائهم، فيجوز لورثتهم والشركاء الباقين الاحتفاظ بعنوان الشركة بشرط:","o":["موافقة المراقب إذا تبين له أن العنوان اكتسب شهرة تجارية","موافقة الوزير ونشر ذلك في الجريدة الرسمية","موافقة المحكمة","أن تتحول الشركة إلى شركة توصية بسيطة"],"a":0},{"q":"إذا اتخذت شركة التضامن اسماً تجارياً خاصاً، فيجب:","o":["أن يقترن بالعنوان الذي سجلت به الشركة ويدرج في وثائقها ومراسلاتها","أن يحل محل عنوان الشركة في جميع وثائقها","أن يتضمن أسماء جميع الشركاء","أن يوافق عليه مجلس الوزراء"],"a":0}]},{"n":"11","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يقدم طلب التسجيل الى المراقب مرفقا به النسخة الاصلية من عقد الشركة موقعا من الشركاء جميعا وبيانا موقعا من كل منهم ، وفقا لاحكام الفقرة (و) من المادة (٧) من هذا القانون على ان يتضمن عقد الشركة وبيانها ما يلي :\n١ - عنوان الشركة واسمها التجاري اذا وجد .\n٢ - اسماء الشركاء وجنسية كل منهم وعمره وعنوانه .\n٣ - المركز الرئيسي للشركة .\n٤ - مقدار رأسمال الشركة وحصة كل شريك منهم .\n٥ - غايات الشركة .\n٦ - مدة الشركة اذا كانت محدودة .\n٧ - اسم الشريك المفوض او اسماء الشركاء المفوضين بادارة الشركة والتوقيع عنها وصلاحياتهم .\n٨ - الوضع الذي ستؤول اليه الشركة في حالة وفاة اي شريك فيها او افلاسه او الحجر عليه ، او وفاة الشركاء جميعاً .\nب - يترتب على المراقب ان يصدر قراره بالموافقة على تسجيل الشركة خلال خمسة عشر يوماً من تاريخ تقديم طلب التسجيل وله رفض الطلب اذا تبين له ان في عقد الشركة او في بيانها ما يخالف هذا القانون او النظام العام او احكام سائر التشريعات المعمول بها ولم يقم الشركاء بازالة المخالفة خلال المدة التي يحددها وللشركاء الاعتراض على قرار الرفض الى الوزير خلال ثلاثين يوماً من تبليغه اليهم .\nواذا قرر الوزير رفض الاعتراض فيحق للمعترضين الطعن في قراره لدى المحكمة الإدارية خلال ثلاثين يوماً من تاريخ تبليغهم القرار .\nج - اذا وافق المراقب على تسجيل شركة التضامن او تمت هذه الموافقة بقرار من الوزير بمقتضى احكام الفقرة ( ب ) من هذه المادة فيتم تسجيلها بعد استيفاء رسوم التسجيل ، ويصدر المراقب للشركة شهادة بتسجيلها تعتبر بينة رسمية في جميع الاجراءات القانونية ، ويترتب على الشركة الاحتفاظ بها وتعليقها في مكان ظاهر في مركزها الرئيسي ، كما يقوم المراقب بنشر اعلان تسجيل الشركة في الجريدة الرسمية .\nد - لا يجوز لشركة التضامن أن تباشر أعمالها أو تمارس أياً منها الا بعد تسجيلها ودفع الرسوم المترتبة عليها بمقتضى أحكام هذه المادة ووفقاً لسائر أحكام هذا القانون والأنظمة الصادرة بمقتضاه .","title":"إجراءات تسجيل شركة التضامن","memo":"⭐ يقرر المراقب الموافقة على التسجيل خلال ١٥ يوماً من تقديم الطلب\n⭐ الاعتراض على الرفض إلى الوزير خلال ٣٠ يوماً من التبليغ، والطعن بقرار الوزير لدى المحكمة الإدارية خلال ٣٠ يوماً\n⭐ شهادة التسجيل بينة رسمية تعلق في مكان ظاهر في المركز الرئيسي، وينشر المراقب إعلان التسجيل في الجريدة الرسمية\n⭐ لا تباشر الشركة أعمالها إلا بعد تسجيلها ودفع الرسوم","qs":[{"q":"يترتب على المراقب إصدار قراره بالموافقة على تسجيل شركة التضامن خلال:","o":["خمسة عشر يوماً من تاريخ تقديم طلب التسجيل","ثلاثين يوماً من تاريخ تقديم طلب التسجيل","سبعة أيام من تاريخ تقديم طلب التسجيل","ستين يوماً من تاريخ تقديم طلب التسجيل"],"a":0},{"q":"رفض المراقب تسجيل شركة تضامن لمخالفة عقدها للقانون، فللشركاء الاعتراض على قرار الرفض إلى:","o":["الوزير خلال ثلاثين يوماً من تبليغه إليهم","المحكمة الإدارية خلال ستين يوماً","مجلس الوزراء خلال ثلاثين يوماً","محكمة البداية خلال خمسة عشر يوماً"],"a":0},{"q":"أي مما يلي لا يشترط تضمينه في عقد شركة التضامن وبيانها عند التسجيل؟","o":["أسماء مدققي حسابات الشركة","غايات الشركة","مدة الشركة إذا كانت محدودة","الوضع الذي ستؤول إليه الشركة في حالة وفاة أي شريك"],"a":0},{"q":"تعتبر شهادة تسجيل شركة التضامن الصادرة عن المراقب:","o":["بينة رسمية في جميع الإجراءات القانونية","بينة أولية قابلة لإثبات العكس دون قيد","شرطاً لنشر عقد الشركة فقط","وثيقة داخلية لا يحتج بها أمام الغير"],"a":0}]},{"n":"12","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"ينظم المراقب سجلاً خاصاً يسجل فيه شركات التضامن بأرقام متسلسلة حسب تاريخ تسجيلها ، وتدرج فيه التعديلات والتغييرات التي تطرأ على كل منها ، ويجوز لاي شخص الاطلاع على هذا السجل بموافقة مسبقة من المراقب اذا اقتنع انه ذو مصلحة في ذلك بعد استيفاء الرسوم المقررة منه .","title":"سجل شركات التضامن","memo":"⭐ ينظم المراقب سجلاً خاصاً بأرقام متسلسلة حسب تاريخ التسجيل\n⭐ يجوز لأي شخص الاطلاع عليه بموافقة مسبقة من المراقب إذا اقتنع أنه ذو مصلحة وبعد استيفاء الرسوم","qs":[{"q":"تسجل شركات التضامن في السجل الخاص بها:","o":["بأرقام متسلسلة حسب تاريخ تسجيلها","حسب الترتيب الهجائي لعناوينها","حسب مقدار رأسمالها","حسب غاياتها"],"a":0},{"q":"يجوز لأي شخص الاطلاع على سجل شركات التضامن بشرط:","o":["موافقة مسبقة من المراقب إذا اقتنع أنه ذو مصلحة وبعد استيفاء الرسوم","موافقة جميع الشركاء في الشركة","قرار من المحكمة","موافقة الوزير"],"a":0}]},{"n":"13","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"لشركة التضامن ان تغير عنوانها او تدخل تعديلاً عليه بموافقة المراقب ويوقع الطلب بذلك من جميع الشركاء ولا يؤثر هذا التغيير او التعديل على ما للشركة من حقوق وما عليها من التزامات ،كما لا يكون سبباً في ابطال اي تصرف او اجراء قانوني او قضائي قامت به او قام به غيرها تجاهها وعلى الشركة ان تطلب من المراقب تسجيل التغيير لاسمها او التعديل الذي أدخلته عليه في السجل الخاص بشركات التضامن وذلك خلال سبعة أيام من اجرائه بعد استيفاء الرسوم المقررة عنه ونشره في الجريدة الرسمية على الموقع الالكتروني للدائرة .","title":"تغيير عنوان شركة التضامن","memo":"⭐ تغيير العنوان أو تعديله بموافقة المراقب وطلب موقع من جميع الشركاء\n⭐ لا يؤثر على حقوق الشركة والتزاماتها ولا يبطل أي تصرف\n⭐ طلب تسجيل التغيير خلال سبعة أيام من إجرائه","qs":[{"q":"يجب على شركة التضامن أن تطلب من المراقب تسجيل تغيير عنوانها خلال:","o":["سبعة أيام من إجرائه","ثلاثين يوماً من إجرائه","خمسة عشر يوماً من إجرائه","ستين يوماً من إجرائه"],"a":0},{"q":"يوقع طلب تغيير عنوان شركة التضامن من قبل:","o":["جميع الشركاء","الشريك المفوض بالإدارة فقط","أغلبية الشركاء","الشركاء المالكين لأكثر من نصف رأس المال"],"a":0},{"q":"قامت شركة تضامن بتغيير عنوانها، فإن هذا التغيير:","o":["لا يؤثر على ما للشركة من حقوق وما عليها من التزامات","يؤدي إلى انقضاء التزامات الشركة السابقة","يبطل الإجراءات القضائية التي قامت بها الشركة قبله","يوجب إعادة تأسيس الشركة"],"a":0}]},{"n":"14","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"اذا طرأ اي تغيير او تعديل على عقد شركة التضامن او على اي بيان من البيانات التي سجلت بموجبها فيترتب على الشركة الطلب من المراقب تسجيل ذلك التغير او التعديل في السجل الخاص به بشركات التضامن وذلك خلال ثلاثين يوماً من تاريخ وقوعه او اجرائه وتتبع اجراءات الموافقة والتسجيل والنشر المقررة بمقتضى هذا القانون ، وللمراقب ان ينشر على الموقع الالكتروني للدائرة اي تعديل او تغيير يطرأ على الشركة يراه ضرورياً على نفقة الشركة .","title":"تعديل عقد شركة التضامن","memo":"⭐ يجب طلب تسجيل أي تغيير أو تعديل على العقد أو البيانات خلال ثلاثين يوماً من تاريخ وقوعه أو إجرائه\n⭐ للمراقب نشر أي تعديل يراه ضرورياً على الموقع الإلكتروني للدائرة على نفقة الشركة","qs":[{"q":"إذا طرأ تعديل على عقد شركة التضامن، فعلى الشركة طلب تسجيله لدى المراقب خلال:","o":["ثلاثين يوماً من تاريخ وقوعه أو إجرائه","سبعة أيام من تاريخ وقوعه","ستين يوماً من تاريخ وقوعه","خمسة عشر يوماً من تاريخ وقوعه"],"a":0},{"q":"ينشر المراقب على الموقع الإلكتروني للدائرة أي تعديل يطرأ على شركة التضامن يراه ضرورياً على نفقة:","o":["الشركة","الدائرة","الشريك طالب التعديل","الوزارة"],"a":0}]},{"n":"15","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"ان التخلف عن التقيد باجراءات التسجيل المنصوص عليها في المواد ( ١١ ) و ( ١٣ ) و ( ١٤ ) من هذا القانون لا يمنع من تقرير وجود الشركة فعلاً او تقرير التغيير الطارئ عليها لمصلحة الغير او من تقرير بطلان الشركة او التغيير لمصلحة الغير و لا يستفيد من ذلك التخلف اي من الشركاء ، ويعتبر كل شريك متضامناً مع الشركة وباقي الشركاء تجاه الغير في تحمل اي ضرر ينتج عن ذلك .","title":"أثر عدم التقيد بإجراءات التسجيل","memo":"⭐ عدم التقيد بإجراءات التسجيل (المواد ١١ و١٣ و١٤) لا يمنع تقرير وجود الشركة فعلاً أو بطلانها لمصلحة الغير\n⭐ لا يستفيد أي شريك من التخلف، وكل شريك متضامن مع الشركة وباقي الشركاء تجاه الغير في تحمل الضرر","qs":[{"q":"إن تخلف شركة التضامن عن التقيد بإجراءات التسجيل:","o":["لا يمنع من تقرير وجود الشركة فعلاً لمصلحة الغير","يؤدي إلى انعدام الشركة بصورة مطلقة تجاه الجميع","يعفي الشركاء من المسؤولية تجاه الغير","يجوز للشركاء الاحتجاج به في مواجهة الغير"],"a":0},{"q":"يكون الشريك في شركة التضامن عند تخلفها عن إجراءات التسجيل، بالنسبة للضرر الذي يلحق بالغير:","o":["متضامناً مع الشركة وباقي الشركاء تجاه الغير","مسؤولاً بقدر حصته في رأس المال فقط","غير مسؤول إذا لم يكن مفوضاً بالإدارة","مسؤولاً تجاه الشركة دون الغير"],"a":0}]},{"n":"16","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - مع مراعاة احكام الفقرة ( ب ) من هذه المادة يحدد عقد شركة التضامن حقوق الشركاء والالتزامات المترتبة عليهم ، على انه اذا لم ينص العقد على كيفية توزيع الأرباح او الخسائر فيتم توزيعها بين الشركاء بنسبة حصة كل منهم في رأسمال الشركة .\nب - للشركاء في شركة التضامن الاتفاق على تغيير اوتعديل حقوقهم والالتزامات المترتبة عليهم تجاه بعضهم بموجب عقد الشركة او في اي وثيقة اخرى ويشترط في ذلك ان يخضع لأحكام التسجيل والنشر في الجريدة الرسمية المنصوص عليها في هذا القانون .","title":"حقوق الشركاء والتزاماتهم","memo":"⭐ يحدد عقد الشركة حقوق الشركاء والتزاماتهم\n⭐ إذا لم ينص العقد على توزيع الأرباح والخسائر فتوزع بنسبة حصة كل شريك في رأس المال\n⭐ تعديل الحقوق والالتزامات يخضع لأحكام التسجيل والنشر في الجريدة الرسمية","qs":[{"q":"إذا لم ينص عقد شركة التضامن على كيفية توزيع الأرباح والخسائر، فتوزع:","o":["بنسبة حصة كل شريك في رأسمال الشركة","بالتساوي بين الشركاء","وفق قرار المراقب","وفق قرار الشريك المفوض بالإدارة"],"a":0},{"q":"يشترط في اتفاق الشركاء في شركة التضامن على تعديل حقوقهم والتزاماتهم تجاه بعضهم:","o":["أن يخضع لأحكام التسجيل والنشر في الجريدة الرسمية","أن يصادق عليه الوزير","أن يصدر به قرار من المحكمة","أن يوافق عليه مدقق الحسابات"],"a":0}]},{"n":"17","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يحق لكل شريك ان يشترك في ادارة شركة التضامن ويحدد عقد الشركة أسماء الشركاء المفوضين بادارتها والتوقيع عنها وصلاحياتهم وعلى الشخص المفوض ان يقوم بأعمال الشركة وفقاً لأحكام هذا القانون والأنظمة الصادرة بموجبه وفي حدود الصلاحيات المفوضة اليه والحقوق الممنوحة له بعقد الشركة ، ولا يجوز له تقاضي مكافأة او أجر عن عمله في ادارة الشركة الا بموافقة باقي الشركاء .\nب - كل شريك مفوض بادارة شركة التضامن والتوقيع عنها يعتبر وكيلاً عن الشركة تلتزم الشركة بالاعمال التي يقوم بها بالنيابة عنها وبالآثار المترتبة على هذه الأعمال. اما اذا كان الشريك غير مفوض وقام باي عمل باسم الشركة فتلتزم الشركة تجاه الغير حسن النية بهذا العمل وتعود على هذا الشريك بالمطالبة بالتعويض عن جميع الخسائر والأضرار التي قد تلحق بها من جراء هذا العمل .","title":"إدارة شركة التضامن","memo":"⭐ يحق لكل شريك الاشتراك في الإدارة، ويحدد العقد المفوضين وصلاحياتهم\n⭐ لا يتقاضى المفوض أجراً عن الإدارة إلا بموافقة باقي الشركاء\n⭐ الشريك المفوض وكيل عن الشركة؛ وعمل الشريك غير المفوض يلزم الشركة تجاه الغير حسن النية مع رجوعها عليه بالتعويض","qs":[{"q":"لا يجوز للشريك المفوض بإدارة شركة التضامن تقاضي مكافأة أو أجر عن عمله في الإدارة إلا:","o":["بموافقة باقي الشركاء","بموافقة المراقب","إذا كانت حصته أقل من نصف رأس المال","بقرار من المحكمة"],"a":0},{"q":"قام شريك غير مفوض في شركة تضامن بإبرام عقد باسم الشركة مع الغير حسن النية، فإن الحكم:","o":["تلتزم الشركة بالعقد تجاه الغير ولها الرجوع على الشريك بالتعويض عن الخسائر والأضرار","يكون العقد باطلاً ولا تلتزم به الشركة","يلتزم الشريك وحده بالعقد دون الشركة","تلتزم الشركة بالعقد دون حق الرجوع على الشريك"],"a":0},{"q":"يعتبر الشريك المفوض بإدارة شركة التضامن والتوقيع عنها بالنسبة للشركة:","o":["وكيلاً عنها تلتزم بأعماله وآثارها","كفيلاً لها","دائناً لها","موظفاً تابعاً للمراقب"],"a":0}]},{"n":"18","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - على الشخص المفوض بادارة شركة التضامن سواء كان شريكاً فيها او لم يكن ان يقوم بالعمل لصالحها بكل أمانة و اخلاص ، وان يحافظ على حقوقها ويراعي مصالحها ، وعليه ان يقدم للشركاء فيها حسابات صحيحة عن أعمال الشركة ومعلومات وبيانات وافية عنها بصورة دورية مناسبة وكلما طلب الشركاء او اي منهم مثل تلك الحسابات والمعلومات والبيانات منه .\nب - يتحمل الشخص المفوض بادارة شركة التضامن مسؤولية ضمان اي ضرر يلحقه بالشركة او يلحق بها بسبب اهماله او تقصيره ، وتسقط هذه المسؤولية بانقضاء خمس سنوات على انتهاء عمله في ادارة الشركة لأي سبب من الأسباب .","title":"واجبات المفوض بالإدارة ومسؤوليته","memo":"⭐ على المفوض العمل بأمانة وإخلاص وتقديم حسابات صحيحة دورياً وكلما طلب الشركاء أو أي منهم\n⭐ يضمن الضرر الناتج عن إهماله أو تقصيره، وتسقط المسؤولية بانقضاء خمس سنوات على انتهاء عمله","qs":[{"q":"تسقط مسؤولية المفوض بإدارة شركة التضامن عن الضرر الناتج عن إهماله أو تقصيره بانقضاء:","o":["خمس سنوات على انتهاء عمله في إدارة الشركة","ثلاث سنوات على انتهاء عمله","سنة واحدة على انتهاء عمله","عشر سنوات على وقوع الضرر"],"a":0},{"q":"يلتزم المفوض بإدارة شركة التضامن بتقديم حسابات صحيحة ومعلومات وافية عن أعمال الشركة:","o":["بصورة دورية مناسبة وكلما طلب الشركاء أو أي منهم ذلك","مرة واحدة سنوياً فقط","عند طلب المراقب فقط","عند انتهاء عمله فقط"],"a":0},{"q":"تسري أحكام المادة (١٨) المتعلقة بواجبات المفوض بإدارة شركة التضامن على المفوض:","o":["سواء كان شريكاً فيها أو لم يكن","إذا كان شريكاً فقط","إذا كان من غير الشركاء فقط","إذا كان يتقاضى أجراً فقط"],"a":0}]},{"n":"19","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يترتب على الشخص المفوض بادارة شركة التضامن ان يقدم للشركاء فيها خلال مدة لا تزيد على ثلاثة أشهر من انتهاء عمله في ادارة الشركة سواء طلبوا منه ذلك ام لم يطلبوا ما يلي :\n١ - حساباً عن كل منفعة نقدية او عينية او حقوق حصل عليها او حازها من اي عمل يتعلق بالشركة قام به او مارسه في سياق ادارته للشركة واحتفظ لنفسه بتلك المنفعة ، بما في ذلك اي منافع من ذلك القبيل حصل عليها نتيجة لاستغلاله اسم الشركة او علاماتها التجارية او شهرتها ، ويترتب عليه رد تلك المنافع للشركة بكامل مقدارها او قيمتها وضمان الضرر الذي لحق بالشركة من جراء ذلك ، بما في ذلك الفوائد والنفقات والمصاريف التي تكبدتها الشركة .\n٢ - حساباً عن اي أموال او موجودات تعود للشركة أقدم على وضعها تحت حيازته او تصرفه واستعمالها او استغلالها او بقصد استغلالها لمنفعته الشخصية ، وان يعيد تلك الأموال والموجودات للشركة وضمان قيمة ما لحق بها من تلف وخسارة ، وتعويض الشركة عما تكبدته من عطل وضرر وما فاتها من ربح .\nب - لا تسري احكام سقوط المسؤولية المنصوص عليها في الفقرة ( ب ) من المادة ( ١٨ ) من هذا القانون على الأفعال المنصوص عليها في هذه المادة ، كما وانه ليس فيها ما يمنع من تحميل مرتكبها مسؤولية جزائية بمقتضى اي قانون آخر .","title":"حسابات المفوض بعد انتهاء عمله","memo":"⭐ يقدم المفوض للشركاء خلال مدة لا تزيد على ثلاثة أشهر من انتهاء عمله حساباً عن المنافع التي احتفظ بها لنفسه وعن أموال الشركة التي وضعها تحت تصرفه، طلبوا أم لم يطلبوا\n⭐ لا يسري سقوط المسؤولية بخمس سنوات (م١٨/ب) على هذه الأفعال، ولا يمنع ذلك المسؤولية الجزائية","qs":[{"q":"يترتب على المفوض بإدارة شركة التضامن تقديم حساب عن المنافع التي حصل عليها واحتفظ بها لنفسه خلال مدة لا تزيد على:","o":["ثلاثة أشهر من انتهاء عمله في إدارة الشركة","شهر واحد من انتهاء عمله","ستة أشهر من انتهاء عمله","سنة من انتهاء عمله"],"a":0},{"q":"استغل مفوض بإدارة شركة تضامن اسمها التجاري لتحقيق منفعة شخصية، وانقضت ست سنوات على انتهاء عمله، فإن مسؤوليته:","o":["لا تسقط لأن أحكام سقوط المسؤولية بمرور خمس سنوات لا تسري على هذه الأفعال","تسقط لمرور أكثر من خمس سنوات على انتهاء عمله","تسقط لمرور أكثر من ثلاثة أشهر على انتهاء عمله","تقتصر على المسؤولية الجزائية دون المدنية"],"a":0},{"q":"يلتزم المفوض بتقديم الحساب المنصوص عليه في المادة (١٩) للشركاء:","o":["سواء طلبوا منه ذلك أم لم يطلبوا","فقط إذا طلبه أغلبية الشركاء","فقط إذا طلبه المراقب","فقط إذا صدر قرار من المحكمة"],"a":0}]},{"n":"20","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . اذا كان الشخص المفوض بادارة شركة التضامن وبالتوقيع عنها شريكا فيها ومعينا بهذه الصفة بمقتضى عقد الشركة او بموجب عقد خاص تم الاتفاق عليه بين الشركاء ، فلا يجوز عزله من ادارتها والتوقيع عنها وتعيين بدلا منه الا بموافقة جميع الشركاء او بناء على قرار يصدر باكثرية تزيد على نصف عددهم ممن يملكون ما يزيد على (%٥٠) من راسمال الشركة اذا كان عقد الشركة يجيز ذلك وتضمن نصا عن كيفية تعيين من يفوض بادارتها والتوقيع عنها من الشركاء بدلا ممن تم عزله وبخلاف ذلك لا يجوز عزل الشريك المفوض .\nب. يجوز عزل الشريك المفوض بالادارة وبالتوقيع عن الشركة بناء على طلب شريك او اكثر وبقرار يصدر عن المحكمة المختصة اذا رات سببا مشروعا يبرر هذا العزل ، وتتخذ المحكمة المختصة قرارا بتعيين المفوض البديل .","title":"عزل الشريك المفوض","memo":"⭐ الشريك المفوض المعين بالعقد لا يعزل إلا بموافقة جميع الشركاء أو بقرار أكثرية تزيد على نصف عددهم يملكون أكثر من ٥٠% من رأس المال إذا أجاز العقد ذلك\n⭐ يجوز عزله بقرار من المحكمة المختصة بطلب شريك أو أكثر لسبب مشروع، وتعين المحكمة المفوض البديل","qs":[{"q":"يجوز عزل الشريك المفوض بإدارة شركة التضامن المعين بمقتضى عقد الشركة، إذا أجاز العقد ذلك، بقرار يصدر بأكثرية:","o":["تزيد على نصف عدد الشركاء ممن يملكون ما يزيد على (٥٠%) من رأسمال الشركة","ثلثي عدد الشركاء دون اعتبار لحصصهم","تزيد على نصف عدد الشركاء دون اعتبار لحصصهم","الشركاء المالكين لما يزيد على (٧٥%) من رأس المال"],"a":0},{"q":"طلب شريك في شركة تضامن عزل الشريك المفوض لسبب مشروع، فإن الجهة المختصة بقرار العزل وتعيين البديل هي:","o":["المحكمة المختصة","المراقب","الوزير","الهيئة العامة للشركة"],"a":0},{"q":"إذا لم يجز عقد شركة التضامن عزل الشريك المفوض بالأكثرية ولم يتضمن نصاً عن كيفية تعيين بديله، فإن عزله بالاتفاق يتطلب:","o":["موافقة جميع الشركاء","موافقة أكثرية الشركاء","موافقة المراقب","موافقة الشركاء المالكين لأكثر من نصف رأس المال"],"a":0}]},{"n":"21","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"لا يجوز للشريك في شركة التضامن او المفوض بادارتها سواء كان من الشركاء او من غيرهم القيام باي عمل من الاعمال التالية دون موافقة خطية مسبقة من باقي الشركاء او من جميعهم حسب مقتضى الحال : -\nأ - عقد اي تعهد مع الشركة للقيام باي عمل لها مهما كان نوعه .\nب - عقد اي تعهد او اتفاق مع اي شخص اذا كان موضوع التعهد او الاتفاق يدخل ضمن غايات الشركة وأعمالها .\nج - ممارسة اي عمل او نشاط ينافس به الشركة ، سواء مارسه لحسابه الخاص او لحساب غيره .\nد - الاشتراك في شركة أخرى تمارس أعمالاً مماثلة او مشابهة لأعمال الشركة ، او القيام بادارة مثل تلك الشركات ، ولا تشمل هذه المادة مجرد المساهمة في الشركات المساهمة العامة .","title":"الأعمال المحظورة على الشريك","memo":"⭐ يحظر على الشريك أو المفوض دون موافقة خطية مسبقة من باقي الشركاء: التعاقد مع الشركة، التعاقد مع الغير ضمن غايات الشركة، منافسة الشركة، الاشتراك في شركة مماثلة أو إدارتها\n⭐ لا يشمل الحظر مجرد المساهمة في الشركات المساهمة العامة","qs":[{"q":"أي مما يلي يجوز للشريك في شركة التضامن القيام به دون موافقة باقي الشركاء؟","o":["المساهمة في شركة مساهمة عامة تمارس أعمالاً مماثلة لأعمال الشركة","إدارة شركة أخرى تمارس أعمالاً مماثلة لأعمال الشركة","ممارسة نشاط ينافس الشركة لحساب غيره","عقد تعهد مع الشركة للقيام بعمل لها"],"a":0},{"q":"يشترط لقيام الشريك في شركة التضامن بعقد تعهد مع الشركة للقيام بعمل لها:","o":["موافقة خطية مسبقة من باقي الشركاء أو جميعهم حسب مقتضى الحال","موافقة المراقب","إشعار الشركاء خلال ثلاثين يوماً من التعاقد","أن تكون قيمة التعهد أقل من حصته في رأس المال"],"a":0},{"q":"يسري الحظر الوارد في المادة (٢١) على المفوض بإدارة شركة التضامن:","o":["سواء كان من الشركاء أو من غيرهم","إذا كان من الشركاء فقط","إذا كان من غير الشركاء فقط","إذا كان يتقاضى أجراً فقط"],"a":0}]},{"n":"22","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تتحمل شركة التضامن النفقات والمصاريف التي تكبدها الشخص المفوض بادارة الشركة في سياق قيامه بتسيير أعمالها ، او بسبب ما تحمله من خسارة او ضرر بسبب قيامه باي عمل لمصلحة الشركة او لحماية اموالها وحقوقها ، ولو لم يحصل على موافقة الشركاء المسبقة على ذلك .","title":"نفقات المفوض بالإدارة","memo":"⭐ تتحمل الشركة نفقات ومصاريف المفوض في تسيير أعمالها وما تحمله من خسارة أو ضرر بسبب عمل لمصلحة الشركة أو حماية أموالها، ولو لم يحصل على موافقة الشركاء المسبقة","qs":[{"q":"تكبد المفوض بإدارة شركة تضامن مصاريف لحماية أموال الشركة دون الحصول على موافقة الشركاء المسبقة، فإن هذه المصاريف:","o":["تتحملها الشركة","يتحملها المفوض وحده","لا تتحملها الشركة إلا بموافقة لاحقة من جميع الشركاء","يتحملها الشركاء بالتساوي من أموالهم الخاصة"],"a":0},{"q":"تتحمل شركة التضامن الخسارة أو الضرر الذي يتحمله المفوض بإدارتها إذا كان ذلك:","o":["بسبب قيامه بعمل لمصلحة الشركة أو لحماية أموالها وحقوقها","بسبب منافسته للشركة","بسبب عمل خارج حدود صلاحياته لمصلحته الشخصية","بسبب إهماله في إدارة الشركة"],"a":0}]},{"n":"23","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز للشركاء في شركة التضامن اخراج اي منهم من الشركة ، الا بقرار من المحكمة بناء على طلب اي من الشركاء .","title":"إخراج أحد الشركاء","memo":"⭐ لا يجوز إخراج أي شريك من شركة التضامن إلا بقرار من المحكمة بناءً على طلب أي من الشركاء","qs":[{"q":"لا يجوز إخراج أي شريك من شركة التضامن إلا:","o":["بقرار من المحكمة بناءً على طلب أي من الشركاء","بقرار من أغلبية الشركاء","بقرار من المراقب","بقرار من الوزير بناءً على تنسيب المراقب"],"a":0}]},{"n":"24","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تلتزم شركة التضامن بحفظ دفاترها وقيودها وسجلاتها في مركزها الرئيسي او في اي محل تمارس فيه أعمالها ، كما تلتزم اذا كان رأسمالها عشرة آلاف دينار او أكثر بحفظ دفاتر وسجلات محاسبية منظمة بصورة اصولية ، ولكل شريك فيها الاطلاع عليها بنفسه او بواسطة من يفوضه خطياً بذلك من أهل الخبرة والاختصاص فيها ، والحصول على نسخ او صور منها ، ويعتبر باطلاً اي اتفاق على غير ذلك .\nب - تلتزم شركة التضامن التي يبلغ رأسمالها ماية الف دينار او أكثر بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء .","title":"دفاتر وسجلات شركة التضامن","memo":"⭐ تلتزم الشركة التي رأسمالها ١٠,٠٠٠ دينار أو أكثر بحفظ دفاتر وسجلات محاسبية منظمة أصولياً\n⭐ لكل شريك الاطلاع عليها بنفسه أو بمن يفوضه خطياً من أهل الخبرة، وأي اتفاق خلاف ذلك باطل\n⭐ الشركة التي رأسمالها ١٠٠,٠٠٠ دينار أو أكثر تعين مدقق حسابات قانونياً ينتخب بأكثرية الشركاء","qs":[{"q":"تلتزم شركة التضامن بحفظ دفاتر وسجلات محاسبية منظمة بصورة أصولية إذا كان رأسمالها:","o":["عشرة آلاف دينار أو أكثر","خمسة آلاف دينار أو أكثر","مئة ألف دينار أو أكثر","خمسون ألف دينار أو أكثر"],"a":0},{"q":"تلتزم شركة التضامن بتعيين مدقق حسابات قانوني إذا بلغ رأسمالها:","o":["مئة ألف دينار أو أكثر","عشرة آلاف دينار أو أكثر","خمسين ألف دينار أو أكثر","مئتين وخمسين ألف دينار أو أكثر"],"a":0},{"q":"نص عقد شركة تضامن على حرمان الشركاء غير المفوضين من الاطلاع على دفاتر الشركة، فإن هذا الاتفاق:","o":["باطل","صحيح لأن العقد شريعة المتعاقدين","صحيح إذا وافق عليه المراقب","صحيح إذا كانت الشركة غير ملزمة بتعيين مدقق حسابات"],"a":0},{"q":"ينتخب مدقق حسابات شركة التضامن الملزمة بتعيينه من قبل:","o":["أكثرية الشركاء","جميع الشركاء","المراقب","الشريك المفوض بالإدارة"],"a":0}]},{"n":"25","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تلتزم شركة التضامن باي عمل قام به اي شخص مفوض بادارتها او القيام بذلك العمل وبأي مستند وقعه باسم الشركة سواء كان شريكاً في الشركة او لم يكن .\nب - يعتبر الشخص المفوض بادارة شؤون الشركة مخولاً بالمخاصمة باسم الشركة ،الا اذا نص عقد الشركة على غير ذلك .","title":"التزام الشركة بأعمال المفوض","memo":"⭐ تلتزم الشركة بأي عمل قام به المفوض بإدارتها وبأي مستند وقعه باسمها سواء كان شريكاً أو لم يكن\n⭐ المفوض مخول بالمخاصمة باسم الشركة إلا إذا نص العقد على غير ذلك","qs":[{"q":"يعتبر الشخص المفوض بإدارة شؤون شركة التضامن مخولاً بالمخاصمة باسم الشركة:","o":["إلا إذا نص عقد الشركة على غير ذلك","فقط إذا نص عقد الشركة صراحة على ذلك","فقط بموافقة جميع الشركاء على كل دعوى","فقط بموافقة المراقب"],"a":0},{"q":"وقع مدير مفوض من غير الشركاء مستنداً باسم شركة التضامن ضمن تفويضه، فإن الشركة:","o":["تلتزم بهذا المستند","لا تلتزم به لأنه ليس شريكاً","لا تلتزم به إلا بموافقة جميع الشركاء","لا تلتزم به إلا بعد تصديقه من المراقب"],"a":0}]},{"n":"26","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - مع مراعاة أحكام المادة ( ٢٧ ) من هذا القانون يعتبر الشريك في شركة التضامن مسؤولاً بالتضامن والتكافل مع سائر شركائه عن الديون والالتزامات التي ترتبت على الشركة اثناء وجوده شريكاً فيها ، ويكون ضامناً بأمواله الشخصية لتلك الديون والالتزامات ، وتنتقل هذه المسؤولية والضمانة الى ورثته بعد وفاته في حدود تركته .\nب - كل من انتحل صفة الشريك في شركة التضامن سواء بالفاظ او بكتابة او تصرف او سمح للغير عن علم منه باظهاره كذلك يكون مسؤولاً تجاه كل من اصبح دائناً للشركة اعتقاداً منه بصحة الادعاء .","title":"مسؤولية الشركاء عن ديون الشركة","memo":"⭐ الشريك المتضامن مسؤول بالتضامن والتكافل عن ديون الشركة أثناء وجوده شريكاً، وضامن بأمواله الشخصية\n⭐ تنتقل المسؤولية إلى ورثته بعد وفاته في حدود تركته\n⭐ منتحل صفة الشريك مسؤول تجاه من أصبح دائناً للشركة اعتقاداً بصحة الادعاء","qs":[{"q":"تنتقل مسؤولية الشريك في شركة التضامن عن ديون الشركة بعد وفاته إلى ورثته:","o":["في حدود تركته","في أموالهم الخاصة دون حد","بنسبة حصة كل وارث في الشركة فقط من أموالهم الخاصة","لا تنتقل إلى الورثة مطلقاً"],"a":0},{"q":"سمح شخص للغير عن علم منه بإظهاره شريكاً في شركة تضامن وهو ليس كذلك، فتعامل معها دائن اعتقاداً بصحة ذلك، فإن هذا الشخص:","o":["يكون مسؤولاً تجاه هذا الدائن","لا يكون مسؤولاً لأنه ليس شريكاً","يكون مسؤولاً تجاه الشركة فقط","يكون مسؤولاً بقدر حصة أصغر شريك"],"a":0},{"q":"يكون الشريك في شركة التضامن مسؤولاً بالتضامن والتكافل عن ديون الشركة التي ترتبت عليها:","o":["أثناء وجوده شريكاً فيها","قبل انضمامه وبعده دون تمييز","بعد خروجه منها فقط","بقدر حصته في رأس المال فقط"],"a":0}]},{"n":"27","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز لدائن شركة التضامن مخاصمة الشركة والشركاء فيها ، الا انه لا يجوز له التنفيذ على الأموال الخاصة للشركاء فيها لتحصيل دينه الا بعد قيامه بالتنفيذ على أموال الشركة ، فاذا لم تكف هذه الأموال لتسديد دينه فله بعد ذلك الرجوع بما تبقى منه على الأموال الخاصة للشركاء ، ولكل شريك الرجوع على الشركاء بنسبة ما دفعه عن كل منهم من دين الشركة .","title":"مخاصمة الشركة والتنفيذ على أموال الشركاء","memo":"⭐ يجوز لدائن الشركة مخاصمة الشركة والشركاء\n⭐ لا يجوز التنفيذ على الأموال الخاصة للشركاء إلا بعد التنفيذ على أموال الشركة وعدم كفايتها\n⭐ لكل شريك الرجوع على الشركاء بنسبة ما دفعه عن كل منهم","qs":[{"q":"يجوز لدائن شركة التضامن التنفيذ على الأموال الخاصة للشركاء:","o":["بعد التنفيذ على أموال الشركة وعدم كفايتها لتسديد دينه","مباشرة دون الحاجة للتنفيذ على أموال الشركة","بعد الحصول على موافقة المراقب","بعد تصفية الشركة وشطب تسجيلها فقط"],"a":0},{"q":"دفع شريك في شركة تضامن كامل دين الشركة من أمواله الخاصة، فله:","o":["الرجوع على الشركاء بنسبة ما دفعه عن كل منهم","الرجوع على المراقب","الرجوع على الدائن لاسترداد ما يزيد على حصته","عدم الرجوع لأن مسؤوليته تضامنية"],"a":0}]},{"n":"28","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - للشريك في شركة التضامن الانسحاب بارادته المنفردة من الشركة اذا كانت غير محدودة المدة ويترتب على ذلك ما يلي :\n١ - ان يبلغ المراقب والشركاء الاخرين في الشركة اشعاراً خطياً على العنوان الوارد في طلب التأسيس يتضمن رغبته بالانسحاب من الشركة ، ويسري حكم الانسحاب اعتباراً من اليوم التالي من نشر المراقب اعلاناً بذلك في الجريدة الرسمية وعلى الموقع الإلكتروني للدائرة ولا يحتج بالانسحاب على الغير الا من هذا التاريخ .\n٢ - ان يظل الشريك المنسحب مسؤولاً بالتضامن والتكافل مع الشركاء الباقين في الشركة عن الديون والالتزامات التي ترتبت عليها قبل انسحابه منها ويعتبر ضامناً لها بأمواله الشخصية مع باقي الشركاء وفقاً لأحكام هذا القانون .\n٣ - ان يكون مسؤولاً تجاه الشركة والشركاء الباقين فيها عن اي عطل او ضرر لحق بها او بهم بسبب انسحابه من الشركة والتعويض عن ذلك .\nب - اما اذا كانت شركة التضامن لمدة محدودة فلا يجوز لاي شريك فيها الانسحاب منها خلال تلك المدة الا بقرار من المحكمة .\nج - يترتب على الشركاء الباقين في الشركة في حال تطبيق أحكام الفقرتين ( أ ، ب ) من هذه المادة اجراء التعديلات اللازمة على عقد الشركة واجراء التغييرات الضرورية على أوضاعها وفقاً لأحكام هذا القانون .\nد - وفي حالة انسحاب احد الشركاء وفقاً لأحكام الفقرة ( أ ) من هذه المادة ، وكانت الشركة مكونة من شخصين اثنين ، فلا يؤدي ذلك الى فسخ الشركة ويترتب على الشريك الباقي ادخال شريك جديد او أكثر الى الشركة عوضاً عن الشريك المنسحب خلال ستة أشهر من تاريخ الانسحاب واذا لم يقم بذلك خلال هذه المدة تنفسخ الشركة حكماً .","title":"الانسحاب من شركة التضامن","memo":"⭐ يجوز الانسحاب بالإرادة المنفردة إذا كانت الشركة غير محدودة المدة، بإشعار خطي للمراقب والشركاء، ويسري من اليوم التالي لنشر المراقب الإعلان في الجريدة الرسمية وعلى الموقع الإلكتروني\n⭐ يبقى المنسحب مسؤولاً عن الديون السابقة لانسحابه وعن الضرر الناتج عن انسحابه\n⭐ الشركة محدودة المدة: لا انسحاب خلالها إلا بقرار من المحكمة\n⭐ شركة من شخصين: على الباقي إدخال شريك خلال ستة أشهر وإلا تنفسخ حكماً","qs":[{"q":"يسري حكم انسحاب الشريك من شركة التضامن غير محدودة المدة ويحتج به على الغير اعتباراً من:","o":["اليوم التالي لنشر المراقب إعلاناً بذلك في الجريدة الرسمية وعلى الموقع الإلكتروني للدائرة","تاريخ تبليغ الإشعار الخطي إلى الشركاء","تاريخ تقديم الإشعار إلى المراقب","مرور ثلاثين يوماً على تقديم الإشعار"],"a":0},{"q":"انسحب أحد الشريكين من شركة تضامن مكونة من شخصين، فعلى الشريك الباقي إدخال شريك جديد خلال:","o":["ستة أشهر من تاريخ الانسحاب وإلا انفسخت الشركة حكماً","ثلاثة أشهر من تاريخ الانسحاب وإلا انفسخت الشركة حكماً","سنة من تاريخ الانسحاب وإلا شطبت الشركة","ثلاثين يوماً من تاريخ الانسحاب وإلا تحولت الشركة إلى مؤسسة فردية"],"a":0},{"q":"لا يجوز للشريك في شركة التضامن محدودة المدة الانسحاب منها خلال تلك المدة إلا:","o":["بقرار من المحكمة","بموافقة المراقب","بإشعار خطي للشركاء","بموافقة أغلبية الشركاء"],"a":0},{"q":"يبقى الشريك المنسحب من شركة التضامن مسؤولاً بالتضامن والتكافل مع الشركاء الباقين عن:","o":["الديون والالتزامات التي ترتبت على الشركة قبل انسحابه","الديون التي ترتبت على الشركة بعد انسحابه فقط","جميع ديون الشركة السابقة واللاحقة لانسحابه","لا يبقى مسؤولاً عن أي ديون بعد انسحابه"],"a":0}]},{"n":"29","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يجوز ضم شريك او أكثر الى شركة التضامن بموافقة جميع الشركاء فيها الا اذا نص عقد الشركة على غير ذلك ، ويصبح الشريك الجديد مسؤولاً مع باقي الشركاء عن الديون والالتزامات التي ترتبت على الشركة بعد انضمامه اليها ، وضامناً لها بأمواله الخاصة.\nب - تسري أحكام الفقرة ( أ ) من هذه المادة على اي شريك جديد ينضم الى الشركة بتنازل أحد الشركاء الآخرين له عن حصته في الشركة او اي جزء منها ، وتطبق على الشريك المنسحب في هذه الحالة أحكام البندين ( ٢ و ٣ ) من الفقرة ( أ ) من المادة ( ٢٨ ) من هذا القانون .","title":"ضم شريك إلى شركة التضامن","memo":"⭐ ضم شريك جديد بموافقة جميع الشركاء إلا إذا نص العقد على غير ذلك\n⭐ الشريك الجديد مسؤول عن الديون التي ترتبت بعد انضمامه\n⭐ يسري ذلك على من ينضم بتنازل شريك عن حصته، ويطبق على المتنازل حكم الشريك المنسحب","qs":[{"q":"يجوز ضم شريك جديد إلى شركة التضامن:","o":["بموافقة جميع الشركاء إلا إذا نص عقد الشركة على غير ذلك","بموافقة أغلبية الشركاء","بموافقة الشريك المفوض بالإدارة","بموافقة المراقب فقط"],"a":0},{"q":"انضم شريك جديد إلى شركة تضامن، فإنه يكون مسؤولاً مع باقي الشركاء عن:","o":["الديون والالتزامات التي ترتبت على الشركة بعد انضمامه إليها","جميع ديون الشركة منذ تأسيسها","الديون السابقة لانضمامه فقط","ديون الشركة بقدر حصته فقط"],"a":0},{"q":"تنازل شريك في شركة تضامن عن حصته لشخص جديد انضم إلى الشركة، فإن الشريك المتنازل:","o":["تطبق عليه أحكام الشريك المنسحب فيبقى مسؤولاً عن الديون السابقة للتنازل","تبرأ ذمته من جميع ديون الشركة","يبقى مسؤولاً عن ديون الشركة اللاحقة للتنازل","يبقى شريكاً موصياً في الشركة"],"a":0}]},{"n":"30","chapter":"","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - ما لم ينص عقد الشركة او اي عقد آخر وقعه جميع الشركاء قبل وفاة أحد شركائها على غير ذلك .\n١ - تبقى شركة التضامن قائمة ويستمر وجودها في حالة وفاة أحد شركائها .\n٢- ينضم الى الشركة بصفة شريك متضامن كل من يرغب من ورثة الشريك المتوفى بنسبة ما آل اليه من حصة مورثه اذا كان ممن تتوافر فيه الشروط الواجب توافرها في الشريك المتضامن وفقا لاحكام هذا القانون . وعلى الورثة غير الراغبين في الانضمام الى الشركة تبليغ المراقب خطيا بذلك خلال شهرين من تاريخ الوفاة ، وفي جميع الاحوال على الورثة المنضمين والشركاء اجراء التعديلات اللازمة على عقد الشركة وبيانها بما يتفق واحكام القانون خلال مدة يحددها المراقب .\n٣ - اذا كان بين ورثة الشريك المتوفي قاصراً او فاقداً للأهلية القانونية ، فينضم الى الشركة بصفة شريك موصي وتتحول عندها الشركة حكماً الى شركة توصية بسيطة .\nب - اذا استمرت شركة التضامن في العمل بعد وفاة اي من الشركاء فيها دون ان يكون في عقدها او في اي عقد آخر وقعه جميع الشركاء قبل وفاة الشريك نص صريح يمنع استمرار قيامها واستمرت على ذلك الوجه ، فلا تسأل تركة الشريك المتوفي عن اي من الديون والالتزامات التي ترتبت على الشركة بعد وفاته .","title":"وفاة أحد الشركاء","memo":"⭐ ما لم ينص العقد على غير ذلك: تبقى الشركة قائمة عند وفاة أحد الشركاء، وينضم الورثة الراغبون بصفة شركاء متضامنين\n⭐ الورثة غير الراغبين يبلغون المراقب خطياً خلال شهرين من تاريخ الوفاة\n⭐ الوارث القاصر أو فاقد الأهلية ينضم شريكاً موصياً وتتحول الشركة حكماً إلى توصية بسيطة\n⭐ لا تسأل تركة المتوفى عن الديون اللاحقة لوفاته","qs":[{"q":"على ورثة الشريك المتوفى في شركة التضامن غير الراغبين في الانضمام إلى الشركة تبليغ المراقب خطياً بذلك خلال:","o":["شهرين من تاريخ الوفاة","شهر من تاريخ الوفاة","ستة أشهر من تاريخ الوفاة","ثلاثين يوماً من تاريخ حصر الإرث"],"a":0},{"q":"توفي شريك في شركة تضامن وكان من بين ورثته قاصر، فإن القاصر:","o":["ينضم بصفة شريك موصٍ وتتحول الشركة حكماً إلى شركة توصية بسيطة","ينضم بصفة شريك متضامن بواسطة وليه","لا ينضم إلى الشركة وتصفى حصته","ينضم بصفة شريك متضامن وتتحول الشركة إلى ذات مسؤولية محدودة"],"a":0},{"q":"استمرت شركة التضامن في العمل بعد وفاة أحد الشركاء دون وجود نص يمنع استمرارها، فإن تركة الشريك المتوفى:","o":["لا تسأل عن الديون والالتزامات التي ترتبت على الشركة بعد وفاته","تسأل عن جميع ديون الشركة اللاحقة لوفاته","تسأل عن الديون اللاحقة لوفاته بنسبة حصته","تسأل عن الديون اللاحقة لوفاته لمدة سنة"],"a":0},{"q":"الأصل عند وفاة أحد الشركاء في شركة التضامن ما لم ينص العقد على غير ذلك:","o":["بقاء الشركة قائمة واستمرار وجودها","انقضاء الشركة حكماً","تحول الشركة إلى شركة ذات مسؤولية محدودة","وضع الشركة تحت التصفية"],"a":0}]},{"n":"31","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- إذا خضعت الشركة لاجراءات الاعسار وفقا لأحكـام قـانـون الاعسـار فيعتبر الشركاء المتضامنون فيهـا فـي حالـة اعسار وتدخل أموالهم في ذمة الاعسار .\nب- إذا أشهر إعسار أي من الاشخاص الشركاء فـي شـركة التضامن فيتم تصـنيف ديـون دائنـي الشـركة وفـق التصـنيفات الـواردة في قانون الاعسار، وإذا خضعت شركة التضامن لاجراءات التصفية وفقا لاحكام قانون الاعسار فتعطى ديون دائنيها حق التقدم على ديون الشركاء فيها.","title":"إعسار شركة التضامن أو أحد الشركاء","memo":"⭐ إذا خضعت الشركة لإجراءات الإعسار يعتبر الشركاء المتضامنون في حالة إعسار وتدخل أموالهم في ذمة الإعسار\n⭐ إذا أشهر إعسار شريك تصنف ديون دائني الشركة وفق قانون الإعسار؛ وعند تصفية الشركة تعطى ديون دائنيها حق التقدم على ديون الشركاء","qs":[{"q":"إذا خضعت شركة التضامن لإجراءات الإعسار وفقاً لقانون الإعسار، فإن الشركاء المتضامنين فيها:","o":["يعتبرون في حالة إعسار وتدخل أموالهم في ذمة الإعسار","لا يتأثرون بإعسار الشركة","تقتصر مسؤوليتهم على حصصهم في رأس المال","يعتبرون دائنين للشركة"],"a":0},{"q":"إذا خضعت شركة التضامن لإجراءات التصفية وفقاً لقانون الإعسار، فإن ديون دائني الشركة:","o":["تعطى حق التقدم على ديون الشركاء فيها","تتساوى مع ديون الشركاء","تتأخر عن ديون الشركاء","تسقط بشطب تسجيل الشركة"],"a":0}]},{"n":"32","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"تنقضي شركة التضامن في اي من الحالات التالية :\nأ - باتفاق الشركاء جميعهم على حل الشركة او دمجها في شركة اخرى .\nب - بانتهاء المدة المحددة للشركة سواء أكانت المدة الأصلية لها او التي مددت اليها باتفاق جميع الشركاء .\nج - بانتهاء الغاية التي أسست من أجلها .\nد - ببقاء شريك واحد فيها ، مع مراعاة ما ورد في الفقرة ( د ) من المادة ( ٢٨ ) من هذا القانون .\nه - بتصفية الشركة وشطب تسجيلها وفقا لأحكام قانون الإعسار.\nو - بإشهار إعسار أحد الشركاء وخضوعه للتصفية وفقاً لاحكام قانون الاعسار او بالحجر عليه ، ما لم يقرر باقي الشركاء جميعهم استمرار الشركة بينهم وفقاً لعقد الشركة .\nز - بفسخ الشركة بحكم قضائي .\nح - بشطب تسجيل الشركة بقرار من المراقب بمقتضى أحكام هذا القانون .","title":"حالات انقضاء شركة التضامن","memo":"⭐ تنقضي: باتفاق جميع الشركاء على الحل أو الدمج، بانتهاء المدة، بانتهاء الغاية، ببقاء شريك واحد (مع مراعاة م٢٨/د)، بالتصفية والشطب وفق قانون الإعسار، بإعسار أحد الشركاء أو الحجر عليه ما لم يقرر الباقون جميعهم الاستمرار، بحكم قضائي، بشطب المراقب","qs":[{"q":"أي مما يلي ليس من حالات انقضاء شركة التضامن الواردة في المادة (٣٢)؟","o":["تغيير عنوان الشركة","انتهاء الغاية التي أسست من أجلها","فسخ الشركة بحكم قضائي","شطب تسجيل الشركة بقرار من المراقب"],"a":0},{"q":"أشهر إعسار أحد الشركاء في شركة تضامن وخضع للتصفية، فإن الشركة:","o":["تنقضي ما لم يقرر باقي الشركاء جميعهم استمرارها بينهم","تستمر حكماً دون حاجة لأي قرار","تتحول حكماً إلى شركة توصية بسيطة","تنقضي ما لم يقرر المراقب استمرارها"],"a":0},{"q":"يتطلب حل شركة التضامن أو دمجها في شركة أخرى بالاتفاق:","o":["اتفاق الشركاء جميعهم","اتفاق أغلبية الشركاء","اتفاق الشركاء المالكين لأكثر من نصف رأس المال","موافقة المراقب فقط"],"a":0}]},{"n":"33","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تنظر المحكمة في فسخ شركة التضامن بناء على دعوى يقدمها أحد الشركاء ، وذلك في اي من الحالات التالية :\n١ - اذا أخل اي شريك بعقد الشركة اخلالاً جوهرياً مستمراً ، او ألحق ضرراً جسيماً بها نتيجة ارتكابه خطأ او تقصيراً او اهمالاً في ادارة شؤونها او في رعاية مصالحها او المحافظة على حقوقها .\n٢ - اذا لم يعد ممكناً استمرار الشركة في أعمالها الا بخسارة لاي سبب من الأسباب .\n٣ - اذا خسرت الشركة جميع أموالها او جزءاً كبيراً منها بحيث اصبحت الجدوى منتفية من استمرارها .\n٤ - اذا وقع اي خلاف بين الشركاء واصبح استمرار الشركة معه متعذراً .\n٥ - اذا اصبح اي من الشركاء عاجزاً بشكل دائم عن القيام بأعماله تجاه الشركة او الوفاء بالتزاماتها .\nب - للمحكمة في اي حالة من الحالات المنصوص عليها في الفقرة ( أ ) من هذه المادة اما ان تقرر فسخ الشركة ، او ان تقرر بقاءها واستمرارها في العمل بعد اخراج شريك او أكثر منها اذا كان ذلك حسب تقديرها سيؤدي الى استمرار الشركة في أعمالها بصورة طبيعية تحقق مصلحة الشركة والشركاء الباقين فيها وتحفظ حقوق الغير .","title":"فسخ شركة التضامن قضائياً","memo":"⭐ تنظر المحكمة في الفسخ بدعوى من أحد الشركاء في حالات: الإخلال الجوهري المستمر أو الضرر الجسيم، عدم إمكان الاستمرار إلا بخسارة، خسارة جميع الأموال أو جزء كبير، الخلاف الذي يتعذر معه الاستمرار، العجز الدائم لأحد الشركاء\n⭐ للمحكمة أن تقرر الفسخ أو بقاء الشركة بعد إخراج شريك أو أكثر","qs":[{"q":"نشب خلاف بين الشركاء في شركة تضامن أصبح معه استمرار الشركة متعذراً، فأقام أحدهم دعوى فسخ، فإن للمحكمة:","o":["أن تقرر فسخ الشركة أو بقاءها بعد إخراج شريك أو أكثر منها","أن تقرر فسخ الشركة فقط دون أي خيار آخر","أن تحيل الأمر إلى المراقب للبت فيه","أن تقرر تحويل الشركة إلى شركة ذات مسؤولية محدودة"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي تنظر فيها المحكمة في فسخ شركة التضامن وفق المادة (٣٣)؟","o":["انضمام شريك جديد إلى الشركة","إذا أصبح أحد الشركاء عاجزاً بشكل دائم عن القيام بأعماله تجاه الشركة","إذا خسرت الشركة جزءاً كبيراً من أموالها بحيث انتفت الجدوى من استمرارها","إذا لم يعد ممكناً استمرار الشركة في أعمالها إلا بخسارة"],"a":0},{"q":"تنظر المحكمة في فسخ شركة التضامن بناءً على:","o":["دعوى يقدمها أحد الشركاء","طلب من المراقب","قرار من الوزير","طلب من أحد دائني الشركة"],"a":0}]},{"n":"34","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ-اذا توقفت شركة التضامن عن ممارسة اعمالها فعلى الشريك المفوض او أي شريك فيها تبليغ المراقب بذلك خلال مدة لا تزيد على ثلاثين يوما من تاريخ توقفها ، او اذا وصل لعلم المراقب ان الشركة متوقفة عن ممارسة اعمالها وبعد التحقق من ذلك فله في كلتا الحالتين امهالها مدة محددة لاستئناف ممارسة اعمالها ، واذا لم تستجب فيتم قيدها فـي سجل خاص وتشطب حكما اذا مضى على قيدها في هذا السجل مدة سنة.\nب- تبقى مسؤولية الشركاء عن ديون الشركة قائمة في حال التوقف أو الشطب ولدائني الشركة الرجـوع عليهم مباشرة للمطالبة بديونهم على الشركة.","title":"توقف شركة التضامن عن العمل","memo":"⭐ على الشريك المفوض أو أي شريك تبليغ المراقب بالتوقف خلال مدة لا تزيد على ثلاثين يوماً من تاريخه\n⭐ للمراقب إمهالها مدة لاستئناف العمل، فإن لم تستجب تقيد في سجل خاص وتشطب حكماً بعد مضي سنة على القيد\n⭐ تبقى مسؤولية الشركاء عن الديون قائمة عند التوقف أو الشطب","qs":[{"q":"إذا توقفت شركة التضامن عن ممارسة أعمالها، فعلى الشريك المفوض أو أي شريك تبليغ المراقب خلال مدة لا تزيد على:","o":["ثلاثين يوماً من تاريخ توقفها","ستين يوماً من تاريخ توقفها","سبعة أيام من تاريخ توقفها","ستة أشهر من تاريخ توقفها"],"a":0},{"q":"قيدت شركة تضامن متوقفة عن العمل في السجل الخاص لعدم استجابتها لمهلة المراقب، فإنها تشطب حكماً إذا مضى على قيدها مدة:","o":["سنة","ستة أشهر","سنتين","ثلاث سنوات"],"a":0},{"q":"شطبت شركة تضامن بسبب توقفها عن العمل، فإن مسؤولية الشركاء عن ديونها:","o":["تبقى قائمة ولدائني الشركة الرجوع عليهم مباشرة","تنقضي بالشطب","تنتقل إلى المراقب","تبقى قائمة لمدة سنة فقط"],"a":0}]},{"n":"35","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تعتبر شركة التضامن بعد انقضائها لأي سبب من الأسباب المنصوص عليها في هذا القانون ، في حالة تصفية ، وتتم تصفية أموالها وتقسيمها بين الشركاء ، وفقاً لما هو متفق عليه في عقد الشركة او في اي وثيقة موقعة من جميع الشركاء، فاذا لم يوجد بينهم مثل ذلك الاتفاق فتتبع في تصفية الشركة وتقسيم اموالها بين الشركاء أحكام هذا القانون .\nب - تحتفظ شركة التضامن الموجودة تحت التصفية بشخصيتها الاعتبارية الى ان تتم تصفيتها وذلك بالقدر والى المدى اللازمين للتصفية ولاجراءاتها ، وتنتهي سلطة المدير المفوض بادارة أعمال الشركة في هذه الحالة سواء كان من الشركاء او غيرهم .","title":"حالة التصفية وأثرها","memo":"⭐ تعتبر الشركة بعد انقضائها في حالة تصفية، وتصفى وفق اتفاق العقد أو وثيقة موقعة من جميع الشركاء وإلا فوفق القانون\n⭐ تحتفظ بشخصيتها الاعتبارية بالقدر اللازم للتصفية، وتنتهي سلطة المدير المفوض","qs":[{"q":"تحتفظ شركة التضامن الموجودة تحت التصفية بشخصيتها الاعتبارية:","o":["إلى أن تتم تصفيتها وبالقدر والمدى اللازمين للتصفية وإجراءاتها","لمدة سنة من تاريخ انقضائها","حتى تاريخ تعيين المصفي فقط","لا تحتفظ بها لأنها تزول بالانقضاء"],"a":0},{"q":"يترتب على وضع شركة التضامن تحت التصفية بالنسبة للمدير المفوض بإدارة أعمالها:","o":["انتهاء سلطته سواء كان من الشركاء أو غيرهم","استمرار سلطته حتى انتهاء التصفية","تحوله حكماً إلى مصفٍ للشركة","انتهاء سلطته إذا كان من غير الشركاء فقط"],"a":0}]},{"n":"36","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"اذا كانت تصفية شركة التضامن اختيارية باتفاق جميع الشركاء فيعين المصفي وتحدد أجوره من قبلهم ، فاذا اختلفوا على ذلك فيتم تعيين المصفي وتحديد أجوره من قبل المحكمة بناء على طلب الشركاء او اي منهم ، واما اذا كانت الشركة قد انقضت بحكم القانون او بقرار قضائي فيتم تعيين المصفي وتحديد أجوره من قبل المحكمة .","title":"تعيين مصفي شركة التضامن","memo":"⭐ التصفية الاختيارية: يعين المصفي ويحدد أجوره الشركاء، فإن اختلفوا فالمحكمة بطلب الشركاء أو أي منهم\n⭐ الانقضاء بحكم القانون أو بقرار قضائي: تعين المحكمة المصفي وتحدد أجوره","qs":[{"q":"انقضت شركة تضامن بقرار قضائي، فإن الجهة التي تعين المصفي وتحدد أجوره هي:","o":["المحكمة","الشركاء","المراقب","الوزير"],"a":0},{"q":"اتفق الشركاء على تصفية شركة التضامن اختيارياً لكنهم اختلفوا على تعيين المصفي، فإنه يعين:","o":["من قبل المحكمة بناءً على طلب الشركاء أو أي منهم","من قبل المراقب","من قبل أكثرية الشركاء","من قبل الوزير"],"a":0}]},{"n":"37","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - على مصفي شركة التضامن ان يبدا عمله باعلان عن تصفية الشركة على الموقع الالكتروني للدائرة واعداد قائمة تتضمن موجودات الشركة ومطلوباتها ، وان يعمل على تحديد وتسوية مالها من حقوق على الغير وما عليها من التزامات ، ولا يحق له التنازل عن أي من هذه الاموال والموجودات والحقوق او يتصرف بها الا بموافقة مسبقة من جميع الشركاء او باذن من المحكمة .\nب - ليس للمصفي ان يمارس اي عمل جديد من أعمال الشركة او باسمها الا ما كان لازماً او ضرورياً لاتمام عمل سبق للشركة ان بدأته .\nج - يعتبر المصفي مسؤولأ بصفته الشخصية عن مخالفة احكام هذه المادة .","title":"أعمال مصفي شركة التضامن","memo":"⭐ يبدأ المصفي بالإعلان عن التصفية على الموقع الإلكتروني للدائرة وإعداد قائمة بالموجودات والمطلوبات\n⭐ لا يتنازل عن الأموال أو يتصرف بها إلا بموافقة مسبقة من جميع الشركاء أو بإذن المحكمة\n⭐ لا يمارس عملاً جديداً إلا ما كان لازماً لإتمام عمل سابق، ومسؤول شخصياً عن المخالفة","qs":[{"q":"لا يحق لمصفي شركة التضامن التصرف بأموال الشركة وموجوداتها إلا:","o":["بموافقة مسبقة من جميع الشركاء أو بإذن من المحكمة","بموافقة المراقب","بموافقة أغلبية الشركاء","بموافقة دائني الشركة"],"a":0},{"q":"يجوز لمصفي شركة التضامن أن يمارس عملاً جديداً من أعمال الشركة إذا كان:","o":["لازماً أو ضرورياً لإتمام عمل سبق للشركة أن بدأته","مربحاً للشركة","بموافقة أحد الشركاء","ضمن غايات الشركة"],"a":0},{"q":"يبدأ مصفي شركة التضامن عمله بـ:","o":["الإعلان عن تصفية الشركة على الموقع الإلكتروني للدائرة وإعداد قائمة بموجودات الشركة ومطلوباتها","بيع موجودات الشركة","توزيع أموال الشركة على الشركاء","تسديد ديون الخزينة العامة"],"a":0}]},{"n":"38","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يترتب على المصفي التقيد بالاجراءات القانونية والعملية لتصفية شركة التضامن وفقاً لأحكام هذا القانون واي تشريع اخر يرى انه يترتب عليه تطبيقه ، بما في ذلك تحصيل الديون المستحقة للشركة ، وتسديد الديون المستحقة عليها حسب الأولوية القانونية المقررة لها .","title":"واجبات مصفي شركة التضامن","memo":"⭐ يتقيد المصفي بالإجراءات القانونية والعملية للتصفية، بما في ذلك تحصيل ديون الشركة وتسديد الديون المستحقة عليها حسب الأولوية القانونية","qs":[{"q":"يلتزم مصفي شركة التضامن بتسديد الديون المستحقة على الشركة:","o":["حسب الأولوية القانونية المقررة لها","حسب أقدمية تاريخ نشوئها","بالتساوي بين جميع الدائنين","حسب ما يقرره الشركاء"],"a":0},{"q":"أي مما يلي يدخل ضمن واجبات مصفي شركة التضامن وفق المادة (٣٨)؟","o":["تحصيل الديون المستحقة للشركة","ممارسة أعمال جديدة لتنمية أرباح الشركة","ضم شركاء جدد للشركة","تعديل عقد الشركة"],"a":0}]},{"n":"39","chapter":"","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تتبع الاحكام والقواعد التالية في تسوية الحقوق بين الشركاء بعد انقضاء شركة التضامن ووضعها تحت التصفية ، وتستعمل أموالها وموجوداتها في تسوية تلك الحقوق والالتزامات المترتبة عليها بما في ذلك الأموال التي قدمها الشركاء لأغراض تلك التسوية وكجزء منها وفق الترتيبات التالية :\n١ - نفقات التصفية واتعاب المصفي .\n٢ - المبالغ المستحقة على الشركة للعاملين فيها .\n٣ - المبالغ المستحقة على الشركة للخزينة العامة .\n٤ - الديون المستحقة على الشركة لغير الشركاء فيها على ان تراعي في دفعها حقوق الامتياز .\n٥ - القروض التي قدمها الشركاء للشركة ولم تكن جزءاً من حصصهم في رأس مالها .\nب - ينال كل شريك من الربح ويتحمل من الخسارة ، بما في ذلك ربح او خسارة التصفية حسب النسبة المتفق عليها والمحددة في عقد الشركة ، واذا لم ينص العقد على هذه النسبة ، فيتم توزيع الأرباح والخسائر بنسبة حصة كل منهم في رأس المال .\nويقسم ما تبقى بعد ذلك من أموال الشركة وموجوداتها بين الشركاء كل بنسبة حصته في رأسمالها .","title":"ترتيب تسوية الحقوق بعد الانقضاء","memo":"⭐ ترتيب التسوية: ١- نفقات التصفية وأتعاب المصفي ٢- مستحقات العاملين ٣- مستحقات الخزينة العامة ٤- ديون غير الشركاء مع مراعاة حقوق الامتياز ٥- قروض الشركاء التي ليست جزءاً من حصصهم\n⭐ توزع الأرباح والخسائر (ومنها ربح أو خسارة التصفية) حسب النسبة في العقد وإلا بنسبة الحصص في رأس المال","qs":[{"q":"أول ما يدفع من أموال شركة التضامن عند تسوية الحقوق بعد انقضائها:","o":["نفقات التصفية وأتعاب المصفي","المبالغ المستحقة للعاملين في الشركة","المبالغ المستحقة للخزينة العامة","الديون المستحقة لغير الشركاء"],"a":0},{"q":"تأتي المبالغ المستحقة على شركة التضامن للخزينة العامة في ترتيب التسوية بعد:","o":["نفقات التصفية وأتعاب المصفي والمبالغ المستحقة للعاملين","الديون المستحقة لغير الشركاء","القروض التي قدمها الشركاء للشركة","نفقات التصفية فقط وقبل مستحقات العاملين"],"a":0},{"q":"قدم شريك قرضاً لشركة التضامن لا يعد جزءاً من حصته في رأس المال، فإن هذا القرض يسدد عند التصفية:","o":["بعد سداد ديون غير الشركاء","قبل سداد مستحقات العاملين","مع نفقات التصفية","قبل مستحقات الخزينة العامة"],"a":0},{"q":"إذا لم ينص عقد شركة التضامن على نسبة توزيع ربح أو خسارة التصفية، فتوزع:","o":["بنسبة حصة كل شريك في رأس المال","بالتساوي بين الشركاء","وفق تقدير المصفي","وفق تقدير المحكمة"],"a":0}]},{"n":"40","chapter":"","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ . على المصفي عند الانتهاء من تصفية شركة التضامن ان يقدم لكل شريك فيها حسابا ختاميا عن الاعمال والاجراءات التي قام بها في سياق التصفية ويقدم ذلك الحساب الى المحكمة اذا كان المصفي قد عين من قبلها ويبلغ المراقب في جميع الحالات باسباب التصفية ويزود بنسخة من ذلك الحساب خلال مدة لا تتجاوز سنة من تاريخ قرار التصفية وبخلاف ذلك للمراقب تحويل الشركة تحت التصفية للمحكمة لاستكمال اجراءات التصفية تحت اشرافها او منح المصفي مهلة مناسبة لاكمال تلك الاجراءات وفي جميع الحالات يترتب على المراقب نشر الاعلان عن تصفية الشركة في الجريدة الرسمية وعلـى الموقـع الإلكتروني للدائرة ويسـري موعـد الاستئناف مـن تـاريخ النشـر في الجريدة الرسمية ما لم يصدر قرار التصفية بحضور الاطراف .\nب. اذا تبين بعد الانتهاء من اجراءات التصفية وشطب تسجيل الشركة وجود اموال منقولة او غير منقولة باسم الشركة لم تشملها التصفية فللشركاء تقديم طلب مستعجل للمحكمة لاصدار قرار يحدد كيفية تصفية هذه الاموال سواء بتعيين مصف جديدا او استمرار المصفي القديم بعمله .","title":"واجبات المصفي عند انتهاء التصفية","memo":"⭐ يقدم المصفي حساباً ختامياً لكل شريك، وللمحكمة إن كانت عينته، ويبلغ المراقب ويزوده بنسخة خلال مدة لا تتجاوز سنة من تاريخ قرار التصفية\n⭐ وإلا فللمراقب تحويل الشركة للمحكمة أو منح المصفي مهلة مناسبة\n⭐ يسري موعد الاستئناف من تاريخ النشر في الجريدة الرسمية ما لم يصدر قرار التصفية بحضور الأطراف\n⭐ الأموال المكتشفة بعد الشطب: للشركاء تقديم طلب مستعجل للمحكمة","qs":[{"q":"على مصفي شركة التضامن تزويد المراقب بنسخة من الحساب الختامي خلال مدة لا تتجاوز:","o":["سنة من تاريخ قرار التصفية","ستة أشهر من تاريخ قرار التصفية","ثلاثة أشهر من تاريخ قرار التصفية","سنتين من تاريخ قرار التصفية"],"a":0},{"q":"لم يقدم المصفي الحساب الختامي للمراقب خلال المدة المحددة، فللمراقب:","o":["تحويل الشركة تحت التصفية للمحكمة لاستكمال إجراءاتها أو منح المصفي مهلة مناسبة","عزل المصفي وتعيين بديل عنه بقراره","شطب الشركة حكماً","فرض غرامة على الشركاء"],"a":0},{"q":"تبين بعد شطب تسجيل شركة التضامن وجود أموال باسمها لم تشملها التصفية، فللشركاء:","o":["تقديم طلب مستعجل للمحكمة لإصدار قرار يحدد كيفية تصفية هذه الأموال","اقتسام هذه الأموال مباشرة بينهم","تقديم طلب للمراقب لإعادة تسجيل الشركة","تقديم اعتراض للوزير"],"a":0},{"q":"يسري موعد الاستئناف لقرار تصفية شركة التضامن الذي لم يصدر بحضور الأطراف من تاريخ:","o":["النشر في الجريدة الرسمية","تقديم الحساب الختامي للمراقب","تعيين المصفي","النشر على الموقع الإلكتروني للدائرة"],"a":0}]},{"n":"41","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تتألف شركة التوصية البسيطة من الفئتين التاليتين من الشركاء وتدرج وجوباً أسماء الشركاء في كل منهما في عقد الشركة .\nأ - الشركاء المتضامنون: وهم الذين يتولون ادارة الشركة وممارسة أعمالها ، ويكونون مسؤولين بالتضامن والتكافل عن ديون الشركة والالتزامات المترتبة عليها في أموالهم الخاصة .\nب - الشركاء الموصون:ويشاركون في رأس المال دون ان يحق لهم ادارة الشركة او ممارسة أعمالها ، ويكون كل منهم مسؤولاً عن ديون الشركة والالتزامات المترتبة عليها بمقدار حصته في رأس مال الشركة .","title":"فئات الشركاء في شركة التوصية البسيطة","memo":"⭐ الشركاء المتضامنون: يتولون الإدارة ومسؤولون بالتضامن والتكافل في أموالهم الخاصة\n⭐ الشركاء الموصون: يشاركون في رأس المال دون الإدارة، ومسؤولون بمقدار حصصهم\n⭐ تدرج أسماء الفئتين وجوباً في عقد الشركة","qs":[{"q":"تكون مسؤولية الشريك الموصي في شركة التوصية البسيطة عن ديون الشركة:","o":["بمقدار حصته في رأس مال الشركة","بالتضامن والتكافل في أمواله الخاصة","بضعف حصته في رأس المال","غير محدودة كالشريك المتضامن"],"a":0},{"q":"يتولى إدارة شركة التوصية البسيطة وممارسة أعمالها:","o":["الشركاء المتضامنون","الشركاء الموصون","مدير يعينه المراقب","جميع الشركاء بالتساوي"],"a":0},{"q":"تدرج أسماء الشركاء المتضامنين والموصين في شركة التوصية البسيطة:","o":["وجوباً في عقد الشركة","جوازاً في عقد الشركة","في عنوان الشركة","في سجل خاص لدى المحكمة"],"a":0}]},{"n":"42","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز ان يشتمل عنوان شركة التوصية البسيطة الا على أسماء الشركاء المتضامنين واذا لم يكن فيها الا شريك واحد متضامن فيجب ان تضاف عبارة ( وشركاه ) الى اسمه ، كما لا يجوز ان يدرج اسم اي شريك موص في عنوان شركة التوصية البسيطة ، فاذا ادرج بناء على طلبه او بعلمه بذلك ، كان مسؤولاً عن ديون الشركة والالتزامات التي تترتب عليها كشريك متضامن تجاه الغير ممن يكون قد اعتمد في تعامله مع الشركة على ذلك بحسن نية .","title":"عنوان شركة التوصية البسيطة","memo":"⭐ لا يشتمل العنوان إلا على أسماء الشركاء المتضامنين، ومع شريك متضامن واحد تضاف عبارة (وشركاه)\n⭐ إدراج اسم الموصي بطلبه أو بعلمه يجعله مسؤولاً كشريك متضامن تجاه الغير حسن النية","qs":[{"q":"لا يجوز أن يشتمل عنوان شركة التوصية البسيطة إلا على أسماء:","o":["الشركاء المتضامنين","الشركاء الموصين","جميع الشركاء","الشريك صاحب أكبر حصة"],"a":0},{"q":"أدرج اسم شريك موصٍ في عنوان شركة التوصية البسيطة بعلمه، فتعامل الغير مع الشركة بحسن نية اعتماداً على ذلك، فإن الشريك الموصي:","o":["يكون مسؤولاً عن ديون الشركة كشريك متضامن تجاه هذا الغير","تبقى مسؤوليته بمقدار حصته","يفقد صفته كشريك","يكون مسؤولاً تجاه الشركة فقط"],"a":0},{"q":"إذا لم يكن في شركة التوصية البسيطة إلا شريك متضامن واحد، فيجب:","o":["أن تضاف عبارة (وشركاه) إلى اسمه في عنوان الشركة","أن يضاف اسم أحد الشركاء الموصين إلى العنوان","أن تتحول الشركة إلى شركة تضامن","أن يتخذ للشركة اسم تجاري خاص بدلاً من العنوان"],"a":0}]},{"n":"43","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - ليس للشريك الموصي ان يشترك في ادارة شؤون شركة التوصية البسيطة وليس له سلطة الزامها ، انما يجوز له ان يطلع على دفاترها وحساباتها والسجلات الخاصة بالقرارات المتخذة في سياق ادارتها وان يستوضح عن حالتها وأمورها ويتداول والشركاء الاخرين بشأنها .\nب - اذا اشترك الشريك الموصي في ادارة أمورها فيكون مسؤولاً عن جميع الديون والالتزامات التي تحملتها الشركة أثناء اشتراكه في ادارتها كأنه شريك متضامن .","title":"منع الموصي من الإدارة","memo":"⭐ ليس للشريك الموصي الاشتراك في الإدارة ولا سلطة إلزام الشركة، وله الاطلاع على دفاترها وحساباتها وسجلات قراراتها والاستيضاح والتداول\n⭐ إن اشترك في الإدارة يسأل عن الديون التي تحملتها الشركة أثناء اشتراكه كأنه شريك متضامن","qs":[{"q":"اشترك شريك موصٍ في إدارة شركة توصية بسيطة، فإنه يكون مسؤولاً عن:","o":["جميع الديون والالتزامات التي تحملتها الشركة أثناء اشتراكه في إدارتها كأنه شريك متضامن","ديون الشركة بمقدار حصته فقط","جميع ديون الشركة السابقة واللاحقة كشريك متضامن","الأضرار التي لحقت بالشركاء فقط"],"a":0},{"q":"أي مما يلي لا يحق للشريك الموصي في شركة التوصية البسيطة؟","o":["إلزام الشركة","الاطلاع على دفاتر الشركة وحساباتها","الاستيضاح عن حالة الشركة وأمورها","التداول مع الشركاء الآخرين بشأن الشركة"],"a":0}]},{"n":"44","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"للشريك الموصي في شركة التوصية البسيطة التنازل عن حصته بارادته المنفردة الى شخص آخر ودون الحاجة الى اخذ موافقة الشركاء المتضامنين ويصبح هذا الشخص شريكاً موصياً في الشركة الا اذا وافق جميع الشركاء المتضامنون على ان يدخل متضامناً في الشركة .","title":"تنازل الشريك الموصي عن حصته","memo":"⭐ للموصي التنازل عن حصته بإرادته المنفردة دون موافقة الشركاء المتضامنين، ويصبح المتنازل له شريكاً موصياً\n⭐ يدخل المتنازل له شريكاً متضامناً فقط إذا وافق جميع الشركاء المتضامنين","qs":[{"q":"يجوز للشريك الموصي في شركة التوصية البسيطة التنازل عن حصته إلى شخص آخر:","o":["بإرادته المنفردة دون الحاجة إلى موافقة الشركاء المتضامنين","بموافقة جميع الشركاء المتضامنين","بموافقة أغلبية الشركاء","بموافقة المراقب"],"a":0},{"q":"تنازل شريك موصٍ عن حصته لشخص آخر، فإن المتنازل له يدخل الشركة شريكاً متضامناً إذا:","o":["وافق جميع الشركاء المتضامنين على ذلك","وافق أغلبية الشركاء الموصين على ذلك","طلب ذلك المتنازل له","وافق المراقب على ذلك"],"a":0}]},{"n":"45","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز قبول شريك متضامن جديد في شركة التوصية البسيطة بموافقة جميع الشركاء المتضامنين فيها او أكثريتهم اذا أجاز عقد الشركة ذلك ولا تشترط موافقة الشركاء الموصين على ذلك .","title":"ضم شريك متضامن جديد","memo":"⭐ يقبل شريك متضامن جديد بموافقة جميع الشركاء المتضامنين أو أكثريتهم إذا أجاز العقد ذلك\n⭐ لا تشترط موافقة الشركاء الموصين","qs":[{"q":"يجوز قبول شريك متضامن جديد في شركة التوصية البسيطة بموافقة:","o":["جميع الشركاء المتضامنين أو أكثريتهم إذا أجاز عقد الشركة ذلك","جميع الشركاء المتضامنين والموصين","أكثرية الشركاء الموصين","المراقب"],"a":0},{"q":"أراد الشركاء المتضامنون في شركة توصية بسيطة قبول شريك متضامن جديد، فإن موافقة الشركاء الموصين:","o":["لا تشترط","تشترط بالإجماع","تشترط بالأغلبية","تشترط إذا زادت حصصهم على نصف رأس المال"],"a":0}]},{"n":"46","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يفصل الشركاء المتضامنون في شركة التوصية البسيطة في اي خلاف يقع في ادارة الشركة باجماع آرائهم او باتفاق أكثريتهم على ان يكونوا ممن يملكوا اكثر من (%٥٠) من راسمال الشركة ( اذا أجاز عقد الشركة ذلك ) على انه لا يجوز اجراء اي تغيير او تعديل في عقد وبيان الشركة الا بموافقة جميع الشركاء المتضامنين .","title":"الفصل في خلافات إدارة شركة التوصية","memo":"⭐ يفصل الشركاء المتضامنون في خلافات الإدارة بالإجماع أو بأكثرية من يملكون أكثر من (50%) من رأس المال إذا أجاز العقد ذلك\n⭐ أي تغيير أو تعديل في عقد وبيان الشركة يتطلب موافقة جميع الشركاء المتضامنين","qs":[{"q":"يفصل في أي خلاف يقع في إدارة شركة التوصية البسيطة:","o":["الشركاء المتضامنون","الشركاء الموصون","المراقب","المحكمة المختصة"],"a":0},{"q":"إذا أجاز عقد شركة التوصية البسيطة الفصل في خلافات الإدارة بالأكثرية، فيشترط أن يملك الشركاء المتضامنون المتفقون:","o":["أكثر من (50%) من رأس مال الشركة","(75%) من رأس مال الشركة على الأقل","ثلثي رأس مال الشركة","ربع رأس مال الشركة على الأقل"],"a":0},{"q":"لا يجوز إجراء أي تغيير أو تعديل في عقد وبيان شركة التوصية البسيطة إلا بموافقة:","o":["جميع الشركاء المتضامنين","أكثرية الشركاء المتضامنين","جميع الشركاء الموصين","المراقب والوزير"],"a":0}]},{"n":"47","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا تفسخ شركة التوصية البسيطة بافلاس الشريك الموصي او اعساره او وفاته او فقدانه الأهلية او اصابته بعجز دائم .","title":"حالات لا تفسخ بها شركة التوصية","memo":"⭐ لا تفسخ شركة التوصية البسيطة بإفلاس الشريك الموصي أو إعساره أو وفاته أو فقدانه الأهلية أو إصابته بعجز دائم","qs":[{"q":"توفي أحد الشركاء الموصين في شركة توصية بسيطة، فما أثر ذلك على الشركة؟","o":["لا تفسخ الشركة","تفسخ الشركة حكماً","تفسخ الشركة بقرار من المراقب","تتحول الشركة إلى شركة تضامن حكماً"],"a":0},{"q":"لا تفسخ شركة التوصية البسيطة بإفلاس أو إعسار أو وفاة أو فقدان أهلية أو العجز الدائم للشريك:","o":["الموصي","المتضامن المدير","الظاهر","المفوض بالتوقيع"],"a":0}]},{"n":"48","chapter":"الباب الثاني - شركة التوصية البسيطة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تطبق على شركة التوصية البسيطة الأحكام التي تطبق على شركة التضامن المنصوص عليها في هذا القانون وذلك في الحالات والأمور التي لم يرد عليها النص في هذا الباب .","title":"تطبيق أحكام شركة التضامن على التوصية","memo":"⭐ تطبق على شركة التوصية البسيطة أحكام شركة التضامن في الحالات التي لم يرد عليها نص في باب التوصية البسيطة","qs":[{"q":"في الحالات التي لم يرد عليها نص في باب شركة التوصية البسيطة، تطبق عليها الأحكام المتعلقة بـ:","o":["شركة التضامن","الشركة ذات المسؤولية المحدودة","الشركة المساهمة العامة","شركة المحاصة"],"a":0},{"q":"يقتصر تطبيق أحكام شركة التضامن على شركة التوصية البسيطة على:","o":["الحالات والأمور التي لم يرد عليها نص في باب شركة التوصية البسيطة","الأمور المتعلقة بالشركاء الموصين فقط","الحالات التي يوافق عليها المراقب","جميع الأمور بما فيها ما ورد بشأنه نص في باب التوصية"],"a":0}]},{"n":"49","chapter":"الباب الثالث - شركة المحاصة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - شركة المحاصة شركة تجارية تنعقد بين شخصين او أكثر ، يمارس أعمالها شريك ظاهر يتعامل مع الغير بحيث تكون الشركة مقتصرة على العلاقة الخاصة بين الشركاء على انه يجوز اثبات الشركة بين الشركاء بجميع طرق الاثبات .\nب - لا تتمتع شركة المحاصة بالشخصية الاعتبارية ولا تخضع لأحكام واجراءات التسجيل والترخيص .","title":"تعريف شركة المحاصة وخصائصها","memo":"⭐ شركة تجارية بين شخصين أو أكثر يمارس أعمالها شريك ظاهر يتعامل مع الغير وتقتصر على العلاقة الخاصة بين الشركاء\n⭐ يجوز إثباتها بين الشركاء بجميع طرق الإثبات\n⭐ لا تتمتع بالشخصية الاعتبارية ولا تخضع لأحكام وإجراءات التسجيل والترخيص","qs":[{"q":"أقل عدد من الأشخاص تنعقد بينهم شركة المحاصة:","o":["شخصان","شخص واحد","ثلاثة أشخاص","خمسة أشخاص"],"a":0},{"q":"أي مما يلي صحيح بشأن شركة المحاصة؟","o":["لا تتمتع بالشخصية الاعتبارية ولا تخضع لإجراءات التسجيل والترخيص","تتمتع بالشخصية الاعتبارية بعد تسجيلها لدى المراقب","تخضع للتسجيل دون الترخيص","تتمتع بالشخصية الاعتبارية دون حاجة للتسجيل"],"a":0},{"q":"يجوز إثبات شركة المحاصة بين الشركاء:","o":["بجميع طرق الإثبات","بالكتابة الرسمية فقط","بشهادة التسجيل الصادرة عن المراقب","بعقد موثق لدى الكاتب العدل فقط"],"a":0}]},{"n":"50","chapter":"الباب الثالث - شركة المحاصة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يعتبر الشريك غير الظاهر في شركة المحاصة تاجراً الا اذا قام بالعمل التجاري بنفسه .","title":"صفة التاجر للشريك غير الظاهر","memo":"⭐ لا يعتبر الشريك غير الظاهر في شركة المحاصة تاجراً إلا إذا قام بالعمل التجاري بنفسه","qs":[{"q":"متى يعتبر الشريك غير الظاهر في شركة المحاصة تاجراً؟","o":["إذا قام بالعمل التجاري بنفسه","بمجرد انضمامه إلى الشركة","إذا تجاوزت حصته نصف رأس المال","إذا وافق الشريك الظاهر على ذلك"],"a":0}]},{"n":"51","chapter":"الباب الثالث - شركة المحاصة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"ليس للغير حق الرجوع الا على الشريك الذي تعامل معه في شركة المحاصة ، فاذا أقر أحد الشركاء فيها بوجود الشركة أو صدر عنه ما يدل للغير على وجودها بين الشركاء جاز اعتبارها شركة قائمة فعلاً ، وأصبح الشركاء فيها مسؤولين تجاه ذلك الغير بالتضامن.","title":"رجوع الغير على شركاء المحاصة","memo":"⭐ ليس للغير الرجوع إلا على الشريك الذي تعامل معه\n⭐ إذا أقر أحد الشركاء بوجود الشركة أو صدر عنه ما يدل للغير على وجودها جاز اعتبارها شركة قائمة فعلاً ويصبح الشركاء مسؤولين تجاه الغير بالتضامن","qs":[{"q":"الأصل في شركة المحاصة أن الغير ليس له حق الرجوع إلا على:","o":["الشريك الذي تعامل معه","جميع الشركاء بالتضامن","الشريك صاحب الحصة الأكبر","الشركة بموجوداتها"],"a":0},{"q":"حالة عملية: أقر أحد الشركاء في شركة محاصة أمام أحد الموردين بوجود الشركة، فما الأثر؟","o":["يجوز اعتبارها شركة قائمة فعلاً ويصبح الشركاء مسؤولين تجاه ذلك المورد بالتضامن","تبطل الشركة حكماً","يسأل الشريك المقر وحده بمقدار حصته","تكتسب الشركة الشخصية الاعتبارية وتلتزم بالتسجيل"],"a":0}]},{"n":"52","chapter":"الباب الثالث - شركة المحاصة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يحدد عقد شركة المحاصة حقوق الشركاء في الشركة والالتزامات المترتبة عليهم تجاه الشركة وتجاه بعضهم بما في ذلك كيفية توزيع الأرباح والخسائر بينهم .","title":"حقوق والتزامات شركاء المحاصة","memo":"⭐ يحدد عقد شركة المحاصة حقوق الشركاء والتزاماتهم تجاه الشركة وتجاه بعضهم بما في ذلك كيفية توزيع الأرباح والخسائر","qs":[{"q":"تحدد كيفية توزيع الأرباح والخسائر بين الشركاء في شركة المحاصة بموجب:","o":["عقد شركة المحاصة","قرار المراقب","نظام يصدر لهذه الغاية","قرار الوزير"],"a":0}]},{"n":"53","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تتألف الشركة ذات المسؤولية المحدودة من شخصين أو أكثر ، وتعتبر الذمة المالية للشركة مستقلة عن الذمة المالية لكل شريك فيها وتكون الشركة بموجوداتها وأموالها مسؤولة عن الديون والالتزامات المترتبة عليها ولا يكون الشريك مسؤولا عن تلك الديون والالتزامات والخسائر إلا بمقدار حصصه التي يملكها في الشركة .\nب - يجوز للمراقب الموافقة على تسجيل شركة ذات مسؤولية محدودة تتالف من شخص واحد أو أن تصبح مملوكة لشخص واحد .\nج - إذا توفي أي شريك في الشركة ذات المسؤولية المحدودة فتنتقل حصته إلى ورثته ويطبق هذا الحكم على الموصي لهم بأي حصة أو حصص في الشركة .","title":"تأسيس الشركة ذات المسؤولية المحدودة","memo":"⭐ تتألف من شخصين أو أكثر وذمتها المالية مستقلة عن ذمة الشركاء، ولا يسأل الشريك إلا بمقدار حصصه\n⭐ يجوز للمراقب الموافقة على تسجيلها من شخص واحد أو أن تصبح مملوكة لشخص واحد\n⭐ عند وفاة الشريك تنتقل حصته إلى ورثته ويطبق ذلك على الموصى لهم","qs":[{"q":"تتألف الشركة ذات المسؤولية المحدودة كأصل عام من:","o":["شخصين أو أكثر","ثلاثة أشخاص أو أكثر","سبعة أشخاص أو أكثر","شخص واحد فقط"],"a":0},{"q":"الجهة التي يجوز لها الموافقة على تسجيل شركة ذات مسؤولية محدودة تتألف من شخص واحد:","o":["المراقب","الوزير","مجلس الوزراء","المحكمة المختصة"],"a":0},{"q":"حالة عملية: توفي شريك في شركة ذات مسؤولية محدودة، فإن حصته:","o":["تنتقل إلى ورثته","تؤول إلى باقي الشركاء بالتساوي","تباع بالمزاد العلني","تلغى ويخفض رأس المال بمقدارها"],"a":0},{"q":"يكون الشريك في الشركة ذات المسؤولية المحدودة مسؤولاً عن ديون الشركة والتزاماتها:","o":["بمقدار حصصه التي يملكها في الشركة","بأمواله الخاصة بالتضامن مع باقي الشركاء","بضعف قيمة حصصه","بمقدار ما قبضه من أرباح"],"a":0}]},{"n":"54","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٨-٠٧-٢٣"],"source":"أ - يحدد راس مال الشركة ذات المسؤولية المحدودة بالدينار الاردني ، على ان لا يقل راسمال الشركة عن الحد الادنى الذي يحدده النظام الذي يصدر لهذه الغاية والذي يحدد الاحكام والشروط اللازمة لذلك ويقسم راس المال الى حصص متساوية قيمة الحصة الواحدة دينار واحد على الاقل غير قابلة للتجزئة ، على انه اذا تملك الحصة اكثر من شخص واحد لاي سبب وجب على الشركاء فيها اختيار احدهم ليمثلهم لدى الشركة ، فاذا لم يتفق الشركاء فيها او لم يوافقوا على ذلك خلال ثلاثين يوما من تاريخ اشتراكهم في الحصة فيمثلهم الشخص الذي يختاره من بينهم مدير الشركة او هيئة المديرين فيها .\nب - لا يجوز للشركة ذات المسؤولية المحدودة طرح حصصها او زيادة رأسمالها او الاقتراض بطريقة الاكتتاب ولا يحق لها اصدار أسهم او أسناد قرض قابل للتداول .","title":"رأس مال الشركة ذات المسؤولية المحدودة","memo":"⭐ يحدد رأس المال بالدينار الأردني ولا يقل عن الحد الأدنى الذي يحدده النظام، ويقسم إلى حصص متساوية قيمة الحصة دينار واحد على الأقل غير قابلة للتجزئة\n⭐ إذا تملك الحصة أكثر من شخص يختارون من يمثلهم، وإن لم يتفقوا خلال ثلاثين يوماً يختار المدير أو هيئة المديرين ممثلهم\n⭐ لا يجوز لها طرح حصصها أو زيادة رأسمالها أو الاقتراض بطريقة الاكتتاب ولا إصدار أسهم أو أسناد قرض قابلة للتداول","qs":[{"q":"الحد الأدنى لقيمة الحصة الواحدة في الشركة ذات المسؤولية المحدودة:","o":["دينار واحد","عشرة دنانير","مئة دينار","ألف دينار"],"a":0},{"q":"إذا تملك الحصة أكثر من شخص ولم يتفقوا على من يمثلهم خلال المدة القانونية، فيمثلهم من يختاره من بينهم:","o":["مدير الشركة أو هيئة المديرين","المراقب","الهيئة العامة للشركة","المحكمة المختصة"],"a":0},{"q":"المدة الممنوحة للشركاء في الحصة الواحدة لاختيار من يمثلهم لدى الشركة من تاريخ اشتراكهم فيها:","o":["ثلاثون يوماً","خمسة عشر يوماً","ستون يوماً","تسعون يوماً"],"a":0},{"q":"جميع ما يلي محظور على الشركة ذات المسؤولية المحدودة باستثناء:","o":["تقسيم رأس مالها إلى حصص متساوية","طرح حصصها بطريقة الاكتتاب","إصدار أسهم قابلة للتداول","الاقتراض بطريقة الاكتتاب"],"a":0}]},{"n":"55","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"تستمد الشركة ذات المسؤولية المحدودة اسمها من غاياتها ويجب ان تضاف اليها عبارة ( ذات المسؤولية المحدودة ) ويمكن اختصار هذه العبارة بالأحرف ( ذ.م.م ) وان يدرج اسمها هذا ومقدار رأسمالها ورقم تسجيلها في جميع الأوراق والمطبوعات التي تستخدمها في أعمالها وفي العقود التي تبرمها .","title":"اسم الشركة ذات المسؤولية المحدودة","memo":"⭐ تستمد اسمها من غاياتها وتضاف إليه عبارة (ذات المسؤولية المحدودة) ويجوز اختصارها (ذ.م.م)\n⭐ يدرج اسمها ومقدار رأسمالها ورقم تسجيلها في جميع أوراقها ومطبوعاتها وعقودها","qs":[{"q":"تستمد الشركة ذات المسؤولية المحدودة اسمها من:","o":["غاياتها","أسماء الشركاء فيها","اسم مديرها","مكان مركزها الرئيسي"],"a":0},{"q":"جميع ما يلي يجب إدراجه في أوراق ومطبوعات الشركة ذات المسؤولية المحدودة وعقودها باستثناء:","o":["أسماء الشركاء فيها","اسم الشركة","مقدار رأسمالها","رقم تسجيلها"],"a":0}]},{"n":"56","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يحق لشركة التضامن او التوصية البسيطة الاحتفاظ باسمها الأصلي اذا ما رغبت بالتحول الى شركة ذات مسؤولية محدودة .","title":"احتفاظ الشركة المتحولة باسمها","memo":"⭐ يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي إذا رغبت بالتحول إلى شركة ذات مسؤولية محدودة","qs":[{"q":"يحق لشركة التضامن أو التوصية البسيطة الراغبة بالتحول إلى شركة ذات مسؤولية محدودة:","o":["الاحتفاظ باسمها الأصلي","الإعفاء من رسوم التسجيل","الاحتفاظ بمسؤولية الشركاء التضامنية","الإعفاء من وضع نظام للشركة"],"a":0}]},{"n":"57","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يقدم طلب تأسيس الشركة ذات المسؤولية المحدودة الى المراقب مرفقاً به عقد تأسيسها ونظامها على النماذج المعتمدة لهذه الغاية ، وتوقع أمام المراقب او من يفوضه خطياً بذلك او أمام الكاتب العدل او أحد المحامين المجازين .\nب - يجب ان يتضمن عقد تأسيس الشركة ذات المسؤولية المحدودة البيانات التالية :\n١ - اسم الشركة وغاياتها والمركز الرئيسي لها .\n٢ - أسماء الشركاء وجنسية كل منهم وعنوانه المختار للتبليغ .\n٣ - مقدار رأس مال الشركة ، وحصة كل شريك فيه .\n٤ - بيان الحصة او الحصص العينية في رأس المال واسم الشريك الذي قدمها وقيمتها التي قدرت بها .\n٥ - اي بيانات اخرى اضافية يقدمها الشركاء او يطلب المراقب تقديمها تنفيذاً لاحكام القانون .\nج - يجب ان يتضمن نظام الشركة ذات المسؤولية المحدودة ، البيانات المنصوص عليها في الفقرة ( ب ) من هذه المادة بالاضافة الى البيانات التالية :\n١- طريقة ادارة الشركة وعدد أعضاء هيئة المديرين وصلاحيات هذه الهيئة بما في ذلك حدود وسقف الاستدانة ورهن موجودات الشركة وكفالة التزامات الغير بما يحقق مصلحة الشركة وغاياتها .\n٢ - شروط التنازل عن الحصص في الشركة والإجراءات الواجب اتباعها في ذلك والصيغة التي يجب ان يحرر بها التنازل .\n٣ - كيفية توزيع الأرباح والخسائر على الشركاء .\n٤- اجتماعات الهيئة العامة للشركة وهيئة المديرين فيها والنصاب القانوني لاجتماعاتها واتخاذ القرارات فيها والاجراءات الخاصة بكيفية عقد تلك الاجتماعات واجراءات الدعوة لحضورها .\n٥ - قواعد واجراءات تصفية الشركة .\n٦ - اي بيانات أخرى اضافية يقدمها الشركاء او يطلب المراقب تقديمها .","title":"طلب التأسيس وعقد الشركة ونظامها","memo":"⭐ يقدم الطلب إلى المراقب مع عقد التأسيس والنظام على النماذج المعتمدة، ويوقع أمام المراقب أو من يفوضه خطياً أو الكاتب العدل أو أحد المحامين المجازين\n⭐ عقد التأسيس: الاسم والغايات والمركز، الشركاء وجنسياتهم وعناوينهم، رأس المال وحصة كل شريك، الحصص العينية\n⭐ النظام يتضمن بيانات العقد إضافة إلى طريقة الإدارة وسقف الاستدانة وشروط التنازل عن الحصص وتوزيع الأرباح والاجتماعات والنصاب وقواعد التصفية","qs":[{"q":"يقدم طلب تأسيس الشركة ذات المسؤولية المحدودة إلى:","o":["المراقب","الوزير","المحكمة المختصة","غرفة التجارة"],"a":0},{"q":"جميع ما يلي جهات يجوز التوقيع أمامها على عقد تأسيس الشركة ذات المسؤولية المحدودة ونظامها باستثناء:","o":["مدقق حسابات قانوني","المراقب أو من يفوضه خطياً","الكاتب العدل","أحد المحامين المجازين"],"a":0},{"q":"أي مما يلي يرد في نظام الشركة ذات المسؤولية المحدودة ولا يشترط وروده في عقد تأسيسها؟","o":["قواعد وإجراءات تصفية الشركة","اسم الشركة وغاياتها","مقدار رأس مال الشركة وحصة كل شريك","أسماء الشركاء وجنسية كل منهم"],"a":0},{"q":"يتضمن نظام الشركة ذات المسؤولية المحدودة صلاحيات هيئة المديرين بما في ذلك:","o":["حدود وسقف الاستدانة ورهن موجودات الشركة وكفالة التزامات الغير","تعيين مدقق الحسابات وتحديد أتعابه","إصدار أسناد القرض القابلة للتداول","طرح الحصص بطريقة الاكتتاب"],"a":0}]},{"n":"58","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - اذا كان رأسمال الشركة او جزء منه حصصاً عينية فعلى مقدمي هذه الحصص المحافظة على هذه المقدمات وعدم التصرف بها الى حين تسليمها الى الشركة وتسجيلها باسمها ونقل ملكيتها اليها .\nب- اذا لم يلتزم مقدموا الحصص العينية بتسليمها وبنقل ملكيتها ، حسب مقتضى الحال ، الى الشركة خلال مدة ثلاثين يوما من تاريخ تسجيل الشركة ، قابلة للتجديد بموافقة المراقب ، يعتبر كل منهم ملزما حكما بدفع قيمتها نقدا وفق السعر الذي اعتمده المؤسسون في نظام الشركة ويحق للمراقب طلب ما يثبت صحة تقدير قيمة الحصص العينية .\nج- ١- اذا لم يقتنع المراقب بصحة تقدير الحصص العينية المقدمة من الشركاء ، فعلى الوزير بناء على تنسيب المراقب تشكيل لجنة من ذوي الخبرة والاختصاص على نفقة الشركة لتقدير الحصص المراد تقويمها بالنقد على ان يكون احد الشركاء من اعضاء اللجنة ، وتقدم اللجنة تقريرها الى المراقب خلال مدة لا تتجاوز ثلاثين يوما من تاريخ تشكيلها .\n٢- للشركاء الاعتراض لدى الوزير على هذا التقرير خلال عشرة ايام من تاريخ تقديمه الى المراقب وعلى الوزير البت في الاعتراض خلال اسبوعين من تقديمه الى المراقب فاذا قبل الاعتراض يتم رفض تسجيل الشركة الا اذا عاد الشركاء ووافقوا على التقييم ففي هذه الحالة تستكمل اجراءات تسجيلها وفقا لاحكام هذا القانون .\nد - تعتبر حقوق الامتياز وحقوق الاختراع والمعرفة الفنية وغيرها من الحقوق المعنوية من المقدمات العينية .","title":"الحصص العينية في الشركة ذات المسؤولية المحدودة","memo":"⭐ يلتزم مقدمو الحصص العينية بتسليمها ونقل ملكيتها خلال (30) يوماً من تسجيل الشركة قابلة للتجديد بموافقة المراقب، وإلا التزموا بدفع قيمتها نقداً\n⭐ إذا لم يقتنع المراقب بالتقدير يشكل الوزير بتنسيبه لجنة خبراء على نفقة الشركة أحد أعضائها شريك، تقدم تقريرها خلال (30) يوماً\n⭐ الاعتراض لدى الوزير خلال (10) أيام ويبت فيه خلال أسبوعين\n⭐ حقوق الامتياز والاختراع والمعرفة الفنية والحقوق المعنوية تعد مقدمات عينية","qs":[{"q":"مدة التزام مقدمي الحصص العينية بتسليمها ونقل ملكيتها إلى الشركة ذات المسؤولية المحدودة:","o":["ثلاثون يوماً من تاريخ تسجيل الشركة قابلة للتجديد بموافقة المراقب","ستون يوماً من تاريخ تسجيل الشركة","خمسة عشر يوماً من تاريخ تقديم الطلب","سنتان من تاريخ تسجيل الشركة"],"a":0},{"q":"إذا لم يقتنع المراقب بصحة تقدير الحصص العينية، فإن الجهة التي تشكل لجنة التقدير هي:","o":["الوزير بناء على تنسيب المراقب","المراقب منفرداً","الهيئة العامة للشركة","المحكمة المختصة"],"a":0},{"q":"مدة اعتراض الشركاء لدى الوزير على تقرير لجنة تقدير الحصص العينية:","o":["عشرة أيام من تاريخ تقديمه إلى المراقب","ثلاثون يوماً من تاريخ تشكيل اللجنة","أسبوعان من تاريخ تقديمه إلى المراقب","خمسة عشر يوماً من تاريخ تبليغ الشركاء"],"a":0},{"q":"أي مما يلي يعد من المقدمات العينية وفقاً للنص؟","o":["المعرفة الفنية","الحصص النقدية المودعة لدى البنك","أسناد القرض","الأرباح المدورة"],"a":0}]},{"n":"59","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يصدر المراقب قراره بالموافقة على تسجيل الشركة خلال خمسة عشر يوماً من تاريخ تقديم الطلب والتوقيع عليه من قبل الشركاء ، وله رفض الطلب اذا تبين له ان في عقد الشركة او نظامها ما يخالف الأحكام المنصوص عليها في هذا القانون والأنظمة الصادرة بموجبه او يخالف اي تشريع آخر معمول به في المملكة ، ولم يقم الشركاء بإزالة المخالفة خلال المدة التي يحددها المراقب ، وللشركاء الاعتراض على قرار الرفض الى الوزير خلال ثلاثين يوماً من تبليغه اليهم ، واذا قرر الوزير رفض الاعتراض ، فيحق للمعترضين الطعن في قراره لدى المحكمة الإدارية خلال ثلاثين يوماً من تاريخ تبليغهم القرار .\nب-١ - اذا وافق المراقـب على تسجيل الشركة أو تمت هذه الموافقة بقرار من الوزير وفقا لاحكام الفقرة (أ) من هذه المادة يستوفي المراقب رسوم التسجيل ويصدر شهادة بتسجيل الشركة ويتم النشر في الجريدة الرسمية وعلى الموقع الالكتروني الخاص بدائرة مراقبة الشركات.\n٢- على الشركاء تسديد ما لا يقل عن (%٥٠) من رأسمال الشركة خلال (٦٠) يوما من تاريخ تسجيلها وتزويد المراقب بما يفيد الإيداع لدى بنـك فـي المملكـة وبـخـلاف ذلـك علـى المراقـب قيد الشركة في سجل الشركات الموقوفة ويتم شطب تسجيلها وفقاً لأحكـام المـادة (٢٨٥) مـن هـذا القانون وفـي جميـع الاحـوال يجـب تسـديـد بــــاقي رأسمال الشـركة خــلال سـنتين من تاريخ تسجيلها.\n٣ - تسري أحكام البنـدين (١) و(٢) من هذه الفقرة على أي زيـادة تطرأ على رأسمال الشركة.\nج - لا يجوز للبنك الذي تم لديه ايداع أي مبالغ لحساب راسمال الشركة تحت التاسيس ردها الا بعد ابراز شهادة من المراقب تفيد العدول عن تاسيس الشركة ، ويطبق هذا الحكم عند أي زيادة في راسمال الشركة .","title":"تسجيل الشركة وتسديد رأس المال","memo":"⭐ يصدر المراقب قراره خلال (15) يوماً من تقديم الطلب، والاعتراض على الرفض للوزير خلال (30) يوماً، والطعن بقرار الوزير لدى المحكمة الإدارية خلال (30) يوماً\n⭐ يسدد الشركاء ما لا يقل عن (50%) من رأس المال خلال (60) يوماً من التسجيل وإلا تقيد في سجل الشركات الموقوفة، ويسدد الباقي خلال سنتين\n⭐ لا يرد البنك المبالغ المودعة إلا بشهادة من المراقب تفيد العدول عن التأسيس","qs":[{"q":"يصدر المراقب قراره بالموافقة على تسجيل الشركة ذات المسؤولية المحدودة خلال:","o":["خمسة عشر يوماً من تاريخ تقديم الطلب والتوقيع عليه","ثلاثين يوماً من تاريخ تقديم الطلب","ستين يوماً من تاريخ تقديم الطلب","عشرة أيام من تاريخ تقديم الطلب"],"a":0},{"q":"الحد الأدنى من رأس مال الشركة ذات المسؤولية المحدودة الواجب تسديده خلال (60) يوماً من تاريخ تسجيلها:","o":["(50%)","(25%)","(75%)","(100%)"],"a":0},{"q":"حالة عملية: لم يسدد الشركاء النسبة المطلوبة من رأس المال خلال المدة القانونية، فإن على المراقب:","o":["قيد الشركة في سجل الشركات الموقوفة","إحالة الشركة إلى المحكمة لتصفيتها","فرض غرامة على المدير فقط","تحويل الشركة إلى شركة تضامن"],"a":0},{"q":"يطعن الشركاء في قرار الوزير برفض اعتراضهم على رفض تسجيل الشركة لدى:","o":["المحكمة الإدارية خلال ثلاثين يوماً من تبليغهم القرار","محكمة البداية خلال خمسة عشر يوماً","مجلس الوزراء خلال ثلاثين يوماً","محكمة التمييز خلال ستين يوماً"],"a":0}]},{"n":"60","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يتولى ادارة الشركة مدير او هيئة مديرين لا يقل عدد اعضائها عن اثنين ولا يزيد على سبعة سواء كانوا من الشركاء او من غيرهم وذلك وفقا لما ينص عليه النظام الاساسي للشركة لمدة اربع سنوات ويجوز ان ينص النظام على مدة اقل من ذلك وتنتخب هيئة المديرين رئيسا لها ونائبا له والمفوضين بالتوقيع عن الشركة .\nب - يكون لمدير الشركة ذات المسؤولية المحدودة او لهيئة المديرين فيها الصلاحيات الكاملة في ادارة الشركة في الحدود التي يبينها نظامها. وتعتبر الأعمال والتصرفات التي يقوم بها او يمارسها المدير او هيئة المديرين باسم الشركة ملزمة لها في مواجهة الغير الذي يتعامل مع الشركة بحسن نية بغض النظر عن اي قيد يرد في نظام الشركة اوعقد تأسيسها .\nج - يعد الغير الذي يتعامل مع الشركة حسن النية ما لم يثبت غير ذلك على انه لا يلزم ذلك الغير بالتحقق من وجود اي قيد على صلاحيات المدير او هيئة المديرين على سلطتهم في الزام الشركة بموجب عقدها او نظامها .","title":"إدارة الشركة ذات المسؤولية المحدودة","memo":"⭐ يديرها مدير أو هيئة مديرين من (2) إلى (7) أعضاء من الشركاء أو غيرهم لمدة (4) سنوات ويجوز للنظام النص على مدة أقل\n⭐ تنتخب الهيئة رئيساً ونائباً والمفوضين بالتوقيع\n⭐ تصرفات المدير أو الهيئة ملزمة للشركة تجاه الغير حسن النية بغض النظر عن أي قيد، والغير حسن النية ما لم يثبت العكس","qs":[{"q":"عدد أعضاء هيئة المديرين في الشركة ذات المسؤولية المحدودة:","o":["لا يقل عن اثنين ولا يزيد على سبعة","لا يقل عن ثلاثة ولا يزيد على تسعة","لا يقل عن اثنين ولا يزيد على خمسة","لا يقل عن ثلاثة ولا يزيد على سبعة"],"a":0},{"q":"مدة هيئة المديرين في الشركة ذات المسؤولية المحدودة ما لم ينص النظام على مدة أقل:","o":["أربع سنوات","ثلاث سنوات","سنتان","خمس سنوات"],"a":0},{"q":"حالة عملية: أبرم مدير شركة ذات مسؤولية محدودة عقداً مع غير حسن النية متجاوزاً قيداً ورد في نظام الشركة، فإن العقد:","o":["ملزم للشركة في مواجهة الغير","باطل بطلاناً مطلقاً","موقوف على إجازة المراقب","ملزم للمدير شخصياً فقط"],"a":0}]},{"n":"61","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يعتبر مدير الشركة ذات المسؤولية المحدودة ، سواء كان مديراً منفرداً لها او أحد أعضاء هيئة المديرين فيها ، مسؤولاً تجاه الشركة والشركاء فيها والغير ، عن ارتكابه اية مخالفة لأحكام هذا القانون و الأنظمة الصادرة بموجبه ، ولعقد تأسيس الشركة ونظامها والقرارات الصادرة عن هيئاتها العامة او هيئة المديرين .","title":"مسؤولية مدير الشركة ذات المسؤولية المحدودة","memo":"⭐ المدير المنفرد أو عضو هيئة المديرين مسؤول تجاه الشركة والشركاء والغير عن أي مخالفة للقانون والأنظمة وعقد التأسيس والنظام وقرارات الهيئات العامة أو هيئة المديرين","qs":[{"q":"يكون مدير الشركة ذات المسؤولية المحدودة مسؤولاً عن مخالفته لأحكام القانون وعقد الشركة ونظامها تجاه:","o":["الشركة والشركاء فيها والغير","الشركة فقط","الشركاء فقط","المراقب فقط"],"a":0},{"q":"أي مما يلي لا يرد في النص ضمن ما يسأل مدير الشركة ذات المسؤولية المحدودة عن مخالفته؟","o":["تعليمات البنك الذي تتعامل معه الشركة","أحكام قانون الشركات والأنظمة الصادرة بموجبه","عقد تأسيس الشركة ونظامها","القرارات الصادرة عن الهيئة العامة أو هيئة المديرين"],"a":0}]},{"n":"62","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"على مدير الشركة ذات المسؤولية المحدودة او هيئة مديريها اعداد الميزانية السنوية للشركة وحساباتها الختامية بما في ذلك حساب الارباح والخسائر والايضاحات اللازمة وبيان تدفقاتها النقدية مدققة جميعها من مدقق حسابات قانوني وفقا لمعايير المحاسبة والتدقيق الدولية المتعارف عليها والمعتمدة اضافة الى التقرير السنوي عن اعمال الشركة وتقديمها الى الهيئة العامة للشركة في اجتماعها العادي السنوي وتقديم نسخة منها للمراقب مرفقة بها التوصيات المناسبة قبل نهاية الاشهر الثلاثة الاولى من السنة المالية الجديدة .","title":"البيانات المالية للشركة ذات المسؤولية المحدودة","memo":"⭐ يعد المدير أو هيئة المديرين الميزانية والحسابات الختامية وحساب الأرباح والخسائر والإيضاحات وبيان التدفقات النقدية مدققة من مدقق حسابات قانوني وفق معايير المحاسبة والتدقيق الدولية\n⭐ تقدم للهيئة العامة في اجتماعها العادي السنوي ونسخة للمراقب قبل نهاية الأشهر الثلاثة الأولى من السنة المالية الجديدة","qs":[{"q":"يجب تقديم نسخة من الميزانية السنوية والحسابات الختامية للشركة ذات المسؤولية المحدودة إلى المراقب قبل نهاية:","o":["الأشهر الثلاثة الأولى من السنة المالية الجديدة","الأشهر الأربعة الأولى من السنة المالية الجديدة","الأشهر الستة الأولى من السنة المالية الجديدة","الشهر الأول من السنة المالية الجديدة"],"a":0},{"q":"الجهة المسؤولة عن إعداد الميزانية السنوية والحسابات الختامية في الشركة ذات المسؤولية المحدودة:","o":["مدير الشركة أو هيئة مديريها","مدقق الحسابات القانوني","المراقب","الهيئة العامة"],"a":0},{"q":"تعد البيانات المالية للشركة ذات المسؤولية المحدودة مدققة وفقاً لـ:","o":["معايير المحاسبة والتدقيق الدولية المتعارف عليها والمعتمدة","تعليمات يصدرها المدير","قرار الهيئة العامة","نظام الشركة فقط"],"a":0}]},{"n":"63","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يحظر على مدير الشركة ذات المسؤولية المحدودة سواء أكان مديراً منفرداً أو مديراً معيناً من قبل هيئة المديرين كما ويحظر على اي من أعضاء هيئة المديرين فيها تولي وظيفة في شركة اخرى ذات غايات مماثلة او منافسة لأعمال الشركة او ممارسة عمل مماثل لأعمال الشركة سواء لحسابه او لحساب الغير بأجر او بدونه او الاشتراك في ادارة شركة أخرى ذات غايات مماثلة او منافسة للشركة الا بموافقة الهيئة العامة باغلبية لا تقل عن ( %٧٥ ) من الحصص المكونة لرأسمال الشركة .\nب - اذا تخلف أي شخص من الاشخاص المذكورين في الفقرة (أ) من هذه المادة عن الحصول على موافقة الهيئة العامة ، وتم تبليغ المراقب خطيا عن هذه المخالفة من قبل احد الشركاء فعلى المراقب الطلب من الشريك المخالف تصحيح الوضع وازالة المخالفة خلال ثلاثين يوما من تاريخ تبلغه بذلك وبخلاف ذلك يعتبر الشخص فاقدا لعضويته من هيئة المديرين او مركزه في الشركة حكما ويعاقب المخالف بغرامة لا تقل عن الف دينار ولا تزيد على عشرة الاف دينار والزامه بالضرر الذي لحق بالشركة او الشركاء .","title":"حظر المنافسة على مديري الشركة","memo":"⭐ يحظر على المدير وأعضاء هيئة المديرين تولي وظيفة أو ممارسة عمل مماثل أو منافس أو الاشتراك في إدارة شركة منافسة إلا بموافقة الهيئة العامة بأغلبية لا تقل عن (75%) من الحصص\n⭐ عند المخالفة وتبليغ أحد الشركاء للمراقب خطياً يطلب المراقب إزالة المخالفة خلال (30) يوماً وإلا فقد العضوية حكماً\n⭐ الغرامة من (1000) إلى (10000) دينار مع التعويض عن الضرر","qs":[{"q":"يجوز لمدير الشركة ذات المسؤولية المحدودة الاشتراك في إدارة شركة منافسة بموافقة الهيئة العامة بأغلبية لا تقل عن:","o":["(75%) من الحصص المكونة لرأس المال","(50%) من الحصص المكونة لرأس المال","(51%) من الحصص الممثلة في الاجتماع","ثلثي الحصص المكونة لرأس المال"],"a":0},{"q":"مدة إزالة المخالفة الممنوحة لعضو هيئة المديرين الذي مارس عملاً منافساً دون موافقة الهيئة العامة:","o":["ثلاثون يوماً من تاريخ تبلغه","خمسة عشر يوماً من تاريخ تبلغه","ستون يوماً من تاريخ تبلغه","عشرة أيام من تاريخ تبلغه"],"a":0},{"q":"الغرامة المقررة على المخالف لحظر المنافسة في الشركة ذات المسؤولية المحدودة:","o":["لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار","لا تقل عن مئة دينار ولا تزيد على ألف دينار","لا تقل عن خمسمئة دينار ولا تزيد على خمسة آلاف دينار","لا تقل عن عشرة آلاف دينار ولا تزيد على خمسين ألف دينار"],"a":0}]},{"n":"64","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تتألف الهيئة العامة في الشركة ذات المسؤولية المحدودة من جميع الشركاء فيها ، وتعقد اجتماعاً سنوياً واحداً خلال الأشهر الأربعة الأولى من السنة المالية للشركة ، بدعوة من المدير او رئيس هيئة المديرين وفي الموعد والمكان اللذين يحدد لهما .\nب- ١- للهيئة العامة في الشركة ذات المسؤولية المحدودة عقد اجتماع غير عادي اكثر بدعوة من المدير او هيئة المديرين لبحث أي من الامور التي تدخل ضمن اختصاصها وفقا لاحكام هذا القانون في أي من الحالتين التاليتين:\n- بناء على طلب عدد من الشركاء ممن يملكون ربع رأسمال الشركة على الاقل على ان ترسل نسخة منه الى المراقب . - بناء على طلب المراقب اذا قدم اليه طلب بذلك من عدد من الشركاء ممن يملكون (%١٥) من راسمال الشركة على الاقل واقتنع المراقب بالاسباب الواردة في الطلب .\n٢- اذا لم يستجب المدير او هيئة المديرين للطلب خلال اسبوع من تاريخ تقديمه ، يتولى المراقب الدعوة للاجتماع على نفقة الشركة .\nج - لكل شريك في الشركة ذات المسؤولية المحدودة حضور اجتماعات الهيئة العامة العادية وغير العادية للشركة لمناقشة الامور التي تعرض عليها والتصويت على القرارات التي تتخذها وله تفويض احد الشركاء لحضور الاجتماع نيابة عنه بموجب قسيمة التوكيل المعدة من قبل ادارة الشركة او بموجب وكالة عدلية كما يجوز التوكيل او التفويض للغير بذات الطريقة اذا اجاز عقد الشركة ذلك .\nد - تبلغ الدعوة لكل شريك في الشركة ذات المسؤولية المحدودة لحضور اجتماعات الهيئة العامة للشركة سواء كان عاديا او غير عادي اما بتسليم الدعوة باليد مقابل التوقيع بالتسلم او ارسالها اليه بالبريد المسجل ، على ان يتم ارسالها بالبريد قبل خمسة عشر يوما على الاقل من التاريخ المحدد لعقد الاجتماع ، على ان تكون الدعوة مشتملة على جدول الاعمال السنوي ، ومرفقا بها البيانات المشار اليها في المادة (٦٢) من هذا القانون وتعتبر الدعوة مبلغة للشريك خلال مدة لا تزيد على ستة ايام من تاريخ ايداعها في البريد المسجل على عنوانه المسجل لدى الشركة .\nهـ - لا يدعى المراقب لحضور اجتماعات الهيئة العامة في الشركة ذات المسؤولية المحدودة سواء كانت عادية او غير عادية ولكن على مدير الشركة او هيئة المديرين فيها تزويد المراقب بنسخة من محضر الاجتماع موقعة من رئيس الاجتماع ومن كاتب المحضر وذلك خلال عشرة ايام من تاريخ انعقاده وللمراقب حضور الجلسة بناء على طلب المدير او هيئة المديرين او بناءً على طلب خطي من شركاء يحملون ما لا يقل عن ( %١٥ ) من الحصص المكونة لرأسمال الشركة .\nو - اذا لم تتم مراعاة الاصول المبينة في الفقرة (د) من هذه المادة فللمراقب عدم اعتماد محضر الاجتماع والقرارات الصادرة عن الاجتماع الا اذا وافق الشريك او الشركاء غير المبلغين وفق تلك الاصول من غير الحاضرين للاجتماع على اعتبار انفسهم مبلغين دون ان تدخل حصته او حصصهم في النصاب المقرر لصدور القرار .","title":"اجتماعات الهيئة العامة ودعوتها","memo":"⭐ تتألف من جميع الشركاء وتعقد اجتماعاً سنوياً خلال الأشهر الأربعة الأولى من السنة المالية\n⭐ الاجتماع غير العادي بطلب شركاء يملكون ربع رأس المال على الأقل، أو بطلب المراقب إذا طلبه شركاء يملكون (15%)؛ وإن لم يستجب المدير خلال أسبوع يدعو المراقب على نفقة الشركة\n⭐ ترسل الدعوة بالبريد قبل (15) يوماً على الأقل وتعتبر مبلغة خلال (6) أيام من إيداعها\n⭐ لا يدعى المراقب، ويزود بنسخة المحضر خلال (10) أيام، وله الحضور بطلب المدير أو شركاء يحملون (15%)","qs":[{"q":"تعقد الهيئة العامة للشركة ذات المسؤولية المحدودة اجتماعها السنوي العادي خلال:","o":["الأشهر الأربعة الأولى من السنة المالية","الأشهر الثلاثة الأولى من السنة المالية","الأشهر الستة الأولى من السنة المالية","الشهرين الأولين من السنة المالية"],"a":0},{"q":"يجوز عقد اجتماع غير عادي للهيئة العامة للشركة ذات المسؤولية المحدودة بناء على طلب شركاء يملكون من رأس المال على الأقل:","o":["الربع","النصف","الثلث","العشر"],"a":0},{"q":"إذا لم يستجب المدير لطلب عقد الاجتماع غير العادي خلال أسبوع من تقديمه، فإن الدعوة للاجتماع يتولاها:","o":["المراقب على نفقة الشركة","الشركاء الطالبون على نفقتهم","الوزير على نفقة الشركة","المحكمة المختصة"],"a":0},{"q":"يجب على مدير الشركة ذات المسؤولية المحدودة تزويد المراقب بنسخة من محضر اجتماع الهيئة العامة خلال:","o":["عشرة أيام من تاريخ انعقاده","خمسة عشر يوماً من تاريخ انعقاده","ثلاثين يوماً من تاريخ انعقاده","ستة أيام من تاريخ انعقاده"],"a":0}]},{"n":"65","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يكون نصاب الاجتماع العادي للهيئة العامة للشركة ذات المسؤولية المحدودة قانونياً بحضور عدد من الشركاء يمثلون أكثر من نصف رأسمال الشركة أصالة ووكالة واذا لم يتوفر هذا النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع الى موعد آخر يعقد خلال خمسة عشر يوماً من التاريخ المحدد للاجتماع الاول ويعاد تبليغ الشركاء الذين لم يحضروا ويكون النصاب في الاجتماع الثاني قانونياً بالشركاء الذين يحضرونه مهما كان عددهم او النسبة التي يملكونها في رأس المال .\nب - يكون نصاب الاجتماع غير العادي للهيئة العامة للشركة ذات المسؤولية المحدودة قانونياً بحضور عدد من الشركاء يمثلون ( %٧٥ ) من الحصص المكونة لرأسمال الشركة على الأقل أصالة ووكالة ، ما لم ينص نظام الشركة على اغلبية أعلى واذا لم يتوفر النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع الى موعد آخر خلال عشرة ايام من التاريخ المحدد للاجتماع الاول ويعاد تبليغ الشركاء الذين لم يحضروا ويكون النصاب في الاجتماع الثاني قانونياً بحضور ( %٥٠ ) على الاقل من الحصص المكونة لرأسمال الشركة أصالة ووكالة ما لم ينص نظام الشركة على أغلبية اعلى ، واذا لم يتوفر هذا النصاب يلغى الاجتماع مهماكانت اسباب الدعوة اليه .","title":"نصاب اجتماعات الهيئة العامة","memo":"⭐ العادي: أكثر من نصف رأس المال أصالة ووكالة، وإلا يؤجل خلال (15) يوماً ويكون الثاني قانونياً بمن حضر\n⭐ غير العادي: (75%) من الحصص على الأقل، وإلا يؤجل خلال (10) أيام ويكون نصاب الثاني (50%) على الأقل، وإلا يلغى الاجتماع\n⭐ الانتظار ساعة من الوقت المحدد قبل التأجيل","qs":[{"q":"نصاب الاجتماع العادي الأول للهيئة العامة للشركة ذات المسؤولية المحدودة:","o":["حضور شركاء يمثلون أكثر من نصف رأس المال أصالة ووكالة","حضور شركاء يمثلون (75%) من رأس المال","حضور شركاء يمثلون ثلث رأس المال","حضور جميع الشركاء"],"a":0},{"q":"نصاب الاجتماع غير العادي الثاني (المؤجل) للهيئة العامة للشركة ذات المسؤولية المحدودة ما لم ينص النظام على أغلبية أعلى:","o":["(50%) على الأقل من الحصص المكونة لرأس المال","(75%) من الحصص المكونة لرأس المال","الشركاء الحاضرون مهما كان عددهم","(40%) من الحصص المكونة لرأس المال"],"a":0},{"q":"حالة عملية: لم يتوفر النصاب في الاجتماع العادي الأول للهيئة العامة لشركة ذات مسؤولية محدودة، فيؤجل إلى موعد يعقد خلال:","o":["خمسة عشر يوماً، ويكون النصاب بالشركاء الحاضرين مهما كان عددهم","عشرة أيام، ويكون النصاب (50%) من الحصص","ثلاثين يوماً، ويكون النصاب أكثر من نصف رأس المال","سبعة أيام، ويكون النصاب ثلث رأس المال"],"a":0}]},{"n":"66","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٢١-١٠-١٦"],"source":"أ - يشتمل جدول اعمال الهيئة العامة العادي للشركة ذات المسؤولية المحدودة في اجتماعها السنوي العادي على الأمور التالية :\n١ - مناقشة تقرير المدير او هيئة المديرين عن اعمال الشركة وأوجه نشاطها ومركزها المالي خلال السنة المالية السابقة والخطة المستقبلية للشركة .\n٢ - مناقشة ميزانية الشركة وحساب أرباحها وخسائرها وتدفقاتها النقدية ، والمصادقة عليها بعد تقديم مدققي الحسابات لتقريرهم ومناقشته .\n٣ - انتخاب مدير الشركة او هيئة المديرين لها حسب مقتضى الحال ووفقاً لاحكام هذا القانون .\n٤ - انتخاب مدقق حسابات الشركة وتحديد اتعابه .\n٥ - اي أمور أخرى تتعلق بالشركة تعرض على الهيئة العامة من قبل مدير الشركة او هيئة المديرين فيها او يقدمها اي شريك وتوافق الهيئة العامة على مناقشتها، على ان لا يكون اي من تلك الأمور مما لا يجوز عرضه على الهيئة العامة الا في اجتماع غير عادي لها بمقتضى هذا القانون .\nب - تتخذ الهيئة العامة في الشركة ذات المسؤولية المحدودة قراراتها في اي من الأمور المنصوص عليها في الفقرة ( أ ) من هذه المادة بأكثرية الحصص من رأس المال الممثلة في الاجتماع ويكون لكل حصة صوت واحد .\nج- لا تسري أحكام التصويت النسبي المنصوص عليه في الفقرة (أ) من المادة (١٣٢) من هذا القانون على انتخاب هيئة مديري الشركة ذات المسؤولية المحدودة.","title":"جدول أعمال الاجتماع العادي","memo":"⭐ يشمل: تقرير المدير، الميزانية وحساب الأرباح والخسائر والتدفقات النقدية بعد تقرير المدققين، انتخاب المدير أو هيئة المديرين، انتخاب المدقق وتحديد أتعابه، وأي أمور أخرى تقبل الهيئة مناقشتها\n⭐ القرارات بأكثرية الحصص الممثلة في الاجتماع ولكل حصة صوت واحد\n⭐ لا يسري التصويت النسبي (م132/أ) على انتخاب هيئة المديرين","qs":[{"q":"تتخذ الهيئة العامة العادية للشركة ذات المسؤولية المحدودة قراراتها في أمور جدول أعمالها:","o":["بأكثرية الحصص من رأس المال الممثلة في الاجتماع","بأغلبية (75%) من الحصص المكونة لرأس المال","بإجماع الشركاء الحاضرين","بأكثرية عدد الشركاء الحاضرين"],"a":0},{"q":"أي مما يلي يدخل ضمن جدول أعمال الاجتماع العادي السنوي للهيئة العامة للشركة ذات المسؤولية المحدودة؟","o":["انتخاب مدقق حسابات الشركة وتحديد أتعابه","فسخ الشركة وتصفيتها","تخفيض رأس مال الشركة","دمج الشركة"],"a":0},{"q":"لا تسري أحكام التصويت النسبي على:","o":["انتخاب هيئة مديري الشركة ذات المسؤولية المحدودة","انتخاب مدقق حسابات الشركة ذات المسؤولية المحدودة","المصادقة على ميزانية الشركة","مناقشة تقرير المدير"],"a":0}]},{"n":"67","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تدعى الهيئة العامة في الشركة ذات المسؤولية المحدودة الى اجتماع غير عادي ولا يجوز مناقشة أي من الامور التالية اذا لم تكن مدرجة في الدعوة الى الاجتماع :\n١. النص المعدل لعقد تأسيس الشركة او نظامها .\n٢. تخفيض او زيادة رأسمال الشركة وتحديد مقدار علاوة الاصدار او خصم الاصدار ، على ان تراعى في تخفيض راس المال أحكام المادة (٦٨) من هذا القانون وعلى ان يتم تحديد طريقة زيادة رأس المال .\n٣. دمج الشركة واندماجها بأي من طرق الاندماج الواردة في هذا القانون .\n٤. فسخ الشركة وتصفيتها .\n٥. اقالة مدير الشركة او هيئة المديرين فيها او أي من اعضائها .\n٦. بيع الشركة او بيع كامل موجوداتها او تملك شركة اخرى او شراء موجوداتها كليا او جزئيا .\n٧. كفالة التزامات الغير اذا اقتضت مصلحة الشركة ذلك .\n٨. أي امر يدخل ضمن اختصاص الهيئة العامة غير العادية نص عليه هذا القانون او نظام الشركة الاساسي .\nب - على الرغم مما هو وارد في المادتين ( ٦٨ ) و ( ٧٥ ) من هذا القانون ، واذا كان الهدف اعادة هيكلة رأس المال ، يجوز للشركة تخفيض رأسمالها واعادة زيادته في نفس اجتماع الهيئة العامة غير العادية المدعوة وفقاً لأحكام القانون لهذا الغرض ، وعلى ان تتضمن الدعوة المبررات والجدوى التي يهدف اليها هذا الاجراء ، وان يتم نشر اعادة هيكلة رأس المال في صحيفتين محليتين ولمرة واحدة على الاقل ،\nج - للهيئة العامة للشركاء في الشركة ذات المسؤولية المحدودة ان تناقش في اجتماعها غير العادي اياً من الامور المنصوص عليها في المادة ( ٦٦ ) من هذا القانون على ان تدرج في الدعوة الى الاجتماع وتتخذ قراراتها فيها باكثرية الحصص من رأس المال الممثلة في الاجتماع .\nد - تتخذ الهيئة العامة في الشركة ذات المسؤولية المحدودة قراراتها في اي من الامور المنصوص عليها في الفقرة ( أ ) من هذه المادة باكثرية لا تقل عن (%٧٥) من الحصص المكونة لرأس المال الممثلة في الاجتماع ، ما لم ينص نظام الشركة على أغلبية أعلى ، وتخضع القرارات التي تتخذها الهيئة العامة في الامور المنصوص عليها في البنود ( ١ ) ، ( ٢ ) ، ( ٣ ) ، ( ٤ ) ، ( ٦ ) من الفقرة ( أ ) ، والفقرة ( ب ) من هذه المادة لأحكام الموافقة والتسجيل والنشر المنصوص عليها في هذا القانون .\nهـ - اذا لم تتمكن الهيئة العامة في اجتماعها العادي او غير العادي من اتخاذ قرار بسبب تساوي الاصوات في اجتماعين متتالين فيمنحها المراقب مدة لا تزيد على ثلاثين يوما لاتخاذ القرار المناسب وفي حالة عدم صدور هذا القرار للمراقب حق احالتها الى المحكمة لتقرير تصفيتها .","title":"الاجتماع غير العادي للهيئة العامة","memo":"⭐ من أموره: تعديل العقد أو النظام، تخفيض أو زيادة رأس المال، الدمج، الفسخ والتصفية، إقالة المدير، بيع الشركة أو موجوداتها، كفالة التزامات الغير\n⭐ القرارات بأكثرية لا تقل عن (75%) من الحصص الممثلة في الاجتماع ما لم ينص النظام على أعلى\n⭐ إعادة هيكلة رأس المال (تخفيض وزيادة في نفس الاجتماع) مع النشر في صحيفتين محليتين مرة على الأقل\n⭐ تساوي الأصوات في اجتماعين متتاليين: يمنح المراقب مدة لا تزيد على (30) يوماً ثم له الإحالة للمحكمة للتصفية","qs":[{"q":"تتخذ الهيئة العامة غير العادية للشركة ذات المسؤولية المحدودة قراراتها في الأمور المخصصة لها بأكثرية لا تقل عن:","o":["(75%) من الحصص الممثلة في الاجتماع","(50%) من الحصص الممثلة في الاجتماع","ثلثي الحصص المكونة لرأس المال","(51%) من الحصص المكونة لرأس المال"],"a":0},{"q":"أي مما يلي من الأمور التي تختص بها الهيئة العامة غير العادية للشركة ذات المسؤولية المحدودة؟","o":["إقالة مدير الشركة أو هيئة المديرين","انتخاب مدقق الحسابات وتحديد أتعابه","المصادقة على الميزانية السنوية","مناقشة تقرير المدير عن أعمال الشركة"],"a":0},{"q":"إذا كان الهدف إعادة هيكلة رأس المال، فيجوز تخفيض رأس المال وإعادة زيادته في نفس الاجتماع، على أن يتم نشر ذلك في:","o":["صحيفتين محليتين ولمرة واحدة على الأقل","صحيفة يومية واحدة ثلاث مرات متتالية","الجريدة الرسمية فقط","الموقع الإلكتروني للشركة فقط"],"a":0},{"q":"إذا تعذر على الهيئة العامة اتخاذ قرار بسبب تساوي الأصوات في اجتماعين متتاليين، يمنحها المراقب مدة لا تزيد على:","o":["ثلاثين يوماً","خمسة عشر يوماً","ستين يوماً","عشرة أيام"],"a":0}]},{"n":"68","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - للشركة ذات المسؤولية المحدودة ان تخفض رأسمالها اذا زاد على حاجتها او اذا لحقت بها خسائر تزيد على نصف رأسمالها على ان تراعي في هذه الحالة احكام المادة ( ٧٥ ) من هذا القانون .\nب - على المراقب ان ينشر اعلاناً على نفقة الشركة ذات المسؤولية المحدودة في صحيفة يومية واحدة على الأقل ثلاث مرات متتالية يتضمن قرار الهيئة العامة للشركة بتخفيض رأسمالها ويحق لكل من دائنيها الاعتراض خطياً على التخفيض لدى المراقب خلال خمسةعشر يوماً من تاريخ نشر آخر اعلان لقرار التخفيض وللدائن حق الطعن في قرارات التخفيض لدى المحكمة اذا لم يتمكن المراقب من تسوية اعتراضه خلال ثلاثين يوماً من تاريخ تقديمه اليه على ان لا يوقف هذا الطعن اجراءات التخفيض الا اذا قررت المحكمة ذلك .","title":"تخفيض رأس مال الشركة ذات المسؤولية المحدودة","memo":"⭐ يجوز التخفيض إذا زاد رأس المال على حاجتها أو لحقت بها خسائر تزيد على نصف رأسمالها\n⭐ ينشر المراقب إعلاناً على نفقة الشركة في صحيفة يومية واحدة على الأقل ثلاث مرات متتالية\n⭐ اعتراض الدائنين لدى المراقب خلال (15) يوماً من آخر إعلان، والطعن لدى المحكمة إذا لم يسوّ خلال (30) يوماً، ولا يوقف الطعن التخفيض إلا بقرار المحكمة","qs":[{"q":"يجوز للشركة ذات المسؤولية المحدودة تخفيض رأسمالها إذا لحقت بها خسائر تزيد على:","o":["نصف رأسمالها","ربع رأسمالها","ثلاثة أرباع رأسمالها","ثلث رأسمالها"],"a":0},{"q":"ينشر إعلان قرار تخفيض رأس مال الشركة ذات المسؤولية المحدودة:","o":["في صحيفة يومية واحدة على الأقل ثلاث مرات متتالية","في صحيفتين محليتين لمرة واحدة","في الجريدة الرسمية مرة واحدة","في صحيفة يومية مرتين متتاليتين"],"a":0},{"q":"مدة اعتراض الدائن خطياً على قرار التخفيض لدى المراقب:","o":["خمسة عشر يوماً من تاريخ نشر آخر إعلان","ثلاثون يوماً من تاريخ نشر أول إعلان","عشرة أيام من تاريخ صدور القرار","ستون يوماً من تاريخ نشر آخر إعلان"],"a":0},{"q":"حالة عملية: طعن أحد الدائنين في قرار التخفيض لدى المحكمة، فإن إجراءات التخفيض:","o":["لا تتوقف إلا إذا قررت المحكمة ذلك","تتوقف حكماً حتى صدور الحكم","تلغى حكماً","تتوقف بقرار من المراقب"],"a":0}]},{"n":"69","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تعفى الشركة ذات المسؤولية المحدودة من نشر ميزانيتها السنوية وحساب ارباحها وخسائرها والموجز من تقرير مديرها او هيئة المديرين فيها في الصحف المحلية .","title":"الإعفاء من نشر الميزانية","memo":"⭐ تعفى الشركة ذات المسؤولية المحدودة من نشر ميزانيتها السنوية وحساب أرباحها وخسائرها وموجز تقرير مديرها في الصحف المحلية","qs":[{"q":"تعفى الشركة ذات المسؤولية المحدودة من:","o":["نشر ميزانيتها السنوية وحساب أرباحها وخسائرها في الصحف المحلية","تدقيق حساباتها من مدقق قانوني","تقديم نسخة من ميزانيتها إلى المراقب","عقد اجتماع سنوي لهيئتها العامة"],"a":0}]},{"n":"70","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠١٧-١٠-١٧"],"source":"أ - على الشركة ذات المسؤولية المحدودة ان تقتطع ( %١٠ ) من ارباحها السنوية الصافية لحساب الاحتياطي الاجباري ، وان تستمر على هذا الاقتطاع لكل سنة على ان لا يتجاوز مجموع ما اقتطع لهذا الاحتياطي رأس مال الشركة .\nب - للهيئة العامة في الشركة ذات المسؤولية المحدودة ان تقرر اقتطاع نسبة لا تزيد على ( %٢٠ ) من الارباح السنوية الصافية للشركة لحساب الاحتياطي الاختياري ، وللهيئة العامة ان تقرر استخدام هذا الاحتياطي لاغراض الشركة او توزيعه على الشركاء كأرباح اذا لم يستخدم في تلك الاغراض .\nج- للهيئة العامة وبعد استنفاد الاحتياطيات الأخرى ان تقرر في اجتماع غير عادي إطفاء خسائرها من المبالغ المتجمعة في حساب الاحتياطي الإجباري على ان يعاد بناؤه وفقاً لأحكام الفقرة (أ) من هذه المادة .","title":"احتياطيات الشركة ذات المسؤولية المحدودة","memo":"⭐ الاحتياطي الإجباري: (10%) من الأرباح السنوية الصافية حتى يبلغ رأس المال\n⭐ الاحتياطي الاختياري: نسبة لا تزيد على (20%) بقرار الهيئة العامة، ويجوز استخدامه لأغراض الشركة أو توزيعه أرباحاً\n⭐ يجوز إطفاء الخسائر من الاحتياطي الإجباري في اجتماع غير عادي بعد استنفاد الاحتياطيات الأخرى على أن يعاد بناؤه","qs":[{"q":"نسبة ما تقتطعه الشركة ذات المسؤولية المحدودة من أرباحها السنوية الصافية لحساب الاحتياطي الإجباري:","o":["(10%)","(20%)","(5%)","(25%)"],"a":0},{"q":"يتوقف اقتطاع الاحتياطي الإجباري في الشركة ذات المسؤولية المحدودة عندما يبلغ مجموعه:","o":["رأس مال الشركة","نصف رأس مال الشركة","ربع رأس مال الشركة","ضعف رأس مال الشركة"],"a":0},{"q":"الحد الأعلى لنسبة الاحتياطي الاختياري التي يجوز للهيئة العامة اقتطاعها من الأرباح السنوية الصافية:","o":["(20%)","(10%)","(15%)","(25%)"],"a":0},{"q":"يجوز للهيئة العامة إطفاء الخسائر من الاحتياطي الإجباري بشرط:","o":["استنفاد الاحتياطيات الأخرى واتخاذ القرار في اجتماع غير عادي وإعادة بنائه","موافقة الوزير المسبقة","أن تقل الخسائر عن ربع رأس المال","اتخاذ القرار في الاجتماع العادي السنوي"],"a":0}]},{"n":"71","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تحتفظ الشركة ذات المسؤولية المحدودة في المركز الرئيسي لها بسجل خاص للشركاء تدون فيه البيانات التالية عنهم ، ويكون المدير او هيئة المديرين في الشركة مسؤولين عنه وعن صحة البيانات المدرجة فيه :\n١ - اسم الشريك ولقبه اذا كان له لقب وجنسيته ومركز اقامته وعنوانه على وجه التحديد .\n٢ - عدد الحصص التي يملكها الشريك وقيمتها .\n٣ - التغير الذي يطرأ على حصة او حصص الشريك ، وتفاصيله ، وتاريخ وقوعه .\n٤ - ما يقع على حصة او حصص الشريك من حجز ورهن واي قيود اخرى والتفاصيل المتعلقة بها .\n٥ - اي بيانات اخرى يقرر مدير الشركة او هيئة المديرين فيها تدوينها في السجل .\nويحق لكل شريك في الشركة الاطلاع على هذا السجل بنفسه او بواسطة من يفوضه خطياً بذلك .\nب - على مدير الشركة ذات المسؤولية المحدودة او رئيس هيئة المديرين فيها تزويد المراقب سنوياً بالبيانات المدونة في السجل الخاص بالشركاء في الشركة المنصوص عليها في الفقرة ( أ ) من هذه المادة ، وذلك خلال الشهر الاول من انتهاء السنة المالية للشركة ، وبكل تعديل او تغيير يطرأ على تلك البيانات خلال مدة لا تزيد على ثلاثين يوماً من تاريخ وقوع التعديل او التغيير .","title":"سجل الشركاء","memo":"⭐ يحفظ السجل في المركز الرئيسي ويكون المدير أو هيئة المديرين مسؤولين عنه، ولكل شريك الاطلاع عليه بنفسه أو بمن يفوضه خطياً\n⭐ يزود المراقب ببياناته سنوياً خلال الشهر الأول من انتهاء السنة المالية، وبأي تعديل خلال مدة لا تزيد على (30) يوماً من وقوعه","qs":[{"q":"يتولى المسؤولية عن سجل الشركاء في الشركة ذات المسؤولية المحدودة وصحة بياناته:","o":["المدير أو هيئة المديرين","المراقب","مدقق حسابات الشركة","الهيئة العامة"],"a":0},{"q":"يزود المراقب سنوياً ببيانات سجل الشركاء في الشركة ذات المسؤولية المحدودة خلال:","o":["الشهر الأول من انتهاء السنة المالية للشركة","الأشهر الثلاثة الأولى من السنة المالية","الأشهر الأربعة الأولى من السنة المالية","عشرة أيام من انتهاء السنة المالية"],"a":0},{"q":"حالة عملية: طرأ تغيير على حصص أحد الشركاء، فيجب تزويد المراقب بهذا التغيير خلال مدة لا تزيد على:","o":["ثلاثين يوماً من تاريخ وقوعه","خمسة عشر يوماً من تاريخ وقوعه","ستين يوماً من تاريخ وقوعه","أسبوع من تاريخ وقوعه"],"a":0}]},{"n":"72","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - للشريك في الشركة ذات المسؤولية المحدودة ان يتنازل عن حصصه في الشركة الى أي من الشركاء او لغيرهم ، بموجب سند تحويل وفقا للصيغة التي يعتمدها المراقب ويتم التوقيع على هذا السند وفقا للاجراءات المتبعة في تسجيل الشركة بمقتضى احكام هذا القانون .\nب- وفي جميع الاحوال ، يتم توثيق سند التنازل لدى المراقب والاعلان عنه واستيفاء الرسوم المقررة لذلك ، ولا يحتج بهذا التنازل في مواجهة الشركة او الشركاء او الغير الا من تاريخ توثيقه لدى المراقب .\nج- يجوز للشريك التنازل عن حصصه في الشركة بغير البيع الى الزوجة او لاحد الاقارب حتى الدرجة الثالثة او الوقف واعلام المدير او هيئة المديرين بهذا التنازل ما لم ينص النظام الاساسي للشركة على غير ذلك .","title":"التنازل عن الحصص","memo":"⭐ يتنازل الشريك عن حصصه لأي من الشركاء أو لغيرهم بسند تحويل وفق صيغة يعتمدها المراقب\n⭐ يوثق السند لدى المراقب ولا يحتج بالتنازل في مواجهة الشركة أو الشركاء أو الغير إلا من تاريخ توثيقه\n⭐ يجوز التنازل بغير البيع للزوجة أو الأقارب حتى الدرجة الثالثة أو الوقف ما لم ينص النظام على غير ذلك","qs":[{"q":"لا يحتج بتنازل الشريك عن حصصه في الشركة ذات المسؤولية المحدودة في مواجهة الشركة والشركاء والغير إلا من تاريخ:","o":["توثيقه لدى المراقب","توقيع سند التحويل بين الطرفين","إعلام المدير به","موافقة الهيئة العامة عليه"],"a":0},{"q":"يجوز للشريك التنازل عن حصصه بغير البيع إلى أقاربه حتى الدرجة:","o":["الثالثة","الثانية","الرابعة","الأولى"],"a":0},{"q":"يتم التنازل عن الحصص بموجب سند تحويل وفقاً للصيغة التي يعتمدها:","o":["المراقب","الوزير","مدير الشركة","الكاتب العدل"],"a":0}]},{"n":"73","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - اذا رغب احد الشركاء في الشركة في بيع حصصه او جزء منها للغير فعليه تقديم طلب بذلك الى مدير الشركة او هيئة مديريها ، حسب مقتضى الحال ، ونسخ منه الى الشركاء والى المراقب يتضمن السعر الذي يطلبه وعدد الحصص التي يرغب في بيعها وعلى المدير او رئيس هيئة المديرين تبليغ باقي الشركاء بشروط التنازل اما باليد مقابل التوقيع او بالبريد المسجل وذلك خلال اسبوع من تاريخ تقديم الطلب ويكون للشركاء الاولوية بالشراء بالسعر المعروض ، وعلى المدير او رئيس هيئة المديرين تبليغ المراقب خطيا بانه قد قام بتبليغ الشركاء وذلك تحت طائلة المسؤولية بالتعويض عن الضرر الذي يلحق بالشريك المتضرر .\nب - اذا تقدم اكثر من شريك لشراء الحصة او الحصص المراد التنازل عنها بالسعر المعروض ، تقسم الحصص بين الراغبين من الشركاء بالشراء كل بنسبة حصته في رأس مال الشركة ، اما في حالة الاختلاف على السعر فعندها يعين المراقب مدقق حسابات قانوني على على نفقة البائع والمشتري من الشركاء لتحديد السعر ويعتبر تقديره نهائياً وتقسم الحصص بين الشركاء الراغبين بالشراء واذا لم يلتزم الشريك باتمام عملية البيع او الشراء بعد صدور التقرير فانه يكون مسؤولا عن تلك النفقات تجاه الشركة .\nج - اذا انقضت ثلاثون يوماً من تاريخ اخطار الشركاء بشروط البيع دون ان يبدي أحد منهم رغبته في الشراء سواء بالسعر المعروض او بالسعر المقدر من مدقق الحسابات فيكون للشريك الراغب بالبيع الحق في بيع حصته للغير بالسعر المعروض او بالسعر المقدر كحد ادنى .\nد - اذا لم يبد اي من الشركاء او الغير رغبته في شراء الحصة او الحصص المراد بيعها خلال ثلاثين يوماً من انتهاء المدة المبينة في الفقرة ( ج ) اعلاه، بحيث اصبح بيع هذه الحصة او الحصص متعسراً ، فعندها يجوز للراغب بالبيع الطلب من المراقب بيع الحصص بالمزاد العلني ويصدر الوزير بناء على تنسيب المراقب التعليمات اللازمة لتنفيذ عملية البيع بالمزاد العلني .","title":"بيع الحصص وحق الأولوية","memo":"⭐ يقدم الشريك الراغب بالبيع طلباً للمدير ونسخاً للشركاء والمراقب، ويبلغ المدير الشركاء خلال أسبوع، وللشركاء الأولوية بالسعر المعروض\n⭐ تعدد الراغبين: تقسم بنسبة حصصهم؛ الخلاف على السعر: يعين المراقب مدقق حسابات على نفقة البائع والمشتري وتقديره نهائي\n⭐ بعد (30) يوماً دون رغبة الشركاء يبيع للغير بالسعر المعروض أو المقدر كحد أدنى، وبعد (30) يوماً أخرى يجوز طلب البيع بالمزاد العلني","qs":[{"q":"على مدير الشركة تبليغ باقي الشركاء بشروط بيع الحصص خلال:","o":["أسبوع من تاريخ تقديم الطلب","ثلاثين يوماً من تاريخ تقديم الطلب","خمسة عشر يوماً من تاريخ تقديم الطلب","عشرة أيام من تاريخ تقديم الطلب"],"a":0},{"q":"إذا تقدم أكثر من شريك لشراء الحصص المعروضة بالسعر المعروض، فإنها تقسم بينهم:","o":["كل بنسبة حصته في رأس مال الشركة","بالتساوي بينهم","لمن تقدم أولاً","بالقرعة"],"a":0},{"q":"في حال الاختلاف على سعر الحصص المعروضة للبيع، يعين المراقب لتحديد السعر:","o":["مدقق حسابات قانونياً على نفقة البائع والمشتري من الشركاء","لجنة خبراء على نفقة الشركة","خبيراً على نفقة الخزينة","مدقق حسابات الشركة على نفقة الشركة"],"a":0},{"q":"حالة عملية: انقضت ثلاثون يوماً من إخطار الشركاء بشروط البيع دون أن يبدي أحد رغبته بالشراء، فإن للشريك الراغب بالبيع:","o":["بيع حصته للغير بالسعر المعروض أو المقدر كحد أدنى","بيع حصته للغير بأي سعر","طلب تصفية الشركة","إلزام الشركة بشراء حصته"],"a":0}]},{"n":"74","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - اذا صدر حكم قضائي بالتنفيذ على حصة او حصص أحد الشركاء المدينين فتعطى الاولوية في شراء تلك الحصة او الحصص لباقي الشركاء في الشركة ، واذا لم يتقدم احد منهم لشرائها او تعذر الاتفاق على السعر خلال مدة ثلاثين يوماً من تاريخ صدور الحكم القطعي به ، فتعرض تلك الحصص للبيع بالمزاد العلني ، ولكل شريك في الشركة الدخول باسمه في المزاد على قدم المساواة مع الغير وشراء تلك الحصة او الحصص لنفسه .\nب - يصدر المراقب التعليمات اللازمة لتنفيذ عمليات البيع بالمزاد العلني لاغراض هذه المادة .","title":"التنفيذ القضائي على حصة الشريك","memo":"⭐ عند صدور حكم بالتنفيذ على حصص شريك مدين تعطى الأولوية لباقي الشركاء\n⭐ إذا لم يتقدم أحد أو تعذر الاتفاق على السعر خلال (30) يوماً من الحكم القطعي تباع بالمزاد العلني، ولكل شريك الدخول فيه على قدم المساواة مع الغير\n⭐ يصدر المراقب تعليمات البيع بالمزاد","qs":[{"q":"إذا صدر حكم قضائي بالتنفيذ على حصص أحد الشركاء المدينين، فتعطى الأولوية في شرائها لـ:","o":["باقي الشركاء في الشركة","الدائن المنفذ","الشركة نفسها","المراقب"],"a":0},{"q":"إذا تعذر الاتفاق على السعر خلال ثلاثين يوماً من تاريخ صدور الحكم القطعي، فإن الحصص:","o":["تعرض للبيع بالمزاد العلني","تؤول إلى الشركة","يخفض بها رأس المال","تنتقل إلى الدائن مباشرة"],"a":0},{"q":"الجهة التي تصدر التعليمات اللازمة لتنفيذ البيع بالمزاد العلني للحصص المنفذ عليها:","o":["المراقب","الوزير","المحكمة","هيئة المديرين"],"a":0}]},{"n":"75","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . اذا زادت خسائر الشركة ذات المسؤولية المحدودة على نصف راسمالها فيترتب على مديرها او هيئة المديرين فيها دعوة الهيئة العامة للشركة الى اجتماع غير عادي لتصدر قرارها اما بتصفية الشركة او باستمرار قيامها بما يحقق تصحيح اوضاعها ، واذا لم تتمكن الهيئة العامة من اتخاذ قرار بهذا الشان خلال اجتماعين متتالين فيمنح المراقب الشركة مدة لا تزيد على شهر لاتخاذ القرار واذا لم تتمكن من ذلك فتتم احالة الشركة للمحكمة لغايات تصفيتها تصفية اجبارية وفقا لاحكام القانون .\nب. اذا بلغت خسائر الشركة ثلاثة ارباع قيمة راسمالها فيجب تصفيتها الا اذا قررت الهيئة العامة في اجتماع غير عادي زيادة راسمالها لمعالجة وضع الخسائر او اطفائها بما يتفق مع معايير المحاسبة والتدقيق الدولية المعتمدة على ان لا يزيد مجمل الخسائر المتبقية على نصف راسمال الشركة في كلتا الحالتين .","title":"خسائر الشركة ذات المسؤولية المحدودة","memo":"⭐ إذا زادت الخسائر على نصف رأس المال يدعو المدير الهيئة العامة لاجتماع غير عادي لتقرر التصفية أو الاستمرار، وإن لم تقرر خلال اجتماعين متتاليين يمنح المراقب مدة لا تزيد على شهر ثم تحال للمحكمة للتصفية الإجبارية\n⭐ إذا بلغت الخسائر ثلاثة أرباع رأس المال يجب تصفيتها إلا إذا قررت الهيئة غير العادية زيادة رأس المال أو إطفاء الخسائر على ألا تزيد الخسائر المتبقية على نصف رأس المال","qs":[{"q":"يترتب على مدير الشركة ذات المسؤولية المحدودة دعوة الهيئة العامة لاجتماع غير عادي إذا زادت خسائر الشركة على:","o":["نصف رأسمالها","ربع رأسمالها","ثلاثة أرباع رأسمالها","كامل رأسمالها"],"a":0},{"q":"إذا لم تتمكن الهيئة العامة من اتخاذ قرار بشأن الخسائر خلال اجتماعين متتاليين، فيمنح المراقب الشركة مدة لا تزيد على:","o":["شهر","شهرين","ثلاثة أشهر","أسبوعين"],"a":0},{"q":"حالة عملية: بلغت خسائر شركة ذات مسؤولية محدودة ثلاثة أرباع رأسمالها، فإن الحكم:","o":["وجوب تصفيتها إلا إذا قررت الهيئة غير العادية زيادة رأسمالها أو إطفاء الخسائر","استمرارها حكماً دون أي إجراء","تحويلها إلى شركة تضامن","وقفها عن العمل لمدة سنة"],"a":0},{"q":"عند معالجة خسائر بلغت ثلاثة أرباع رأس المال بالزيادة أو الإطفاء، يشترط ألا يزيد مجمل الخسائر المتبقية على:","o":["نصف رأس مال الشركة","ربع رأس مال الشركة","ثلث رأس مال الشركة","ثلاثة أرباع رأس مال الشركة"],"a":0}]},{"n":"76","chapter":"الباب الرابع - الشركة ذات المسؤولية المحدودة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تطبق الأحكام المتعلقة بالشركة المساهمة العامة على الشركة ذات المسؤولية المحدودة في كل ما لم يرد بشأنه نص صريح في الاحكام المتعلقة بالشركات ذات المسؤولية المحدودة .","title":"تطبيق أحكام المساهمة العامة على ذات المسؤولية المحدودة","memo":"⭐ تطبق أحكام الشركة المساهمة العامة على الشركة ذات المسؤولية المحدودة في كل ما لم يرد بشأنه نص صريح في أحكامها","qs":[{"q":"في ما لم يرد بشأنه نص صريح في أحكام الشركة ذات المسؤولية المحدودة، تطبق عليها الأحكام المتعلقة بـ:","o":["الشركة المساهمة العامة","شركة التضامن","شركة التوصية البسيطة","الشركة المساهمة الخاصة"],"a":0},{"q":"تطبق أحكام الشركة المساهمة العامة على الشركة ذات المسؤولية المحدودة:","o":["في كل ما لم يرد بشأنه نص صريح في أحكام الشركات ذات المسؤولية المحدودة","في جميع الأمور ولو ورد بشأنها نص خاص","في أمور التصفية فقط","بقرار من المراقب في كل حالة"],"a":0}]},{"n":"77","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- تؤسس شركات رأس المال المغامر لغايات الاستثمار المباشر أو للاستثمار في شركات ذات مخاطر مرتفعة وإمكانيات نمو عالية لقاء حصولها على عوائد عند بيع مساهمتها أو حصصها في رأسمال الشركة المستثمر بها شريطة أن لا تستثمر في الشركات المدرجة أسهمها في السوق المالي.\nب- ينشأ في الدائرة سجل خاص يسمى ( سجل شركات رأس المال المغامر) يسجل فيه هذا النوع من الشركات بأرقام متسلسلة حسب تاريخ تسجيلها وتدرج فيه التعديلات والتغييرات التي تطرأ عليها.\nج- يقدم طلب تأسيس شركة رأس المال المغامر الى المراقب مرفقاً به عقد تأسيسها على النموذج المعتمد لهذه الغاية، ويوقع أمام المراقب او من يفوضه خطياً بذلك أو أمام الكاتب العدل أو أحد المحامين المزاولين.\nد- يجب أن يتضمن عقد تأسيس الشركة البيانات التالية:-\n١- اسم الشركة.\n٢ - مركز الشركة الرئيسي وعنوانها المعتمد لغايات التبليغ.\n٣- مدة الشركة اذا كانت محدودة المدة.\n٤ - أسماء الشركاء وجنسية كل منهم وعمره اذا كان شخصا طبيعيا والعنوان الذي يختاره للتبليغ.\n٥ - رأسمال الشركة الملتزم به غير المدفوع ورأسمالها المدفوع وعدد الحصص وقيمتها الإسمية.\n٦ - مقدار حصص الشركاء الملتزم بها غير المدفوعة ومقدار الحصص المدفوعة.\n٧- أسماء المفوضين بالتوقيع عن الشركة من الشركاء المديرين أو غيرهم.\n٨- الوضع الذي ستؤول إليه الشركة في حال وفاة شريك مدير.\n٩- أي أمر ورد ضمن اتفاقية الشراكة ونصت الاتفاقي على إدراجه في عقد تأسيس الشركة.\n١٠- أي أمور أخرى يحددها الشركاء أو يطلب المراقب إدراجها.\nه- يجوز أن يشتمل اسم الشركة على اسم أحد الشركاء المديرين فيها او جميعهم أو أي اسم آخر يوافق المراقب عليه مضافا اليه عبارة (شركة رأس مال مغامر) وعلى الشركة إدراج اسمها على الأوراق والمطبوعات والإعلانات التي تستخدمها في أعمالها وعلى العقود والاتفاقيات التي تبرمها مع الغير.","title":"غايات شركة رأس المال المغامر وتأسيسها","memo":"⭐ تؤسس للاستثمار المباشر أو في شركات ذات مخاطر مرتفعة وإمكانيات نمو عالية، ولا تستثمر في الشركات المدرجة أسهمها في السوق المالي\n⭐ تسجل في (سجل شركات رأس المال المغامر) بأرقام متسلسلة حسب تاريخ التسجيل\n⭐ يقدم الطلب للمراقب ويوقع أمامه أو من يفوضه خطياً أو الكاتب العدل أو أحد المحامين المزاولين\n⭐ يضاف إلى اسمها عبارة (شركة رأس مال مغامر)","qs":[{"q":"يحظر على شركة رأس المال المغامر الاستثمار في:","o":["الشركات المدرجة أسهمها في السوق المالي","الشركات ذات المخاطر المرتفعة","الشركات ذات إمكانيات النمو العالية","الاستثمار المباشر"],"a":0},{"q":"تسجل شركات رأس المال المغامر في سجل خاص لدى الدائرة بأرقام متسلسلة حسب:","o":["تاريخ تسجيلها","مقدار رأسمالها","عدد الشركاء فيها","نوع استثماراتها"],"a":0},{"q":"العبارة التي يجب إضافتها إلى اسم شركة رأس المال المغامر:","o":["(شركة رأس مال مغامر)","(ذات المسؤولية المحدودة)","(شركة مساهمة خاصة محدودة)","(شركة توصية بالأسهم)"],"a":0},{"q":"أي مما يلي من البيانات الواجب تضمينها في عقد تأسيس شركة رأس المال المغامر؟","o":["الوضع الذي ستؤول إليه الشركة في حال وفاة شريك مدير","عدد أعضاء هيئة المديرين وصلاحياتهم","أسماء أعضاء مجلس الرقابة","قيمة علاوة الإصدار"],"a":0}]},{"n":"78","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- ينظم الشركاء اتفاقية الشراكة خطيا متضمنة المعلومات المطلوبة في عقد التأسيس وشروط وطرق إدارة وتشغيل وتنظيم شؤون الشركة وأداء أعمالها وتنظيم العلاقة بين الشركاء ، وأي أمور أخرى يتفق عليها الشركاء بما لا يخالف أحكام هذا القانون .\nب- تخضع اتفاقية الشراكة للتشريعات الأردنية وتكون المحاكم الأردنية صاحبة الاختصاص للنظر في أي خلافات قد تنشأ عنها ما لم تنص اتفاقية الشراكة على شرط تحكيم.\nج- ١- إذا نصت اتفاقية الشراكة على طريقة تعديلها بما في ذلك اشتراط موافقة شخص من غير أطراف اتفاقية الشراكة أو استيفاء شروط معينة فلا يجوز تعديلها إلا بتحقق هذه الشروط.\n٢- في حال لم تنص الاتفاقية على طريقة تعديلها فلا يتم إجراء أي تعديل إلا بعد الحصول على موافقة الشركاء جميعهم.\n٣ - يجوز أن يتم الاتفاق في اتفاقية الشراكة على أن يكون تعديلها دون تصويت أو الحصول على اعتماد أو موافقة شريك أو فئة معينة من الشركاء شريطة أن لا يؤدي هذا التعديل إلى زيادة رأس المال الملتزم به لأي شريك دون موافقة خطية منه.\nد- يجوز تنظيم اتفاقية الشراكة بأي لغة شريطة أن يرفق بها ترجمة معتمدة باللغة العربية وفي حال التعارض بينهما تعتمد النسخة العربية من الاتفاقية.","title":"اتفاقية الشراكة","memo":"⭐ ينظم الشركاء اتفاقية الشراكة خطياً، وتخضع للتشريعات الأردنية واختصاص المحاكم الأردنية ما لم تنص على شرط تحكيم\n⭐ إذا لم تنص على طريقة تعديلها فلا تعدل إلا بموافقة الشركاء جميعهم\n⭐ لا يجوز أن يؤدي التعديل دون تصويت إلى زيادة رأس المال الملتزم به لأي شريك دون موافقته الخطية\n⭐ يجوز تنظيمها بأي لغة مع ترجمة معتمدة بالعربية، وعند التعارض تعتمد النسخة العربية","qs":[{"q":"تكون المحاكم الأردنية صاحبة الاختصاص في النظر في الخلافات الناشئة عن اتفاقية الشراكة في شركة رأس المال المغامر ما لم:","o":["تنص الاتفاقية على شرط تحكيم","يوافق المراقب على غير ذلك","يكن أحد الشركاء غير أردني","تنظم الاتفاقية بلغة أجنبية"],"a":0},{"q":"إذا لم تنص اتفاقية الشراكة على طريقة تعديلها، فلا يتم أي تعديل إلا بموافقة:","o":["الشركاء جميعهم","الشركاء الذين يملكون أكثر من نصف رأس المال المدفوع","الشركاء المديرين فقط","المراقب"],"a":0},{"q":"حالة عملية: نظمت اتفاقية الشراكة باللغة الإنجليزية وأرفقت بها ترجمة عربية معتمدة، ثم ظهر تعارض بين النسختين، فتعتمد:","o":["النسخة العربية","النسخة الإنجليزية","النسخة التي يختارها الشريك المدير","النسخة التي يحددها المراقب"],"a":0}]},{"n":"79","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- يتألف رأسمال الشركة من رأس مال ملتزم به ورأس مال مدفوع.\nب- يقسم رأسمال الشركة الى عدد من الحصص لا تقل القيمة الاسمية للحصة الواحدة عن دينار واحد.\nج- لا يجوز أن تقل حصة أي شريك ممول في رأسمال الشركة المدفوع عن خمسين ألف دينار وأن لا تقل حصة أي شريك مدير في رأسمال الشركة الملتزم به والمدفوع عن الف دينار.\nد- لا يجوز أن تكون مساهمة أي شريك في الشركة بغير النقد.\nه- ما لم تنص اتفاقية الشراكة على غير ذلك يجوز للشريك دفع مساهمته دفعة واحدة أو تقسيطها على دفعات على ان تتناسب قيمة القسط مع خصصه في الشركة وعلى ان يتم تسديد قيمة رأس المال الملتزم به غير المدفوع خلال ثلاث سنوات من تاريخ دخوله شريكا في الشركة.\nو - يجب أن ينص في اتفاقية الشراكة على الإجراءات التي ينبغي اتخاذها بحق الشريك غير الملتزم بتسديد قيمة رأس المال الملتزم به للشركة في حال تخلفه عن أداء القسط او عدم السداد خلال المدة المحددة في الفقرة (ه) من هذه المادة.","title":"رأس مال شركة رأس المال المغامر","memo":"⭐ يتألف من رأس مال ملتزم به ورأس مال مدفوع، والقيمة الاسمية للحصة لا تقل عن دينار واحد\n⭐ حصة الشريك الممول في رأس المال المدفوع لا تقل عن (50) ألف دينار، وحصة الشريك المدير في الملتزم به والمدفوع لا تقل عن (1000) دينار\n⭐ لا يجوز أن تكون المساهمة بغير النقد\n⭐ يسدد رأس المال الملتزم به غير المدفوع خلال ثلاث سنوات من تاريخ دخول الشريك","qs":[{"q":"الحد الأدنى لحصة الشريك الممول في رأس المال المدفوع لشركة رأس المال المغامر:","o":["خمسون ألف دينار","ألف دينار","عشرون ألف دينار","مئة ألف دينار"],"a":0},{"q":"الحد الأدنى لحصة الشريك المدير في رأس المال الملتزم به والمدفوع لشركة رأس المال المغامر:","o":["ألف دينار","خمسون ألف دينار","خمسمئة دينار","عشرة آلاف دينار"],"a":0},{"q":"حالة عملية: رغب شريك في شركة رأس مال مغامر بتقديم قطعة أرض حصةً له في رأس المال، فإن ذلك:","o":["غير جائز لأن المساهمة لا تكون بغير النقد","جائز بعد تقدير قيمتها من لجنة خبراء","جائز بموافقة المراقب","جائز إذا نصت اتفاقية الشراكة على ذلك"],"a":0},{"q":"يجب تسديد رأس المال الملتزم به غير المدفوع في شركة رأس المال المغامر خلال:","o":["ثلاث سنوات من تاريخ دخول الشريك في الشركة","سنتين من تاريخ تسجيل الشركة","سنة من تاريخ دخول الشريك في الشركة","خمس سنوات من تاريخ تسجيل الشركة"],"a":0}]},{"n":"80","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- تتألف الشركة من الفئتين التاليتين من الشركاء:-\n١ - شريك مدير واحد أو أكثر يتولى إدارة شؤون الشركة وممارسة أعمالها، ويكون كل منهم مسؤولا بالتضامن والتكافل بأمواله الخاصة عن ديونها والتزاماتها، ويجوز أن يكون شخصا طبيعيا أو اعتباريا.\n٢- شريك ممول واحد أو أكثر لا يشارك في إدارة شؤون الشركة وممارسة أعمالها أو التوقيع عنها، ويكون مسؤولاً عن ديون الشركة والتزاماتها بمقدار حصته في رأسمال الشركة، ويجوز أن يكون شخصاً طبيعياً أو اعتبارياً .\nب- يجوز أن تنص اتفاقية الشراكة على تقسيم الشركاء المديرين أو الشركاء الممولين إلى فئات وتتمتع كل فئة بالحقوق والصلاحيات والواجبات المحددة في اتفاقية الشراكة.\nج- يجوز أن تنص اتفاقية الشراكة على منح جميع الشركاء أو بعضهم أو فئة محددة منهم الحق في التصويت بشكل منفصل أو ضمن فئة أو مجموعة من الشركاء كما يمكن أن يكون حق التصويت للفرد الواحد أو وفقاً لحصة أو فئة أو مجموعة الشركاء أو على أي أساس آخر متفق عليه في اتفاقية الشراكة.\nد - ما لم تنص اتفاقية الشراكة على غير ذلك، يجوز للشركاء عقد اجتماعاتهم بأي من الوسائل الإلكترونية ويشترط لنفاذ القرارات التي تتخذ في الاجتماعات التي تعقد بهذه الوسائل موافقة الشركاء الذين يملكون ما يزيد على نصف رأس مال الشركة المدفوع وسواء كانت الموافقة خطية أو عن طريق الوسائل الإلكترونية أو بأي وسيلة أخرى يسمح بها هذا القانون.\nه- توزع الأرباح والخسائر في الشركة بين الشركاء وفئاتهم إن وجدت بالطريقة المنصوص عليها في اتفاقية الشراكة وفي حال لم تنص اتفاقية الشراكة على ذلك يتم توزيع الأرباح والخسائر على أساس المبلغ المدفوع من كل شريك في رأس مال الشركة.\nو- يتم توزيع أي عوائد أو إيرادات أو مبالغ متأتية للشركة من نشاطاتها أو استثماراتها على الشركاء، شريطة التزام الشريك المدير بالتثبت من قدرة الشركة على الوفاء بالتزاماتها تجاه الدائنين والغير خلال (١٨) شهراً التي تلي هذا التوزيع وفي حال لم تنص اتفاقية الشراكة على ذلك يتم التوزيع بما يتناسب مع رأس المال المدفوع لكل شريك.","title":"فئات الشركاء وتوزيع الأرباح","memo":"⭐ الشريك المدير يدير الشركة ومسؤول بالتضامن والتكافل بأمواله الخاصة، والشريك الممول لا يشارك في الإدارة ومسؤول بمقدار حصته، ويجوز أن يكون كل منهما طبيعياً أو اعتبارياً\n⭐ قرارات الاجتماعات الإلكترونية تنفذ بموافقة من يملكون ما يزيد على نصف رأس المال المدفوع\n⭐ توزع الأرباح والخسائر وفق الاتفاقية وإلا على أساس المبلغ المدفوع من كل شريك\n⭐ يتثبت الشريك المدير من قدرة الشركة على الوفاء بالتزاماتها خلال (18) شهراً تلي التوزيع","qs":[{"q":"مسؤولية الشريك المدير في شركة رأس المال المغامر عن ديون الشركة والتزاماتها:","o":["بالتضامن والتكافل بأمواله الخاصة","بمقدار حصته في رأس المال المدفوع","بمقدار حصته في رأس المال الملتزم به","لا يسأل عن ديون الشركة"],"a":0},{"q":"يشترط لنفاذ القرارات المتخذة في اجتماعات الشركاء المعقودة بالوسائل الإلكترونية موافقة الشركاء الذين يملكون:","o":["ما يزيد على نصف رأس مال الشركة المدفوع","(75%) من رأس مال الشركة الملتزم به","ثلثي رأس مال الشركة المدفوع","جميع حصص رأس المال"],"a":0},{"q":"إذا لم تنص اتفاقية الشراكة على طريقة توزيع الأرباح والخسائر، فإنها توزع على أساس:","o":["المبلغ المدفوع من كل شريك في رأس مال الشركة","رأس المال الملتزم به لكل شريك","التساوي بين الشركاء","عدد الشركاء في كل فئة"],"a":0},{"q":"عند توزيع العوائد على الشركاء يلتزم الشريك المدير بالتثبت من قدرة الشركة على الوفاء بالتزاماتها خلال:","o":["(18) شهراً التي تلي التوزيع","(12) شهراً التي تلي التوزيع","(24) شهراً التي تلي التوزيع","(6) أشهر التي تلي التوزيع"],"a":0}]},{"n":"81","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- يشترط في الشريك المدير أو في ممثل الشخص الاعتباري ما يلي: -\n١- أن لا يقل عمره عن خمس وعشرين سنة.\n٢- أن لا يكون محكوماً بجناية أو بجنحة مخلة بالشرف أو الأخلاق العامة.\n٣- أن لا يكون فاقداً للأهلية أو قد سبق إشهار إعساره أو إعلان إفلاسه ما لم يرد له اعتباره.\nب- ١ - يتولى الشريك المدير أو الشركاء المديرون إدارة الشركة وممارسة أعمالها في الحدود التي تبينها اتفاقية الشراكة ويكونون مفوضين للقيام بكافة الأمور الإدارية والمالية والقضائية والقانونية اللازمة لتسيير أعمال الشركة وتحقيقها لغاياتها.\n٢- تعتبر الأعمال والتصرفات التي يقوم بها أو يمارسها الشريك أو الشركاء المديرون باسم الشركة ملزمة لها في مواجهة الغير الذي يتعامل معها بحسن نية بغض النظر عن أي قيد يرد في اتفاقية الشراكة وعقد الشركة.\nج- إذا تولى إدارة الشركة وممارسة أعمالها شريكان مديران اثنان فتتخذ قراراتها بالإجماع وإذا كانوا أكثر من ذلك فتتخذ قراراتهم بأغلبية عدد الأعضاء ما لم تنص اتفاقية الشراكة على غير ذلك.\nد - للشريك المدير الحق في تفويض أي من صلاحياته للغير مالم تنص اتفاقية الشراكة على غير ذلك شريطة أن يكون التفويض خطياً ومحدداً.\nه - يفقد الشريك المدير صفته شريكاً مديراً في الشركة في أي من الحالات التالية:-\n١ - إذا تنازل عن ملكية حصصه في الشركة وفقاً لأحكام هذا القانون.\n٢ إذا توفي أو فقد أهليته أو تم تعيين وصي أو قيم على ممتلكاته أو إذا فقد أياً من الشروط المنصوص عليها في الفقرة (أ) من هذه المادة.\n٣ - إذا تقرر تصفيته إذا كان شخصاً اعتبارياً أو تم اتخاذ أي إجراءات قانونية جعلته غير قادر على أداء مهامه.\n٤ - إذا تحقق أي شرط من شروط فقدان الصفة المنصوص عليها في اتفاقية الشراكة.\nو- ما لم تنص اتفاقية الشراكة على غير ذلك:-\n١- في حال فقدان الشريك الوحيد صفته شريكاً مديراً للشركة يقرر الشركاء الباقون في الشركة دخول شريك مدير جديد خلال ستين يوما من تاريخ فقدان الشريك المدير صفته وبقرار يصدر بنسبة (٧٥ %) من حصص الشركاء الباقين في الشركة ما لم تنص اتفاقية الشراكة على نسبة أخرى ويتولى الشركاء الممولون تسيير أعمال الشركة خلال تلك المدة.\n٢- يجوز ضم أي شخص كشريك مدير في الشركة، ويصبح شريكا مديرا اعتبارا من تاريخ انضمامه وتثبيته في سجلات الشركة لدى الدائرة، ويصبح الشريك المدير الجديد مسؤولا بالتكافل والتضامن مع باقي الشركاء المديرين عن الديون والالتزامات التي ترتبت على الشركة من تاريخ انضمامه اليها ولا يكون الشريك المدير الجديد مسؤولا عن الالتزامات والديون التي ترتبت على الشركة قبل انضمامه إليها.","title":"الشريك المدير: شروطه وصلاحياته","memo":"⭐ يشترط ألا يقل عمره عن (25) سنة، وألا يكون محكوماً بجناية أو جنحة مخلة بالشرف، وألا يكون فاقداً للأهلية أو معسراً أو مفلساً ما لم يرد اعتباره\n⭐ شريكان مديران: القرارات بالإجماع، وأكثر: بأغلبية عدد الأعضاء\n⭐ التفويض للغير خطي ومحدد\n⭐ فقدان الشريك المدير الوحيد صفته: يقرر الباقون دخول شريك مدير جديد خلال (60) يوماً بنسبة (75%) ويسير الممولون الأعمال خلالها\n⭐ الشريك المدير الجديد لا يسأل عن الديون السابقة لانضمامه","qs":[{"q":"الحد الأدنى لعمر الشريك المدير أو ممثل الشخص الاعتباري في شركة رأس المال المغامر:","o":["خمس وعشرون سنة","ثماني عشرة سنة","إحدى وعشرون سنة","ثلاثون سنة"],"a":0},{"q":"إذا تولى إدارة شركة رأس المال المغامر شريكان مديران اثنان، فتتخذ قراراتهما:","o":["بالإجماع","بأغلبية الحصص","بترجيح رأي صاحب الحصة الأكبر","بقرار من الشركاء الممولين"],"a":0},{"q":"حالة عملية: فقد الشريك المدير الوحيد صفته، فيقرر الشركاء الباقون دخول شريك مدير جديد خلال:","o":["ستين يوماً وبنسبة (75%) من حصص الشركاء الباقين","ثلاثين يوماً وبنسبة (51%) من حصص الشركاء الباقين","تسعين يوماً وبإجماع الشركاء الباقين","ستين يوماً وبنسبة (50%) من حصص الشركاء الباقين"],"a":0},{"q":"يكون الشريك المدير الجديد المنضم إلى شركة رأس المال المغامر مسؤولاً عن الديون والالتزامات:","o":["التي ترتبت على الشركة من تاريخ انضمامه إليها","التي ترتبت على الشركة منذ تأسيسها","التي ترتبت خلال السنة السابقة لانضمامه","بمقدار حصته فقط دون تضامن"],"a":0}]},{"n":"82","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- ما لم ينص في اتفاقية الشراكة على غير ذلك، يحظر على الشريك المدير والشخص المفوض بالتوقيع عن الشركة القيام بأي عمل من الأعمال التالية:-\n١- ممارسة أي عمل او نشاط ينافس به الشركة، سواء مارسه لحسابه الخاص او لحساب الغير.\n٢- المساهمة في شركة أخرى تمارس أعمالا مماثلة و مشابهة لأعمال الشركة، أو القيام بإدارة مثل تلك الشركات وتستثنى من ذلك المساهمة في الشركات المساهمة العامة.\nب - ١ - يحظر على الشريك الممول الاشتراك في إدارة الشركة أو التصرف باسمها او تمثيلها أو ترتيب التزامات عليها وبخلاف ذلك تعتبر الأعمال والتصرفات التي قام بها او مارسها ملزمة للشركة في مواجهة الغير حسن النية، ويكون الشريك الممول مسؤولا بأمواله الخاصة تجاه الشركة والشركاء الآخرين عن أي أضرار قد تلحق بالشركة نتيجة هذه الأعمال والتصرفات.\n٢- لا يعد قيام الشريك الممول بأي من الأعمال التالية مشاركة منه في إدارة الشركة:-\nأ- الاتفاق مع الشركة للقيام بأي عمل لها مهما كان نوعه شريطة موافقة جميع الشركاء الآخرين المسبقة على ذلك.\nب - مشاركته في التصويت على أي قرار للشركة بصفته شريكا ممولا.","title":"المحظورات على الشريك المدير والممول","memo":"⭐ يحظر على الشريك المدير والمفوض بالتوقيع ممارسة عمل منافس أو المساهمة في شركة مماثلة أو إدارتها، ويستثنى المساهمة في الشركات المساهمة العامة (ما لم تنص الاتفاقية على غير ذلك)\n⭐ يحظر على الشريك الممول الاشتراك في الإدارة، وتصرفاته المخالفة ملزمة للشركة تجاه الغير حسن النية ويسأل بأمواله الخاصة عن الأضرار\n⭐ لا يعد مشاركة في الإدارة: الاتفاق مع الشركة على عمل بموافقة جميع الشركاء المسبقة، والتصويت بصفته شريكاً ممولاً","qs":[{"q":"يستثنى من حظر مساهمة الشريك المدير في شركة أخرى تمارس أعمالاً مماثلة لأعمال شركة رأس المال المغامر المساهمة في:","o":["الشركات المساهمة العامة","الشركات ذات المسؤولية المحدودة","شركات التضامن","شركات رأس المال المغامر الأخرى"],"a":0},{"q":"حالة عملية: تصرف شريك ممول باسم شركة رأس المال المغامر مع غير حسن النية، فإن هذا التصرف:","o":["ملزم للشركة ويسأل الممول بأمواله الخاصة عن الأضرار تجاه الشركة والشركاء","باطل ولا يلزم الشركة","ملزم للشريك الممول وحده تجاه الغير","موقوف على إجازة المراقب"],"a":0},{"q":"أي مما يلي لا يعد مشاركة من الشريك الممول في إدارة شركة رأس المال المغامر؟","o":["مشاركته في التصويت على أي قرار للشركة بصفته شريكاً ممولاً","التوقيع عن الشركة","تمثيل الشركة أمام الغير","ترتيب التزامات على الشركة"],"a":0}]},{"n":"83","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- ما لم تنص اتفاقية الشراكة على غير ذلك للشركاء الحق في التنازل عن حصصهم في الشركة كليا أو جزئيا أو نقلها أو التصرف بها وفقا لأحكام اتفاقية الشراكة .\nب- يكون المتنازل له مسؤولا عن التزامات الشريك المتنازل بسداد قيمة الحصص الملتزم بها.\nج- يترتب على نفاذ حكم التنازل عن حصص الشراكة أو نقلها أن يصبح المتنازل إليه او المنقول له شريكا على الفور على ان يتم تثبيت ذلك في سجلات الشركة.\nد - ١ - يجوز ان تتضمن اتفاقية الشراكة إنشاء رهن او ترتيب ضمان على حصص الشركاء، واذا لم تتضمن الاتفاقية ذلك فيشترط لنفاذ الرهن أو الضمان موافقة الشركاء جميعهم .\n٢ - يجوز بموافقة باقي الشركاء ان يصبح صاحب حق الرهن أو الضمان شريكا في الشركة على ان يتم تثبيت ذلك في سجلاتها .\nه -١ لا يتحمل المتنازل إليه أو المنقول إليه أو المرتهن أو أي طرف دائن بدين مضمون أي مسؤولية كشريك حتى يكتسب صفته شريكا ما لم تنص اتفاقية الشراكة على غير ذلك.\n٢- إذا اكتسب الشخص الجديد صفته شريكا، يكون مسؤولاً عن التزامات الشريك السابق، ما لم تنص اتفاقية الشراكة على غير ذلك","title":"التنازل عن الحصص ورهنها","memo":"⭐ للشركاء التنازل عن حصصهم كلياً أو جزئياً وفق اتفاقية الشراكة، والمتنازل له مسؤول عن سداد قيمة الحصص الملتزم بها\n⭐ يصبح المتنازل إليه شريكاً على الفور على أن يثبت ذلك في السجلات\n⭐ إذا لم تتضمن الاتفاقية الرهن أو الضمان يشترط لنفاذه موافقة الشركاء جميعهم\n⭐ لا يتحمل المتنازل إليه أو المرتهن مسؤولية كشريك حتى يكتسب صفة الشريك","qs":[{"q":"يكون مسؤولاً عن التزامات الشريك المتنازل بسداد قيمة الحصص الملتزم بها في شركة رأس المال المغامر:","o":["المتنازل له","الشريك المتنازل وحده","الشريك المدير","الشركة"],"a":0},{"q":"إذا لم تتضمن اتفاقية الشراكة إنشاء رهن على حصص الشركاء، فيشترط لنفاذ الرهن:","o":["موافقة الشركاء جميعهم","موافقة الشريك المدير","موافقة المراقب","موافقة الشركاء الذين يملكون (51%) من الحصص"],"a":0},{"q":"يترتب على نفاذ التنازل عن حصص الشراكة أن يصبح المتنازل إليه شريكاً:","o":["على الفور على أن يتم تثبيت ذلك في سجلات الشركة","بعد مرور ثلاثين يوماً من التنازل","بعد موافقة المراقب","بعد سداد كامل قيمة الحصص"],"a":0}]},{"n":"84","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- على الشركة أن تقدم للمراقب خلال ستة الأشهر الأولى من بداية السنة المالية الخاصة بها ميزانية مصدقة من محاسب قانوني مرفقا بها قرار صادر عن الشركاء بالأغلبية المطلقة لحصصهم المدفوعة بالموافقة عليها واعتمادها.\nب- تحتفظ الشركة بوثائقها وسجلاتها المحاسبية وعقد تأسيسها واتفاقية الشراكة وأي وثائق أخرى متعلقة باتفاقية الشراكة أو بأي من الشركاء فيها في مركزها الرئيسي، ويكون الشركاء المديرون مسؤولين عن حفظها وإدامتها وبما يعكس الواقع الحقيقي للشركة والشركاء فيها، ولها أن تحتفظ بأي من الوثائق أعلاه إلكترونيا.\nج- على الشركاء المديرين تقديم حسابات صحيحة عن أعمال الشركة تتضمن معلومات وبيانات وافية تبين مركزها المالي كلما طلب أي من الشركاء الممولين ذلك الا اذا نصت اتفاقية الشراكة على آلية أخرى.\nد- لكل شريك في الشركة الطلب بنفسه أو بواسطة من يفوضه خطيا من الشركاء المديرين الحصول على أي من الوثائق والمعلومات المتعلقة بالشركة وفقا لأحكام اتفاقية الشراكة، وللشريك المدير الامتناع عن تزويد أي من الشركاء الممولين بأي معلومات تعد من الأسرار أو يرى بحسن نية أن الإفشاء بهذه المعلومات قد يضر بأعمال الشركة ومصالحها أو اذا كان هناك اتفاق مع طرف ثالث يلزم بالمحافظة على سرية المعلومات ما لم تنص اتفاقية الشراكة على خلاف ذلك.\nه- لكل شريك حق الاطلاع على المعلومات والوثائق المتعلقة بالشركة والخاصة بها المحفوظة لدى الدائرة والحصول على صورة مصدقة عنها، وله تفويض غيره بذلك.\nو- تودع قرارات الشركة ونتائج التصويت عليها ومحاضر اجتماعاتها لدى المراقب على ان يتم توقيع تعهد من شريك مدير واحد على الاقل بما يضمن صحة ودقة هذه المحاضر وصحة المعلومات الواردة فيها أو صحة أي وثيقة أخرى من وثائق الشركة تحت طائلة المساءلة القانونية.\nز - يكون الشريك المدير مسؤولاً عن ضمان التزام الشركة بمتطلبات الإفصاح المعمول بها في أي تشريع نافذ.","title":"البيانات المالية والوثائق والإفصاح","memo":"⭐ تقدم الشركة للمراقب خلال الأشهر الستة الأولى من السنة المالية ميزانية مصدقة من محاسب قانوني مع قرار الشركاء بالأغلبية المطلقة لحصصهم المدفوعة\n⭐ تحفظ الوثائق في المركز الرئيسي والشركاء المديرون مسؤولون عن حفظها ويجوز حفظها إلكترونياً\n⭐ للشريك المدير الامتناع عن تزويد الممولين بالمعلومات السرية أو الضارة بحسن نية\n⭐ تودع القرارات والمحاضر لدى المراقب مع تعهد من شريك مدير واحد على الأقل","qs":[{"q":"تقدم شركة رأس المال المغامر للمراقب ميزانية مصدقة من محاسب قانوني خلال:","o":["الأشهر الستة الأولى من بداية السنة المالية","الأشهر الثلاثة الأولى من بداية السنة المالية","الأشهر الأربعة الأولى من بداية السنة المالية","الشهر الأول من بداية السنة المالية"],"a":0},{"q":"يرفق بالميزانية المقدمة للمراقب قرار صادر عن الشركاء بالموافقة عليها واعتمادها:","o":["بالأغلبية المطلقة لحصصهم المدفوعة","بإجماع الشركاء","بأغلبية (75%) من الحصص الملتزم بها","بأغلبية عدد الشركاء المديرين"],"a":0},{"q":"تودع قرارات الشركة ومحاضر اجتماعاتها لدى المراقب على أن يوقع تعهد بصحتها من:","o":["شريك مدير واحد على الأقل","جميع الشركاء المديرين","محاسب قانوني","الشركاء الممولين"],"a":0}]},{"n":"85","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- تلتزم الشركة بما يلي: -\n١- أن لا يكون لها استثمار في الأوراق المالية للشركات المساهمة العامة أو أي نوع من الشركات المدرجة أسهمها في السوق المالي.\n٢- أن لا تزيد نسبة مساهمتها على (٢٠ %) من رأس مالها الملتزم به في أي من الشركات المستثمر بها .\n٣- أن لا تزيد ملكيتها في أي من الشركات المستثمر بها على (%٥١) من رأسمال تلك الشركات خلال فترة الاثني عشر شهرا التي تلي استثمارها بها.\nب- يجوز للشركة الاحتفاظ بالأوراق المالية للشركة المستثمر فيها اذا اصبحت مدرجة في السوق المالي.","title":"قيود استثمارات شركة رأس المال المغامر","memo":"⭐ لا تستثمر في الأوراق المالية للشركات المساهمة العامة أو أي شركة مدرجة\n⭐ لا تزيد مساهمتها على (20%) من رأسمالها الملتزم به في أي شركة مستثمر بها\n⭐ لا تزيد ملكيتها في أي شركة مستثمر بها على (51%) من رأسمالها خلال (12) شهراً التي تلي الاستثمار\n⭐ يجوز الاحتفاظ بأوراق الشركة المستثمر بها إذا أصبحت مدرجة","qs":[{"q":"الحد الأعلى لنسبة مساهمة شركة رأس المال المغامر في أي من الشركات المستثمر بها منسوبة إلى رأسمالها الملتزم به:","o":["(20%)","(51%)","(10%)","(25%)"],"a":0},{"q":"لا يجوز أن تزيد ملكية شركة رأس المال المغامر في أي شركة مستثمر بها خلال الاثني عشر شهراً التي تلي استثمارها على:","o":["(51%) من رأسمال تلك الشركة","(20%) من رأسمال تلك الشركة","(75%) من رأسمال تلك الشركة","(50%) من رأسمال تلك الشركة"],"a":0},{"q":"حالة عملية: أصبحت إحدى الشركات التي تستثمر بها شركة رأس مال مغامر مدرجة في السوق المالي، فإن الشركة:","o":["يجوز لها الاحتفاظ بالأوراق المالية للشركة المستثمر فيها","يجب عليها بيع الأوراق المالية فوراً","تعتبر مخالفة وتصفى إجبارياً","يجب عليها الحصول على موافقة الوزير للاحتفاظ بها"],"a":0}]},{"n":"86","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- ما لم تنص اتفاقية الشراكة على غير ذلك:-\n١ - يجوز للشريك بموافقة باقي الشركاء أن يكفل الشركة او يضمنها او ان يقرضها المال.\n٢- يجوز للشركة الاقتراض من غير الشركاء بما لا يزيد على (%٢٠) من رأسمالها المدفوع من الأشخاص الاعتباريين والمؤسسات المالية والمصرفية والبنوك المحلية والدولية ولها في سبيل ذلك إصدار سندات قابلة للتحويل الى حصص بما لا يتجاوز تلك النسبة.\nب- يحظر على الشركة تحت طائلة البطلان كفالة أي من الشركاء أو ضمان التزاماتهم، كما يحظر عليها أن تقرض الشركاء أو الغير.","title":"الاقتراض والكفالة في شركة رأس المال المغامر","memo":"⭐ يجوز للشريك بموافقة باقي الشركاء أن يكفل الشركة أو يقرضها\n⭐ يجوز الاقتراض من غير الشركاء بما لا يزيد على (20%) من رأس المال المدفوع وإصدار سندات قابلة للتحويل إلى حصص ضمن النسبة\n⭐ يحظر تحت طائلة البطلان كفالة الشركاء أو ضمان التزاماتهم، ويحظر إقراض الشركاء أو الغير","qs":[{"q":"الحد الأعلى لاقتراض شركة رأس المال المغامر من غير الشركاء:","o":["(20%) من رأسمالها المدفوع","(50%) من رأسمالها المدفوع","(20%) من رأسمالها الملتزم به","(51%) من رأسمالها الملتزم به"],"a":0},{"q":"قيام شركة رأس المال المغامر بكفالة أحد الشركاء أو ضمان التزاماته:","o":["محظور تحت طائلة البطلان","جائز بموافقة باقي الشركاء","جائز ضمن (20%) من رأس المال المدفوع","جائز بموافقة المراقب"],"a":0},{"q":"أي مما يلي يجوز لشركة رأس المال المغامر القيام به ما لم تنص اتفاقية الشراكة على غير ذلك؟","o":["إصدار سندات قابلة للتحويل إلى حصص ضمن نسبة الاقتراض المسموح بها","إقراض الشركاء","إقراض الغير","ضمان التزامات الشركاء"],"a":0}]},{"n":"87","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- مع مراعاة أحكام قانون الاعسار تصفى الشركة تصفية اختيارية في أي من الحالات التالية:-\n١- اذا نصت اتفاقية الشراكة على ذلك.\n٢ - موافقة جميع الشركاء المديرين وما نسبته (%٥١) من الحصص المدفوعة للشركاء الممولين.\n٣ - موافقة شركاء ممولين يمتلكون مجتمعين ما لا يقل عن (%٧٥) من حصص الشراكة المملوكة لجميع الشركاء الممولين.\nب- تقدم الشركة إلى المراقب القرارات المتخذة وفقاً لأحكام الفقرة (أ) من هذه المادة للسير في إجراءات تصفيتها اختيارياً.\nج- تقدم الشركة فور انتهائها من إجراءات التصفية الاختيارية إشعارا للمراقب بانتهاء الإجراءات.","title":"التصفية الاختيارية لشركة رأس المال المغامر","memo":"⭐ مع مراعاة قانون الإعسار تصفى اختيارياً: إذا نصت الاتفاقية، أو بموافقة جميع الشركاء المديرين و(51%) من الحصص المدفوعة للممولين، أو بموافقة ممولين يملكون (75%) على الأقل من حصص الممولين\n⭐ تقدم القرارات للمراقب، وتشعره فور انتهاء التصفية","qs":[{"q":"من حالات التصفية الاختيارية لشركة رأس المال المغامر موافقة جميع الشركاء المديرين وما نسبته:","o":["(51%) من الحصص المدفوعة للشركاء الممولين","(75%) من الحصص المدفوعة للشركاء الممولين","(50%) من الحصص الملتزم بها للشركاء الممولين","جميع الشركاء الممولين"],"a":0},{"q":"حالة عملية: وافق شركاء ممولون يملكون مجتمعين (75%) من حصص الشراكة المملوكة لجميع الممولين على تصفية الشركة دون موافقة الشريك المدير، فإن:","o":["الشركة تصفى تصفية اختيارية","التصفية لا تتم إلا بموافقة الشريك المدير","التصفية تكون إجبارية بقرار المحكمة","القرار يحتاج إلى موافقة الوزير"],"a":0},{"q":"تقدم شركة رأس المال المغامر قرارات التصفية الاختيارية للسير في إجراءاتها إلى:","o":["المراقب","المحكمة المختصة","الوزير","هيئة الأوراق المالية"],"a":0}]},{"n":"88","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- تصفى الشركة تصفية إجبارية في أي من الحالات التالية:-\n١- عند انتهاء المدة المحددة في عقد تأسيسها اذا كانت محددة المدة مالم يقرر الشركاء الذين يملكون ما لا يقل عن (%٥١) من الحصص تمديدها قبل ستين يوماً من المدة المحددة لإنتهائها.\n٢- فقدان الشريك المدير الوحيد صفته شريكا مديرا ما لم يتم تعيين شريك مدير آخر وفقا لأحكام الفقرة (و) من المادة (٨١) من هذا القانون.\n٣- ارتكاب الشركة مخالفة جسيمة لأحكام القانون .\nب- تتم اجراءات التصفية الاجبارية في الحالات المنصوص عليها في الفقرة (أ) من هذه المادة بطلب من المراقب يقدم للمحكمة المختصة.\nج- يزود المراقب جميع الشركاء في الشركة بنسخة من الطلب المقدم وفقا لأحكام الفقرة (ب) من هذه المادة ولكل شريك الحق في تقديم رد إلى المحكمة على طلب المراقب والمشاركة في جميع الإجراءات أمام المحكمة.","title":"التصفية الإجبارية لشركة رأس المال المغامر","memo":"⭐ تصفى إجبارياً: بانتهاء مدتها ما لم يقرر من يملكون (51%) على الأقل التمديد قبل (60) يوماً، أو فقدان الشريك المدير الوحيد صفته دون تعيين بديل، أو ارتكاب مخالفة جسيمة للقانون\n⭐ تتم بطلب من المراقب للمحكمة المختصة، ويزود الشركاء بنسخة ولهم الرد والمشاركة","qs":[{"q":"يجوز تجنب التصفية الإجبارية لشركة رأس المال المغامر محددة المدة إذا قرر الشركاء تمديدها قبل انتهاء مدتها بـ:","o":["ستين يوماً، بقرار من يملكون (51%) على الأقل من الحصص","ثلاثين يوماً، بقرار من يملكون (75%) من الحصص","تسعين يوماً، بإجماع الشركاء","ستين يوماً، بقرار من يملكون (75%) من الحصص"],"a":0},{"q":"تتم إجراءات التصفية الإجبارية لشركة رأس المال المغامر بطلب يقدم للمحكمة المختصة من:","o":["المراقب","الشريك المدير","الشركاء الممولين","الوزير"],"a":0},{"q":"أي مما يلي ليس من حالات التصفية الإجبارية لشركة رأس المال المغامر؟","o":["موافقة جميع الشركاء المديرين و(51%) من الحصص المدفوعة للممولين","انتهاء المدة المحددة في عقد تأسيسها دون تمديد","فقدان الشريك المدير الوحيد صفته دون تعيين بديل","ارتكاب الشركة مخالفة جسيمة لأحكام القانون"],"a":0}]},{"n":"89","chapter":"الباب الخامس - شركة رأس المال المغامر","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- تنقضي الشركة بعد الانتهاء من أعمال تصفيتها، ويتم شطب تسجيلها بقرار من المراقب اذا تمت تصفيتها تصفية اختيارية وبقرار من المحكمة اذا تمت تصفيتها تصفية إجبارية.\nب - تطبق على الشركة أحكام التصفية الواردة ضمن نظام تصفية الشركات أو أي تشريع آخر وبما لا يتعارض مع أحكام هذا القانون.\nج- يجوز بموافقة جميع الشركاء تحويل سجل أي شركة قائمة ونقلها إلى سجل شركات رأس المال المغامر شريطة الالتزام بالمتطلبات المنصوص عليها في هذا القانون والتعليمات التي تصدر لهذه الغاية وموافقة المراقب .","title":"انقضاء الشركة والتحويل إلى سجل رأس المال المغامر","memo":"⭐ تنقضي بعد انتهاء التصفية، ويشطب تسجيلها بقرار المراقب في التصفية الاختيارية وبقرار المحكمة في الإجبارية\n⭐ تطبق أحكام نظام تصفية الشركات أو أي تشريع آخر بما لا يتعارض مع القانون\n⭐ يجوز بموافقة جميع الشركاء وموافقة المراقب تحويل سجل أي شركة قائمة إلى سجل شركات رأس المال المغامر","qs":[{"q":"يشطب تسجيل شركة رأس المال المغامر التي صفيت تصفية اختيارية بقرار من:","o":["المراقب","المحكمة","الوزير","الشريك المدير"],"a":0},{"q":"يشطب تسجيل شركة رأس المال المغامر التي صفيت تصفية إجبارية بقرار من:","o":["المحكمة","المراقب","الوزير","المصفي"],"a":0},{"q":"يجوز تحويل سجل أي شركة قائمة ونقلها إلى سجل شركات رأس المال المغامر بشرط:","o":["موافقة جميع الشركاء وموافقة المراقب والالتزام بالمتطلبات","موافقة أغلبية الشركاء فقط","موافقة الوزير دون الشركاء","قرار من المحكمة المختصة"],"a":0}]},{"n":"65 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"تأسيس الشركة المساهمة الخاصة :\nأ . تتالف الشركة المساهمة الخاصة من شخصين او اكثر ويجوز للوزير بناء على تنسيب مبرر من المراقب الموافقة على تسجيل شركة مساهمة خاصة مؤلفة من شخص واحد او ان يصبح عدد مساهميها شخصا واحدا .\nب . تعتبر الذمة المالية للشركة المساهمة الخاصة مستقلة عن الذمة المالية لكل مساهم فيها وتكون الشركة باموالها وموجوداتها هي وحدها المسؤولة عن الديون والالتزامات المترتبة عليها ولا يكون المساهم مسؤولا تجاه الشركة عن تلك الديون والالتزامات الا بمقدار مساهمته في راسمال الشركة.\nج . يجب ان لا يتعارض اسم الشركة مع غاياتها على ان تتبعه اينما وردت عبارة ( شركة مساهمة خاصة محدودة ) ويجوز ان يكون باسم شخص طبيعي اذا كانت غاية الشركة استثمار براءة اختراع مسجلة بصورة قانونية باسم ذلك الشخص .\nد . تكون مدة الشركة المساهمة الخاصة غير محددة الا اذا حدد عقد تاسيسها ونظامها الاساسي خلاف ذلك فعندئذ تنتهي مدتها بانتهاء المدة او العمل الذي حدد لها .","title":"تأسيس الشركة المساهمة الخاصة","memo":"⭐ تتألف من شخصين أو أكثر، ويجوز للوزير بتنسيب مبرر من المراقب الموافقة على تسجيلها من شخص واحد\n⭐ ذمتها المالية مستقلة، والمساهم مسؤول بمقدار مساهمته في رأس المال\n⭐ يتبع اسمها عبارة (شركة مساهمة خاصة محدودة)، ويجوز أن يكون باسم شخص طبيعي إذا كانت غايتها استثمار براءة اختراع مسجلة باسمه\n⭐ مدتها غير محددة ما لم يحدد عقدها ونظامها خلاف ذلك","qs":[{"q":"الجهة التي يجوز لها الموافقة على تسجيل شركة مساهمة خاصة مؤلفة من شخص واحد:","o":["الوزير بناء على تنسيب مبرر من المراقب","المراقب منفرداً","مجلس الوزراء","الهيئة العامة"],"a":0},{"q":"العبارة التي يجب أن تتبع اسم الشركة المساهمة الخاصة أينما ورد:","o":["(شركة مساهمة خاصة محدودة)","(ذات المسؤولية المحدودة)","(شركة مساهمة عامة محدودة)","(ذ.م.م)"],"a":0},{"q":"يجوز أن يكون اسم الشركة المساهمة الخاصة باسم شخص طبيعي إذا كانت غايتها:","o":["استثمار براءة اختراع مسجلة بصورة قانونية باسم ذلك الشخص","الاستثمار في الأوراق المالية","ممارسة أعمال تجارية عامة","الاستثمار العقاري"],"a":0},{"q":"مدة الشركة المساهمة الخاصة كأصل عام:","o":["غير محددة ما لم يحدد عقد تأسيسها ونظامها خلاف ذلك","خمس وعشرون سنة قابلة للتجديد","عشر سنوات قابلة للتجديد","تحددها الهيئة العامة سنوياً"],"a":0}]},{"n":"66 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"رأسمال الشركة :\nأ . يكون رأسمال الشركة المساهمة الخاصة هو مجموع القيم الاسمية لاسهم الشركة على ان لا يقل راس المال المكتتب به عن خمسين الف دينار اردني .\nب . يحدد راس مال الشركة المساهمة الخاصة بالدينار الاردني .\nج . مع مراعاة قانون الاوراق المالية للشركة المساهمة الخاصة اصدار اسهم واسناد قرض واوراق مالية اخرى ويجوز للشركة ان تقرر ادراج اوراقها المالية في السوق المالي وتداولها من خلاله وفق الانظمة والتعليمات الصادرة عن هيئة الاوراق المالية.","title":"رأس مال الشركة المساهمة الخاصة","memo":"⭐ رأس المال = مجموع القيم الاسمية للأسهم\n⭐ الحد الأدنى لرأس المال المكتتب به: ٥٠ ألف دينار أردني\n⭐ يحدد رأس المال بالدينار الأردني\n⭐ يجوز إدراج أوراقها المالية في السوق المالي وفق تعليمات هيئة الأوراق المالية","qs":[{"q":"الحد الأدنى لرأس المال المكتتب به في الشركة المساهمة الخاصة هو:","o":["خمسون ألف دينار","ثلاثون ألف دينار","مئة ألف دينار","خمسمائة ألف دينار"],"a":0},{"q":"يكون رأس مال الشركة المساهمة الخاصة:","o":["مجموع القيم الاسمية لأسهم الشركة","مجموع القيم السوقية لأسهم الشركة","مجموع موجودات الشركة مطروحاً منها مطلوباتها","مجموع رأس المال المصرح به والاحتياطي الإجباري"],"a":0},{"q":"وفق أحكام الشركة المساهمة الخاصة، إدراج أوراقها المالية في السوق المالي وتداولها من خلاله:","o":["جائز بقرار من الشركة وفق أنظمة وتعليمات هيئة الأوراق المالية","محظور مطلقاً","وجوبي عند التأسيس","جائز فقط بعد تحولها إلى شركة مساهمة عامة"],"a":0}]},{"n":"67 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"طلب التأسيس :\nأ - يقدم طلب تاسيس الشركة المساهمة الخاصة الى المراقب مرفقا به عقد تاسيسها ونظامها الاساسي واسماء مؤسسي الشركة . ويجب ان يكون عقد تاسيس الشركة ونظامها الاساسي باللغة العربية الا انه يجوز ان يلازم ذلك ترجمة له بلغة اخرى وفي حالة تعارض او اختلاف النصوص يعتمد النص العربي .\nب - يجب ان يتضمن عقد تاسيس الشركة المساهمة الخاصة البيانات التالية وفق ما يتفق عليه مؤسسوا او مساهموا الشركة :\n١ . اسم الشركة .\n٢ . مركزها الرئيسي وعنوانها المعتمد للتبليغ .\n٣ . غايات الشركة .\n٤ . اسماء مؤسسي الشركة وجنسياتهم وعناوينهم المختارة للتبليغ وعدد الاسهم المملوكة من قبل كل منهم عند التاسيس .\n٥ . راسمال الشركة المصرح به وعدد الاسهم المصرح بها وانواعها وفئاتها وقيمتها الاسمية .\n٦ . طريقة ادارة الشركة وعدد اعضاء مجلس الادارة وصلاحياته .\n٧ . اسماء الاشخاص الذين سيتولون دعوة الهيئة العامة التاسيسية للانعقاد وادارة الشركة الى حين انتخاب مجلس الادارة الاول .\nج - يجب ان يتضمن النظام الاساسي للشركة المساهمة الخاصة البيانات التالية وفق ما يتفق عليه مؤسسو او مساهموا الشركة :\n١ . اسم الشركة .\n٢ . مركزها الرئيسي وعنوانها المعتمد للتبليغ .\n٣ . غايات الشركة .\n٤ . اسماء مؤسسي الشركة وجنسياتهم وعناوينهم المختارة للتبليغ وعدد الاسهم المملوكة من قبل كل منهم عند التاسيس .\n٥ . راسمال الشركة المصرح به وعدد الاسهم المصرح بها وانواعها وقيمها الاسمية وحقوقها وصفاتها وميزاتها .\n٦ . الشروط العامة لنقل ملكية اسهم الشركة والاجراءات الواجب اتباعها في ذلك .\n٧ . طريقة ادارة الشركة وعدد اعضاء مجلس الادارة وصلاحياته واسس اتخاذ القرارات فيه .\n٨ . اجراءات وقواعد اجتماعات الهيئة العامة للمساهمين العادية وغير العادية ونصابها القانوني واصول الدعوة لها وصلاحياتها وطريقة اتخاذ القرارات فيها وجميع الامور المتعلقة بها .\n٩ . اجراءات وقواعد تصفية الشركة .\n١٠ . اسماء الاشخاص الذين سيتولون دعوة الهيئة التاسيسية للانعقاد وادارة الشركة لحين انتخاب مجلس الادارة الاول وطريقة الدعوة لمجلس الادارة الاول .\n١١ . اذا كان لمساهمي وحاملي الاوراق المالية الصادرة عن الشركة حق الاولوية في اصدارات جديدة للشركة .\nد - يجوز لاي شخص الاطلاع على عقد تاسيس الشركة وفق تعليمات تصدر عن الوزير ولا يجوز لغير مساهمي الشركة الاطلاع على نظام الشركة الاساسي الا بتفويض من احد المساهمين او الشركة او اذا تطلب أي تشريع اخر ذلك .","title":"طلب تأسيس الشركة المساهمة الخاصة","memo":"⭐ يقدم طلب التأسيس إلى المراقب مرفقاً بعقد التأسيس والنظام الأساسي وأسماء المؤسسين\n⭐ العقد والنظام باللغة العربية، وعند التعارض مع الترجمة يعتمد النص العربي\n⭐ لأي شخص الاطلاع على عقد التأسيس وفق تعليمات الوزير\n⭐ النظام الأساسي لا يطلع عليه غير المساهمين إلا بتفويض من مساهم أو الشركة أو إذا تطلب تشريع ذلك","qs":[{"q":"يقدم طلب تأسيس الشركة المساهمة الخاصة إلى:","o":["المراقب","الوزير","هيئة الأوراق المالية","المحكمة المختصة"],"a":0},{"q":"في حال تعارض نص عقد تأسيس الشركة المساهمة الخاصة باللغة العربية مع ترجمته بلغة أخرى:","o":["يعتمد النص العربي","يعتمد النص المترجم","يرجع إلى قرار المراقب","يرجع إلى قرار الهيئة العامة"],"a":0},{"q":"طلب شخص ليس مساهماً في شركة مساهمة خاصة الاطلاع على نظامها الأساسي دون أي تفويض، ولا يوجد تشريع يتطلب ذلك، فإن:","o":["لا يجوز له الاطلاع على النظام الأساسي","يجوز له الاطلاع وفق تعليمات الوزير","يجوز له الاطلاع بموافقة المراقب فقط","يجوز له الاطلاع مقابل رسم يحدده المراقب"],"a":0},{"q":"أي مما يلي ليس من البيانات الواجب تضمينها في عقد تأسيس الشركة المساهمة الخاصة؟","o":["إجراءات وقواعد تصفية الشركة","اسم الشركة ومركزها الرئيسي","غايات الشركة","طريقة إدارة الشركة وعدد أعضاء مجلس الإدارة"],"a":0}]},{"n":"68 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"انواع الاسهم وخيارات المساهمة :-\nأ - مع مراعاة أي احكام وردت في هذا الباب ، يجوز للشركة :\nوحسب ما ينص عليه نظامها الاساسي اصدار عدة انواع وفئات من الاسهم تختلف فيما بينها من حيث القيمة الاسمية والقوة التصويتية ومن حيث كيفية توزيع الارباح والخسائر على المساهمين وحقوق واولويات كل منها عند التصفية وقابليتها للتحول لانواع اخرى من الاسهم وما الى ذلك من الحقوق والمزايا والاولويات والقيود الاخرى على ان يتم تضمينها او ملخص عنها على شهادات الاسهم ان وجدت .\nب - يجوز ان ينص النظام الاساسي للشركة المساهمة الخاصة على حق الشركة اصدار اسهم قابلة للاسترداد اما بطلب من الشركة او من حامل السهم او عند توافر شروط معينة وعلى الوزير إصدار التعليمات اللازمة التي تحدد شروط إصدار هذا النوع من الأسهم وحالات استردادها.\nج - يجوز ان يكون لاي نوع او فئة من اسهم الشركة افضلية في توزيع الارباح على غيرها من الانواع او الفئات كما ويجوز ان تستحق مقدارا مقطوعا او نسبة معينة من الارباح وذلك بالشروط وفي الاوقات التي يحددها نظام الشركة الاساسي كما يجوز ان يكون لاي من هذه الانواع والفئات حق الاولوية في استيفاء ارباحها عن أي سنوات لم توزع فيها الارباح بالاضافة الى الربح المقرر لها في تلك السنة المالية .\nد - يجوز ان ينص النظام الاساسي للشركة المساهمة الخاصة على قابلية تحول او استبدال أي نوع او فئة من الاسهم الصادرة عنها الى أي نوع او فئة اخرى بطلب من الشركة او المساهم او عند تحقق شرط معين وفق النسب والكيفية التي تحدد في نظام الشركة الاساسي .\nهـ - يجوز للشركة المساهمة الخاصة شراء الاسهم التي سبق وان اصدرتها ولها اما اعادة اصدار او بيع هذه الاسهم بالسعر الذي يراه مجلس الادارة مناسبا او الغائها وتخفيض راس مالها بمقدار هذه الاسهم حسب الاسس المبينة في نظامها الاساسي وهذا الباب ولا تؤخذ الاسهم التي تمتلكها الشركة بعين الاعتبار لغايات توافر النصاب في اجتماعات الهيئة العامة ولاتخاذ القرارات فيها وذلك مع مراعاة احكام قانون الاوراق المالية والانظمة والتعليمات الصادرة بموجبه .\nو - مع مراعاة احكام نظام الشركة الاساسي وقانون الاوراق المالية والانظمة والتعليمات الصادرة بموجبه يجوز للشركة المساهمة الخاصة اصدار خيارات اسهم تسمح لحامليها شراء او طلب اصدار اسهم من الشركة وتحدد شروط الخيارات وتواريخ تنفيذها واسعار تنفيذها في نظام الشركة الاساسي او بقرار من مجلس الادارة اذا فوضته الهيئة العامة غير العادية بذلك .","title":"أنواع الأسهم وخيارات المساهمة","memo":"⭐ يجوز إصدار أنواع وفئات من الأسهم تختلف بالقيمة الاسمية والقوة التصويتية وتوزيع الأرباح وأولويات التصفية\n⭐ يجوز إصدار أسهم قابلة للاسترداد، والوزير يصدر تعليمات شروطها\n⭐ الأسهم التي تملكها الشركة لا تحتسب في النصاب ولا في اتخاذ القرارات\n⭐ خيارات الأسهم تحدد شروطها في النظام الأساسي أو بقرار مجلس الإدارة إذا فوضته الهيئة العامة غير العادية","qs":[{"q":"الجهة التي تصدر التعليمات اللازمة لتحديد شروط إصدار الأسهم القابلة للاسترداد في الشركة المساهمة الخاصة هي:","o":["الوزير","المراقب","هيئة الأوراق المالية","مجلس إدارة الشركة"],"a":0},{"q":"الأسهم التي تمتلكها الشركة المساهمة الخاصة بعد شرائها:","o":["لا تؤخذ بعين الاعتبار لغايات النصاب واتخاذ القرارات في الهيئة العامة","تحتسب في النصاب دون التصويت","تحتسب في النصاب والتصويت كسائر الأسهم","يصوت بها مجلس الإدارة نيابة عن الشركة"],"a":0},{"q":"تحدد شروط خيارات الأسهم وتواريخ تنفيذها وأسعارها في الشركة المساهمة الخاصة في النظام الأساسي أو بقرار من:","o":["مجلس الإدارة إذا فوضته الهيئة العامة غير العادية","المراقب بناء على طلب الشركة","الهيئة العامة العادية حصراً","المدير العام للشركة"],"a":0}]},{"n":"69 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"اجراءات التسجيل :-\nأ- تسجل الشركة خلال خمسة عشر يومـا مـن تـاريخ تقديم الطلـب المستوفي لشروط التسجيل ، وفي حال وجود أي مخالفة في نظام وعقد تأسيس الشركة يتم إعلام المؤسسين بعدم تسجيلها الى حين إزالـة أسباب المخالفـة خـلال مدة لا تزيـد علـى ثلاثين يومـا مـن تـاريخ تقديم الطلـب علـى أن يبقـى حـق المؤسسـين بـالطعن لدى المحكمة الإدارية.\nب- بعد أن يتم تسجيل الشركة وفقا لأحكام الفقرة (أ) من هذه المادة وبعد أن يقدم المساهمون الوثائق التي تثبت انه قد تم دفع رأسمالها المنصوص عليه في هذا القانون يقوم المراقب باستيفاء رسوم التسجيل ويصدر شهادة بتسجيلها وتنشر في الجريدة الرسمية.\nج - لا يجوز للشركة المباشرة باعمالها الا بعد صدور شهادة تسجيلها من قبل المراقب ، الا انه يجوز لمساهمي الشركة المساهمة الخاصة الموافقة في اجتماع الهيئة العامة التاسيسي على اقرار التزامات المؤسسين نيابة عن الشركة قبل اعلان تسجيل الشركة فان لم توافق الهيئة العامة التاسيسية على ذلك لا تلزم الشركة باي من هذه الالتزامات .","title":"إجراءات تسجيل الشركة المساهمة الخاصة","memo":"⭐ تسجل الشركة خلال ١٥ يوماً من تقديم الطلب المستوفي للشروط\n⭐ عند وجود مخالفة يعلم المؤسسون خلال مدة لا تزيد على ٣٠ يوماً، مع حق الطعن لدى المحكمة الإدارية\n⭐ لا تباشر الشركة أعمالها إلا بعد صدور شهادة التسجيل من المراقب\n⭐ التزامات المؤسسين قبل التسجيل لا تلزم الشركة إلا بموافقة الهيئة العامة التأسيسية","qs":[{"q":"تسجل الشركة المساهمة الخاصة خلال مدة من تاريخ تقديم الطلب المستوفي لشروط التسجيل مقدارها:","o":["خمسة عشر يوماً","ثلاثون يوماً","عشرة أيام","ستون يوماً"],"a":0},{"q":"يحق لمؤسسي الشركة المساهمة الخاصة الطعن في عدم تسجيلها لدى:","o":["المحكمة الإدارية","محكمة البداية","الوزير","هيئة الأوراق المالية"],"a":0},{"q":"أبرم مؤسسو شركة مساهمة خاصة التزامات نيابة عنها قبل إعلان تسجيلها، ولم توافق الهيئة العامة التأسيسية عليها، فإن الشركة:","o":["لا تلزم بأي من هذه الالتزامات","تلزم بها بقوة القانون","تلزم بها إذا وافق المراقب","تلزم بنصفها ويتحمل المؤسسون الباقي"],"a":0}]},{"n":"70 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"المقدمات العينية :\nأ - يجوز لمساهمي الشركة المساهمة الخاصة ان يقدموا مقابل اسهمهم في الشركة مقدمات عينية تقوم بالنقد يوافق عليها المؤسسون او الهيئة العامة في حالة اصدار اسهم جديدة ، وتعتبر حقوق الامتياز والاختراع والمعرفة الفنية والرخص وجميع الحقوق المعنوية واي حقوق اخرى يقرها المساهمون من المقدمات العينية .\nب- اذا لم يلتزم اصحاب المقدمات العينية بنقل ملكيتها وتسليمها الى الشركة خلال ثلاثين يوما من تاريخ تسجيل الشركة او اصدار الاسهم العينية كانوا ملزمين حكما بدفع قيمتها نقدا وفق السعر الذي اعتمده المساهمون في نظام الشركة او قرار الهيئة العامة ويجوز الاتفاق على مدة اطول بموافقة المراقب .\nج- يحق للمراقب من تلقاء نفسه أو اذا اعترض أي من المساهمين خلال ثلاثين يوما من تاريخ موافقة الهيئة العامة على قبول المقدمات العينيـة التنسيب للـوزير بتشكيل لجنـة علـى نفقـة الشركة من ذوي الخبرة والاختصاص لتقدير الأسهم العينيـة بالنقد وتقدم اللجنة تقريرها خلال مدة لا تتجاوز الثلاثين يوما من تاريخ تشكيلها ويعتبر قرار اللجنة بعد موافقة الوزير عليه نهائيـا، مـع حـق أي مـن المساهمين الآخرين أو الشـركـة بـالاعتراض علـى قـرار اللجنـة أمـام المحكمـة المختصـة دون أن يؤثر ذلك على تسجيل الشركة وممارستها لأعمالها ولا يحق لأي من المؤسسين أو المساهمين اللاحقين الاعتراض على قيمة الأسهم العينية المقدمة بعد ذلك وإذا تبين أن تقديرات الاسهم العينية تقل عن قيمتها الحقيقية فيتم تخفيض مساهمة الشريك لتتناسب وقيمة مساهمته العينية الحقيقية.\nد - تكـون لـجنـة المؤسسين ومجلس الإدارة مسؤولة عـن دقـة وكفايـة البيانــات والمعلومـات المقدمـة عـن قيمـة تلك الأسهم العينية.\nه - على اللجنة عند القيام بتقييم المقدمات العينية مراعاة التعليمات التي يصدرها الوزير لهذه الغاية.","title":"المقدمات العينية في الشركة الخاصة","memo":"⭐ حقوق الامتياز والاختراع والمعرفة الفنية والرخص والحقوق المعنوية تعتبر مقدمات عينية\n⭐ إذا لم تنقل ملكيتها خلال ٣٠ يوماً من التسجيل أو إصدار الأسهم العينية يلزم أصحابها بدفع قيمتها نقداً (ويجوز مدة أطول بموافقة المراقب)\n⭐ للمراقب أو عند اعتراض مساهم خلال ٣٠ يوماً التنسيب للوزير بتشكيل لجنة على نفقة الشركة تقدم تقريرها خلال ٣٠ يوماً\n⭐ قرار اللجنة نهائي بعد موافقة الوزير مع حق الاعتراض أمام المحكمة المختصة","qs":[{"q":"إذا لم يلتزم أصحاب المقدمات العينية في الشركة المساهمة الخاصة بنقل ملكيتها وتسليمها خلال المدة القانونية كانوا ملزمين حكماً بدفع قيمتها نقداً، وهذه المدة هي:","o":["ثلاثون يوماً من تاريخ تسجيل الشركة أو إصدار الأسهم العينية","خمسة عشر يوماً من تاريخ تسجيل الشركة","ستون يوماً من تاريخ موافقة الهيئة العامة","ثلاثة أشهر من تاريخ تسجيل الشركة"],"a":0},{"q":"يتم تشكيل لجنة تقدير الأسهم العينية في الشركة المساهمة الخاصة من قبل الوزير بناء على تنسيب:","o":["المراقب","مجلس الإدارة","هيئة الأوراق المالية","لجنة المؤسسين"],"a":0},{"q":"أي مما يلي لا يعتبر من المقدمات العينية وفق أحكام الشركة المساهمة الخاصة؟","o":["المبالغ النقدية المدفوعة مقابل الأسهم","حقوق الامتياز","المعرفة الفنية","الرخص"],"a":0},{"q":"الجهة المسؤولة عن دقة وكفاية البيانات والمعلومات المقدمة عن قيمة الأسهم العينية هي:","o":["لجنة المؤسسين ومجلس الإدارة","المراقب","لجنة التقدير","مدقق الحسابات"],"a":0}]},{"n":"71 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"الاجتماع التاسيسي :\nيتوجب على المساهمين عقد اجتماع هيئة عامة عادي تاسيسي خلال شهر من تاريخ صدور شهادة تسجيل الشركة من قبل المراقب ليتم فيه ما يلي :\nأ . انتخاب مجلس ادارة الشركة الاول .\nب . اتخاذ القرار المناسب بشان مصاريف التاسيس واي التزامات تمت من قبل المؤسسين قبل التاسيس .\nج . انتخاب مدقق حسابات وتحديد اتعابه او تفويض مجلس الادارة بتحديد اتعابه .","title":"الاجتماع التأسيسي للشركة الخاصة","memo":"⭐ يعقد اجتماع هيئة عامة عادي تأسيسي خلال شهر من صدور شهادة التسجيل\n⭐ يتم فيه: انتخاب مجلس الإدارة الأول، والبت في مصاريف التأسيس والتزامات المؤسسين، وانتخاب مدقق الحسابات وتحديد أتعابه أو تفويض المجلس بها","qs":[{"q":"يتوجب على مساهمي الشركة المساهمة الخاصة عقد اجتماع الهيئة العامة التأسيسي خلال:","o":["شهر من تاريخ صدور شهادة التسجيل","ستين يوماً من تاريخ صدور شهادة التسجيل","خمسة عشر يوماً من تاريخ تقديم طلب التسجيل","ثلاثة أشهر من تاريخ تقديم طلب التسجيل"],"a":0},{"q":"أي مما يلي ليس من المهام التي تتم في الاجتماع التأسيسي للشركة المساهمة الخاصة؟","o":["تعديل عقد تأسيس الشركة","انتخاب مجلس الإدارة الأول","اتخاذ القرار بشأن مصاريف التأسيس","انتخاب مدقق الحسابات وتحديد أتعابه"],"a":0}]},{"n":"72 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"مجلس الادارة :\nأ - يتولى ادارة الشركة المساهمة الخاصة مجلس ادارة يحدد النظام الاساسي للشركة عدد اعضائه ومؤهلات العضوية فيه وطريقة ملء المقاعد الشاغرة وصلاحياته ومكافاته وكيفية تعيينه او انتخابه وعقد اجتماعاته واتخاذ قراراته ومدته بحيث لا تزيد على اربع سنوات وينتخب مجلس الادارة من بين اعضائه رئيسا ونائبا للرئيس كما ويعين امينا لسر من بين اعضائه او من غيرهم ويكون لرئيس المجلس صوتا ترجيحيا في حال تساوي الاصوات ما لم ينص النظام الاساسي للشركة على خلاف ذلك ويعين مجلس الإدارة مديرا عاما للشركة وتحـدد صـلاحياته في قرار تعيينه.\nب- على مجلس الادارة تحديد المفوضين بالتوقيع عن الشركة بما لا يتعارض واحكام عقد تاسيس الشركة ونظامها الاساسي في اول اجتماع له بعد انتخابه على ان يتم ذلك في موعد اقصاه اسبوع من انتخاب المجلس ويجوز للمجلس اعادة انتخاب الرئيس ونائب الرئيس واستبدال امين السر وتعديل صلاحيات المفوضين بالتوقيع في أي وقت بما لا يتعارض مع احكام هذا الباب واحكام عقد تاسيس الشركة ونظامها الاساسي .\nج- يعتبر أي محضر او شهادة صادرة عن رئيس مجلس الادارة او نائبه في حالة غيابه ومصدقا عليها من قبل امين السر فيما يخص قرارات مجلس الادارة او الهيئة العامة للشركة دليلا على صحة هذه القرارات ويتحمل الرئيس ونائب الرئيس وامين السر مسؤولية أي شهادة تصدر عنهم بهذا الخصوص .\nد- يجوز لمجلس ادارة الشركة المساهمة الخاصة عقد اجتماعاته بواسطة الهاتف او أي من وسائل الاتصال الاخرى اذا اجاز النظام الاساسي للشركة ذلك شريطة ان يتمكن جميع الاعضاء المشاركين في الاجتماعات سماع ومناقشة بعضهم البعض حول جدول اعمال الاجتماع على ان يصادق رئيس المجلس وامين السر على المحضر وبانعقاد الاجتماع بشكل قانوني .","title":"مجلس إدارة الشركة المساهمة الخاصة","memo":"⭐ مدة المجلس يحددها النظام الأساسي بحيث لا تزيد على ٤ سنوات\n⭐ ينتخب المجلس رئيساً ونائباً من بين أعضائه، وأمين السر من بين أعضائه أو من غيرهم\n⭐ لرئيس المجلس صوت ترجيحي عند التساوي ما لم ينص النظام على خلافه، والمجلس يعين المدير العام\n⭐ تحديد المفوضين بالتوقيع في أول اجتماع وخلال أسبوع من انتخاب المجلس، ويجوز الاجتماع بالهاتف إذا أجازه النظام الأساسي","qs":[{"q":"الحد الأقصى لمدة مجلس إدارة الشركة المساهمة الخاصة هو:","o":["أربع سنوات","ثلاث سنوات","خمس سنوات","سنتان"],"a":0},{"q":"على مجلس إدارة الشركة المساهمة الخاصة تحديد المفوضين بالتوقيع عن الشركة في موعد أقصاه:","o":["أسبوع من انتخاب المجلس","شهر من انتخاب المجلس","خمسة عشر يوماً من انتخاب المجلس","ثلاثة أيام من انتخاب المجلس"],"a":0},{"q":"يعين أمين سر مجلس إدارة الشركة المساهمة الخاصة:","o":["من بين أعضاء المجلس أو من غيرهم","من بين أعضاء المجلس حصراً","من قبل الهيئة العامة","من قبل المراقب"],"a":0},{"q":"يجوز لمجلس إدارة الشركة المساهمة الخاصة عقد اجتماعاته بواسطة الهاتف أو وسائل الاتصال الأخرى بشرط:","o":["أن يجيز النظام الأساسي ذلك وأن يتمكن جميع الأعضاء المشاركين من سماع ومناقشة بعضهم","موافقة المراقب المسبقة على كل اجتماع","حضور أغلبية الأعضاء شخصياً","موافقة الهيئة العامة غير العادية على كل اجتماع"],"a":0}]},{"n":"73 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"مسؤولية مجلس الادارة :\nأ . رئيس واعضاء مجلس ادارة الشركة المساهمة الخاصة مسؤولون تجاه الشركة والمساهمين فيها والغير عن كل مخالفة ارتكبها أي منهم او جميعهم للقوانين والانظمة المعمول بها ولنظام الشركة الاساسي وعن أي خطا في ادارة الشركة , ولا تحول موافقة الهيئة العامة على ابراء ذمة مجلس الادارة دون الملاحقة القانونية لرئيس واعضاء المجلس .\nب . تكون المسؤولية المنصوص عليها في الفقرة (أ) من هذه المادة اما شخصية تترتب على عضو او اكثر من اعضاء مجلس ادارة الشركة او مشتركة بين رئيس واعضاء المجلس ويكونون جميعهم في هذه الحالة مسؤولين بالتضامن والتكافل عن التعويض عن الضرر الذي نتج عن المخالفة او الخطا على ان لا تشمل هذه المسؤولية أي عضو اثبت اعتراضه خطيا في محضر الاجتماع على القرار الذي تضمن المخالفة او الخطا وفي جميع الاحوال لا تسمع الدعوى بهذه المسؤولية بعد مرور خمس سنوات على تاريخ اجتماع الهيئة العامة الذي صادقت فيه على الميزانية السنوية والحسابات الختامية للشركة للسنة المالية التي جرى فيها الخطا او المخالفة .","title":"مسؤولية مجلس إدارة الشركة الخاصة","memo":"⭐ الرئيس والأعضاء مسؤولون تجاه الشركة والمساهمين والغير عن مخالفة القوانين والنظام الأساسي وعن الخطأ في الإدارة\n⭐ إبراء الهيئة العامة لذمة المجلس لا يحول دون الملاحقة القانونية\n⭐ المسؤولية شخصية أو مشتركة بالتضامن، ولا تشمل العضو الذي أثبت اعتراضه خطياً في المحضر\n⭐ لا تسمع الدعوى بعد مرور ٥ سنوات على اجتماع الهيئة العامة الذي صادق على الميزانية للسنة التي وقعت فيها المخالفة","qs":[{"q":"لا تسمع دعوى المسؤولية على أعضاء مجلس إدارة الشركة المساهمة الخاصة بعد مرور:","o":["خمس سنوات على تاريخ اجتماع الهيئة العامة الذي صادق على الميزانية للسنة التي وقع فيها الخطأ","ثلاث سنوات على تاريخ وقوع الخطأ","سنتين على تاريخ اجتماع الهيئة العامة","عشر سنوات على تاريخ وقوع المخالفة"],"a":0},{"q":"وافقت الهيئة العامة لشركة مساهمة خاصة على إبراء ذمة مجلس الإدارة، ثم تبين وجود مخالفة للقانون ارتكبها المجلس، فإن:","o":["الإبراء لا يحول دون الملاحقة القانونية لرئيس وأعضاء المجلس","الإبراء يمنع أي ملاحقة قانونية","الملاحقة تتطلب موافقة المراقب","الملاحقة تقتصر على رئيس المجلس"],"a":0},{"q":"في حالة المسؤولية المشتركة لأعضاء مجلس إدارة الشركة المساهمة الخاصة، لا تشمل المسؤولية العضو الذي:","o":["أثبت اعتراضه خطياً في محضر الاجتماع على القرار","غاب عن الاجتماع بعذر","امتنع عن التصويت دون تسجيل اعتراض","استقال بعد صدور القرار"],"a":0}]},{"n":"74 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"التزامات مجلس الادارة والموظفين :\nأ . يحظر على اعضاء مجلس ادارة الشركة المساهمة الخاصة ان يكونوا اعضاء في مجالس ادارات شركات اخرى ذات غايات مماثلة او منافسة لاعمال الشركة الا بموافقة الهيئة العامة غير العادية للشركة .\nب . يحظر على مدير عام الشركة وموظفيها تولي وظيفة في شركة اخرى ذات غايات مماثلة او منافسة لاعمال الشركة سواء لحسابه او لحساب الغير باجر او بدون اجر الا بموافقة مجلس ادارة الشركة .\nج . اذا تخلف أي شخص من الاشخاص المذكورين في الفقرتين (أ) و(ب) من هذه المادة عن الحصول على الموافقة المنصوص عليها وتم ابلاغ المراقب فعلى المراقب امهاله مدة ثلاثين يوما من تاريخ تبلغه بذلك لتوفيق اوضاعه , وبخلاف ذلك يعتبر الشخص فاقدا لوظيفته او عضويته في مجلس الادارة حكما كما ويعاقب بغرامة لا تزيد على الف دينار والزامه بالضرر الذي لحق بالشركة او المساهمين .\nد . لا يجوز لعضو مجلس الادارة التصويت على أي قرار له فيه مصلحة شخصية مباشرة او غير مباشرة الا انه يجوز احتساب حضوره لغايات النصاب القانوني للمجلس .\nهـ . لا يجوز ان يكون لاعضاء مجلس ادارة الشركة المساهمة الخاصة او مديرها العام او أي موظف مسؤول فيها مصلحة مباشرة او غير مباشرة في العقود والمشاريع والارتباطات التي تعقد مع الشركة او لحسابها الا بموافقة الهيئة العامة غير العادية للشركة .","title":"التزامات مجلس الإدارة والموظفين","memo":"⭐ عضوية مجالس إدارة شركات مماثلة أو منافسة: بموافقة الهيئة العامة غير العادية\n⭐ عمل المدير العام والموظفين في شركة منافسة: بموافقة مجلس الإدارة\n⭐ المخالف يمهله المراقب ٣٠ يوماً لتوفيق أوضاعه وإلا يفقد وظيفته أو عضويته حكماً، وغرامة لا تزيد على ١٠٠٠ دينار\n⭐ العضو صاحب المصلحة لا يصوت لكن يحتسب حضوره للنصاب","qs":[{"q":"يحظر على أعضاء مجلس إدارة الشركة المساهمة الخاصة أن يكونوا أعضاء في مجالس إدارات شركات أخرى منافسة إلا بموافقة:","o":["الهيئة العامة غير العادية للشركة","مجلس إدارة الشركة","المراقب","الهيئة العامة العادية للشركة"],"a":0},{"q":"يحظر على المدير العام لشركة مساهمة خاصة تولي وظيفة في شركة منافسة إلا بموافقة:","o":["مجلس إدارة الشركة","الهيئة العامة غير العادية","المراقب","الوزير"],"a":0},{"q":"إذا تخلف عضو مجلس الإدارة عن الحصول على الموافقة اللازمة لعضويته في شركة منافسة وأبلغ المراقب، فإن المراقب يمهله لتوفيق أوضاعه مدة:","o":["ثلاثين يوماً","خمسة عشر يوماً","ستين يوماً","عشرة أيام"],"a":0},{"q":"عضو مجلس إدارة في شركة مساهمة خاصة له مصلحة شخصية مباشرة في قرار معروض على المجلس، فإنه:","o":["لا يجوز له التصويت ويجوز احتساب حضوره لغايات النصاب","يجوز له التصويت بعد الإفصاح عن مصلحته","لا يحتسب حضوره للنصاب ولا يصوت","يصوت بموافقة رئيس المجلس"],"a":0}]},{"n":"75 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"اعداد الحسابات :\nأ . على مجلس ادارة الشركة المساهمة الخاصة خلال الاشهر الثلاثة الاولى من السنة المالية الجديدة اعداد الميزانية السنوية للشركة وحساباتها الختامية بما في ذلك حساب الارباح والخسائر وبيان تدفقاتها النقدية والايضاحات المرفقة ، مدققة جميعها من مدققي حساباتها القانونيين وفقا لقواعد واصول ومعايير المحاسبة الدولية المتعارف عليها وكذلك اعداد التقرير السنوي عن اعمال الشركة وانجازاتها ومشاريعها وتقديمها جميعا الى الهيئة العامة للشركة وللمراقب مع التوصية المناسبة وارفاقها بالدعوة .\nب . على مجلس ادارة الشركة المساهمة الخاصة اعداد تقرير كل ستة اشهر يبين فيه المركز المالي للشركة ونتائج اعمالها ويصدق هذا التقرير من رئيس مجلس الادارة ويزود المراقب والهيئة بنسخة منه خلال ثلاثين يوما من انتهاء المدة .","title":"إعداد الحسابات الختامية","memo":"⭐ خلال الأشهر الثلاثة الأولى من السنة المالية: الميزانية والحسابات الختامية وبيان التدفقات النقدية مدققة وفق معايير المحاسبة الدولية + التقرير السنوي\n⭐ تقدم إلى الهيئة العامة والمراقب مع التوصية\n⭐ تقرير كل ٦ أشهر عن المركز المالي يصدقه رئيس المجلس، ويزود المراقب والهيئة بنسخة خلال ٣٠ يوماً من انتهاء المدة","qs":[{"q":"على مجلس إدارة الشركة المساهمة الخاصة إعداد الميزانية السنوية والحسابات الختامية خلال:","o":["الأشهر الثلاثة الأولى من السنة المالية الجديدة","الأشهر الأربعة الأولى من السنة المالية الجديدة","الشهرين الأولين من السنة المالية الجديدة","الأشهر الستة الأولى من السنة المالية الجديدة"],"a":0},{"q":"يعد مجلس إدارة الشركة المساهمة الخاصة تقريراً يبين المركز المالي ونتائج الأعمال كل:","o":["ستة أشهر","ثلاثة أشهر","سنة","شهر"],"a":0},{"q":"يصدق التقرير نصف السنوي للشركة المساهمة الخاصة من قبل:","o":["رئيس مجلس الإدارة","مدقق الحسابات","المراقب","المدير العام"],"a":0}]},{"n":"76 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"الهيئة العامة :\nأ . تتالف الهيئة العامة للشركة المساهمة الخاصة من جميع مساهميها الذين يحق لهم التصويت حسب احكام النظام الاساسي للشركة .\nب . مع مراعاة احكام الفقرة (ج) من هذه المادة تدعى الهيئة العامة للشركة المساهمة الخاصة لاجتماع عادي او اكثر ولاجتماع غير عادي او اكثر حسب ما ينص عليه النظام الاساسي للشركة وما يراه مجلس الادارة او المساهمون مناسبا .\nج . يتوجب على مجلس ادارة الشركة دعوة الهيئة العامة العادية للانعقاد مرة واحدة على الاقل خلال الاشهر الاربعة الاولى التالية لنهاية السنة المالية للشركة لمناقشة ما يلي واتخاذ القرارات المناسبة بشانها .\n١ . تقرير مجلس الادارة عن اعمال الشركة واوجه نشاطها ومركزها المالي خلال السنة المالية السابقة والخطة المستقبلية للشركة .\n٢ . مناقشة ميزانية الشركة وحساب ارباحها وخسائرها وتدفقاتها النقدية والمصادقة عليها بعد تقديم مدققي الحسابات لتقريرهم ومناقشته .\n٣ . انتخاب مجلس ادارة الشركة حسب مقتضى الحال ووفقا لاحكام نظام الشركة الاساسي .\n٤ . انتخاب مدقق حسابات الشركة وتحديد اتعابه .\n٥ . أي امور اخرى تتعلق بالشركة تعرض على الهيئة العامة من قبل مجلس الادارة او أي مساهم وتوافق الهيئة العامة على مناقشتها على ان لا يكون أي من تلك الامور مما لا يجوز عرضه على الهيئة العامة الا في اجتماع غير عادي لها بمقتضى هذا القانون او نظام الشركة الاساسي .","title":"الهيئة العامة العادية للشركة الخاصة","memo":"⭐ تتألف من جميع المساهمين الذين يحق لهم التصويت حسب النظام الأساسي\n⭐ يدعو المجلس الهيئة العامة العادية مرة على الأقل خلال الأشهر الأربعة الأولى التالية لنهاية السنة المالية\n⭐ تناقش: تقرير المجلس، الميزانية والحسابات، انتخاب المجلس، انتخاب المدقق وتحديد أتعابه، وأي أمور أخرى لا تختص بها الهيئة غير العادية","qs":[{"q":"يتوجب على مجلس إدارة الشركة المساهمة الخاصة دعوة الهيئة العامة العادية للانعقاد مرة واحدة على الأقل خلال:","o":["الأشهر الأربعة الأولى التالية لنهاية السنة المالية","الأشهر الثلاثة الأولى التالية لنهاية السنة المالية","الأشهر الستة الأولى التالية لنهاية السنة المالية","الشهر الأول التالي لنهاية السنة المالية"],"a":0},{"q":"تتألف الهيئة العامة للشركة المساهمة الخاصة من:","o":["جميع مساهميها الذين يحق لهم التصويت حسب النظام الأساسي","جميع مساهميها دون استثناء","المساهمين الذين يملكون ٥٪ فأكثر من رأس المال","أعضاء مجلس الإدارة وكبار المساهمين"],"a":0},{"q":"أي مما يلي لا يناقش في اجتماع الهيئة العامة العادية السنوي للشركة المساهمة الخاصة؟","o":["الأمور التي لا يجوز عرضها إلا في اجتماع غير عادي","انتخاب مدقق الحسابات وتحديد أتعابه","تقرير مجلس الإدارة والخطة المستقبلية","ميزانية الشركة وحساب أرباحها وخسائرها"],"a":0}]},{"n":"77 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"اختصاص الهيئة العامة غير العادية :\nأ . تختص الهيئة العامة غير العادية بمناقشة واقرار الامور التالية ولا يجوز مناقشة واقرار أي امر منها اذا لم يكن مدرجا في الدعوة الى الاجتماع :\n١ . تعديل عقد تاسيس الشركة او نظامها الاساسي على ان ترفق التعديلات المقترحة بالدعوة .\n٢ . تخفيض او زيادة راس مال الشركة على ان تراعي في تخفيض راس المال احكام المادة (٨٢ مكرر) من هذا الباب .\n٣ . دمج الشركة او اندماجها باحدى طرق الاندماج الواردة في هذا القانون .\n٤ . تصفية الشركة وفسخها .\n٥ . اقالة مجلس ادارة الشركة او احد اعضائه ما لم يكن العضو معينا من قبل فئة او نوع معين من الاسهم فتتم الاقالة في هذه الحالة وفق ما ينص عليه النظام الاساسي للشركة .\n٦ . بيع كامل موجودات الشركة او تملك ما يزيد على (%٥٠) من راسمال شركة اخرى .\n٧ . أي امر يدخل ضمن اختصاص الهيئة العامة غير العادية نص عليه هذا الباب او نظام الشركة الاساسي صراحة او دلالة .\n٨ . اصدار اسناد قرض قابلة للتحويل الى اسهم .\nب . يجوز للهيئة العامة غير العادية مناقشة واقرار أي امر من الامور التي تقع ضمن صلاحية الهيئة العامة العادية للشركة المساهمة الخاصة .","title":"اختصاص الهيئة العامة غير العادية","memo":"⭐ لا يجوز مناقشة أي أمر من اختصاصها ما لم يكن مدرجاً في الدعوة\n⭐ تختص بـ: تعديل العقد والنظام، تخفيض أو زيادة رأس المال، الدمج، التصفية، إقالة المجلس أو أحد أعضائه\n⭐ وكذلك: بيع كامل الموجودات أو تملك أكثر من ٥٠٪ من رأسمال شركة أخرى، إصدار إسناد قرض قابلة للتحويل\n⭐ يجوز لها مناقشة أمور الهيئة العامة العادية","qs":[{"q":"تختص الهيئة العامة غير العادية للشركة المساهمة الخاصة بإقرار تملك الشركة نسبة من رأسمال شركة أخرى تزيد على:","o":["٥٠٪","٢٥٪","٧٥٪","١٠٪"],"a":0},{"q":"أي مما يلي ليس من اختصاص الهيئة العامة غير العادية للشركة المساهمة الخاصة حصراً؟","o":["انتخاب مدقق حسابات الشركة","دمج الشركة","إصدار إسناد قرض قابلة للتحويل إلى أسهم","تصفية الشركة وفسخها"],"a":0},{"q":"عرض على الهيئة العامة غير العادية لشركة مساهمة خاصة اقتراح بتعديل نظامها الأساسي لم يكن مدرجاً في الدعوة، فإن:","o":["لا يجوز مناقشته وإقراره","يجوز مناقشته بموافقة أغلبية الحاضرين","يجوز مناقشته بموافقة المراقب","يجوز إقراره بأكثرية ٧٥٪ من الحاضرين"],"a":0}]},{"n":"78 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"اجتماعات الهيئة العامة :\nأ . بالاضافة الى أي طريقة اخرى يحددها النظام الاساسي للشركة تعقد اجتماعات الهيئة العامة بدعوة من مجلس الادارة او بناء على طلب عدد من مساهمين يملكون اسهما يحق لها التصويت في اجتماعات الهيئة العامة تشكل (%٢٥) على الاقل من مجموع الاصوات التي يحق لها حضور الاجتماع او بناء على طلب المراقب اذا قدم اليه طلب بذلك من احد اعضاء مجلس الادارة او مدقق حساباتها او من عدد من المساهمين يملكون اسهما يحق لها التصويت في اجتماعات الهيئة العامة تشكل (%١٥) على الاقل من مجموع الاصوات التي يحق لها حضور الاجتماع .\nب . تبلغ الدعوة لحضور اجتماع الهيئة العامة العادية او غير العادية لكل مساهم يحق له التصويت اما :\n١ . بارسال الدعوة بالبريد المسجل قبل خمسة عشر يوما على الاقل من التاريخ المحدد للاجتماع ويعتبر المساهم متبلغا خلال مدة لا تزيد على ستة ايام من ايداع الدعوة في البريد المسجل ، او .\n٢ . تسليمها باليد مقابل التوقيع بالتسلم ويعتبر المساهم متبلغا عند الاستلام .\nج . يجب ان تحدد الدعوة للاجتماع مكان وموعد الاجتماع .\nد . يعتبر المساهم متبلغا حكما اذا حضر الاجتماع ولم يعترض على صحة التبليغ او اذا ارسل كتابا لاحقا للشركة يوافق فيه على كل ما تم في الاجتماع .\nهـ . لا يدعى المراقب لحضور اجتماعات الهيئة العامة في الشركة المساهمة الخاصة سواء كانت عادية او غير عادية ولكن على مجلس الادارة فيها تزويد المراقب بنسخة من محضر الاجتماع خلال عشرة ايام من تاريخ انعقاده وللمراقب حضور الجلسة بناء على طلب مجلس الادارة او بناء على طلب خطي من مساهمين يحملون ما لا يقل عن ( %١٥) من الاسهم المكونة لراسمال الشركة .","title":"اجتماعات الهيئة العامة ودعوتها","memo":"⭐ تعقد بدعوة من المجلس أو بطلب مساهمين يملكون ٢٥٪ على الأقل من الأصوات، أو بطلب المراقب إذا طلب منه عضو مجلس أو المدقق أو مساهمون يملكون ١٥٪\n⭐ الدعوة بالبريد المسجل قبل ١٥ يوماً على الأقل (يعتبر متبلغاً خلال مدة لا تزيد على ٦ أيام) أو باليد\n⭐ لا يدعى المراقب للحضور، ويزود بنسخة المحضر خلال ١٠ أيام، ويحضر بطلب المجلس أو مساهمين يحملون ١٥٪","qs":[{"q":"يجوز لمساهمين في الشركة المساهمة الخاصة طلب عقد اجتماع الهيئة العامة مباشرة إذا كانوا يملكون أسهماً تشكل من مجموع الأصوات ما لا يقل عن:","o":["٢٥٪","١٥٪","١٠٪","٥٠٪"],"a":0},{"q":"ترسل دعوة اجتماع الهيئة العامة للشركة المساهمة الخاصة بالبريد المسجل قبل التاريخ المحدد للاجتماع بمدة لا تقل عن:","o":["خمسة عشر يوماً","سبعة أيام","عشرة أيام","ثلاثين يوماً"],"a":0},{"q":"على مجلس إدارة الشركة المساهمة الخاصة تزويد المراقب بنسخة من محضر اجتماع الهيئة العامة خلال:","o":["عشرة أيام من تاريخ انعقاده","خمسة عشر يوماً من تاريخ انعقاده","ثلاثين يوماً من تاريخ انعقاده","سبعة أيام من تاريخ انعقاده"],"a":0},{"q":"حضر مساهم اجتماع الهيئة العامة لشركة مساهمة خاصة ولم يعترض على صحة التبليغ رغم عدم وصول الدعوة إليه، فإنه:","o":["يعتبر متبلغاً حكماً","يحق له الطعن في الاجتماع لعدم تبليغه","يعتبر الاجتماع باطلاً بالنسبة له","يجب إعادة تبليغه خطياً"],"a":0}]},{"n":"79 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"نصاب اجتماعات الهيئة العامة :\nأ- ما لم يحدد النظام الاساسي للشركة نسبا اعلى ، يكون نصاب الاجتماع العادي للهيئة العامة للشركة المساهمة الخاصة قانونيا بحضور مساهمين يحملون اصالة او وكالة اسهما يزيد عدد اصواتها عن نصف عدد الاصوات التي يحق لها اتخاذ قرار في اجتماع الهيئة العامة كما يحددها النظام الاساسي للشركة ، فاذا لم يتوافر هذا النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع الى موعد اخر يعقد خلال خمسة عشر يوما من التاريخ المحدد للاجتماع الاول ويعاد تبليغ المساهمين الذين لم يحضروا ويكون النصاب في الاجتماع الثاني قانونيا بحضور مساهمين يحملون اصالة او وكالة اسهما يحق لها التصويت مهما بلغ عددها .\nب- ما لم يحدد النظام الاساسي للشركة نسبا اعلى يكون نصاب الاجتماع غير العادي للهيئة العامة للشركة المساهمة الخاصة قانونيا بحضور مساهمين يحملون اصالة او وكالة اسهما يبلغ عدد اصواتها ( %٧٥ ) او اكثر من عدد الاصوات التي يحق لها اتخاذ قرار في اجتماع الهيئة العامة كما يحددها النظام الاساسي للشركة فاذا لم يتوافر هذا النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع الى موعد اخر يعقد خلال خمسة عشر يوما من التاريخ المحدد للاجتماع الاول ويعاد تبليغ المساهمين الذين لم يحضروا ويكون النصاب في الاجتماع الثاني قانونيا بحضور ( %٥٠) او اكثر يحملون اصالة او وكالة اسهما يحق لها التصويت ، فاذا لم يتوافر هذا النصاب يلغى الاجتماع مهما كانت اسباب الدعوة اليه .\nج- اذا لم تتمكن الهيئة العامة في اجتماعها العادي او غير العادي من اتخاذ القرار المطلوب اتخاذه تنفيذا لحكم القانون في اجتماعين متتاليين فيعطي المراقب لها مهلة شهر لاتخاذ القرار المناسب ويتم قيـد الشـركـة فـي سـجل الشركات الموقوفـة لمـدة لا تزيـد على ثلاثة أشهر وفي حالة عدم صدور هذا القرار فيتم احالة الشركة الى المحكمة لاتخاذ الاجراء القانوني المناسب بما في ذلك تقرير تصفيتها .","title":"نصاب اجتماعات الهيئة العامة","memo":"⭐ العادي: أكثر من نصف الأصوات؛ وإلا يؤجل خلال ١٥ يوماً، والنصاب الثاني بأي عدد\n⭐ غير العادي: ٧٥٪ أو أكثر؛ وإلا يؤجل خلال ١٥ يوماً، والنصاب الثاني ٥٠٪ أو أكثر وإلا يلغى الاجتماع\n⭐ مهلة توافر النصاب: ساعة من الوقت المحدد\n⭐ العجز عن اتخاذ القرار في اجتماعين متتاليين: مهلة شهر من المراقب وقيد في سجل الشركات الموقوفة مدة لا تزيد على ٣ أشهر ثم الإحالة للمحكمة","qs":[{"q":"ما لم يحدد النظام الأساسي نسباً أعلى، يكون نصاب الاجتماع غير العادي الأول للهيئة العامة للشركة المساهمة الخاصة بحضور أسهم تمثل:","o":["٧٥٪ أو أكثر من الأصوات","أكثر من نصف الأصوات","٥٠٪ أو أكثر من الأصوات","ثلثي الأصوات"],"a":0},{"q":"إذا لم يتوافر نصاب الاجتماع العادي للهيئة العامة للشركة المساهمة الخاصة خلال ساعة، يؤجل إلى موعد آخر يعقد خلال:","o":["خمسة عشر يوماً من تاريخ الاجتماع الأول","عشرة أيام من تاريخ الاجتماع الأول","ثلاثين يوماً من تاريخ الاجتماع الأول","سبعة أيام من تاريخ الاجتماع الأول"],"a":0},{"q":"في الاجتماع الثاني المؤجل للهيئة العامة غير العادية للشركة المساهمة الخاصة، إذا لم يحضر ما نسبته ٥٠٪ أو أكثر من الأسهم فإن:","o":["الاجتماع يلغى مهما كانت أسباب الدعوة إليه","الاجتماع يعقد بمن حضر","يؤجل الاجتماع مرة ثالثة","يحال الأمر إلى المراقب لاتخاذ القرار"],"a":0},{"q":"إذا لم تتمكن الهيئة العامة للشركة المساهمة الخاصة من اتخاذ القرار المطلوب قانوناً في اجتماعين متتاليين، تقيد الشركة في سجل الشركات الموقوفة لمدة لا تزيد على:","o":["ثلاثة أشهر","شهر واحد","ستة أشهر","سنة واحدة"],"a":0}]},{"n":"80 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"قرارات الهيئة العامة :\nأ . تتخذ الهيئة العامة العادية قراراتها باغلبية الاصوات الحاضرة للاجتماع والتي يحق لها التصويت في الاجتماع على اي بند من بنود جدول اعمال الاجتماع ما لم ينص نظام الشركة الاساسي على نسبة اعلى .\nب . ما لم ينص نظام الشركة على نسبة اعلى ، تتخذ الهيئة العامة غير العادية قراراتها في اي من الامور الواردة في المادة ( ٧٧ / مكرر ) من هذا الباب باكثرية لا تقل عن ( %٧٥) من الاصوات الحاضرة والتي يحق لها التصويت في الاجتماع على أي بند من بنود جدول اعمال الاجتماع فاذا ناقشت الهيئة العامة غير العادية امور اخرى غير مخصصة للهيئة العامة غير العادية فتتخذ القرارات باغلبية الاصوات الحاضرة والتي يحق لها التصويت في الاجتماع على أي بند من بنود جدول اعمال الاجتماع .\nج . لا يجوز تعديل أي حقوق او مزايا ممنوحة بموجب عقد التاسيس والنظام الاساسي للشركة المساهمة الخاصة لاي من حملة نوع او فئة من الاسهم الا بموافقة حملة هذه الاسهم في اجتماع غير عادي يعقد لتلك الغاية يحضره اصالة او وكالة ما لا يقل عن ( %٧٥ ) من حملة ذلك النوع او الفئة من الاسهم وبقرار يتخذه ما لا يقل عن (%٧٥) من الحاضرين من حملة ذلك النوع او الفئة من الاسهم وذلك ما لم ينص النظام الاساسي للشركة على نسب اعلى .\nد . يجوز للمساهم في الشركة المساهمة الخاصة الذي يحق له التصويت حضور اجتماعات الهيئة العامة والادلاء باصواته اما شخصيا او ان يوكل غيره من المساهمين او غيرهم حسب ما يحدده النظام الاساسي للشركة .\nهـ . تعتبر قرارات الهيئة العامة العادية وغير العادية المتخذة وفقا لاحكام هذا القانون والنظام الاساسي للشركة ملزمة لمجلس الادارة والمساهمين الحاضرين للاجتماع والذين لم يحضروا .","title":"قرارات الهيئة العامة للشركة الخاصة","memo":"⭐ العادية: بأغلبية الأصوات الحاضرة ما لم ينص النظام على نسبة أعلى\n⭐ غير العادية في أمور المادة ٧٧ مكرر: بأكثرية لا تقل عن ٧٥٪ من الأصوات الحاضرة، وفي غيرها بالأغلبية\n⭐ تعديل حقوق فئة من الأسهم: اجتماع غير عادي لحملتها يحضره ٧٥٪ ويقرره ٧٥٪ من الحاضرين\n⭐ القرارات ملزمة للمجلس وللمساهمين الحاضرين والغائبين","qs":[{"q":"تتخذ الهيئة العامة غير العادية للشركة المساهمة الخاصة قراراتها في الأمور المخصصة لها بأكثرية لا تقل عن:","o":["٧٥٪ من الأصوات الحاضرة","أغلبية الأصوات الحاضرة","ثلثي الأصوات الحاضرة","٥٠٪ من مجموع أسهم الشركة"],"a":0},{"q":"ناقشت الهيئة العامة غير العادية لشركة مساهمة خاصة أمراً من اختصاص الهيئة العامة العادية، فتتخذ القرار فيه:","o":["بأغلبية الأصوات الحاضرة","بأكثرية ٧٥٪ من الأصوات الحاضرة","بالإجماع","بأكثرية ثلثي الأصوات الحاضرة"],"a":0},{"q":"قرارات الهيئة العامة للشركة المساهمة الخاصة المتخذة وفق القانون والنظام الأساسي:","o":["ملزمة لمجلس الإدارة والمساهمين الحاضرين والذين لم يحضروا","ملزمة للمساهمين الحاضرين فقط","ملزمة للمساهمين الذين وافقوا عليها فقط","غير ملزمة إلا بعد مصادقة المراقب عليها"],"a":0}]},{"n":"81 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"اصدار الاسهم :\nأ . يجوز للشركة المساهمة الخاصة بقرار من مجلس ادارتها اصدار أي اسهم مصرح باصدارها في عقد تاسيسها ونظامها الاساسي مع مراعاة أي شروط او قيود نص عليها عقد التاسيس والنظام الاساسي او قرارات الهيئة العامة .\nب . وللمجلس اصدار الاسهم المصرح باصدارها باي سعر سواء كان ذلك مساويا للقيمة الاسمية او اعلى او اقل منها ، وسواء كان ذلك نقدا او اسهما عينية او عن طريق تحويل اسناد القرض القابلة للتحويل الى اسهم او طرح اسهم لموظفي الشركة او صندوق ادخارهم او أي طريقة اخرى وفقا للشروط التي يحددها نظام الشركة الاساسي وهيئتها العامة .\nج . للمساهمين حق الاولوية في أي اصدارات جديدة من الاسهم ما لم ينص نظام الشركة الاساسي على غير ذلك .\nد . في حال طرح اسهم لموظفي الشركة باصدار خاص وفي حال اقرت الشركة اعطاء الموظفين حق خيار المساهمة والاكتتاب باسهم الشركة المطروحة ضمن مدة معينة فيجب ان لا تتجاوز المدة ما بين تاريخ اصدار حق خيار المساهمة من قبل الهيئة العامة وبين تاريخ اصدار تلك الاسهم للموظفين الذين منحوا خيار المساهمة والاكتتاب في حالة ممارستهم للحق عشر سنوات .\nهـ . في حال اقرت الشركة المساهمة الخاصة خطة لتمليك موظفيها او صندوق ادخارهم اسهما في الشركة ، فيتعين عليها الافصاح قبل نقل الملكية الى الموظفين او صندوق الادخار او منحهم حق خيار المساهمة والاكتتاب حسب واقع الحال عن جميع الامور المتعلقة بالشركة والتي يفصح عنها عادة لمساهمي الشركات المساهمة العامة ، وشروط الخطة وعلى سبيل المثال لا الحصر تلتزم الشركة بالافصاح عما يلي :\n١ . البيانات المالية الخاصة بالشركة واي معلومات مالية ذات اهمية على ان تشمل هذه المعلومات الميزانية العامة وحساب الارباح والخسائر وبيان التدفقات النقدية لاخر سنة مالية .\n٢ . المخاطر التي قد تنجم عن الاستثمار في اسهم الشركة والاثار الضريبية لهذا الاستثمار .\n٣ . القيود على نقل ملكية الاسهم .\n٤ . آلية تقييم سعر الاسهم عند بيعها والية تقييمها دوريا ان وجدت .\n٥ . طريقة تسديد ثمن الاسهم وآلية تقييم سعر الاسهم ، ان وجدت .","title":"إصدار الأسهم في الشركة الخاصة","memo":"⭐ يصدر مجلس الإدارة الأسهم المصرح بها بأي سعر: مساوٍ للقيمة الاسمية أو أعلى أو أقل\n⭐ للمساهمين حق الأولوية في الإصدارات الجديدة ما لم ينص النظام على غير ذلك\n⭐ المدة بين إصدار حق خيار المساهمة للموظفين وإصدار الأسهم لهم لا تتجاوز ١٠ سنوات\n⭐ خطة تمليك الموظفين تستوجب الإفصاح المسبق (البيانات المالية، المخاطر والآثار الضريبية، القيود على النقل، آلية التقييم والتسديد)","qs":[{"q":"يجوز لمجلس إدارة الشركة المساهمة الخاصة إصدار الأسهم المصرح بها بسعر:","o":["مساوٍ للقيمة الاسمية أو أعلى أو أقل منها","مساوٍ للقيمة الاسمية فقط","لا يقل عن القيمة الاسمية","أعلى من القيمة الاسمية فقط"],"a":0},{"q":"يجب ألا تتجاوز المدة بين تاريخ إصدار حق خيار المساهمة لموظفي الشركة المساهمة الخاصة وتاريخ إصدار الأسهم لهم:","o":["عشر سنوات","خمس سنوات","أربع سنوات","ثلاث سنوات"],"a":0},{"q":"حق الأولوية في الإصدارات الجديدة من أسهم الشركة المساهمة الخاصة:","o":["ثابت للمساهمين ما لم ينص النظام الأساسي على غير ذلك","غير ثابت إلا إذا نص عليه النظام الأساسي","مقرر للموظفين قبل المساهمين","مقرر لأعضاء مجلس الإدارة فقط"],"a":0}]},{"n":"82 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"تخفيض راس المال :\nأ . مع مراعاة ما ورد في هذا القانون للشركة المساهمة الخاصة بقرار من الهيئة العامة غير العادية تخفيض راسمالها اذا زاد عن حاجتها او لاطفاء خسائرها .\nب . على المراقب ان ينشر اعلانا على نفقة الشركة المساهمة الخاصة في صحيفة يومية واحدة على الاقل ثلاث مرات متتالية يتضمن قرار الهيئة العامة غير العادية بتخفيض راس المال ويحق لكل من دائنيها الاعتراض خطيا لدى المراقب خلال خمسة عشر يوما من تاريخ نشر اخر اعلان وللدائن حق الطعن في قرارات التخفيض لدى المحكمة اذا لم يتمكن المراقب من تسوية اعتراضه خلال ثلاثين يوما من تاريخ تقديمه على ان لا يوقف هذا الطعن اجراءات التخفيض الا اذا قررت المحكمة ذلك .\nج . يجوز للشركة المساهمة الخاصة تخفيض راسمالها المصرح به وغير المكتتب به او ان تلغي اي اسهم غير مكتتب بها قامت باعادة شرائها او استردادها حسب ما يسمح به نظامها الاساسي وقانون الاوراق المالية والانظمة والتعليمات الصادرة بموجبه وتخفيض راسمالها بما يعادل قيمة هذه الاسهم الاسمية المستردة او المعاد شراؤها دون الحاجة الى السير بالاجراءات المنصوص عليها في الفقرة ( أ ) من هذه المادة او وجود حق لاعتراض الدائنين .\nد . على الرغم مما ورد في هذه المادة والمادة (٨٦ مكرر ) من هذا القانون ، اذا كان الهدف اعادة هيكلة راس المال ، يجوز للشركة المساهمة الخاصة تخفيض راسمالها واعادة زيادته في نفس الاجتماع ، على ان تتضمن الدعوة المبررات والجدوى التي يهدف اليها هذا الاجراء وان يتم نشر اعلان اعادة هيكلة راس المال في صحيفتين محليتين ولمرة واحدة على الاقل .","title":"تخفيض رأس مال الشركة الخاصة","memo":"⭐ التخفيض بقرار الهيئة العامة غير العادية إذا زاد رأس المال عن الحاجة أو لإطفاء الخسائر\n⭐ ينشر المراقب إعلاناً على نفقة الشركة في صحيفة يومية ٣ مرات متتالية؛ وللدائنين الاعتراض خلال ١٥ يوماً من آخر إعلان\n⭐ الطعن لدى المحكمة إذا لم يسوّ المراقب الاعتراض خلال ٣٠ يوماً، ولا يوقف الطعن التخفيض إلا بقرار المحكمة\n⭐ إعادة الهيكلة: تخفيض وزيادة في نفس الاجتماع مع نشر الإعلان في صحيفتين محليتين لمرة واحدة على الأقل","qs":[{"q":"يحق لدائني الشركة المساهمة الخاصة الاعتراض خطياً لدى المراقب على قرار تخفيض رأس المال خلال:","o":["خمسة عشر يوماً من تاريخ نشر آخر إعلان","ثلاثين يوماً من تاريخ نشر أول إعلان","عشرة أيام من تاريخ قرار الهيئة العامة","ستين يوماً من تاريخ نشر آخر إعلان"],"a":0},{"q":"ينشر المراقب إعلان قرار تخفيض رأس مال الشركة المساهمة الخاصة في صحيفة يومية واحدة على الأقل:","o":["ثلاث مرات متتالية","مرة واحدة","مرتين متتاليتين","أربع مرات متتالية"],"a":0},{"q":"طعن دائن لدى المحكمة في قرار تخفيض رأس مال شركة مساهمة خاصة، فإن هذا الطعن:","o":["لا يوقف إجراءات التخفيض إلا إذا قررت المحكمة ذلك","يوقف إجراءات التخفيض حكماً","يوقف التخفيض إذا وافق المراقب","يلغي قرار التخفيض حكماً"],"a":0},{"q":"قررت شركة مساهمة خاصة إعادة هيكلة رأسمالها بتخفيضه وإعادة زيادته في نفس الاجتماع، فيجب نشر الإعلان:","o":["في صحيفتين محليتين ولمرة واحدة على الأقل","في صحيفة يومية واحدة ثلاث مرات متتالية","في الجريدة الرسمية فقط","لا يشترط النشر"],"a":0}]},{"n":"83 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"سجل المساهمين وتحويل الاسهم ورهنها :\nأ . تحتفظ الشركة المساهمة الخاصة في المركز الرئيسي لها بسجل خاص للمساهمين تدون فيه البيانات التالية عنهم ، ويكون مجلس ادارة الشركة مسؤولا عن هذا السجل ، وعن صحة البيانات المدرجة فيه :\n١ . اسم المساهم ولقبه اذا كان له لقب وجنسيته ومركز اقامته وعنوانه المختار للتبليغ على وجه التحديد .\n٢ . عدد الاسهم التي يملكها المساهم ونوعها وفئتها والقيمة الاسمية لها .\n٣ . التغيير الذي يطرا على اسهم المساهم ، وتفاصيله ، وتاريخ وقوعه .\n٤ . ما يقع على اسهم المساهم من حجر ورهن واي قيود اخرى والتفاصيل المتعلقة بها .\n٥ . اي بيانات اخرى يقرر مجلس الادارة تدوينها في السجل . ويحق لكل مساهم في الشركة الاطلاع على هذا السجل بنفسه او بواسطة من يفوضه خطيا بذلك .\nب . على مجلس ادارة الشركة المساهمة الخاصة تزويد المراقب سنويا بالبيانات المدونة في السجل الخاص بالمساهمين في الشركة المنصوص عليها في الفقرة ( أ ) من هذه المادة ، وذلك خلال الشهر الاول من انتهاء السنة المالية للشركة ، وبكل تعديل او تغيير يطرا على تلك البيانات خلال مدة لا تزيد على ثلاثين يوما من تاريخ وقوع التعديل او التغيير .\nج . لا تصدر الشركة المساهمة الخاصة شهادات باسهم مساهميها الا اذا نص نظام الشركة الاساسي على خلاف ذلك . وفي هذه الحالة يحدد النظام الاساسي شكل هذه الشهادات وكيفية اصدارها وتوقيعها واجراءات استبدالها في حالة ضياعها او تلفها او سرقتها .\nد . يتم تحويل اسهم الشركة المساهمة الخاصة بموجب سند تحويل بما يتوافق مع الصيغة المحددة في نظام الشركة الاساسي ويتضمن عنوان المحال له المختار للتبليغ على ان يتم توقيعه امام المراقب او كاتب العدل او احد المحامين المجازين في المملكة ويتم قيده وتوثيقه لدى المراقب والاعلان عنه ودفع الرسوم المقررة لذلك ولا يحتج بهذا التحويل من قبل الشركة او المساهمين او الغير ما لم يتم قيده وتوثيقه على الوجه المتقدم .\nهـ . لا يتوقف تنازل المساهم عن اسهمه في الشركة المساهمة الخاص بالبيع او خلافه على موافقة الشركة او المساهمين او مجلس الادارة ما لم ينص نظام الشركة على خلاف ذلك ، ولا يكون لاي قيد او حق اولوية متعلق باي سهم لم يتضمنه نظام الشركة الاساسي او سجل المساهمين اثرا تجاه اي شخص لم يعلم به .\nو . لا يعتبر اي رهن او حجز قضائي نافذا تجاه الشركة والمساهمين الاخرين والغير ما لم يتم قيد هذا الرهن او الحجز في سجل الشركة لدى المراقب ، وفي حالة ايقاع الرهن لا يجوز تحويل السهم المرهون او المحجوز الا بموافقة الراهن او الجهة التي اوقعت الحجز وتدفع الارباح الموزعة على الاسهم المرهونة او المحجوزة لمالك السهم ما لم ينص سند الرهن او طلب الحجز على خلاف ذلك .\nز . في حال ادراج اسهم الشركة لدى اي سوق تكون للاحكام الخاصة بذلك السوق المالي الاولوية بالتطبيق على احكام هذه المادة .","title":"سجل المساهمين وتحويل الأسهم ورهنها","memo":"⭐ سجل المساهمين في المركز الرئيسي ومجلس الإدارة مسؤول عنه\n⭐ تزويد المراقب سنوياً خلال الشهر الأول من انتهاء السنة المالية، وبالتعديلات خلال مدة لا تزيد على ٣٠ يوماً\n⭐ لا تصدر شهادات أسهم إلا إذا نص النظام على ذلك\n⭐ سند التحويل يوقع أمام المراقب أو الكاتب العدل أو محامٍ مجاز، ولا يحتج به ما لم يقيد لدى المراقب؛ والرهن والحجز غير نافذين ما لم يقيدا","qs":[{"q":"على مجلس إدارة الشركة المساهمة الخاصة تزويد المراقب سنوياً ببيانات سجل المساهمين خلال:","o":["الشهر الأول من انتهاء السنة المالية","الأشهر الثلاثة الأولى من انتهاء السنة المالية","خمسة عشر يوماً من انتهاء السنة المالية","الأشهر الأربعة الأولى من انتهاء السنة المالية"],"a":0},{"q":"الأصل في الشركة المساهمة الخاصة بشأن شهادات الأسهم أنها:","o":["لا تصدر شهادات بأسهم مساهميها إلا إذا نص النظام الأساسي على خلاف ذلك","تصدر شهادات لجميع المساهمين وجوباً","تصدر الشهادات بطلب من المراقب","تصدر الشهادات لكبار المساهمين فقط"],"a":0},{"q":"أي مما يلي ليس من الجهات التي يجوز توقيع سند تحويل أسهم الشركة المساهمة الخاصة أمامها؟","o":["مدقق حسابات الشركة","المراقب","الكاتب العدل","أحد المحامين المجازين في المملكة"],"a":0},{"q":"رهن مساهم أسهمه في شركة مساهمة خاصة ولم يقيد الرهن في سجل الشركة لدى المراقب، فإن الرهن:","o":["لا يعتبر نافذاً تجاه الشركة والمساهمين الآخرين والغير","نافذ تجاه الجميع من تاريخ توقيعه","نافذ تجاه الشركة فقط","نافذ بعد موافقة مجلس الإدارة"],"a":0}]},{"n":"84 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"الاعفاء من النشر :\nتعفى الشركة المساهمة الخاصة من نشر ميزانيتها السنوية وحساب ارباحها وخسائرها وبيان تدفقاتها النقدية وتقرير مجلس ادارتها في الصحف المحلية ، ما لم يتطلب ذلك اي تشريع اخر او انظمة او تعليمات صادرة بموجبه .","title":"الإعفاء من نشر البيانات المالية","memo":"⭐ تعفى الشركة المساهمة الخاصة من نشر ميزانيتها وحساب الأرباح والخسائر وبيان التدفقات النقدية وتقرير المجلس في الصحف المحلية\n⭐ ما لم يتطلب ذلك تشريع آخر أو أنظمة أو تعليمات صادرة بموجبه","qs":[{"q":"بالنسبة لنشر ميزانية الشركة المساهمة الخاصة وتقرير مجلس إدارتها في الصحف المحلية، فإن الشركة:","o":["تعفى من النشر ما لم يتطلب ذلك تشريع آخر","ملزمة بالنشر في صحيفتين محليتين","ملزمة بالنشر في صحيفة واحدة","تنشرها بقرار من المراقب في كل سنة"],"a":0},{"q":"أي مما يلي ليس من البيانات التي تعفى الشركة المساهمة الخاصة من نشرها في الصحف المحلية؟","o":["قرار تخفيض رأس المال","الميزانية السنوية","بيان التدفقات النقدية","تقرير مجلس الإدارة"],"a":0}]},{"n":"85 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"الاحتياطيات :\nأ . على الشركة المساهمة الخاصة ان تقتطع (%١٠) من ارباحها السنوية الصافية لحساب الاحتياطي الاجباري وان تستمر على هذا الاقتطاع لكل سنة على ان لا يتجاوز مجموع ما يقتطع ( %٢٥) من راس مال الشركة المكتتب به .\nب . للهيئة العامة في الشركة المساهمة الخاصة ان تقرر اقتطاع نسبة اضافية معينة من الارباح السنوية للشركة لحساب الاحتياطي الاختياري ، وللهيئة العامة ان تقرر استخدام هذا الاحتياطي لاغراض الشركة او توزيعه على المساهمين كارباح اذا لم يستخدم في تلك الاغراض .\nج. للهيئة العامة وبعد استنفاد الاحتياطيات الأخرى ان تقرر في اجتماع غير عادي إطفاء خسائرها من المبالغ المتجمعة في حساب الاحتياطي الإجباري على ان يعاد بناؤه وفقاً لأحكام الفقرة (أ) من هذه المادة.","title":"الاحتياطيات في الشركة الخاصة","memo":"⭐ الاحتياطي الإجباري: اقتطاع ١٠٪ من الأرباح السنوية الصافية بحيث لا يتجاوز المجموع ٢٥٪ من رأس المال المكتتب به\n⭐ الاحتياطي الاختياري: نسبة إضافية تقررها الهيئة العامة، ويجوز توزيعه أرباحاً إذا لم يستخدم\n⭐ إطفاء الخسائر من الاحتياطي الإجباري: بعد استنفاد الاحتياطيات الأخرى في اجتماع غير عادي على أن يعاد بناؤه","qs":[{"q":"تقتطع الشركة المساهمة الخاصة من أرباحها السنوية الصافية لحساب الاحتياطي الإجباري نسبة:","o":["١٠٪","٥٪","٢٠٪","٢٥٪"],"a":0},{"q":"يتوقف اقتطاع الاحتياطي الإجباري في الشركة المساهمة الخاصة عندما يبلغ مجموعه:","o":["٢٥٪ من رأس المال المكتتب به","١٠٠٪ من رأس المال المكتتب به","٥٠٪ من رأس المال المكتتب به","٢٥٪ من رأس المال المصرح به"],"a":0},{"q":"يجوز للهيئة العامة للشركة المساهمة الخاصة إطفاء خسائرها من الاحتياطي الإجباري بشرط:","o":["استنفاد الاحتياطيات الأخرى وأن يتم القرار في اجتماع غير عادي","موافقة المراقب المسبقة","أن تتجاوز الخسائر نصف رأس المال","أن يتم القرار في اجتماع عادي بالأغلبية"],"a":0}]},{"n":"86 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"الخسائر الجسيمة :\nمع مراعاة أحكام قانون الإعسار اذا تعرضت الشركة المساهمة الخاصة لخسائر جسيمة بحيث اصبحت غير قادرة على الوفاء بالتزاماتها اتجاه دائنيها فيترتب على مجلس الادارة فيها دعوة الهيئة العامة غير العادية للشركة الى اجتماع لتصدر قرارها اما بتصفية الشركة او باصدار اسهم جديدة او باي قرار اخر يكفل قدرتها على الوفاء بالتزاماتها ، واذا لم تتمكن الهيئة العامة من اتخاذ قرار واضح بذلك خلال اجتماعين متتاليين فيمنح المراقب الشركة مهلة شهر لاتخاذ القرار المطلوب واذا لم تتمكن من ذلك فتطبـق عليهـا إجـراءات الإعسـار الـواردة في قانون الإعسار.","title":"الخسائر الجسيمة في الشركة الخاصة","memo":"⭐ عند العجز عن الوفاء بالالتزامات بسبب خسائر جسيمة يدعو المجلس الهيئة العامة غير العادية\n⭐ تقرر: التصفية أو إصدار أسهم جديدة أو أي قرار يكفل الوفاء\n⭐ إذا تعذر القرار في اجتماعين متتاليين يمنح المراقب مهلة شهر، ثم تطبق إجراءات قانون الإعسار","qs":[{"q":"إذا تعرضت الشركة المساهمة الخاصة لخسائر جسيمة جعلتها غير قادرة على الوفاء بالتزاماتها، يدعو مجلس الإدارة:","o":["الهيئة العامة غير العادية","الهيئة العامة العادية","المراقب لحضور اجتماع المجلس","الدائنين إلى اجتماع خاص"],"a":0},{"q":"إذا لم تتمكن الهيئة العامة للشركة المساهمة الخاصة المتعثرة من اتخاذ قرار واضح خلال اجتماعين متتاليين، ثم لم تتخذه خلال المهلة الممنوحة، فإن:","o":["تطبق عليها إجراءات الإعسار الواردة في قانون الإعسار","تحل الشركة حكماً بقرار من المراقب","تتحول إلى شركة ذات مسؤولية محدودة","يعين الوزير مجلس إدارة مؤقتاً"],"a":0},{"q":"المهلة التي يمنحها المراقب للشركة المساهمة الخاصة المتعثرة لاتخاذ القرار المطلوب بعد فشل اجتماعين متتاليين هي:","o":["شهر","ثلاثة أشهر","خمسة عشر يوماً","ستة أشهر"],"a":0}]},{"n":"87 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"توزيع الارباح :\nأ . للشركة المساهمة الخاصة بموافقة الهيئة العامة العادية توزيع ارباح على المساهمين اما نقدا او عينا او باصدار اسهم جديدة ، وفي حالة اصدار اسهم جديدة فتعتبر هذه الاسهم زيادة في راس المال بموافقة الهيئة العامة غير العادية ، ولا يعتبر تقسيم الاسهم المصدرة الى اسهم اكثر عددا زيادة في راس المال .\nب . مع مراعاة اي شروط اضافية في نظام الشركة الاساسي ، يجوز للشركة المساهمة الخاصة توزيع الارباح من ارباحها السنوية الصافية او من ارباحها السنوية المدورة من السنين السابقة او من الاحتياطي الاختياري ، ولا يجوز توزيع ارباح من الاحتياطي الاجباري للشركة.\nج . ينشا حق المساهم في الارباح بصدور قرار الهيئة العامة بتوزيعها .\nد . يكون الحق في استيفاء الربح تجاه الشركة لمالك السهم بتاريخ اجتماع الهيئة العامة الذي تقرر فيه توزيع الارباح ، ما لم ينص نظام الشركة الاساسي على خلاف ذلك .\nهـ . تلتزم الشركة بدفع الارباح المقرر توزيعها على المساهمين خلال ستين يوما من تاريخ اجتماع الهيئة العامة او التاريخ الذي حددته الهيئة العامة لتوزيع الارباح ، وفي حال الاخلال بذلك تلتزم الشركة بدفع فائدة للمساهم بمعدل سعر الفائدة السائد على الودائع لاجل خلال فترة التاخير ، على ان لا تتجاوز مدة تاخير دفع الارباح ستة اشهر من تاريخ استحقاقها .","title":"توزيع الأرباح في الشركة الخاصة","memo":"⭐ التوزيع بموافقة الهيئة العامة العادية نقداً أو عيناً أو بإصدار أسهم جديدة (زيادة رأس المال بموافقة غير العادية)\n⭐ يجوز التوزيع من الأرباح الصافية أو المدورة أو الاحتياطي الاختياري، ولا يجوز من الاحتياطي الإجباري\n⭐ ينشأ الحق بصدور قرار الهيئة العامة، والحق لمالك السهم بتاريخ الاجتماع\n⭐ الدفع خلال ٦٠ يوماً وإلا فائدة بسعر الودائع لأجل، ولا يتجاوز التأخير ٦ أشهر","qs":[{"q":"تلتزم الشركة المساهمة الخاصة بدفع الأرباح المقرر توزيعها خلال:","o":["ستين يوماً من تاريخ اجتماع الهيئة العامة أو التاريخ الذي حددته","ثلاثين يوماً من تاريخ اجتماع الهيئة العامة","تسعين يوماً من تاريخ اجتماع الهيئة العامة","ستة أشهر من تاريخ اجتماع الهيئة العامة"],"a":0},{"q":"لا يجوز للشركة المساهمة الخاصة توزيع أرباح من:","o":["الاحتياطي الإجباري","الاحتياطي الاختياري","الأرباح السنوية الصافية","الأرباح المدورة من السنين السابقة"],"a":0},{"q":"ينشأ حق المساهم في أرباح الشركة المساهمة الخاصة:","o":["بصدور قرار الهيئة العامة بتوزيعها","بانتهاء السنة المالية","بمصادقة المدقق على الحسابات الختامية","بتوصية مجلس الإدارة بالتوزيع"],"a":0},{"q":"قسمت شركة مساهمة خاصة أسهمها المصدرة إلى أسهم أكثر عدداً، فإن ذلك:","o":["لا يعتبر زيادة في رأس المال","يعتبر زيادة في رأس المال تتطلب موافقة الهيئة العامة غير العادية","يعتبر توزيعاً للأرباح","يعتبر تخفيضاً لرأس المال"],"a":0}]},{"n":"88 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"تنقضي الشركة المساهمة الخاصة حسب احكام تصفية الشركات المساهمة العامة مع مراعاة اي اولويات او شروط نص عليها عقد نظام الشركة الاساسي بخصوص مساهمي الشركة وانواع وفئات اسهمهم .","title":"انقضاء الشركة المساهمة الخاصة","memo":"⭐ تنقضي حسب أحكام تصفية الشركات المساهمة العامة\n⭐ مع مراعاة الأولويات والشروط في النظام الأساسي بخصوص المساهمين وأنواع وفئات أسهمهم","qs":[{"q":"تنقضي الشركة المساهمة الخاصة وفق أحكام:","o":["تصفية الشركات المساهمة العامة مع مراعاة أولويات نظامها الأساسي","تصفية الشركات ذات المسؤولية المحدودة","تصفية شركات التضامن","قانون الإعسار حصراً"],"a":0},{"q":"عند تصفية الشركة المساهمة الخاصة تراعى الأولويات والشروط المنصوص عليها في نظامها الأساسي بخصوص:","o":["مساهمي الشركة وأنواع وفئات أسهمهم","أعضاء مجلس الإدارة فقط","الدائنين الممتازين فقط","موظفي الشركة فقط"],"a":0}]},{"n":"89 مكرر","chapter":"الباب الخامس - الشركات المساهمة الخاصة","notes":["تاريخ السريان ٢٠٠٢-٠٢-١٧"],"source":"أ . تطبق الاحكام المتعلقة بالشركات المساهمة العامة الواردة في هذا القانون على الشركة المساهمة الخاصة على كل ما لم يرد بشانه نص صريح في هذا الباب او في عقد تاسيسها او نظام الاساسي .\nب . تخضع الشركات المساهمة الخاصة لاحكام المادة ( ١٦٧) من القانون الاصلي .\nج. تخضع الشركات المساهمة الخاصة والتي يزيد رأسمالها المكتتب به على خمسمائة الف دينار لأحكام المادة (١٥١) من هذا القانون .\nد . تطبق الاحكام الواردة في كل من الباب الرابع عشر ( الرقابة على الشركات ) والباب الخامس عشر ( العقوبات ) والاحكام الختامية الواردة في القانون الاصلي على الشركات المساهمة الخاصة .","title":"تطبيق أحكام المساهمة العامة على الخاصة","memo":"⭐ تطبق أحكام المساهمة العامة على كل ما لم يرد بشأنه نص في الباب أو العقد أو النظام\n⭐ تخضع لأحكام المادة (١٦٧)\n⭐ الشركات التي يزيد رأسمالها المكتتب به على ٥٠٠ ألف دينار تخضع لأحكام المادة (١٥١)\n⭐ تطبق عليها أبواب الرقابة على الشركات والعقوبات والأحكام الختامية","qs":[{"q":"تخضع الشركة المساهمة الخاصة لأحكام المادة (١٥١) من القانون إذا زاد رأسمالها المكتتب به على:","o":["خمسمائة ألف دينار","مئة ألف دينار","خمسين ألف دينار","مليون دينار"],"a":0},{"q":"في المسائل التي لم يرد بشأنها نص صريح في باب الشركة المساهمة الخاصة أو عقد تأسيسها أو نظامها الأساسي تطبق:","o":["الأحكام المتعلقة بالشركات المساهمة العامة","الأحكام المتعلقة بالشركات ذات المسؤولية المحدودة","أحكام القانون المدني مباشرة","تعليمات يصدرها المراقب"],"a":0},{"q":"نصت المادة صراحة على تطبيق أحكام الباب الخامس عشر من القانون على الشركات المساهمة الخاصة، وهو الباب المتعلق بـ:","o":["العقوبات","الشركات المعفاة","الشركات غير الربحية","الشركات القابضة"],"a":0}]},{"n":"90","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تتألف الشركة المساهمة العامة من عدد من المؤسسين لا يقل عن اثنين يكتتبون فيها باسهم قابلة للادراج في اسواق للأوراق المالية وللتداول والتحويل وفقاً لاحكام هذا القانون واي تشريعات اخرى معمول بها .\nب - مع مراعاة احكام الفقرة (ب) من المادة (٩٩) من هذا القانون يجوز للوزير بناء على تنسيب مبرر من المراقب الموافقة على ان يكون مؤسس الشركة المساهمة العامة المحدودة شخصاً واحداً او ان تؤول ملكية الشركة الى مساهم واحد في حال شرائه كامل اسهمهما\nج - تستمد الشركة المساهمة العامة اسمها من غاياتها على ان تتبعه اينما ورد عبارة ( شركة مساهمة عامة محدودة ) ، ولا يجوز ان تكون باسم شخص طبيعي الا اذا كانت غاية الشركة استثمار براءة اختراع مسجلة بصورة قانونية باسم ذلك الشخص .\nد - تكون مدة الشركة المساهمة العامة غير محدودة الا اذا كانت غاياتها القيام بعمل معين ، فتنقضي الشركة بانتهائه .","title":"تأسيس الشركة المساهمة العامة واسمها ومدتها","memo":"⭐ لا يقل عدد المؤسسين عن ٢، بأسهم قابلة للإدراج والتداول\n⭐ يجوز للوزير بتنسيب مبرر من المراقب الموافقة على مؤسس واحد أو أيلولة الملكية لمساهم واحد\n⭐ الاسم مستمد من الغايات متبوعاً بعبارة (شركة مساهمة عامة محدودة)، ولا يكون باسم شخص طبيعي إلا لاستثمار براءة اختراع مسجلة باسمه\n⭐ مدتها غير محدودة إلا إذا كانت غايتها عملاً معيناً فتنقضي بانتهائه","qs":[{"q":"الحد الأدنى لعدد مؤسسي الشركة المساهمة العامة كقاعدة عامة هو:","o":["اثنان","ثلاثة","خمسة","سبعة"],"a":0},{"q":"يجوز أن يكون مؤسس الشركة المساهمة العامة شخصاً واحداً بموافقة:","o":["الوزير بناء على تنسيب مبرر من المراقب","المراقب بناء على طلب المؤسس","هيئة الأوراق المالية","مجلس الوزراء بناء على تنسيب الوزير"],"a":0},{"q":"يجوز أن تكون الشركة المساهمة العامة باسم شخص طبيعي في حالة:","o":["كانت غايتها استثمار براءة اختراع مسجلة قانونياً باسم ذلك الشخص","كان ذلك الشخص أكبر المساهمين فيها","وافق الوزير على ذلك","كان ذلك الشخص رئيساً لمجلس إدارتها"],"a":0},{"q":"تأسست شركة مساهمة عامة لغاية إنشاء مشروع معين، فإن مدتها:","o":["تنقضي بانتهاء ذلك العمل","غير محدودة","خمس وعشرون سنة قابلة للتجديد","يحددها المراقب في شهادة التسجيل"],"a":0}]},{"n":"91","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تعتبر الذمة المالية للشركة المساهمة العامة مستقلة عن الذمة المالية لكل مساهم فيها، وتكون الشركة بموجوداتها وأموالها مسؤولة عن الديون والألتزامات المترتبة عليها ولا يكون المساهم مسؤولاً تجاه الشركة عن تلك الديون والالتزامات، الا بمقدار الأسهم التي يملكها في الشركة .","title":"الذمة المالية للشركة المساهمة العامة","memo":"⭐ ذمة الشركة المالية مستقلة عن ذمة كل مساهم\n⭐ الشركة مسؤولة بموجوداتها وأموالها عن ديونها والتزاماتها\n⭐ مسؤولية المساهم بمقدار الأسهم التي يملكها فقط","qs":[{"q":"تكون مسؤولية المساهم في الشركة المساهمة العامة عن ديونها والتزاماتها:","o":["بمقدار الأسهم التي يملكها في الشركة","مسؤولية تضامنية في جميع أمواله","بمقدار ضعف قيمة أسهمه","بنسبة مساهمته من مجموع الديون في أمواله الخاصة"],"a":0},{"q":"ترتبت على شركة مساهمة عامة ديون تزيد على موجوداتها، فإن الدائنين:","o":["يستوفون ديونهم من موجودات الشركة وأموالها دون الرجوع على أموال المساهمين الخاصة","يرجعون على المساهمين بالتضامن في أموالهم الخاصة","يرجعون على أعضاء مجلس الإدارة حكماً","يرجعون على المؤسسين فقط"],"a":0}]},{"n":"92","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يقدم طلب تأسيس الشركة من قبل مؤسسي الشركة إلى المراقب على النموذج المقرر لهذا الغرض مرفقاً بما يلي :-\n١ - عقد تأسيس الشركة .\n٢ - نظامها الأساسي .\n٣ - أسماء مؤسسي الشركة .\n٤ - محضر اجتماع المؤسسين المتضمن انتخاب لجنة المؤسسين التي تتولى الاشراف على اجراءات التاسيس وتحديد صلاحية التوقيع عن الشركة خلال مدة التاسيس .\n٥ - اسم مدقق الحسابات الذي اختاره المؤسسون لمرحلة التاسيس .\nب - يجب أن يتضمن عقد تأسيس الشركة المساهمة ونظامها الأساسي البيانات التالية:-\n١ - إسم الشركة .\n٢ - مركزها الرئيسي .\n٣ - غايات الشركة .\n٤ - أسماء مؤسسي الشركة وجنسياتهم وعناوينهم المختارة للتبليغ وعدد الأسهم المكتتب بها .\n٥ - رأس مال الشركة المصرح به والجزء المكتتب به فعلاً .\n٦ - بيان بالمقدمات العينية في الشركة إن وجدت وقيمتها .\n٧ - فيما اذا كان للمساهمين وحاملي اسناد القرض القابلة للتحويل حق أولوية للاكتتاب في أي اصدارات جديدة للشركة .\n٨ - كيفية ادارة الشركة والمفوضين بالتوقيع في الفترة ما بين تأسيسها واجتماع الهيئة العامة الأول الذي يجب أن يعقد خلال ستين يوماً من تاريخ تأسيس الشركة .\n٩ - تحديد اسلوب وشكل وطريقة دعوة مجلس ادارة الشركة للاجتماع .\nج - يوقع عقد تأسيس الشركة المساهمة العامة ونظامها الأساسي من كل مؤسس أمام المراقب أو من يفوضه خطيا بذلك . ويجوز توقيعها أمام الكاتب العدل أو أحد المحامين المجازين .","title":"طلب تأسيس الشركة المساهمة العامة","memo":"⭐ يقدم الطلب من المؤسسين إلى المراقب على النموذج المقرر مع: العقد، النظام، أسماء المؤسسين، محضر انتخاب لجنة المؤسسين، اسم مدقق الحسابات لمرحلة التأسيس\n⭐ اجتماع الهيئة العامة الأول يجب أن يعقد خلال ٦٠ يوماً من تاريخ التأسيس\n⭐ يوقع العقد والنظام أمام المراقب أو من يفوضه خطياً، ويجوز أمام الكاتب العدل أو محامٍ مجاز","qs":[{"q":"يجب أن يعقد اجتماع الهيئة العامة الأول للشركة المساهمة العامة خلال:","o":["ستين يوماً من تاريخ تأسيس الشركة","ثلاثين يوماً من تاريخ تأسيس الشركة","شهر من تاريخ صدور شهادة التسجيل","تسعين يوماً من تاريخ تأسيس الشركة"],"a":0},{"q":"أي مما يلي ليس من الوثائق التي يرفق بها طلب تأسيس الشركة المساهمة العامة؟","o":["الميزانية الافتتاحية المدققة للشركة","محضر اجتماع المؤسسين المتضمن انتخاب لجنة المؤسسين","اسم مدقق الحسابات الذي اختاره المؤسسون لمرحلة التأسيس","أسماء مؤسسي الشركة"],"a":0},{"q":"يوقع عقد تأسيس الشركة المساهمة العامة ونظامها الأساسي من كل مؤسس أمام:","o":["المراقب أو من يفوضه خطياً، ويجوز أمام الكاتب العدل أو أحد المحامين المجازين","الوزير حصراً","مدقق حسابات الشركة","رئيس لجنة المؤسسين"],"a":0}]},{"n":"93","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز القيام بأي عمل من الأعمال التالية الا من قبل شركات مساهمة عامة يتم تأسيسها وتسجيلها وفقاً لأحكام هذا القانون .\nأ - اعمال البنوك والشركات المالية والتأمين بأنواعه المختلفة .\nب - الشركات ذات الامتياز .","title":"الأعمال المقتصرة على الشركات المساهمة العامة","memo":"⭐ لا يجوز القيام بها إلا من شركات مساهمة عامة: أعمال البنوك والشركات المالية والتأمين بأنواعه\n⭐ وكذلك الشركات ذات الامتياز","qs":[{"q":"أي من الأعمال التالية لا يجوز القيام بها إلا من قبل شركة مساهمة عامة؟","o":["أعمال التأمين بأنواعه المختلفة","أعمال المقاولات","أعمال التجارة العامة","أعمال الاستشارات الهندسية"],"a":0},{"q":"أراد مستثمرون تأسيس شركة ذات امتياز، فإن الشكل القانوني الواجب لها هو:","o":["شركة مساهمة عامة","شركة ذات مسؤولية محدودة","شركة مساهمة خاصة","شركة توصية بالأسهم"],"a":0}]},{"n":"94","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يصدر الوزير بناء على تنسيب المراقب قراره بقبول تسجيل الشركة أو رفض هذا التسجيل خلال مدة أقصاها ثلاثين يوماً من تاريخ تنسيب المراقب وعلى المراقب أن يجري التنسيب خلال ثلاثين يوماً من تاريخ تقديم الطلب اليه موقعاً من المؤسسين ومستكملاً للشروط القانونية، فإذا لم يصدر الوزير قراره خلال تلك المدة يعتبر الطلب مقبولاً .\nب - لمؤسسي الشركة في حالة رفض الوزير تسجيل الشركة الطعن في قراره لدى المحكمة الإدارية .","title":"قبول ورفض تسجيل الشركة المساهمة العامة","memo":"⭐ يجري المراقب التنسيب خلال ٣٠ يوماً من تقديم الطلب المستكمل\n⭐ يصدر الوزير قراره بالقبول أو الرفض خلال ٣٠ يوماً من التنسيب، وإلا يعتبر الطلب مقبولاً\n⭐ الطعن في قرار الرفض لدى المحكمة الإدارية","qs":[{"q":"الجهة التي تصدر قرار قبول أو رفض تسجيل الشركة المساهمة العامة هي:","o":["الوزير بناء على تنسيب المراقب","المراقب بناء على تنسيب الوزير","هيئة الأوراق المالية","مجلس الوزراء"],"a":0},{"q":"إذا لم يصدر الوزير قراره بشأن طلب تسجيل الشركة المساهمة العامة خلال المدة القانونية من تاريخ تنسيب المراقب، فإن الطلب:","o":["يعتبر مقبولاً","يعتبر مرفوضاً","يحال إلى مجلس الوزراء","يعاد إلى المراقب لإعادة التنسيب"],"a":0},{"q":"على المراقب إجراء التنسيب بشأن طلب تسجيل الشركة المساهمة العامة خلال:","o":["ثلاثين يوماً من تاريخ تقديم الطلب المستكمل","خمسة عشر يوماً من تاريخ تقديم الطلب","ستين يوماً من تاريخ تقديم الطلب","عشرة أيام من تاريخ تقديم الطلب"],"a":0}]},{"n":"95","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يحدد رأس مال الشركة المساهمة العامة المصرح به وكذلك الجزء المكتتب به فعلاً بالدينار الأردني ويقسم الى أسهم أسمية وتكون قيمة السهم ديناراً واحداً، شريطة أن لا يقل رأس المال المصرح به عن خمسمائة ألف ( ٥٠٠.٠٠٠ ) دينار ورأس المال المكتتب به عن مئة ألف (\n١٠٠.٠٠٠ ) دينار أو عشرين بالمائة ( %٢٠ ) من رأس المال المصرح به أيهما أكثر .\nب - مع مراعاة احكام الفقرة (د) من هذه المادة يسدد الجزء غير المكتتب به خلال ثلاث سنوات من تاريخ تسجيل الشركة او زيادة راس المال ، حسب مقتضى الحال ، وفي حال التخلف عن تسديد الجزء غير المكتتب به خلال هذه المدة يراعى ما يلي :\n١ - اذا كان رأس المال المكتتب به يزيد عن خمسمائة ألف ( ٥٠٠.٠٠٠ ) دينار عند انتهاء المدة فيصبح رأس مال الشركة المصرح به هو رأس مالها المكتتب به فعلاً .\n٢ - أذا كان رأس المال المكتتب به يقل عن خمسمائة ألف ( ٥٠٠.٠٠٠ ) دينار عند انتهاء المدة فعلى المراقب انذار الشركة بضرورة العمل على تسديد فرق المبلغ اللازم حتى يصبح رأس مال الشركة المكتتب به فعلاً خمسمائة ألف ( ٥٠٠.٠٠٠ ) دينار وذلك خلال ثلاثين يوماً من تاريخ تبليغ الانذار إلى الشركة، فإذا تخلفت الشركة عن ذلك فيحق للمراقب بعدها الطلب إلى المحكمة تصفية الشركة حسب أحكام المادة (\n٢٢٦ ) من هذا القانون .\nج - يجوز لمجلس ادارة الشركة اعادة طرح الاسهم غير المكتتب بها من رأس مال الشركة المصرح به حسب ما تقتضيه مصلحة الشركة وبالقيمة التي يراها المجلس مناسبة سواء كانت هذه القيمة مساوية لقيمة السهم الاسمية او اعلى او اقل منها على ان تصدر هذه الاسهم وفقا لاحكام الانظمة والتشريعات المعمول بها .\nد - على مجلس ادارة الشركة المساهمة العامة الحصول على موافقة الهيئة العامة غير العادية في حال تغطية الاسهم غير المكتتب بها بأي من الطرق التالية :\n١ - ضم الاحتياطي الاختياري لرأسمال الشركة .\n٢ - رسملة ديون الشركة او اي جزء منها شريطة موافقة اصحاب هذه الديون خطياً على ذلك .\n٣ - تحويل اسناد القرض القابلة للتحويل الى اسهم وفقاً لاحكام هذا القانون .\nهـ - يجوز بقرار من الهيئة العامة وفق الاسس التي تحدها لهذه الغاية تخصيص جزء من راسمال الشركة غير المكتتب به لعرضه على العاملين لدى الشركة كحافز لهم ، ويجوز في هذه الحالة بقاء هذا الجزء معروضا عليهم لمدة لا تزيد على اربع سنوات من تاريخ تسجيل الشركة او زيادة راسمالها ، حسب مقتضى الحال .\nو - لمجلس الادارة اصدار الاسهم حسب ما تسمح به احكام قانون الاوراق المالية المعمول به .","title":"رأس مال الشركة المساهمة العامة","memo":"⭐ قيمة السهم دينار واحد؛ رأس المال المصرح به لا يقل عن ٥٠٠,٠٠٠ دينار، والمكتتب به لا يقل عن ١٠٠,٠٠٠ دينار أو ٢٠٪ من المصرح به أيهما أكثر\n⭐ يسدد الجزء غير المكتتب به خلال ٣ سنوات؛ فإن زاد المكتتب على ٥٠٠ ألف يصبح هو المصرح به، وإن قل ينذر المراقب الشركة بإكماله خلال ٣٠ يوماً وإلا يطلب التصفية\n⭐ تغطية غير المكتتب بضم الاحتياطي الاختياري أو رسملة الديون أو تحويل الإسناد: بموافقة الهيئة العامة غير العادية\n⭐ تخصيص جزء للعاملين كحافز لمدة لا تزيد على ٤ سنوات","qs":[{"q":"الحد الأدنى لرأس المال المصرح به للشركة المساهمة العامة هو:","o":["خمسمائة ألف دينار","مئة ألف دينار","مليون دينار","خمسون ألف دينار"],"a":0},{"q":"شركة مساهمة عامة رأسمالها المصرح به (٢) مليون دينار، فإن الحد الأدنى لرأسمالها المكتتب به هو:","o":["٤٠٠,٠٠٠ دينار","١٠٠,٠٠٠ دينار","٥٠٠,٠٠٠ دينار","١,٠٠٠,٠٠٠ دينار"],"a":0},{"q":"يسدد الجزء غير المكتتب به من رأس مال الشركة المساهمة العامة خلال:","o":["ثلاث سنوات من تاريخ تسجيل الشركة أو زيادة رأس المال","سنتين من تاريخ تسجيل الشركة","أربع سنوات من تاريخ تسجيل الشركة","خمس سنوات من تاريخ زيادة رأس المال"],"a":0},{"q":"انتهت مدة تسديد الجزء غير المكتتب به لشركة مساهمة عامة وكان رأسمالها المكتتب به ٧٠٠ ألف دينار، فإن:","o":["رأس مالها المصرح به يصبح هو رأس مالها المكتتب به فعلاً","المراقب ينذرها بتسديد كامل رأس المال المصرح به خلال ٣٠ يوماً","المراقب يطلب تصفيتها من المحكمة","تمنح مهلة إضافية مدتها سنة"],"a":0}]},{"n":"96","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يكون السهم في الشركة المساهمة العامة غير قابل للتجزئة ، ولكن يجوز للورثة الاشتراك في ملكية السهم الواحد بحكم الخلفية فيه لمورثهم ، وينطبق هذا الحكم عليهم اذا اشتركوا في ملكية اكثر من سهم واحد من تركة مورثهم ، على ان يختاروا في الحالتين احدهم ليمثلهم تجاه الشركة ولديها واذا تخلفوا عن ذلك خلال المدة التي يحددها لهم مجلس ادارة الشركة يعين المجلس احدهم من بينهم .","title":"عدم قابلية السهم للتجزئة","memo":"⭐ السهم في الشركة المساهمة العامة غير قابل للتجزئة\n⭐ يجوز للورثة الاشتراك في ملكية السهم بحكم الخلفية لمورثهم\n⭐ يختار الورثة أحدهم ليمثلهم أمام الشركة، فإن تخلفوا خلال المدة التي يحددها المجلس يعين المجلس أحدهم","qs":[{"q":"الاستثناء الوارد على مبدأ عدم قابلية السهم للتجزئة في الشركة المساهمة العامة يتعلق بـ:","o":["اشتراك الورثة في ملكية السهم بحكم الخلفية لمورثهم","اشتراك الزوجين في ملكية السهم","اشتراك المؤسسين في ملكية السهم","اشتراك الموظفين في ملكية السهم عبر صندوق الادخار"],"a":0},{"q":"آلت أسهم مساهم متوفى إلى ورثته ولم يختاروا ممثلاً عنهم أمام الشركة خلال المدة التي حددها مجلس الإدارة، فإن:","o":["مجلس الإدارة يعين أحدهم من بينهم","المراقب يعين ممثلاً عنهم","المحكمة تعين ممثلاً عنهم","تجمد حقوقهم في الأسهم لحين اختيار ممثل"],"a":0}]},{"n":"97","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . تكون اسهم الشركة المساهمة العامة نقدية ، وتسدد قيمة الاسهم المكتتب بها دفعة واحدة ، ويجوز ان تكون اسهم الشركة عينية ، تعطى مقابل مقدمات عينية مقومة بالنقد وفقا لاحكام هذا القانون ، وتعتبر حقوق الامتياز وحقوق الاختراع والمعرفة الفنية وغيرها من الحقوق المعنوية التي يوافق المؤسسون على اعتبارها مقدمات عينية شريطة تقديم تقارير في تحديد قيمتها من ذوي الخبرة والاختصاص مع مراعاة ما يلي :\n١. اذا لم يلتزم اصحاب المقدمات العينية بتسليمها او نقل ملكيتها الى الشركة خلال شهر من تاريخ تسجيلها فيكونوا ملزمين حكما بدفع قيمتها نقدا وبالسعر الذي اعتمده المؤسسون في طلب تاسيس الشركة وللمراقب طلب ما يثبت صحة تقدير قيمة المقدمات العينية .\n٢. اذا لم يقتنع المراقب بصحة تقدير الاسهم العينية المقدمة من قبل المؤسسين فعلى الوزير تشكيل لجنة على نفقة الشركة من ذوي الخبرة والاختصاص لتقدير الحق المراد تقويمه بالنقد على ان يكون احد المؤسسين من اعضاء اللجنة وتقدم اللجنة تقريرها خلال مدة لا تزيد على ثلاثين يوما من تاريخ تشكيلها الى المراقب ، وللمؤسسين الاعتراض عليه لدى الوزير خلال عشرة ايام من تاريخ اعتماده من قبل المراقب .\nب. على الوزير البت في الاعتراض خلال اسبوعين من تقديمه ، فاذا قبل الاعتراض يرفض تسجيل الشركة الا اذا عاد المؤسسون ووافقوا على التقدير فعندها تستكمل اجراءات التسجيل ولا يحق لاي من المؤسسين او المساهمين اللاحقين الاعتراض على قيمة الاسهم العينية المقدمة في مرحلة التاسيس .","title":"الأسهم النقدية والعينية وتقدير قيمتها","memo":"⭐ الأسهم نقدية وتسدد قيمتها دفعة واحدة، ويجوز أن تكون عينية مقابل مقدمات مقومة بالنقد بتقارير من ذوي الخبرة\n⭐ عدم تسليم المقدمات العينية خلال شهر من التسجيل يلزم أصحابها بدفع قيمتها نقداً\n⭐ إذا لم يقتنع المراقب يشكل الوزير لجنة على نفقة الشركة أحد أعضائها مؤسس، تقدم تقريرها خلال ٣٠ يوماً؛ واعتراض المؤسسين لدى الوزير خلال ١٠ أيام\n⭐ يبت الوزير في الاعتراض خلال أسبوعين","qs":[{"q":"تسدد قيمة الأسهم النقدية المكتتب بها في الشركة المساهمة العامة:","o":["دفعة واحدة","على قسطين خلال سنة","على أقساط خلال ثلاث سنوات","بنسبة ٢٥٪ عند الاكتتاب والباقي خلال سنتين"],"a":0},{"q":"إذا لم يقتنع المراقب بصحة تقدير الأسهم العينية المقدمة من المؤسسين، فإن الجهة التي تشكل لجنة التقدير هي:","o":["الوزير","المراقب","هيئة الأوراق المالية","لجنة المؤسسين"],"a":0},{"q":"يحق لمؤسسي الشركة المساهمة العامة الاعتراض على تقرير لجنة تقدير المقدمات العينية لدى الوزير خلال:","o":["عشرة أيام من تاريخ اعتماده من قبل المراقب","ثلاثين يوماً من تاريخ اعتماده","أسبوعين من تاريخ تقديمه","خمسة عشر يوماً من تاريخ تشكيل اللجنة"],"a":0},{"q":"قبل الوزير اعتراض المؤسسين على تقدير اللجنة للمقدمات العينية، فإن الأثر هو:","o":["رفض تسجيل الشركة إلا إذا عاد المؤسسون ووافقوا على التقدير","تسجيل الشركة وفق تقدير المؤسسين","إحالة الأمر إلى المحكمة المختصة","تشكيل لجنة جديدة من قبل المراقب"],"a":0}]},{"n":"98","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - تحتفظ الشركة المساهمة العامة بسجل او اكثر تدون فيها اسماء المساهمين وعدد الاسهم التي يملكها كل منهم، وعمليات التحويل التي تجري عليها ، واي بيانات اخرى تتعلق بها وبالمساهمين .\nب - مع مراعاة احكام الفقرة ( ج ) من هذه المادة ، يجوز للشركة ان تودع نسخة من السجلات المشار اليها في الفقرة ( أ ) اعلاه لدى اي جهة اخرى بهدف متابعة شؤون المساهمين وان تفوض تلك الجهة حفظ وتنظيم هذه السجلات .\nج - على الشركة المساهمة العامة ادراج اسهمها لدى السوق المالي وتتبع الاجراءات والقواعد المنصوص عليها بالقوانين والانظمة والتعليمات المنظمة لعمليات تداول الاوراق المالية في المملكة والخاصة بتسليم السجلات المشار الها في الفقرة ( أ ) اعلاه الى الجهة التي تحددها هذه القوانين والانظمة والتعليمات .\nد - يجوز لاي مساهم في الشركة الاطلاع على سجل المساهمين فيما يخص مساهمته لاي سبب كان ، وعلى كامل السجل لاي سبب معقول ، ويجوز لاي شخص اخر ذو مصلحة حسب ما تقدره المحكمة الطلب من الشركة الاطلاع على سجل المساهمين ، ويحق للشركة في جميع الاحوال ان تتقاضى بدلاً معقولاً في حالة رغبة اي شخص او مساهم استنساخ السجل او اي جزء منه .\nهـ - يجوز للشركة المساهمة العامة شراء الاسهم الصادرة عنها وبيعها والتصرف فيها وفقا لاحكام قانون الاوراق المالية والانظمة والتعليمات الصادرة بموجبه .","title":"سجل المساهمين في الشركة المساهمة العامة","memo":"⭐ سجل أو أكثر بأسماء المساهمين وعدد أسهمهم والتحويلات\n⭐ يجوز إيداع نسخة لدى جهة أخرى وتفويضها بحفظه، وعلى الشركة إدراج أسهمها لدى السوق المالي\n⭐ للمساهم الاطلاع على مساهمته لأي سبب، وعلى كامل السجل لأي سبب معقول، ولغيره إذا كان ذا مصلحة تقدرها المحكمة\n⭐ للشركة تقاضي بدل معقول عن الاستنساخ، ويجوز لها شراء أسهمها وفق قانون الأوراق المالية","qs":[{"q":"يجوز للمساهم في الشركة المساهمة العامة الاطلاع على كامل سجل المساهمين:","o":["لأي سبب معقول","لأي سبب كان","بموافقة المراقب فقط","بقرار من المحكمة فقط"],"a":0},{"q":"يجوز لشخص غير مساهم الطلب من الشركة المساهمة العامة الاطلاع على سجل المساهمين إذا كان:","o":["ذا مصلحة حسب ما تقدره المحكمة","دائناً للشركة بمبلغ يزيد على ألف دينار","حاصلاً على موافقة مجلس الإدارة","موظفاً في الشركة"],"a":0},{"q":"رغب مساهم في استنساخ جزء من سجل المساهمين في شركة مساهمة عامة، فإن للشركة:","o":["أن تتقاضى بدلاً معقولاً","أن ترفض الاستنساخ مطلقاً","أن تتقاضى رسماً يحدده الوزير","أن تشترط موافقة الهيئة العامة"],"a":0}]},{"n":"99","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يترتب على مؤسسي الشركة المساهمة العامة عند التوقيع على عقد تأسيسها ونظامها الاساسي تغطية كامل قيمة الاسهم التي اكتتبوا بها وتزويد المراقب بما يثبت ذلك ، على ان لا تزيد نسبة الاسهم المكتتب بها من قبل المؤسسين في البنوك والشركات المالية على ( %٥٠ ) من راس المال المصرح به وان لا يقل عدد المؤسسين فيها عن خمسين شخصاً .\nب - يجب ان لا تزيد مساهمة المؤسس او المؤسسين في الشركة المساهمة العامة عند التاسيس على (%٧٥) من راس المال المصرح به ويترتب على المؤسس او لجنة المؤسسين طرح الاسهم المتبقية للاكتتاب حسب ما يسمح به قانون الاوراق المالية الساري المفعول ، الا انه يجوز للشركاء في الشركات المحولة من ذات مسؤولية محدودة او توصية بالاسهم او مساهمة خاصة الى شركة مساهمة عامة تغطية فرق كامل راس مال الشركة المصرح به او طرح الاسهم المتبقية للاكتتاب العام او الخاص وفقا للاجراءات المنصوص عليها في قانون الاوراق المالية .\nج - يحظر على مؤسسي الشركة المساهمة العامة الاكتتاب بالاسهم المطروحة للاكتتاب في مرحلة التأسيس الا ان يجوز لهم تغطية ما تبقى من الاسهم بعد انقضاء ثلاثة ايام على اغلاق الاكتتاب .\nد - في جميع الاحوال اذا لم يتم تغطية الاسهم المطروحة للاكتتاب فيجوز الاكتفاء بعدد الاسهم التي اكتتب بها على ان لا يقل راس المال المكتتب به عن الحد الادنى المنصوص عليه في المادة (٩٥) من هذا القانون وان لا يقل عدد المكتتبين عن اثنين .","title":"اكتتاب المؤسسين وتغطية الأسهم","memo":"⭐ يغطي المؤسسون كامل قيمة أسهمهم عند التوقيع ويزودون المراقب بالإثبات\n⭐ في البنوك والشركات المالية: اكتتاب المؤسسين لا يزيد على ٥٠٪ من المصرح به وعدد المؤسسين لا يقل عن ٥٠ شخصاً\n⭐ مساهمة المؤسسين عند التأسيس لا تزيد على ٧٥٪ من المصرح به (باستثناء الشركات المحولة)\n⭐ يحظر اكتتاب المؤسسين بالأسهم المطروحة، ويجوز تغطية الباقي بعد ٣ أيام من إغلاق الاكتتاب؛ ولا يقل عدد المكتتبين عن اثنين","qs":[{"q":"يجب ألا تزيد نسبة الأسهم التي يكتتب بها المؤسسون في البنوك والشركات المالية على:","o":["٥٠٪ من رأس المال المصرح به","٧٥٪ من رأس المال المصرح به","٢٥٪ من رأس المال المصرح به","٢٠٪ من رأس المال المصرح به"],"a":0},{"q":"الحد الأدنى لعدد المؤسسين في البنوك والشركات المالية المساهمة العامة هو:","o":["خمسون شخصاً","اثنان","عشرون شخصاً","مئة شخص"],"a":0},{"q":"يجب ألا تزيد مساهمة المؤسسين في الشركة المساهمة العامة (غير البنوك والشركات المالية) عند التأسيس على:","o":["٧٥٪ من رأس المال المصرح به","٥٠٪ من رأس المال المصرح به","٩٠٪ من رأس المال المصرح به","٢٥٪ من رأس المال المصرح به"],"a":0},{"q":"يجوز لمؤسسي الشركة المساهمة العامة تغطية ما تبقى من الأسهم المطروحة للاكتتاب في مرحلة التأسيس بعد انقضاء:","o":["ثلاثة أيام على إغلاق الاكتتاب","سبعة أيام على إغلاق الاكتتاب","ثلاثين يوماً على إغلاق الاكتتاب","يوم واحد على إغلاق الاكتتاب"],"a":0}]},{"n":"100","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يحظر التصرف بالسهم التاسيسي في الشركة المساهمة العامة قبل مرور سنتين على الاقل من تأسيس الشركة ويعتبر باطلاً اي تصرف يخالف احكام هذه المادة .\nب - يستثنى من الحظر المنصوص عليه في الفقرة ( أ ) من هذه المادة انتقال السهم التأسيسي الى الورثة وفيما بين الزوجين والاصول والفروع ، وكذلك انتقاله من مؤسس الى مؤسس آخر في الشركة وانتقال السهم الى الغير بقرار قضائي او نتيجة بيعه بالمزاد العلني وفق احكام القانون .","title":"حظر التصرف بالسهم التأسيسي","memo":"⭐ يحظر التصرف بالسهم التأسيسي قبل مرور سنتين على الأقل من التأسيس، والتصرف المخالف باطل\n⭐ يستثنى: الانتقال للورثة، وبين الزوجين والأصول والفروع، ومن مؤسس لمؤسس آخر، وللغير بقرار قضائي أو بالمزاد العلني","qs":[{"q":"يحظر التصرف بالسهم التأسيسي في الشركة المساهمة العامة قبل مرور:","o":["سنتين على الأقل من تأسيس الشركة","سنة على الأقل من تأسيس الشركة","ثلاث سنوات على الأقل من تأسيس الشركة","ستة أشهر على الأقل من تأسيس الشركة"],"a":0},{"q":"الأثر القانوني لبيع مؤسس سهمه التأسيسي لشخص أجنبي عن الشركة بعد سنة من تأسيسها هو:","o":["بطلان التصرف","صحة التصرف مع فرض غرامة","صحة التصرف بموافقة مجلس الإدارة","وقف التصرف حتى انقضاء المدة"],"a":0},{"q":"أي من التصرفات التالية بالسهم التأسيسي خلال مدة الحظر لا يستثنى من الحظر؟","o":["بيعه لأحد المساهمين غير المؤسسين","انتقاله من مؤسس إلى مؤسس آخر في الشركة","انتقاله إلى الورثة","انتقاله نتيجة بيعه بالمزاد العلني وفق القانون"],"a":0}]},{"n":"101","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"مع مراعاة النصوص الواردة في أي قانون آخر ، يجوز لمؤسسي الشركة المساهمة العامة او مجلس ادارتها ان يعهدوا بتغطية اسهم الشركة الى مدير إصدار او اكثر .","title":"تغطية الأسهم بواسطة مدير الإصدار","memo":"⭐ يجوز لمؤسسي الشركة المساهمة العامة أو مجلس إدارتها أن يعهدوا بتغطية أسهمها إلى مدير إصدار أو أكثر\n⭐ مع مراعاة النصوص الواردة في أي قانون آخر","qs":[{"q":"يجوز لمؤسسي الشركة المساهمة العامة أو مجلس إدارتها أن يعهدوا بتغطية أسهم الشركة إلى:","o":["مدير إصدار أو أكثر","المراقب","مدقق حسابات الشركة","هيئة الأوراق المالية"],"a":0},{"q":"الجهة التي يجوز لها، إلى جانب المؤسسين، أن تعهد بتغطية أسهم الشركة المساهمة العامة إلى مدير إصدار هي:","o":["مجلس إدارة الشركة","المراقب","الهيئة العامة غير العادية حصراً","الوزير"],"a":0}]},{"n":"102","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - لا يجوز لاكثر من شخص واحد الاشتراك في الطلب الواحد للاكتتاب في الاسهم المطروحة، ويحظر الاكتتاب الوهمي او باسماء وهمية وذلك تحت طائلة بطلان الاكتتاب في اي من الحالات المنصوص عليها في هذه الفقرة .\nب - يجري الاكتتاب في اسهم الشركة المساهمة العامة بشكل يتفق مع احكام هذا القانون والقوانين النافذة الاخرى .","title":"أسس الاكتتاب في الأسهم","memo":"⭐ لا يجوز لأكثر من شخص الاشتراك في طلب اكتتاب واحد\n⭐ يحظر الاكتتاب الوهمي أو بأسماء وهمية\n⭐ الجزاء: بطلان الاكتتاب","qs":[{"q":"اشترك شخصان في طلب اكتتاب واحد في أسهم مطروحة لشركة مساهمة عامة، فإن الجزاء القانوني هو:","o":["بطلان الاكتتاب","غرامة لا تزيد على ألف دينار","تخصيص الأسهم لأولهما","قبول الاكتتاب مناصفة بينهما"],"a":0},{"q":"أي مما يلي يترتب عليه بطلان الاكتتاب في أسهم الشركة المساهمة العامة؟","o":["الاكتتاب بأسماء وهمية","الاكتتاب عن طريق مدير الإصدار","الاكتتاب بعد إغلاقه بيوم","الاكتتاب بعدد كبير من الأسهم"],"a":0}]},{"n":"103","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"على الشركة تزويد المراقب خلال مدة لا تتجاوز ثلاثين يوماً من تاريخ اغلاق اي اكتتاب في اسهم الشركة المساهمة العامة كشفاً يتضمن اسماء المكتتبين ، ومقدار الاسهم التي اكتتب كل منهم فيها .","title":"تزويد المراقب بأسماء المكتتبين","memo":"⭐ تزود الشركة المراقب بكشف بأسماء المكتتبين ومقدار أسهم كل منهم\n⭐ خلال مدة لا تتجاوز ٣٠ يوماً من تاريخ إغلاق أي اكتتاب","qs":[{"q":"على الشركة المساهمة العامة تزويد المراقب بكشف أسماء المكتتبين خلال مدة لا تتجاوز:","o":["ثلاثين يوماً من تاريخ إغلاق الاكتتاب","خمسة عشر يوماً من تاريخ إغلاق الاكتتاب","ستين يوماً من تاريخ إغلاق الاكتتاب","ثلاثة أيام من تاريخ إغلاق الاكتتاب"],"a":0},{"q":"يتضمن الكشف الذي تقدمه الشركة المساهمة العامة للمراقب بعد إغلاق الاكتتاب:","o":["أسماء المكتتبين ومقدار الأسهم التي اكتتب بها كل منهم","أسماء المؤسسين فقط","المبالغ الزائدة المعادة للمكتتبين","أسماء أعضاء مجلس الإدارة المرشحين"],"a":0}]},{"n":"104","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"اذا زاد الاكتتاب في اسهم الشركة المساهمة العامة على عدد الاسهم المطروحة في الاكتتاب فيترتب على الشركة تخصيص الاسهم المطروحة على المكتتبين وفقاً للانظمة والتشريعات المعمول بها .","title":"تخصيص الأسهم عند زيادة الاكتتاب","memo":"⭐ إذا زاد الاكتتاب على الأسهم المطروحة تخصص الشركة الأسهم على المكتتبين\n⭐ وفقاً للأنظمة والتشريعات المعمول بها","qs":[{"q":"إذا زاد الاكتتاب في أسهم الشركة المساهمة العامة على عدد الأسهم المطروحة، فإن الشركة:","o":["تخصص الأسهم المطروحة على المكتتبين وفقاً للأنظمة والتشريعات المعمول بها","تزيد عدد الأسهم المطروحة حكماً","تقبل الطلبات حسب أسبقية تقديمها دون تخصيص","تلغي الاكتتاب وتعيد طرحه"],"a":0},{"q":"يقع الالتزام بتخصيص الأسهم المطروحة على المكتتبين عند زيادة الاكتتاب على عدد الأسهم المطروحة على عاتق:","o":["الشركة","المراقب","هيئة الأوراق المالية","المكتتبين أنفسهم بالتراضي"],"a":0}]},{"n":"105","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تكون الشركة مسؤولة عن اعادة المبالغ الزائدة على قيمة اسهم الشركة المساهمة العامة المطروحة للاكتتاب وذلك خلال مدة لا تزيد على ثلاثين يوماً من تاريخ اغلاق الاكتتاب او اقرار تخصيص الاسهم ايهما اسبق. واذا تخلفت عن ذلك لاي سبب من الاسباب فيترتب لكل من المستحقين لتلك المبالغ فائدة عليها تحسب من بداية الشهر التالي مباشرة لمدة الثلاثين يوماً المنصوص عليها في هذه المادة وبمعدل اعلى سعر للفائدة السائد بين البنوك الاردنية على الودائع لاجل خلال ذلك الشهر .","title":"إعادة المبالغ الزائدة للمكتتبين","memo":"⭐ تعاد المبالغ الزائدة خلال مدة لا تزيد على ٣٠ يوماً من إغلاق الاكتتاب أو إقرار التخصيص أيهما أسبق\n⭐ عند التخلف: فائدة من بداية الشهر التالي مباشرة لمدة الثلاثين يوماً\n⭐ بمعدل أعلى سعر فائدة سائد بين البنوك الأردنية على الودائع لأجل","qs":[{"q":"تلتزم الشركة المساهمة العامة بإعادة المبالغ الزائدة على قيمة الأسهم المخصصة خلال مدة لا تزيد على ثلاثين يوماً من تاريخ:","o":["إغلاق الاكتتاب أو إقرار تخصيص الأسهم أيهما أسبق","إغلاق الاكتتاب أو إقرار التخصيص أيهما أبعد","تسجيل الشركة","اجتماع الهيئة العامة الأول"],"a":0},{"q":"إذا تأخرت الشركة المساهمة العامة في إعادة المبالغ الزائدة للمكتتبين، تستحق عليها فائدة بمعدل:","o":["أعلى سعر للفائدة السائد بين البنوك الأردنية على الودائع لأجل","أدنى سعر للفائدة السائد على الودائع لأجل","سعر الفائدة القانونية ٩٪","متوسط سعر الفائدة على القروض"],"a":0},{"q":"تحسب الفائدة على المبالغ الزائدة غير المعادة للمكتتبين في الشركة المساهمة العامة اعتباراً من:","o":["بداية الشهر التالي مباشرة لمدة الثلاثين يوماً","تاريخ إغلاق الاكتتاب","تاريخ تقديم طلب الاكتتاب","تاريخ مطالبة المكتتب بها"],"a":0}]},{"n":"106","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يرأس اجتماع الهيئة العامة الاول للشركة المساهمة العامة المشار اليه في المادة ( ٩٢ ) من هذا القانون احد اعضاء لجنة مؤسسي الشركة المكلفين بادارة الشركة بموجب احكام المادة ( ٩٢ ) من هذا القانون وتقوم الهيئة العامة في هذا الاجتماع بما يلي :\n١ - الاطلاع على تقرير لجنة مؤسسي الشركة المكلفين بادارة الشركة الذي يجب ان يتضمن معلومات وبيانات وافية عن جميع اعمال التأسيس واجراءاته مع الوثائق المؤيدة لها ، والتثبت من صحتها ، ومدى موافقتها للقانون ولنظام الشركة الأساسي .\n٢ - الاطلاع على نفقات التاسيس المدققة والمصادق عليها من مدقق حسابات الشركة ومناقشتها واتخاذ القرارات المناسبة بشانها .\n٣ - انتخاب مجلس الادارة الاول للشركة .\n٤ - انتخاب مدقق او مدققي حسابات الشركة وتحديد اتعابهم او تفويض مجلس الادارة بتحديدها .\nب - تطبق على اجتماع الهيئة العامة الاول اجراءات ومتطلبات الدعوة والنصاب القانوني واتخاذ القرارات المطبقة على اجتماعات الهيئة العامة العادية للشركة .\nج - تنتهي صلاحيات لجنة مؤسسي الشركة المساهمة العامة واعمالها فور انتخاب مجلس الادارة الاول للشركة وعليهم تسليم جميع المستندات والوثائق الخاصة بالشركة الى هذا المجلس .","title":"اجتماع الهيئة العامة الأول","memo":"⭐ يرأسه أحد أعضاء لجنة المؤسسين المكلفين بإدارة الشركة\n⭐ تطلع الهيئة على تقرير لجنة المؤسسين ونفقات التأسيس المدققة، وتنتخب مجلس الإدارة الأول ومدقق الحسابات وتحدد أتعابه أو تفوض المجلس\n⭐ تطبق عليه إجراءات الدعوة والنصاب والقرارات الخاصة بالهيئة العامة العادية\n⭐ تنتهي صلاحيات لجنة المؤسسين فور انتخاب مجلس الإدارة الأول وتسلمه المستندات","qs":[{"q":"يرأس اجتماع الهيئة العامة الأول للشركة المساهمة العامة:","o":["أحد أعضاء لجنة المؤسسين المكلفين بإدارة الشركة","المراقب أو من ينتدبه","أكبر المساهمين سناً","مدقق حسابات الشركة"],"a":0},{"q":"تطبق على اجتماع الهيئة العامة الأول للشركة المساهمة العامة إجراءات الدعوة والنصاب واتخاذ القرارات المطبقة على:","o":["اجتماعات الهيئة العامة العادية","اجتماعات الهيئة العامة غير العادية","اجتماعات مجلس الإدارة","اجتماعات لجنة المؤسسين"],"a":0},{"q":"تنتهي صلاحيات لجنة مؤسسي الشركة المساهمة العامة وأعمالها:","o":["فور انتخاب مجلس الإدارة الأول للشركة","بصدور شهادة تسجيل الشركة","بعد مرور سنتين على التأسيس","بمصادقة المراقب على محضر الاجتماع الأول"],"a":0},{"q":"أي مما يلي ليس من مهام الهيئة العامة في اجتماعها الأول للشركة المساهمة العامة؟","o":["زيادة رأس مال الشركة","انتخاب مجلس الإدارة الأول","مناقشة نفقات التأسيس المدققة","انتخاب مدقق حسابات الشركة"],"a":0}]},{"n":"107","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"اذا اعترض مساهمون في الشركة المساهمة العامة يحملون ما لا يقل عن ( %٢٠ ) من الاسهم الممثلة في اجتماع الهيئة العامة الاول للشركة على اي بند من بنود نفقات تأسيس الشركة ، فعلى المراقب التحقق من صحة الاعتراض وتسويته. فاذا لم يتمكن من ذلك لاي سبب من الاسباب فلمقدمي طلب الاعتراض اقامة الدعوى لدى المحكمة ولا تؤثر هذه الدعوى على استمرار الشركة في اعمالها الا اذا قررت المحكمة غير ذلك .","title":"الاعتراض على نفقات التأسيس","memo":"⭐ يحق لمساهمين يحملون ٢٠٪ على الأقل من الأسهم الممثلة في الاجتماع الأول الاعتراض على أي بند من نفقات التأسيس\n⭐ يتحقق المراقب من الاعتراض ويسويه، وإلا فللمعترضين إقامة الدعوى لدى المحكمة\n⭐ الدعوى لا تؤثر على استمرار الشركة في أعمالها إلا إذا قررت المحكمة غير ذلك","qs":[{"q":"يحق للمساهمين الاعتراض على أي بند من نفقات تأسيس الشركة المساهمة العامة إذا كانوا يحملون من الأسهم الممثلة في الاجتماع الأول ما لا يقل عن:","o":["٢٠٪","١٥٪","٢٥٪","١٠٪"],"a":0},{"q":"الجهة التي تتحقق من صحة اعتراض المساهمين على نفقات التأسيس وتسويته ابتداءً هي:","o":["المراقب","المحكمة المختصة","الوزير","مدقق حسابات الشركة"],"a":0},{"q":"أقام مساهمون دعوى لدى المحكمة بشأن نفقات التأسيس بعد تعذر تسوية اعتراضهم، فإن ذلك:","o":["لا يؤثر على استمرار الشركة في أعمالها إلا إذا قررت المحكمة غير ذلك","يوقف أعمال الشركة حكماً لحين الفصل في الدعوى","يؤدي إلى حل مجلس الإدارة الأول","يوقف توزيع الأرباح حكماً"],"a":0}]},{"n":"108","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يترتب على رئيس مجلس الادارة الاول للشركة تزويد المراقب بنسخة من محضر اجتماع الهيئة العامة الاول للشركة والوثائق والبيانات التي قدمتها لجنة مؤسسي الشركة الى الهيئة العامة وذلك خلال خمسة عشر يوماً من تاريخ اجتماع الهيئة العامة الاول .\nب - اذا تبين للمراقب ان الشركة المساهمة العامة قد اغفلت في مرحلة تأسيسها تطبيق اي نص او حكم قانوني او خالفت مثل ذلك النص او الحكم فعليه ان ينذرها خطياً بتصويب اوضاعها خلال ثلاثة اشهر من تاريخ تبليغها الانذار فاذا لم تمتثل لما يتطلبه الانذار احالها الى المحكمة .\nج - اذا تبين له من تدقيق الوثائق المقدمة اليه بمقتضى احكام الفقرة ( أ ) من هذه المادة ان اجراءات تأسيس الشركة المساهمة العامة كانت سليمة من الناحية القانونية فيعلمها خطياً بحقها في الشروع في اعمالها .","title":"رقابة المراقب على إجراءات التأسيس","memo":"⭐ يزود رئيس مجلس الإدارة الأول المراقب بمحضر الاجتماع الأول ووثائق لجنة المؤسسين خلال ١٥ يوماً من الاجتماع\n⭐ عند وجود مخالفة في التأسيس ينذر المراقب الشركة خطياً بتصويب أوضاعها خلال ٣ أشهر وإلا يحيلها إلى المحكمة\n⭐ إذا كانت الإجراءات سليمة يعلمها خطياً بحقها في الشروع في أعمالها","qs":[{"q":"يترتب على رئيس مجلس الإدارة الأول تزويد المراقب بنسخة من محضر اجتماع الهيئة العامة الأول خلال:","o":["خمسة عشر يوماً من تاريخ الاجتماع","عشرة أيام من تاريخ الاجتماع","ثلاثين يوماً من تاريخ الاجتماع","ستين يوماً من تاريخ الاجتماع"],"a":0},{"q":"إذا تبين للمراقب أن الشركة المساهمة العامة خالفت نصاً قانونياً في مرحلة تأسيسها، فإنه ينذرها خطياً بتصويب أوضاعها خلال:","o":["ثلاثة أشهر من تاريخ تبليغها الإنذار","شهر من تاريخ تبليغها الإنذار","ستة أشهر من تاريخ تبليغها الإنذار","ثلاثين يوماً من تاريخ اجتماع الهيئة العامة الأول"],"a":0},{"q":"لم تمتثل شركة مساهمة عامة لإنذار المراقب بتصويب مخالفة وقعت في مرحلة التأسيس خلال المدة المحددة، فإن المراقب:","o":["يحيلها إلى المحكمة","يشطب تسجيلها مباشرة","يفرض عليها غرامة يومية","يحل مجلس إدارتها"],"a":0}]},{"n":"109","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يجوز لمؤسسي الشركة المساهمة العامة ان يقدموا مقابل اسهمهم في الشركة مقدمات عينية تقوم بالنقد ، على ان تراعى بشانها الاحكام المبينة في المادة (٩٧) من هذا القانون .\nب - أما بالنسبة للأسهم العينية المقدمة في أي مرحلة لاحقة للتأسيس فيجب الحصول على موافقة الهيئة العامة غير العادية على قيمة المقدمات العينية .\nج - يحق لأي مساهم حضر اجتماع الهيئة العامة غير العادية وسجل اعتراضه في محضر ذلك الاجتماع أن يطعن لدى المحكمة المختصة بقيمة المقدمات العينية خلال خمسة عشر يوماً من تاريخ الاجتماع .","title":"الأسهم العينية بعد التأسيس","memo":"⭐ المقدمات العينية عند التأسيس تخضع لأحكام المادة (٩٧)\n⭐ الأسهم العينية بعد التأسيس تتطلب موافقة الهيئة العامة غير العادية على قيمتها\n⭐ للمساهم الحاضر الذي سجل اعتراضه في المحضر الطعن لدى المحكمة المختصة خلال ١٥ يوماً من الاجتماع","qs":[{"q":"يشترط لقبول أسهم عينية في الشركة المساهمة العامة في مرحلة لاحقة للتأسيس الحصول على موافقة:","o":["الهيئة العامة غير العادية على قيمة المقدمات العينية","مجلس الإدارة","المراقب","الهيئة العامة العادية"],"a":0},{"q":"يحق للمساهم الطعن لدى المحكمة المختصة بقيمة المقدمات العينية المقبولة بعد التأسيس خلال:","o":["خمسة عشر يوماً من تاريخ الاجتماع","ثلاثين يوماً من تاريخ الاجتماع","عشرة أيام من تاريخ الاجتماع","ستين يوماً من تاريخ الاجتماع"],"a":0},{"q":"مساهم لم يحضر اجتماع الهيئة العامة غير العادية الذي أقر قيمة مقدمات عينية لاحقة للتأسيس، ويرغب بالطعن في قيمتها وفق هذه المادة، فإن:","o":["لا يحق له الطعن لأن الحق مقرر لمن حضر وسجل اعتراضه في المحضر","يحق له الطعن خلال خمسة عشر يوماً","يحق له الطعن خلال ثلاثين يوماً","يحق له الطعن لدى المراقب"],"a":0}]},{"n":"110","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا تصدر الاسهم العينية في الشركة المساهمة العامة لمالكيها الا بعد اتمام الاجراءات القانونية الخاصة بتسليم المقدمات العينية الى الشركة ونقل ملكيتها اليها .","title":"شرط إصدار الأسهم العينية","memo":"⭐ لا تصدر الأسهم العينية لمالكيها إلا بعد إتمام إجراءات تسليم المقدمات العينية إلى الشركة ونقل ملكيتها إليها","qs":[{"q":"لا تصدر الأسهم العينية في الشركة المساهمة العامة لمالكيها إلا بعد:","o":["إتمام إجراءات تسليم المقدمات العينية إلى الشركة ونقل ملكيتها إليها","مرور سنتين على تأسيس الشركة","موافقة هيئة الأوراق المالية","إدراج أسهم الشركة في السوق المالي"],"a":0}]},{"n":"111","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يتمتع مالكو الاسهم العينية في الشركة المساهمة العامة بالحقوق التي يتمتع بها اصحاب الاسهم النقدية واذا كانت الاسهم العينية تأسيسية فتطبق عليها القيود المطبقة على الاسهم النقدية التأسيسية .","title":"حقوق مالكي الأسهم العينية","memo":"⭐ مالكو الأسهم العينية يتمتعون بحقوق أصحاب الأسهم النقدية نفسها\n⭐ إذا كانت الأسهم العينية تأسيسية تطبق عليها قيود الأسهم النقدية التأسيسية","qs":[{"q":"ما الحقوق التي يتمتع بها مالكو الأسهم العينية في الشركة المساهمة العامة؟","o":["الحقوق التي يتمتع بها أصحاب الأسهم النقدية","نصف الحقوق التي يتمتع بها أصحاب الأسهم النقدية","حقوق في الأرباح فقط دون حق التصويت","الحقوق التي تحددها الهيئة العامة العادية لكل حالة"],"a":0},{"q":"إذا كانت الأسهم العينية تأسيسية فإنه يطبق عليها:","o":["القيود المطبقة على الأسهم النقدية التأسيسية","قيود خاصة يحددها المراقب","لا تطبق عليها أي قيود على التصرف","القيود التي يقررها مجلس الإدارة"],"a":0}]},{"n":"112","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز للشركة المساهمة العامة ان تزيد رأسمالها المصرح به بموافقة هيئتها العامة غير العادية اذا كان قد اكتتب به بالكامل على ان تتضمن الموافقة طريقة تغطية الزيادة .","title":"زيادة رأس المال المصرح به","memo":"⭐ تزيد الشركة المساهمة العامة رأسمالها المصرح به بموافقة الهيئة العامة غير العادية\n⭐ شرط ذلك: أن يكون رأس المال المصرح به قد اكتتب به بالكامل\n⭐ يجب أن تتضمن الموافقة طريقة تغطية الزيادة","qs":[{"q":"الجهة المختصة بالموافقة على زيادة رأس المال المصرح به للشركة المساهمة العامة هي:","o":["الهيئة العامة غير العادية","الهيئة العامة العادية","مجلس الإدارة","مراقب الشركات"],"a":0},{"q":"يشترط لزيادة رأس المال المصرح به للشركة المساهمة العامة أن يكون:","o":["قد اكتتب به بالكامل","قد اكتتب بنصفه على الأقل","قد اكتتب بـ (٧٥٪) منه على الأقل","قد مضت سنة على تأسيس الشركة"],"a":0}]},{"n":"113","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"مع مراعاة قانون الاوراق المالية ، للشركة المساهمة العامة زيادة رأسمالها باحدى الطرق التالية او اي طريقة اخرى تقرها الهيئة العامة للشركة :-\n١ - طرح اسهم الزيادة للاكتتاب من قبل المساهمين او غيرهم .\n٢ - ضم الاحتياطي الاختياري او الارباح المدورة المتراكمة او كليهما الى رأسمال الشركة .\n٣ - رسملة الديون المترتبة على الشركة او اي جزء منها شريطة موافقة اصحاب هذه الديون خطياً على ذلك .\n٤ - تحويل اسناد القرض القابلة للتحويل الى اسهم وفقاً لاحكام هذا القانون .","title":"طرق زيادة رأس المال","memo":"⭐ طرق الزيادة (مع مراعاة قانون الأوراق المالية): طرح أسهم للاكتتاب من المساهمين أو غيرهم\n⭐ ضم الاحتياطي الاختياري أو الأرباح المدورة المتراكمة أو كليهما\n⭐ رسملة الديون بشرط موافقة أصحابها خطياً، وتحويل إسناد القرض القابلة للتحويل إلى أسهم\n⭐ أو أي طريقة أخرى تقرها الهيئة العامة","qs":[{"q":"يشترط لزيادة رأس مال الشركة المساهمة العامة عن طريق رسملة الديون المترتبة عليها:","o":["موافقة أصحاب هذه الديون خطياً","موافقة مدقق حسابات الشركة","موافقة المحكمة المختصة","أن لا تقل الديون عن نصف رأس المال"],"a":0},{"q":"أي مما يلي ليس من طرق زيادة رأس مال الشركة المساهمة العامة الواردة في النص؟","o":["ضم الاحتياطي الإجباري إلى رأس المال","ضم الاحتياطي الاختياري إلى رأس المال","ضم الأرباح المدورة المتراكمة إلى رأس المال","تحويل إسناد القرض القابلة للتحويل إلى أسهم"],"a":0},{"q":"قررت شركة مساهمة عامة زيادة رأسمالها بطرح أسهم الزيادة للاكتتاب، فإن الاكتتاب فيها يكون من قبل:","o":["المساهمين أو غيرهم","المساهمين المؤسسين فقط","المساهمين الحاليين حصراً","البنوك والمؤسسات المالية فقط"],"a":0}]},{"n":"114","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يجوز للشركة المساهمة بقرار من الهيئة العامة غير العادية تخفيض الجزء غير المكتتب به من رأسمالها المصرح به ، كما يجوز لها تخفيض رأسمالها المكتتب به اذا زاد على حاجتها او اذا طرأت عليها خسارة ورأت الشركة انقاص رأسمالها بمقدار هذه الخسارة او اي جزء منها ، على ان تراعى في قرار التخفيض واجراءاته حقوق الغير المنصوص عليها في المادة ( ١١٥ ) من هذا القانون .\nب - يجري التخفيض في راس المال المكتتب به بتنزيل قيمة الاسهم بالغاء جزء من ثمنها المدفوع يوازي مبلغ الخسارة في حالة وجود خسارة في الشركة او باعادة جزء منه اذا رأت ان رأسمالها يزيد عن حاجتها .\nج - لا يجوز تخفيض رأسمال الشركة المساهمة العامة في اي حالة من الحالات الى اقل من الحد الادنى المقرر بمقتضى المادة ( ٩٥ ) من هذا القانون .\nد - اذا كان الهدف اعادة هيكلة راسمال الشركة فيجوز اتخاذ قرار تخفيض راسمالها وزيادته باجتماع الهيئة العامة غير العادي نفسه على ان تستكمل اجراءات التخفيض المنصوص عليها في هذا القانون ثم تستكمل اجراءات الزيادة وعلى ان تتضمن دعوة الاجتماع اسباب اعادة الهيكلة والجدوى التي يهدف اليها هذا الاجراء .","title":"تخفيض رأس المال","memo":"⭐ التخفيض بقرار من الهيئة العامة غير العادية: للجزء غير المكتتب به من المصرح به، أو للمكتتب به إذا زاد عن الحاجة أو بسبب خسارة\n⭐ يتم تخفيض المكتتب به بإلغاء جزء من الثمن المدفوع يوازي الخسارة، أو بإعادة جزء منه إذا زاد عن الحاجة\n⭐ لا يجوز التخفيض إلى أقل من الحد الأدنى المقرر في المادة (٩٥)\n⭐ إعادة الهيكلة: قرار التخفيض والزيادة في الاجتماع غير العادي نفسه، تستكمل إجراءات التخفيض أولاً ثم الزيادة","qs":[{"q":"الجهة التي تقرر تخفيض رأس مال الشركة المساهمة هي:","o":["الهيئة العامة غير العادية","مجلس الإدارة","الهيئة العامة العادية","الوزير بناءً على تنسيب المراقب"],"a":0},{"q":"إذا طرأت خسارة على الشركة ورأت تخفيض رأسمالها المكتتب به بمقدارها، فإن التخفيض يجري:","o":["بإلغاء جزء من ثمن الأسهم المدفوع يوازي مبلغ الخسارة","بإعادة جزء من قيمة الأسهم إلى المساهمين","بشراء الشركة لجزء من أسهمها وإلغائها","بضم الاحتياطي الاختياري لتغطية الخسارة"],"a":0},{"q":"لا يجوز تخفيض رأس مال الشركة المساهمة العامة في أي حالة إلى أقل من:","o":["الحد الأدنى المقرر بمقتضى المادة (٩٥) من القانون","نصف رأس المال المصرح به","رأس المال المكتتب به عند التأسيس","مبلغ خسائر الشركة المتراكمة"],"a":0},{"q":"قررت الهيئة العامة غير العادية في الاجتماع نفسه تخفيض رأس المال وزيادته بهدف إعادة الهيكلة، فإن الإجراءات تستكمل على النحو التالي:","o":["إجراءات التخفيض أولاً ثم إجراءات الزيادة","إجراءات الزيادة أولاً ثم إجراءات التخفيض","الإجراءان معاً في وقت واحد","يكتفى بإجراءات الزيادة دون التخفيض"],"a":0}]},{"n":"115","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يقدم مجلس ادارة الشركة المساهمة العامة طلب تخفيض رأس مالها المكتتب به الى المراقب مع الاسباب الموجبة له بعد ان تقرر الهيئة العامة للشركة الموافقة على التخفيض باكثرية لا تقل عن ( %٧٥ ) خمسة وسبعين بالمائة من الاسهم الممثلة في اجتماعها غير العادي الذي تعقده لهذه الغاية ، وترفق بالطلب قائمة باسماء دائني الشركة ومقدار دين كل منهم وعنوانه وبيان بموجودات الشركة والتزاماتها ، على أن تكون قائمة الدائنين للشركة وبيان موجوداتها والتزاماتها مصدقة من مدقق حساباتها .\nب - يبلغ المراقب الدائنين الواردة اسماؤهم في القائمة المقدمة من قبل الشركة اشعاراً يتضمن قرار هيئتها العامة بتخفيض رأس مال الشركة المكتتب به وينشر الاشعار في صحيفتين يوميتين محليتين على نفقة الشركة ،ولكل دائن ان يقدم الى المراقب خلال مدة لا تزيد على ثلاثين يوماً من تاريخ نشر الاشعار لاخر مرة اعتراضاً خطياً على تخفيض رأس مال الشركة، فاذا لم يتمكن المراقب من تسوية الاعتراضات التي قدمت اليه خلال ثلاثين يوماً من تاريخ انتهاء المدة المحددة لتقديمها فيحق لاصحابها مراجعة المحكمة بشأن ما ورد في اعتراضاتهم خلال ثلاثين يوماً من تاريخ انتهاء المدة التي منحت للمراقب لتسويتها وترد اي دعوى تقدم بعد هذه المدة .\nج - اذا تبلغ المراقب اشعاراً خطياً من المحكمة باقامة اي دعوى لديها خلال المدة المنصوص عليها في الفقرة ( ب ) من هذه المادة بالطعن في تخفيض رأس مال الشركة المكتتب به، فيترتب عليه ان يوقف اجراءات التخفيض الى ان يصدر قرار المحكمة في الدعوى ويكتسب الدرجة القطعية ،على ان تعتبر الدعوى في هذه الحالة من الدعاوي ذات الصفة المستعجلة بمقتضى احكام قانون اصول المحاكمات المدنية المعمول به .\nد - اذا لم تقدم اي دعوى الى المحكمة بالطعن في قرار الهيئة العامة للشركة المساهمة العامة بتخفيض رأس مالها المكتتب به او اقيمت دعوى وردتها المحكمة واكتسبت الحكم الدرجة القطعية فيترتب على المراقب متابعة النظر في تخفيض رأس مال الشركة، وان يرفع تنسيبه بشأنه الى الوزير ليصدر القرار الذي يراه مناسباً فيه فاذا قرر الموافقة عليه تم تسجيله ونشره من قبل المراقب على نفقة الشركة وفقاً للاجراءات المنصوص عليها في هذا القانون وبحيث يحل رأس المال المخفض للشركة حكماً محل رأس مالها المدرج في عقد تأسيسها ونظامها .\nهـ - لا تشترط موافقة المراقب والدائنين على تخفيض الجزء غير المكتتتب به من رأس المال المصرح به .","title":"إجراءات تخفيض رأس المال","memo":"⭐ موافقة الهيئة العامة غير العادية بأكثرية لا تقل عن (٧٥٪) من الأسهم الممثلة، ثم يقدم مجلس الإدارة الطلب للمراقب مع قائمة الدائنين وبيان الموجودات مصدقة من المدقق\n⭐ ينشر الإشعار في صحيفتين يوميتين محليتين على نفقة الشركة؛ اعتراض الدائن خطياً خلال (٣٠) يوماً من آخر نشر، وللمراقب (٣٠) يوماً للتسوية، ثم (٣٠) يوماً لمراجعة المحكمة وإلا ترد الدعوى\n⭐ الدعوى مستعجلة ويوقف المراقب الإجراءات حتى يكتسب الحكم الدرجة القطعية؛ القرار النهائي للوزير بتنسيب المراقب\n⭐ لا تشترط موافقة المراقب والدائنين على تخفيض الجزء غير المكتتب به","qs":[{"q":"الأكثرية المطلوبة لموافقة الهيئة العامة على تخفيض رأس المال المكتتب به هي:","o":["لا تقل عن (٧٥٪) من الأسهم الممثلة في الاجتماع غير العادي","لا تقل عن (٥١٪) من الأسهم الممثلة في الاجتماع","ثلثا الأسهم المكتتب بها","الأكثرية المطلقة لأعضاء مجلس الإدارة"],"a":0},{"q":"المدة الممنوحة للدائن لتقديم اعتراض خطي إلى المراقب على تخفيض رأس المال هي:","o":["لا تزيد على ثلاثين يوماً من تاريخ نشر الإشعار لآخر مرة","خمسة عشر يوماً من تاريخ تبليغه","ستون يوماً من تاريخ قرار الهيئة العامة","سبعة أيام من تاريخ النشر الأول"],"a":0},{"q":"الجهة التي تصدر القرار النهائي بالموافقة على تخفيض رأس المال المكتتب به هي:","o":["الوزير بناءً على تنسيب المراقب","المراقب مباشرة","المحكمة المختصة","مجلس الإدارة"],"a":0},{"q":"قررت شركة مساهمة عامة تخفيض الجزء غير المكتتب به من رأسمالها المصرح به، فإن ذلك:","o":["لا يشترط فيه موافقة المراقب والدائنين","يشترط فيه موافقة الدائنين فقط","يشترط فيه موافقة المراقب والدائنين","يشترط فيه موافقة المحكمة"],"a":0}]},{"n":"116","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"اسناد القرض اوراق مالية قابلة للتداول يحق اصدارها للشركة المساهمة العامة او الشركة المساهمة الخاصة او لاي من الشركات التي يجيز لها قانون الاوراق المالية اصدار هذه الاسناد ويتم طرحها وفقا لاحكام هذا القانون وقانون الاوراق المالية للحصول على قرض تتعهد الشركة بموجب هذه الاسناد بسداد القرض وفوائده وفقا لشروط الاصدار .","title":"تعريف إسناد القرض","memo":"⭐ إسناد القرض: أوراق مالية قابلة للتداول تصدرها الشركة المساهمة العامة أو الخاصة أو أي شركة يجيز لها قانون الأوراق المالية ذلك\n⭐ تطرح للحصول على قرض وتتعهد الشركة بسداد القرض وفوائده وفقاً لشروط الإصدار","qs":[{"q":"إسناد القرض وفق قانون الشركات هي:","o":["أوراق مالية قابلة للتداول تصدر للحصول على قرض","حصص في رأس مال الشركة","أوراق تجارية غير قابلة للتداول","أسهم ممتازة لا تمنح حق التصويت"],"a":0},{"q":"أي من الشركات التالية يحق لها إصدار إسناد القرض بموجب النص؟","o":["الشركة المساهمة الخاصة","شركة التضامن","شركة التوصية البسيطة","الشركة ذات المسؤولية المحدودة دون إجازة من قانون الأوراق المالية"],"a":0}]},{"n":"117","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يشترط في اسناد القرض موافقة مجلس ادارة الشركة على اصدارها باغلبية ثلثي اعضاء المجلس على الاقل واذا كانت هذه الاسناد قابلة للتحويل الى اسهم فيشترط كذلك الحصول على موافقة الهيئة العامة غير العادية للشركة، وتعتبر موافقتها هذه بمثابة موافقة على زيادة رأس المال المصرح به للشركة دون ان يكون لمجلس الادارة فيما يتعلق بهذه الزيادة ان يمارس الصلاحيات الممنوحة له بموجب الفقرة ( ب ) من المادة ٩٥ من هذا القانون .","title":"شروط إصدار إسناد القرض","memo":"⭐ إصدار الإسناد يحتاج موافقة مجلس الإدارة بأغلبية ثلثي أعضائه على الأقل\n⭐ الإسناد القابلة للتحويل لأسهم تحتاج كذلك موافقة الهيئة العامة غير العادية، وتعد موافقتها موافقة على زيادة رأس المال المصرح به\n⭐ لا يمارس المجلس بشأن هذه الزيادة صلاحياته وفق الفقرة (ب) من المادة (٩٥)","qs":[{"q":"الأغلبية المطلوبة في مجلس الإدارة لإصدار إسناد القرض هي:","o":["ثلثا أعضاء المجلس على الأقل","الأكثرية المطلقة لأعضاء المجلس","ثلاثة أرباع أعضاء المجلس","أكثرية الأعضاء الحاضرين"],"a":0},{"q":"إذا كانت إسناد القرض قابلة للتحويل إلى أسهم فيشترط إضافة إلى موافقة مجلس الإدارة:","o":["موافقة الهيئة العامة غير العادية","موافقة الهيئة العامة العادية","موافقة الوزير","موافقة هيئة مالكي إسناد القرض"],"a":0},{"q":"تعتبر موافقة الهيئة العامة غير العادية على إصدار إسناد قرض قابلة للتحويل إلى أسهم بمثابة:","o":["موافقة على زيادة رأس المال المصرح به","موافقة على تخفيض رأس المال","تفويض لمجلس الإدارة بممارسة صلاحياته وفق المادة (٩٥/ب)","موافقة على توزيع أرباح"],"a":0}]},{"n":"118","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . تسجل اسناد القرض باسماء مالكيها وتوثق البيوع الواقعة عليها في سجلات الشركة المصدرة لها او لدى الجهة الحافظة لهذه السجلات ، وتكون هذه الاسناد قابلة للتداول في اسواق الاوراق المالية حسب ما ينص عليه قانون الاوراق المالية النافذ .\nب. يجوز في الحالات التي يوافق عليها المراقب وهيئة الاوراق المالية اصدار اسناد قرض لحامله وفقا لتعليمات تصدرها الهيئة لهذه الغاية .","title":"تسجيل إسناد القرض وتداولها","memo":"⭐ تسجل الإسناد بأسماء مالكيها وتوثق البيوع في سجلات الشركة المصدرة أو لدى الجهة الحافظة\n⭐ قابلة للتداول في أسواق الأوراق المالية وفق قانون الأوراق المالية\n⭐ يجوز إصدار إسناد لحامله في حالات يوافق عليها المراقب وهيئة الأوراق المالية وفق تعليمات الهيئة","qs":[{"q":"الأصل في إسناد القرض أنها تسجل:","o":["بأسماء مالكيها","لحاملها","باسم أمين الإصدار","باسم متعهد التغطية"],"a":0},{"q":"يجوز إصدار إسناد قرض لحامله في الحالات التي يوافق عليها:","o":["المراقب وهيئة الأوراق المالية","مجلس الإدارة والهيئة العامة","الوزير وحده","هيئة مالكي إسناد القرض"],"a":0}]},{"n":"119","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تكون اسناد القرض بقيمة اسمية واحدة في الاصدار الواحد وتصدر شهادات الاسناد بفئات مختلفة لاغراض التداول .\nب - يجوز ان يباع سند القرض بقيمته الاسمية او بخصم او بعلاوة اصدار وفي جميع الحالات يسدد السند بقيمته الاسمية .","title":"القيمة الاسمية لإسناد القرض","memo":"⭐ قيمة اسمية واحدة في الإصدار الواحد، وتصدر الشهادات بفئات مختلفة لأغراض التداول\n⭐ يباع السند بقيمته الاسمية أو بخصم أو بعلاوة إصدار\n⭐ في جميع الحالات يسدد السند بقيمته الاسمية","qs":[{"q":"تكون إسناد القرض في الإصدار الواحد:","o":["بقيمة اسمية واحدة","بقيم اسمية متعددة","بقيمة يحددها السوق المالي","بقيمة تساوي القيمة الاسمية للسهم"],"a":0},{"q":"بيع سند قرض قيمته الاسمية (١٠٠) دينار بخصم إصدار بمبلغ (٩٥) ديناراً، فإنه يسدد عند الاستحقاق بمبلغ:","o":["(١٠٠) دينار","(٩٥) ديناراً","(١٠٥) دنانير","المبلغ الذي تحدده الشركة عند الاستحقاق"],"a":0}]},{"n":"120","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"تدفع قيمة سند القرض عند الاكتتاب به دفعة واحدة وتقيد باسم الشركة المقترضة فاذا وجد متعهد تغطية فيجوز في هذه الحالة تسجيل المبالغ المدفوعة باسمه بموافقة مجلس ادارة الشركة المقترضة وتعاد حصيلة الاكتتاب للشركة في الموعد المتفق عليه مع مدير الإصدار .","title":"دفع قيمة سند القرض","memo":"⭐ تدفع قيمة السند عند الاكتتاب دفعة واحدة وتقيد باسم الشركة المقترضة\n⭐ عند وجود متعهد تغطية يجوز تسجيل المبالغ باسمه بموافقة مجلس إدارة الشركة المقترضة\n⭐ تعاد الحصيلة للشركة في الموعد المتفق عليه مع مدير الإصدار","qs":[{"q":"تدفع قيمة سند القرض عند الاكتتاب به:","o":["دفعة واحدة","على قسطين","على أقساط خلال سنتين","بنسبة لا تقل عن (٢٥٪) عند الاكتتاب"],"a":0},{"q":"إذا وجد متعهد تغطية جاز تسجيل المبالغ المدفوعة ثمناً للإسناد باسمه بموافقة:","o":["مجلس إدارة الشركة المقترضة","المراقب","هيئة مالكي إسناد القرض","الهيئة العامة غير العادية"],"a":0}]},{"n":"121","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجب ان يتضمن السند البيانات التالية :-\nأ - على وجه السند :-\n١ - اسم الشركة المقترضة وشعارها ان وجد وعنوانها ورقم تسجيلها وتاريخه ومدة الشركة .\n٢ - اسم مالك سند القرض اذا كان السند اسمياً .\n٣ - رقم السند ونوعه وقيمته الاسمية ومدته وسعر الفائدة .\nب - على ظهر السند :-\n١ - مجموع قيم اسناد القرض المصدرة .\n٢ - مواعيد وشروط اطفاء الاسناد ومواعيد استحقاق الفائدة .\n٣ - الضمانات الخاصة للدين الذي يمثله السند ان وجدت .\n٤ - اي شروط واحكام اخرى ترى الشركة المقترضة اضافتها الى السند شريطة ان تتوافق هذه الاضافات مع شروط الاصدار .","title":"بيانات سند القرض","memo":"⭐ على وجه السند: اسم الشركة وشعارها وعنوانها ورقم وتاريخ تسجيلها ومدتها؛ اسم المالك إن كان اسمياً؛ رقم السند ونوعه وقيمته الاسمية ومدته وسعر الفائدة\n⭐ على ظهر السند: مجموع قيم الإسناد المصدرة؛ مواعيد وشروط الإطفاء واستحقاق الفائدة؛ الضمانات الخاصة؛ أي شروط أخرى تتوافق مع شروط الإصدار","qs":[{"q":"أي من البيانات التالية يجب أن يرد على ظهر سند القرض؟","o":["مجموع قيم إسناد القرض المصدرة","سعر الفائدة","اسم مالك السند إذا كان اسمياً","رقم تسجيل الشركة المقترضة"],"a":0},{"q":"أي من البيانات التالية يجب أن يرد على وجه سند القرض؟","o":["رقم السند ونوعه وقيمته الاسمية ومدته وسعر الفائدة","مواعيد وشروط إطفاء الإسناد","الضمانات الخاصة للدين الذي يمثله السند","مجموع قيم إسناد القرض المصدرة"],"a":0},{"q":"يجوز للشركة المقترضة إضافة شروط وأحكام أخرى إلى سند القرض بشرط:","o":["أن تتوافق مع شروط الإصدار","موافقة المراقب عليها","موافقة هيئة مالكي إسناد القرض","أن تدون على وجه السند"],"a":0}]},{"n":"122","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"اذا كانت اسناد القرض مضمونة باموال منقولة او غير منقولة او بموجودات عينية اخرى او بغير ذلك من الضمانات او الكفالات فيجب ان يتم وضع تلك الاموال والموجودات تأمينا للقرض وفقاً للتشريعات المعمول بها وتوثيق الرهن او الضمان او الكفالة قبل تسليم اموال الاكتتاب في اسناد القرض الى الشركة .","title":"الإسناد المضمونة بأموال أو موجودات","memo":"⭐ إذا كانت الإسناد مضمونة بأموال منقولة أو غير منقولة أو موجودات عينية أو كفالات، توضع تأميناً للقرض وفق التشريعات\n⭐ يجب توثيق الرهن أو الضمان أو الكفالة قبل تسليم أموال الاكتتاب إلى الشركة","qs":[{"q":"إذا كانت إسناد القرض مضمونة بأموال غير منقولة، فيجب توثيق الرهن:","o":["قبل تسليم أموال الاكتتاب في الإسناد إلى الشركة","خلال ثلاثين يوماً من تسليم أموال الاكتتاب","قبل موعد إطفاء الإسناد","بعد انتهاء مدة الاكتتاب بسنة"],"a":0},{"q":"أي مما يلي يصلح ضماناً لإسناد القرض وفق النص؟","o":["الأموال المنقولة وغير المنقولة والكفالات","الأموال غير المنقولة فقط","الكفالات المصرفية فقط","الأسهم التأسيسية للمؤسسين فقط"],"a":0}]},{"n":"123","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تحرر اسناد القرض بالدينار الاردني او باي عملة اجنبية وفق القوانين المعمول بها .","title":"عملة إسناد القرض","memo":"⭐ تحرر إسناد القرض بالدينار الأردني أو بأي عملة أجنبية وفق القوانين المعمول بها","qs":[{"q":"تحرر إسناد القرض الصادرة عن الشركة المساهمة العامة:","o":["بالدينار الأردني أو بأي عملة أجنبية وفق القوانين","بالدينار الأردني حصراً","بالدولار الأمريكي حصراً","بعملة يحددها البنك المركزي لكل إصدار"],"a":0}]},{"n":"124","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لمجلس الادارة ان يكتفي بقيمة الاسناد التي تم الاكتتاب بها اذا لم تتم تغطية جميع الاسناد الصادرة خلال المدة المقررة .","title":"عدم تغطية الإسناد بالكامل","memo":"⭐ إذا لم تغط جميع الإسناد خلال المدة المقررة، لمجلس الإدارة أن يكتفي بقيمة الإسناد المكتتب بها","qs":[{"q":"إذا لم تتم تغطية جميع إسناد القرض الصادرة خلال المدة المقررة، فإن:","o":["لمجلس الإدارة أن يكتفي بقيمة الإسناد التي تم الاكتتاب بها","الإصدار يعتبر باطلاً حكماً","على الشركة إعادة المبالغ للمكتتبين","يقرر المراقب تمديد مدة الاكتتاب"],"a":0}]},{"n":"125","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز للشركة اصدار اسناد قرض قابلة للتحويل الى اسهم وفقاً للاحكام التالية :-\nأ - ان يتضمن قرار مجلس الادارة جميع القواعد والشروط التي يتم على اساسها تحويل الاسناد الى اسهم وان يتم بموافقة مالكيها الخطية و بالشروط وطبقاً للاسس المحددة لذلك .\nب - أن يبدي حامل السند رغبته بالتحويل في المواعيد التي تنص عليها شروط الاصدار ، فإذا لم يبد رغبته خلال هذه المدة فقد حقه في التحويل .\nج - ان تكون للأسهم التي يحصل عليها مالكو الاسناد حقوق في الارباح تتناسب مع المدة الزمنية بين موعد التحويل وانتهاء السنة المالية .\nد - ان يتم في نهاية كل سنة مالية بيان عدد الاسهم التي تم اصدارها خلال السنة مقابل اسناد القرض التي رغب اصحابها في تحويلها الى اسهم خلال تلك السنة .","title":"إسناد القرض القابلة للتحويل","memo":"⭐ يتضمن قرار مجلس الإدارة جميع قواعد وشروط التحويل، ويتم بموافقة مالكي الإسناد الخطية\n⭐ يبدي حامل السند رغبته بالتحويل في المواعيد المحددة في شروط الإصدار وإلا فقد حقه\n⭐ للأسهم الناتجة حقوق في الأرباح تتناسب مع المدة بين موعد التحويل وانتهاء السنة المالية\n⭐ يبين في نهاية كل سنة مالية عدد الأسهم المصدرة مقابل الإسناد المحولة","qs":[{"q":"إذا لم يبد حامل السند القابل للتحويل رغبته بالتحويل في المواعيد المحددة في شروط الإصدار، فإنه:","o":["يفقد حقه في التحويل","يحول سنده إلى أسهم حكماً","يمنح مهلة إضافية مدتها ثلاثون يوماً","يسترد قيمة السند فوراً"],"a":0},{"q":"حقوق الأسهم التي يحصل عليها مالكو الإسناد المحولة في الأرباح تكون:","o":["متناسبة مع المدة الزمنية بين موعد التحويل وانتهاء السنة المالية","كاملة عن السنة المالية التي تم فيها التحويل","معدومة عن السنة المالية التي تم فيها التحويل","مساوية لسعر الفائدة على السند"],"a":0},{"q":"يتم تحويل إسناد القرض إلى أسهم بموافقة:","o":["مالكي الإسناد الخطية","أمين الإصدار وحده","المراقب","هيئة الأوراق المالية"],"a":0}]},{"n":"126","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تتكون حكماً من مالكي اسناد القرض في كل اصدار هيئة تسمى هيئة مالكي اسناد القرض .\nب - لهيئة مالكي اسناد القرض الحق ان تعين اميناً للاصدار على نفقة الشركة المصدرة لاسناد القرض .\nج - يشترط في امين الاصدار ان يكون مرخصاً لممارسة هذا النشاط من قبل الجهات المختصة .","title":"هيئة مالكي إسناد القرض","memo":"⭐ تتكون حكماً من مالكي الإسناد في كل إصدار هيئة تسمى هيئة مالكي إسناد القرض\n⭐ لها تعيين أمين للإصدار على نفقة الشركة المصدرة\n⭐ يشترط في أمين الإصدار أن يكون مرخصاً من الجهات المختصة","qs":[{"q":"تتكون هيئة مالكي إسناد القرض:","o":["حكماً من مالكي إسناد القرض في كل إصدار","بقرار من مجلس إدارة الشركة المصدرة","بقرار من المراقب","بقرار من الهيئة العامة للشركة"],"a":0},{"q":"يكون تعيين أمين الإصدار من قبل هيئة مالكي إسناد القرض على نفقة:","o":["الشركة المصدرة لإسناد القرض","مالكي الإسناد بالتساوي","متعهد التغطية","هيئة الأوراق المالية"],"a":0}]},{"n":"127","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تكون مهمة هيئة مالكي اسناد القرض حماية حقوق مالكيها واتخاذ التدابير اللازمة لصيانة هذه الحقوق بالتعاون مع امين الاصدار .\nب - تجتمع هيئة مالكي اسناد القرض لاول مرة بناء على دعوة من مجلس ادارة الشركة المصدرة للاسناد ويتولى امين الاصدار المعين دعوة الهيئة بعد ذلك .","title":"مهام هيئة مالكي إسناد القرض","memo":"⭐ مهمتها حماية حقوق مالكي الإسناد واتخاذ التدابير لصيانتها بالتعاون مع أمين الإصدار\n⭐ تجتمع لأول مرة بدعوة من مجلس إدارة الشركة المصدرة، ثم يتولى أمين الإصدار دعوتها","qs":[{"q":"تجتمع هيئة مالكي إسناد القرض لأول مرة بناءً على دعوة من:","o":["مجلس إدارة الشركة المصدرة للإسناد","أمين الإصدار","المراقب","هيئة الأوراق المالية"],"a":0},{"q":"بعد الاجتماع الأول لهيئة مالكي إسناد القرض، يتولى دعوتها للاجتماع:","o":["أمين الإصدار المعين","مجلس إدارة الشركة المصدرة","رئيس مجلس الإدارة","المراقب"],"a":0}]},{"n":"128","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يتولى امين الاصدار الصلاحيات التالية :\nأ - تمثيل هيئة مالكي اسناد القرض امام القضاء كمدع او مدعى عليه كما يمثلها امام اي جهة اخرى .\nب - تولي امانة اجتماعات هيئة مالكي اسناد القرض .\nج - القيام بالاعمال اللازمة لحماية مالكي اسناد القرض و المحافظة على حقوقهم .\nد - اي مهام اخرى توكله بها هيئة اسناد القرض .","title":"صلاحيات أمين الإصدار","memo":"⭐ تمثيل هيئة مالكي الإسناد أمام القضاء مدعياً أو مدعى عليه وأمام أي جهة أخرى\n⭐ تولي أمانة اجتماعات الهيئة، والقيام بأعمال حماية مالكي الإسناد، وأي مهام أخرى توكلها به الهيئة","qs":[{"q":"من يمثل هيئة مالكي إسناد القرض أمام القضاء كمدع أو مدعى عليه؟","o":["أمين الإصدار","رئيس مجلس إدارة الشركة المصدرة","المراقب","أكبر مالكي الإسناد"],"a":0},{"q":"أي مما يلي ليس من صلاحيات أمين الإصدار الواردة في النص؟","o":["التصويت على قرارات الهيئة العامة للشركة المقترضة","تولي أمانة اجتماعات هيئة مالكي إسناد القرض","القيام بالأعمال اللازمة لحماية مالكي الإسناد","أي مهام أخرى توكلها به هيئة مالكي الإسناد"],"a":0}]},{"n":"129","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"على الشركة المقترضة دعوة امين الاصدار لاجتماعات الهيئة العامة للشركة وعليه ان يحضر تلك الاجتماعات ويبدي ملاحظاته ولا يكون له حق التصويت على قرارات الهيئة العامة .","title":"حضور أمين الإصدار الهيئة العامة","memo":"⭐ على الشركة المقترضة دعوة أمين الإصدار لاجتماعات هيئتها العامة\n⭐ عليه الحضور وإبداء ملاحظاته، وليس له حق التصويت","qs":[{"q":"ما وضع أمين الإصدار في اجتماعات الهيئة العامة للشركة المقترضة؟","o":["يدعى ويحضر ويبدي ملاحظاته دون حق التصويت","يدعى ويحضر ويصوت على القرارات","لا يدعى إلا بطلب من المراقب","يحضر بصفة مراقب ويصوت على القرارات المتعلقة بالإسناد فقط"],"a":0},{"q":"حضور أمين الإصدار لاجتماعات الهيئة العامة للشركة المقترضة هو:","o":["واجب عليه بعد دعوته","جوازي له","مشروط بموافقة مجلس الإدارة","مقتصر على الاجتماعات غير العادية"],"a":0}]},{"n":"130","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - على امين الاصدار ان يدعو مالكي الاسناد للاجتماع كلما رأى ذلك ضرورياً على ان لا تقل اجتماعات هيئة مالكي اسناد القرض عن مرة واحدة في السنة .\nب - تدعى هيئة مالكي الاسناد وفقاً للقواعد المقررة لدعوة الهيئة العامة العادية وتطبق على الدعوة واجتماعاتها الاحكام ذاتها التي تطبق على هذه الهيئة .\nج - كل تصرف يخالف شروط اصدار اسناد القرض يعتبر باطلاً الا اذا اقرته هيئة مالكي اسناد القرض باكثرية ثلاثة ارباع اصواتهم الممثلة في الاجتماع شريطة ان لا تقل الاسناد الممثلة في الاجتماع عن ثلثي مجموع قيمة الاسناد المصدرة والمكتتب بها.\nد - يبلغ امين الاصدار قرارات هيئة مالكي اسناد القرض الى المراقب والشركة المصدرة للاسناد واي سوق للاوراق المالية تكون الاسناد مدرجة فيها .","title":"اجتماعات هيئة مالكي الإسناد","memo":"⭐ يدعو أمين الإصدار مالكي الإسناد كلما رأى ذلك ضرورياً، ولا تقل الاجتماعات عن مرة واحدة في السنة\n⭐ تدعى وفق قواعد دعوة الهيئة العامة العادية\n⭐ التصرف المخالف لشروط الإصدار باطل إلا إذا أقرته الهيئة بأكثرية ثلاثة أرباع الأصوات الممثلة، بشرط ألا تقل الإسناد الممثلة عن ثلثي مجموع قيمة الإسناد المصدرة والمكتتب بها\n⭐ يبلغ أمين الإصدار القرارات إلى المراقب والشركة المصدرة وسوق الأوراق المالية","qs":[{"q":"الحد الأدنى لعدد اجتماعات هيئة مالكي إسناد القرض هو:","o":["مرة واحدة في السنة","مرتان في السنة","أربع مرات في السنة","مرة كل ستة أشهر على الأقل"],"a":0},{"q":"التصرف المخالف لشروط إصدار إسناد القرض يعتبر باطلاً إلا إذا أقرته هيئة مالكي الإسناد بأكثرية:","o":["ثلاثة أرباع أصواتهم الممثلة في الاجتماع","ثلثي أصواتهم الممثلة في الاجتماع","الأكثرية المطلقة لأصواتهم الممثلة","نصف مجموع قيمة الإسناد المصدرة"],"a":0},{"q":"يشترط لصحة إقرار هيئة مالكي الإسناد لتصرف مخالف لشروط الإصدار ألا تقل الإسناد الممثلة في الاجتماع عن:","o":["ثلثي مجموع قيمة الإسناد المصدرة والمكتتب بها","نصف مجموع قيمة الإسناد المصدرة","ثلاثة أرباع مجموع قيمة الإسناد المصدرة","ربع مجموع قيمة الإسناد المكتتب بها"],"a":0},{"q":"تدعى هيئة مالكي إسناد القرض للاجتماع وفقاً للقواعد المقررة لدعوة:","o":["الهيئة العامة العادية","الهيئة العامة غير العادية","مجلس الإدارة","هيئة المديرين"],"a":0}]},{"n":"131","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز ان تتضمن شروط الاصدار حق الشركة باطفاء اسناد القرض بالقرعة سنوياً على مدة اسناد القرض .","title":"إطفاء إسناد القرض بالقرعة","memo":"⭐ يجوز أن تتضمن شروط الإصدار حق الشركة بإطفاء الإسناد بالقرعة سنوياً على مدة إسناد القرض","qs":[{"q":"يجوز أن تتضمن شروط الإصدار حق الشركة بإطفاء إسناد القرض:","o":["بالقرعة سنوياً على مدة إسناد القرض","دفعة واحدة قبل نهاية السنة الأولى","بقرار من المراقب","بالقرعة كل ثلاثة أشهر"],"a":0}]},{"n":"132","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠١٧-١٠-١٧"],"source":"أ - يتولى ادارة الشركة المساهمة العامة مجلس ادارة لا يقل عدد اعضائه عن ثلاثة اشخاص و لا يزيد على ثلاثة عشر شخصاً وفقاً لما يحدده نظام الشركة ,ويتم انتخابهم من قبل الهيئة العامة للشركة بالاقتراع السري ومن خلال التصويت النسبي والذي يتيح لكل مساهم الخيار بتوزيع عدد الأصوات حسب عدد الأسهم التي يمتلكها، على ان يكون للمساهم الحق باستخدام الأصوات لمرشح واحد او توزيعها على أكثر من مرشح بحيث يكون لكل سهم صوت واحد دون حصول تكرار لهذه الأصوات وفقاً لاحكام هذا القانون ,ويقوم بمهام ومسؤوليات ادارة اعمالها لمدة اربع سنوات تبدأ من تاريخ انتخابه .\nب - على مجلس الادارة ان يدعو الهيئة العامة للشركة للاجتماع خلال الاشهر الثلاثة الاخيرة من مدته لتنتخب مجلس ادارة يحل محله من تاريخ انتخابه ، على ان يستمر في عمله الى ان ينتخب مجلس الادارة الجديد اذا تأخر انتخابه لاي سبب من الاسباب ،و يشترط في ذلك ان لا تزيد مدة ذلك التأخير في اي حالة من الحالات على ثلاثة اشهر من تاريخ انتهاء مدة المجلس القائم .","title":"تشكيل مجلس الإدارة ومدته","memo":"⭐ عدد الأعضاء: لا يقل عن (٣) ولا يزيد على (١٣) وفق نظام الشركة\n⭐ ينتخب من الهيئة العامة بالاقتراع السري والتصويت النسبي (لكل سهم صوت دون تكرار)\n⭐ مدة المجلس (٤) سنوات من تاريخ انتخابه\n⭐ يدعو المجلس الهيئة العامة خلال الأشهر الثلاثة الأخيرة من مدته؛ والتأخير لا يزيد على (٣) أشهر من انتهاء مدته","qs":[{"q":"عدد أعضاء مجلس إدارة الشركة المساهمة العامة:","o":["لا يقل عن ثلاثة ولا يزيد على ثلاثة عشر","لا يقل عن خمسة ولا يزيد على تسعة","لا يقل عن ثلاثة ولا يزيد على تسعة","لا يقل عن خمسة ولا يزيد على ثلاثة عشر"],"a":0},{"q":"مدة مجلس إدارة الشركة المساهمة العامة هي:","o":["أربع سنوات تبدأ من تاريخ انتخابه","ثلاث سنوات تبدأ من تاريخ انتخابه","خمس سنوات تبدأ من تاريخ تسجيل الشركة","سنتان قابلتان للتجديد"],"a":0},{"q":"ينتخب أعضاء مجلس إدارة الشركة المساهمة العامة بالاقتراع السري ومن خلال:","o":["التصويت النسبي","التصويت التراكمي المكرر","التصويت برفع الأيدي","التصويت بالتعيين من المؤسسين"],"a":0},{"q":"انتهت مدة مجلس إدارة شركة مساهمة عامة وتأخر انتخاب المجلس الجديد، فإن مدة التأخير لا يجوز أن تزيد على:","o":["ثلاثة أشهر من تاريخ انتهاء مدة المجلس القائم","ستة أشهر من تاريخ انتهاء مدة المجلس القائم","شهر واحد من تاريخ انتهاء مدة المجلس القائم","سنة من تاريخ انتهاء مدة المجلس القائم"],"a":0}]},{"n":"133","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يحدد نظام الشركة المساهمة العامة عدد الاسهم التي يشترط ان يكون الشخص مالكاً لها في الشركة حتى يترشح لعضوية مجلس ادارتها ويبقى محتفظا بعضويته فيه، ويشترط في هذه الاسهم ان لا تكون محجوزة او مرهونة او مقيدة بأي قيد اخر يمنع التصرف المطلق بها ويستثنى من هذا الحكم القيد المنصوص عليه في المادة( ١٠٠ ) من هذا القانون الذي يقضي بعدم جواز التصرف في الاسهم التأسيسية .\nب - يبقى النصاب المؤهل لعضوية مجلس الادارة محجوزاً ما دام مالك الاسهم عضوا في المجلس ولمدة ستة اشهر بعد انتهاء عضويته فيها ولا يجوز التداول بها خلال تلك المدة. وتحقيقا لذلك توضع اشارة الحجز عليها مع الاشارة الى ذلك في سجل المساهمين ويعتبر هذا الحجز رهناً لمصلحة الشركة ولضمان المسؤوليات والالتزامات المترتبة على ذلك العضو وعلى مجلس الادارة .\nج - تسقط تلقائياً عضوية اي عضو من اعضاء مجلس ادارة الشركة المساهمة العامة اذا نقص عدد الاسهم التي يجب ان يكون مالكا لها بمقتضى احكام الفقرة ( أ ) من هذه المادة، لاي سبب من الاسباب او تثبيت الحجز عليها بحكم قضائي اكتسب الدرجة القطعية او تم رهنها خلال مدة عضويته، مالم يكمل الاسهم التي نقصت من اسهم التأهيل الخاصة به خلال مدة لا تزيد عن ثلاثين يوما ، و لا يجوز له ان يحضر اي اجتماع لمجلس الادارة خلال حدوث النقص في اسهمه .","title":"أسهم التأهيل لعضوية المجلس","memo":"⭐ يحدد نظام الشركة عدد أسهم التأهيل، ويشترط ألا تكون محجوزة أو مرهونة أو مقيدة (باستثناء قيد عدم التصرف بالأسهم التأسيسية م ١٠٠)\n⭐ تبقى أسهم التأهيل محجوزة طوال العضوية ولمدة (٦) أشهر بعد انتهائها، ويعتبر الحجز رهناً لمصلحة الشركة\n⭐ تسقط العضوية تلقائياً بنقص الأسهم أو حجزها بحكم قطعي أو رهنها ما لم يكملها خلال (٣٠) يوماً، ولا يحضر الاجتماعات خلال النقص","qs":[{"q":"الجهة التي تحدد عدد الأسهم التي يشترط امتلاكها للترشح لعضوية مجلس إدارة الشركة المساهمة العامة هي:","o":["نظام الشركة","المراقب","قانون الشركات بنسبة ثابتة","الهيئة العامة غير العادية في كل انتخاب"],"a":0},{"q":"تبقى أسهم التأهيل لعضوية مجلس الإدارة محجوزة طوال مدة العضوية ولمدة بعد انتهائها مقدارها:","o":["ستة أشهر","ثلاثة أشهر","سنة واحدة","ثلاثون يوماً"],"a":0},{"q":"نقص عدد أسهم التأهيل لدى عضو مجلس إدارة، فإن عضويته:","o":["تسقط تلقائياً ما لم يكمل الأسهم خلال مدة لا تزيد على ثلاثين يوماً","تسقط فوراً دون مهلة","تستمر حتى انتهاء مدة المجلس","تسقط بقرار من الهيئة العامة في أول اجتماع لها"],"a":0},{"q":"أي من القيود التالية على أسهم التأهيل لا يمنع الترشح لعضوية المجلس؟","o":["قيد عدم جواز التصرف في الأسهم التأسيسية","الحجز على الأسهم","رهن الأسهم","أي قيد يمنع التصرف المطلق بها"],"a":0}]},{"n":"134","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز ان يترشح لعضوية مجلس ادارة الشركة المساهمة العامة او يكون عضواً فيه اي شخص حكم عليه من محكمة مختصة بمايلي :\nأ - باي عقوبة جنائية او جنحية في جريمة مخلة بالشرف كالرشوة والاختلاس والسرقة والتزوير وسوء استعمال الامانة والشهادة الكاذبة او اي جريمة اخرى مخلة بالاداب والاخلاق العامة او ان يكون فاقد للاهلية المدنية او بالافلاس مالم يرد له اعتباره.\nب - باي عقوبة من العقوبات المنصوص عليها في المادة ( ٢٧٨ ) من هذا القانون .","title":"الممنوعون من الترشح لعضوية المجلس","memo":"⭐ لا يترشح ولا يكون عضواً من حكم عليه بعقوبة جنائية أو جنحية في جريمة مخلة بالشرف (رشوة، اختلاس، سرقة، تزوير، سوء استعمال أمانة، شهادة كاذبة) أو مخلة بالآداب\n⭐ أو فاقد الأهلية المدنية أو المحكوم بالإفلاس ما لم يرد له اعتباره\n⭐ أو المحكوم بأي عقوبة منصوص عليها في المادة (٢٧٨)","qs":[{"q":"حكم على شخص بجريمة سوء استعمال الأمانة ولم يرد له اعتباره، فإنه:","o":["لا يجوز له الترشح لعضوية مجلس إدارة الشركة المساهمة العامة","يجوز له الترشح بموافقة المراقب","يجوز له الترشح بعد مرور سنة على الحكم","يجوز له الترشح ممثلاً لشخص اعتباري فقط"],"a":0},{"q":"أي مما يلي لا يعد مانعاً من الترشح لعضوية مجلس إدارة الشركة المساهمة العامة وفق هذه المادة؟","o":["الحكم بالإفلاس مع رد الاعتبار","الحكم بعقوبة جنحية في جريمة الرشوة","فقدان الأهلية المدنية","الحكم بأي من العقوبات المنصوص عليها في المادة (٢٧٨)"],"a":0}]},{"n":"135","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - ١- إذا ساهمت الحكومة أو أي من الشركات المملوكة لها بالكامل أو أي من المؤسسات الرسمية العامة أو أي شخصية اعتبارية عامة أخرى كالمؤسسة العامة للضمان الاجتماعي في شركة مساهمة عامة تمثل في مجلس إدارتها بما يتناسب مع نسبة مساهمتها في رأسمال الشركة إذا كانت هذه النسبة تؤهلها لعضوية أو أكثر في المجلس، وتحرم في هذه الحالة من المشاركة في انتخاب أعضاء المجلس الأخرين، وإذا قلت مساهمتها عن النسبة التي تؤهلها لعضوية المجلس فتمارس حقها في الترشيح لهذه العضوية والمشاركة في انتخاب أعضاء المجلس شأنها شأن أي مساهم آخر، وفي جميع هذه الحالات يتمتع من يمثلها في المجلس بجميع حقوق العضوية ويتحمل واجباتها، ويشترط أن لا يعين أي شخص بمقتضى أحكام هذه الفقرة عضوا في أكثر من مجلس إدارة شركتين تساهم فيهما الحكومة أو المؤسسة الرسمية العامة أو الشخصية الاعتبارية العامة بما في ذلك الشركات العربية و الأجنبية التي تساهم فيها أي من هذه الجهات.\n٢- اذا تم ، وفي أي حال من الاحوال ، تعيين ممثل للحكومة او المؤسسة الرسمية العامة او الشخصية الاعتبارية العامة في اكثر من مجلس ادارة شركتين فعليه وتحت طائلة المسؤولية القانونية والتاديبية تصحيح وضعه وفقا لاحكام البند (١) من هذه الفقرة ، خلال مدة لا تتجاوز شهرا ، باعلام الجهة المختصة التي يمثلها لتعيين بديل له في الشركة التي تخلى عن عضويته فيها واشعار المراقب بذلك ، وينطبق هذا الحكم على جميع الحالات القائمة حين نفاذ احكام هذا القانون .\nب - تستمر عضوية ممثل الحكومة او المؤسسةالرسمية العامة او الشخصية الاعتبارية العامة الاخرى في مجلس ادارة الشركة المساهمة العامة للمدة المقررة للمجلس، وللجهة التي عينته استبدال غيره به في اي وقت من الاوقات ليكمل مدة سلفه في المجلس، او انتداب من يحل محله بصورة مؤقتة في حالة مرضه او غيابه عن المملكة ،على ان تبلغ الشركة خطياً في الحالتين .\nج - اذا استقال العضو الذي يمثل الحكومة او المؤسسة الرسمية العامة او اي شخصيةاعتبارية عامة اخرى من عضوية مجلس ادارة الشركة فتعتبر الاستقالة نافذة بحقه، وللجهة التي كان يمثلها في مجلس الادارة تعيين من يحل محله فيه .\nد - تحدد الاحكام الخاصة بتعيين ممثلي الحكومة في مجالس ادارة الشركات المساهمة العامة بموجب تعليمات يصدرها مجلس الوزراء لهذه الغاية على أن تراعي تمثيل المرأة وفقاً للنسبة التي تحددها هذه التعليمات .\nهـ - تطبق احكام هذه المادة على الحكومات والاشخاص الاعتبارية العامة غير الاردنية عند مساهمتها في رؤوس اموال اشركات الاردنية .","title":"تمثيل الحكومة والأشخاص العامة في المجلس","memo":"⭐ تمثل الحكومة والمؤسسات الرسمية والشخصيات الاعتبارية العامة (كالضمان الاجتماعي) في المجلس بنسبة مساهمتها، وتحرم من انتخاب الأعضاء الآخرين؛ وإن قلت مساهمتها عن نسبة العضوية تترشح وتنتخب كأي مساهم\n⭐ لا يعين الممثل في أكثر من مجلسي إدارة شركتين، وعليه تصحيح وضعه خلال مدة لا تتجاوز شهراً\n⭐ للجهة استبدال ممثلها في أي وقت ليكمل مدة سلفه أو انتداب بديل مؤقت عند المرض أو الغياب، مع تبليغ الشركة خطياً\n⭐ تعليمات تعيين ممثلي الحكومة يصدرها مجلس الوزراء مع مراعاة تمثيل المرأة؛ وتطبق على الحكومات غير الأردنية","qs":[{"q":"إذا كانت نسبة مساهمة الحكومة في شركة مساهمة عامة تؤهلها لعضوية في مجلس الإدارة، فإنها:","o":["تمثل في المجلس بنسبة مساهمتها وتحرم من المشاركة في انتخاب الأعضاء الآخرين","تمثل في المجلس وتشارك في انتخاب الأعضاء الآخرين","تشارك في الانتخاب كأي مساهم دون تعيين ممثل","تعين نصف أعضاء المجلس بغض النظر عن نسبتها"],"a":0},{"q":"لا يجوز تعيين ممثل الحكومة أو المؤسسة الرسمية العامة عضواً في أكثر من مجلس إدارة:","o":["شركتين","ثلاث شركات","خمس شركات","شركة واحدة"],"a":0},{"q":"عُيِّن ممثل للحكومة في مجالس إدارة ثلاث شركات، فعليه تصحيح وضعه خلال مدة:","o":["لا تتجاوز شهراً","لا تتجاوز أسبوعين","لا تتجاوز ثلاثة أشهر","لا تتجاوز ستين يوماً"],"a":0},{"q":"الجهة التي تصدر التعليمات الخاصة بتعيين ممثلي الحكومة في مجالس إدارة الشركات المساهمة العامة هي:","o":["مجلس الوزراء","وزير الصناعة والتجارة","المراقب","هيئة الأوراق المالية"],"a":0}]},{"n":"136","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"اذا كان الشخص الاعتباري من غير الاشخاص العامة المشار اليهم في المادة (١٣٥) من هذا القانون مساهما في شركة مساهمة عامة ، فيجوز له الترشح لعدد من المقاعد في مجلس الادارة حسب نسبة مساهمته في راسمال الشركة وفي حال انتخابه عليه تسمية شخص طبيعي لتمثيله في مجلس الادارة خلال عشرة ايام من تاريخ انتخابه وعلى ان تتوافر فيه شروط ومؤهلات العضوية المنصوص عليها في هذا القانون باستثناء حيازته للاسهم المؤهلة لعضوية المجلس ، ويعتبر الشخص الاعتباري فاقدا لعضويته اذا لم يقم بتسمية ممثله خلال شهر من تاريخ انتخابه ، كما يجوز له استبدال شخص طبيعي اخر بممثله خلال مدة المجلس .","title":"تمثيل الشخص الاعتباري الخاص في المجلس","memo":"⭐ يترشح الشخص الاعتباري (غير العام) لعدد من المقاعد حسب نسبة مساهمته\n⭐ يسمي شخصاً طبيعياً لتمثيله خلال (١٠) أيام من انتخابه، ولا يشترط فيه حيازة أسهم التأهيل\n⭐ يفقد العضوية إذا لم يسم ممثله خلال شهر من انتخابه، ويجوز له استبدال ممثله خلال مدة المجلس","qs":[{"q":"على الشخص الاعتباري الخاص المنتخب لعضوية مجلس الإدارة تسمية شخص طبيعي لتمثيله خلال:","o":["عشرة أيام من تاريخ انتخابه","سبعة أيام من تاريخ انتخابه","ثلاثين يوماً من تاريخ انتخابه","خمسة عشر يوماً من تاريخ انتخابه"],"a":0},{"q":"يعتبر الشخص الاعتباري فاقداً لعضويته في مجلس الإدارة إذا لم يسم ممثله خلال:","o":["شهر من تاريخ انتخابه","عشرة أيام من تاريخ انتخابه","ثلاثة أشهر من تاريخ انتخابه","أسبوعين من تاريخ انتخابه"],"a":0},{"q":"أي من شروط العضوية التالية لا يشترط توافره في ممثل الشخص الاعتباري الخاص في مجلس الإدارة؟","o":["حيازة الأسهم المؤهلة لعضوية المجلس","ألا يقل عمره عن واحد وعشرين سنة","ألا يكون محكوماً بجريمة مخلة بالشرف","ألا يكون موظفاً في الحكومة"],"a":0}]},{"n":"137","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - ينتخب مجلس ادارة الشركة المساهمة العامة من بين اعضائه بالاقتراع السري رئيساً ونائباً له يقوم بمهام وصلاحيات الرئيس عند غيابه كما ينتخب من بين اعضائه واحدا او اكثر يكون له او لهم حق التوقيع عن الشركة منفردين او مجتمعين وفقاً لما يقرره المجلس بهذا الشان وفي حدود الصلاحيات التي يفوضها اليهم ويزود مجلس ادارة الشركة المراقب بنسخ عن قراراته بانتخاب الرئيس ونائبه والاعضاء المفوضين بالتوقيع عن الشركة وبنماذج عن تواقيعهم وذلك خلال سبعة ايام من صدور تلك القرارات .\nب - لمجلس ادارة الشركة تفويض اي موظف في الشركة بالتوقيع عنها ،وذلك في حدود الصلاحيات التي يفوضها اليه .","title":"انتخاب الرئيس ونائبه والمفوضين بالتوقيع","memo":"⭐ ينتخب المجلس من بين أعضائه بالاقتراع السري رئيساً ونائباً له، وعضواً أو أكثر بحق التوقيع منفردين أو مجتمعين\n⭐ يزود المراقب بنسخ القرارات ونماذج التواقيع خلال (٧) أيام من صدورها\n⭐ للمجلس تفويض أي موظف بالتوقيع في حدود الصلاحيات المفوضة","qs":[{"q":"يزود مجلس الإدارة المراقب بنسخ عن قرارات انتخاب الرئيس ونائبه والمفوضين بالتوقيع خلال:","o":["سبعة أيام من صدور تلك القرارات","عشرة أيام من صدور تلك القرارات","خمسة عشر يوماً من صدور تلك القرارات","ثلاثين يوماً من صدور تلك القرارات"],"a":0},{"q":"ينتخب رئيس مجلس إدارة الشركة المساهمة العامة ونائبه:","o":["من قبل مجلس الإدارة من بين أعضائه بالاقتراع السري","من قبل الهيئة العامة بالاقتراع السري","بالتعيين من المراقب","من قبل أكبر المساهمين"],"a":0},{"q":"هل يجوز لمجلس إدارة الشركة المساهمة العامة تفويض موظف في الشركة بالتوقيع عنها؟","o":["نعم، في حدود الصلاحيات التي يفوضها إليه","لا، فالتوقيع مقصور على أعضاء المجلس","نعم، بشرط موافقة الهيئة العامة","نعم، بشرط موافقة المراقب"],"a":0}]},{"n":"138","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - على كل من رئيس واعضاء مجلس ادارة الشركة المساهمة العامة، وعلى كل من مديرها العام والمديرين الرئيسيين فيها ان يقدم الى مجلس الادارة في اول اجتماع يعقده بعد انتخابه اقراراً خطياً بما يملكه هو و كل من زوجته واولاده القاصرين من اسهم في الشركة واسماء الشركات الاخرى التي يملك هو و كل من زوجته واولاده القاصرين من اسهم في الشركة ، واسماء الشركات الاخرى التي يملك هو وكل من زوجته واولاده القاصرين حصصاً أو أسهماً فيها اذا كانت الشركة مساهمة في تلك الشركات الاخرى وان يقدم الى المجلس اي تغيير يطرأ على هذه البيانات خلال خمسة عشر يوماً من تاريخ وقوع التغيير .\nب - على مجلس ادارة الشركة ان يزود المراقب بنسخ عن البيانات المنصوص عليها في الفقرة ( أ ) من هذه المادة والتغيير الذي يطرأ على اي منها خلال سبعة ايام من تقديمها او تقديم اي تغيير طرأ عليها .","title":"إقرار الملكية لأعضاء المجلس والمديرين","memo":"⭐ يقدم الرئيس والأعضاء والمدير العام والمديرون الرئيسيون إقراراً خطياً في أول اجتماع للمجلس بعد انتخابه بما يملكه هو وزوجته وأولاده القاصرون من أسهم\n⭐ يقدم أي تغيير خلال (١٥) يوماً من وقوعه\n⭐ يزود المجلس المراقب بنسخ عن البيانات وتغييراتها خلال (٧) أيام من تقديمها","qs":[{"q":"يقدم عضو مجلس الإدارة إلى المجلس أي تغيير يطرأ على بيانات ملكيته للأسهم خلال:","o":["خمسة عشر يوماً من تاريخ وقوع التغيير","سبعة أيام من تاريخ وقوع التغيير","ثلاثين يوماً من تاريخ وقوع التغيير","عشرة أيام من تاريخ وقوع التغيير"],"a":0},{"q":"يزود مجلس الإدارة المراقب بنسخ عن إقرارات الملكية والتغييرات عليها خلال:","o":["سبعة أيام من تقديمها","خمسة عشر يوماً من تقديمها","ثلاثين يوماً من تقديمها","ثلاثة أيام من تقديمها"],"a":0},{"q":"أي من الأشخاص التالي ذكرهم لا يشمله إقرار الملكية الذي يقدمه عضو مجلس الإدارة وفق النص؟","o":["أولاده البالغون","زوجته","أولاده القاصرون","العضو نفسه"],"a":0}]},{"n":"139","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز للشركة المساهمة العامة تحت طائلة البطلان ان تقدم قرضاً نقدياً من اي نوع الى رئيس مجلس ادارة الشركة او الى اي من اعضائه او الى اصول اي منهم او فروعه او زوجه، ويستثنى من ذلك البنوك والشركات المالية التي يجوز لها ان تقرض اياً من اولئك ضمن غاياتها بالشروط التي تتعامل بها مع عملائها الاخرين .","title":"حظر إقراض أعضاء المجلس","memo":"⭐ لا يجوز تحت طائلة البطلان تقديم قرض نقدي لرئيس المجلس أو أي عضو أو لأصولهم أو فروعهم أو أزواجهم\n⭐ يستثنى البنوك والشركات المالية ضمن غاياتها وبالشروط نفسها التي تتعامل بها مع عملائها","qs":[{"q":"قدمت شركة مساهمة عامة صناعية قرضاً نقدياً لابن عضو في مجلس إدارتها، فإن حكم القرض:","o":["باطل","صحيح إذا وافقت عليه الهيئة العامة","صحيح إذا وافق عليه ثلثا أعضاء المجلس","صحيح بشرط إعلام المراقب"],"a":0},{"q":"يستثنى من حظر تقديم القروض النقدية لأعضاء مجلس الإدارة:","o":["البنوك والشركات المالية ضمن غاياتها وبشروط تعاملها مع عملائها","الشركات التي يزيد رأسمالها على مليون دينار","القروض التي يوافق عليها المراقب","القروض التي لا تزيد على راتب العضو السنوي"],"a":0}]},{"n":"140","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يترتب على مجلس ادارة الشركة المساهمة العامة ان يعد خلال مدة لا تزيد على ثلاثة اشهر من انتهاء السنة المالية للشركة الحسابات والبيانات التالية لعرضها على الهيئة العامة :-\n١ - الميزانية السنوية العامة للشركة وبيان الأرباح و الخسائر وبيان التدفقات النقدية والايضاحات حولها مقارنة مع السنة المالية السابقة مصدقة جميعها من مدققي حسابات الشركة .\n٢ - التقرير السنوي لمجلس الادارة عن اعمال الشركة خلال السنة الماضية وتوقعاتها المستقبلية للسنة القادمة .\nب - يزود مجلس الادارة المراقب بنسخ عن الحسابات والبيانات المنصوص عليها في الفقرة ( أ ) من هذه المادة قبل الموعد المحدد لاجتماع الهيئة العامة للشركة بمدة لا تقل عن واحد وعشرون يوماً .","title":"إعداد الحسابات والبيانات السنوية","memo":"⭐ يعد المجلس خلال مدة لا تزيد على (٣) أشهر من انتهاء السنة المالية: الميزانية وبيان الأرباح والخسائر والتدفقات النقدية والإيضاحات مقارنة بالسنة السابقة ومصدقة من المدققين، والتقرير السنوي\n⭐ يزود المراقب بنسخ قبل موعد اجتماع الهيئة العامة بمدة لا تقل عن (٢١) يوماً","qs":[{"q":"يعد مجلس إدارة الشركة المساهمة العامة الحسابات والبيانات السنوية خلال مدة لا تزيد على:","o":["ثلاثة أشهر من انتهاء السنة المالية","شهرين من انتهاء السنة المالية","أربعة أشهر من انتهاء السنة المالية","ستة أشهر من انتهاء السنة المالية"],"a":0},{"q":"يزود مجلس الإدارة المراقب بنسخ عن الحسابات والبيانات السنوية قبل موعد اجتماع الهيئة العامة بمدة لا تقل عن:","o":["واحد وعشرين يوماً","أربعة عشر يوماً","ثلاثين يوماً","سبعة أيام"],"a":0},{"q":"أي مما يلي ليس من الحسابات والبيانات التي يعدها المجلس لعرضها على الهيئة العامة وفق النص؟","o":["تقرير هيئة مالكي إسناد القرض","الميزانية السنوية العامة","بيان التدفقات النقدية","التقرير السنوي لمجلس الإدارة"],"a":0}]},{"n":"141","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"على مجلس الادارة للشركة المساهمة العامة ان ينشر الميزانية العامة للشركة وحساب ارباحها وخسائرها وخلاصة وافية عن التقرير السنوي للمجلس وتقرير مدققي حسابات الشركة خلال مدة لا تزيد على ثلاثين يوماً من تاريخ انعقاد الهيئة العامة .","title":"نشر الميزانية العامة","memo":"⭐ ينشر المجلس الميزانية العامة وحساب الأرباح والخسائر وخلاصة التقرير السنوي وتقرير المدققين\n⭐ خلال مدة لا تزيد على (٣٠) يوماً من تاريخ انعقاد الهيئة العامة","qs":[{"q":"ينشر مجلس إدارة الشركة المساهمة العامة الميزانية العامة وحساب الأرباح والخسائر خلال مدة لا تزيد على:","o":["ثلاثين يوماً من تاريخ انعقاد الهيئة العامة","ستين يوماً من تاريخ انعقاد الهيئة العامة","ثلاثة أشهر من انتهاء السنة المالية","أربعة عشر يوماً من تاريخ انعقاد الهيئة العامة"],"a":0},{"q":"أي مما يلي لا يشمله واجب النشر بموجب هذه المادة؟","o":["كشف المبالغ التي حصل عليها أعضاء المجلس","تقرير مدققي حسابات الشركة","خلاصة وافية عن التقرير السنوي للمجلس","حساب الأرباح والخسائر"],"a":0}]},{"n":"142","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يعد مجلس ادارة الشركة المساهمة العامة تقريرا كل ستة اشهر يتضمن المركز المالي للشركة ونتائج اعمالها وحساب الارباح والخسائر وقائمة التدفق النقدي والايضاحات المتعلقة بالبيانات المالية مصادقا عليه من مدقق حسابات الشركة ويزود المراقب بنسخة من التقرير خلال ستين يوما من انتهاء المدة .","title":"التقرير نصف السنوي","memo":"⭐ يعد المجلس تقريراً كل (٦) أشهر يتضمن المركز المالي ونتائج الأعمال والأرباح والخسائر والتدفق النقدي والإيضاحات\n⭐ مصادقاً عليه من مدقق الحسابات\n⭐ يزود المراقب بنسخة خلال (٦٠) يوماً من انتهاء المدة","qs":[{"q":"يعد مجلس إدارة الشركة المساهمة العامة تقريراً يتضمن المركز المالي ونتائج الأعمال كل:","o":["ستة أشهر","ثلاثة أشهر","سنة","شهرين"],"a":0},{"q":"يزود المراقب بنسخة من التقرير نصف السنوي خلال:","o":["ستين يوماً من انتهاء المدة","ثلاثين يوماً من انتهاء المدة","تسعين يوماً من انتهاء المدة","واحد وعشرين يوماً من انتهاء المدة"],"a":0},{"q":"التقرير نصف السنوي للشركة المساهمة العامة يجب أن يكون مصادقاً عليه من:","o":["مدقق حسابات الشركة","المراقب","الهيئة العامة","المدير المالي للشركة"],"a":0}]},{"n":"143","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يضع مجلس ادارة الشركة المساهمة العامة في مركزها الرئيسي قبل ثلاثة ايام على الأقل من الموعد المحدد لاجتماع الهيئة العامة للشركة كشفاً مفصلاً لاطلاع المساهمين يتضمن البيانات التالية ويتم تزويد المراقب بنسخة منها :-\n١ - جميع المبالغ التي حصل عليها كل من رئيس واعضاء مجلس الادارة من الشركة خلال السنة المالية من اجور واتعاب ورواتب وعلاوات ومكافآت وغيرها .\n٢ - المزايا التي يتمتع بها كل من رئيس واعضاء مجلس الادارة من الشركة كالمسكن المجاني والسيارات وغير ذلك .\n٣ - المبالغ التي دفعت لكل من رئيس واعضاء مجلس الادارة خلال السنة المالية كنفقات سفر وانتقال داخل المملكة وخارجها .\n٤ - التبرعات التي دفعتها الشركة خلال السنة المالية مفصلة والجهات التي دفعت لها .\n٥ - بيان باسماء اعضاء مجلس الادارة وعدد الاسهم التي يملكها كل منهم ومدة عضويته .\nب - يعتبر كل من رئيس واعضاء مجلس ادارة الشركة مسؤولين عن تنفيذ احكام هذه المادة وعن صحة البيانات التي تقدم بموجبها لاطلاع المساهمين عليها .","title":"كشف مبالغ ومزايا أعضاء المجلس","memo":"⭐ يضع المجلس في المركز الرئيسي قبل (٣) أيام على الأقل من اجتماع الهيئة العامة كشفاً مفصلاً لاطلاع المساهمين، ويزود المراقب بنسخة\n⭐ يتضمن: مبالغ الرئيس والأعضاء (أجور ورواتب ومكافآت)، المزايا (مسكن وسيارات)، نفقات السفر، التبرعات وجهاتها، أسماء الأعضاء وأسهمهم ومدة عضويتهم\n⭐ الرئيس والأعضاء مسؤولون عن تنفيذ المادة وصحة البيانات","qs":[{"q":"يضع مجلس الإدارة كشف المبالغ والمزايا المتعلقة بأعضائه لاطلاع المساهمين قبل موعد اجتماع الهيئة العامة بمدة:","o":["ثلاثة أيام على الأقل","سبعة أيام على الأقل","أربعة عشر يوماً على الأقل","واحد وعشرين يوماً على الأقل"],"a":0},{"q":"أي مما يلي لا يتضمنه الكشف المفصل المنصوص عليه في هذه المادة؟","o":["رواتب موظفي الشركة غير الأعضاء","التبرعات التي دفعتها الشركة والجهات التي دفعت لها","نفقات سفر الرئيس والأعضاء داخل المملكة وخارجها","المزايا كالمسكن المجاني والسيارات"],"a":0},{"q":"المسؤول عن صحة البيانات الواردة في الكشف المقدم لاطلاع المساهمين هو:","o":["رئيس وأعضاء مجلس الإدارة","مدقق الحسابات","المدير العام وحده","المراقب"],"a":0}]},{"n":"144","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يوجه مجلس ادارة الشركة المساهمة العامة الدعوة الى كل مساهم فيها لحضور اجتماع الهيئة العامة ترسل بالبريد العادي أو بوسائل الاتصال الإلكترونية وفقاً لقانون المعاملات الإلكترونية النافذ قبل أربعة عشر يوما على الاقل من التاريخ المقرر لعقد الاجتماع ويجوز تسليم الدعوة باليد للمساهم مقابل التوقيع بالاستلام .\nب - يرفق بالدعوة جدول اعمال الهيئة العامة وتقرير مجلس ادارة الشركة وميزانيتها السنوية العامة وحساباتها الختامية وتقرير مدققي الحسابات والبيانات الايضاحية .","title":"دعوة الهيئة العامة وجدول أعمالها","memo":"⭐ يوجه المجلس الدعوة لكل مساهم بالبريد العادي أو بالوسائل الإلكترونية قبل (١٤) يوماً على الأقل من الاجتماع، ويجوز التسليم باليد مقابل توقيع\n⭐ يرفق بالدعوة: جدول الأعمال، تقرير المجلس، الميزانية والحسابات الختامية، تقرير المدققين، البيانات الإيضاحية","qs":[{"q":"ترسل الدعوة لحضور اجتماع الهيئة العامة للشركة المساهمة العامة قبل التاريخ المقرر للاجتماع بمدة:","o":["أربعة عشر يوماً على الأقل","سبعة أيام على الأقل","واحد وعشرين يوماً على الأقل","ثلاثين يوماً على الأقل"],"a":0},{"q":"أي من الوسائل التالية لا تعد من وسائل توجيه الدعوة للمساهم وفق النص؟","o":["الإعلان في لوحة إعلانات الشركة فقط","البريد العادي","وسائل الاتصال الإلكترونية","التسليم باليد مقابل التوقيع بالاستلام"],"a":0},{"q":"أي مما يلي يرفق بدعوة الهيئة العامة للشركة المساهمة العامة؟","o":["تقرير مدققي الحسابات","التقرير نصف السنوي للمراقب","كشف التبرعات الموجه للمراقب فقط","قائمة دائني الشركة"],"a":0}]},{"n":"145","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"يترتب على مجلس ادارة الشركة المساهمة العامة ان يعلن عن الموعد المقرر لعقد اجتماع الهيئة العامة للشركة في صحيفتين يوميتين محليتين ولمرة واحدة على الاقل، وذلك قبل مدة لا تزيد على أربعة عشر يوماً من ذلك الموعد، وان يعلن المجلس عن ذلك لمرة واحدة في احدى وسائل الاعلام الصوتية او المرئية قبل ثلاثة ايام على الاكثر من التاريخ المحدد لاجتماع الهيئة العامة .","title":"الإعلان عن موعد اجتماع الهيئة العامة","memo":"⭐ يعلن المجلس في صحيفتين يوميتين محليتين لمرة واحدة على الأقل قبل مدة لا تزيد على (١٤) يوماً من الموعد\n⭐ ويعلن مرة واحدة في وسيلة إعلام صوتية أو مرئية قبل (٣) أيام على الأكثر من الموعد","qs":[{"q":"يعلن مجلس الإدارة عن موعد اجتماع الهيئة العامة في:","o":["صحيفتين يوميتين محليتين لمرة واحدة على الأقل","صحيفة يومية واحدة لمرتين","ثلاث صحف يومية لمرة واحدة","الجريدة الرسمية فقط"],"a":0},{"q":"يكون الإعلان في الصحف عن موعد اجتماع الهيئة العامة قبل الموعد بمدة:","o":["لا تزيد على أربعة عشر يوماً","لا تقل عن أربعة عشر يوماً","لا تزيد على ثلاثة أيام","لا تقل عن واحد وعشرين يوماً"],"a":0},{"q":"يعلن المجلس عن موعد اجتماع الهيئة العامة في إحدى وسائل الإعلام الصوتية أو المرئية قبل الموعد بمدة:","o":["ثلاثة أيام على الأكثر","سبعة أيام على الأقل","أربعة عشر يوماً على الأكثر","يوم واحد على الأقل"],"a":0}]},{"n":"146","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يجوز للشخص ان يكون عضواً في مجالس ادارة ثلاث شركات مساهمة عامة على الاكثر في وقت واحد بصفته الشخصية ، كما يجوز له ان يكون ممثلاً لشخص اعتباري في مجالس ادارة ثلاث شركات مساهمة عامة على الاكثر، وفي جميع الاحوال لا يجوز للشخص ان يكون عضواً في اكثر من مجالس ادارة خمس شركات مساهمة عامة بصفته الشخصية في بعضها وبصفته ممثلاً لشخص اعتباري في بعضها الاخر وتعتبر اي عضوية حصل عليها في مجلس ادارة شركة مساهمة خلافاً لاحكام هذه الفقرة باطلة حكماً .\nب - على كل عضو يتم انتخابه في مجلس ادارة اي شركة مساهمة عامة ان يعلم المراقب خطياً عن اسماء الشركات التي يشترك في عضوية مجالس ادارتها .\nج - لا يجوز لاي شخص ان يرشح نفسه لعضوية مجلس ادارة اي شركة مساهمة عامة بصفته الشخصية او ممثلاً لشخص اعتباري اذا كان عدد العضويات التي يشغلها قد بلغ العدد المنصوص عليه في الفقرة ( أ ) من هذه المادة الا انه يفسح له المجال بالاستقالة من احدى العضويات اذا رغب في ذلك خلال اسبوعين من تاريخ انتخابه للعضوية الجديدة ،على انه لا يجوز له ان يحضر اجتماع مجلس ادارة الشركة التي انتخب عضواً فيها قبل ان يكون قد وفق وضعه مع احكام هذه المادة .","title":"العضوية في أكثر من مجلس إدارة","memo":"⭐ بصفته الشخصية: (٣) شركات مساهمة عامة كحد أقصى؛ ممثلاً لشخص اعتباري: (٣) شركات كحد أقصى\n⭐ في جميع الأحوال لا تزيد على (٥) شركات بالصفتين معاً، والعضوية المخالفة باطلة حكماً\n⭐ يعلم العضو المراقب خطياً بأسماء الشركات التي هو عضو فيها\n⭐ من بلغ الحد يمكنه الاستقالة من إحدى العضويات خلال أسبوعين من انتخابه، ولا يحضر الاجتماعات قبل توفيق وضعه","qs":[{"q":"الحد الأقصى لعدد مجالس إدارة الشركات المساهمة العامة التي يجوز للشخص أن يكون عضواً فيها بصفته الشخصية في وقت واحد هو:","o":["ثلاث شركات","شركتان","خمس شركات","أربع شركات"],"a":0},{"q":"لا يجوز للشخص في جميع الأحوال أن يكون عضواً بصفته الشخصية وممثلاً لشخص اعتباري في أكثر من مجالس إدارة:","o":["خمس شركات مساهمة عامة","ست شركات مساهمة عامة","ثلاث شركات مساهمة عامة","أربع شركات مساهمة عامة"],"a":0},{"q":"انتخب شخص بلغ عدد عضوياته الحد الأقصى عضواً في مجلس إدارة شركة جديدة، فإنه يفسح له المجال بالاستقالة من إحدى العضويات خلال:","o":["أسبوعين من تاريخ انتخابه للعضوية الجديدة","شهر من تاريخ انتخابه للعضوية الجديدة","عشرة أيام من تاريخ انتخابه للعضوية الجديدة","ثلاثة أشهر من تاريخ انتخابه للعضوية الجديدة"],"a":0},{"q":"حكم العضوية التي يحصل عليها الشخص في مجلس إدارة شركة مساهمة خلافاً للحد الأقصى المقرر:","o":["باطلة حكماً","قابلة للإبطال بقرار من المحكمة","صحيحة حتى انتهاء مدة المجلس","موقوفة على موافقة المراقب"],"a":0}]},{"n":"147","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يشترط فيمن يرشح نفسه لعضوية مجلس ادارة اي شركة مساهمة عامة :-\n١ - ان لا يقل عمره عن واحد وعشرين سنة .\n٢ - ان لا يكون موظفاً في الحكومة او اي مؤسسة رسمية عامة .","title":"شروط الترشح لعضوية المجلس","memo":"⭐ ألا يقل عمر المرشح عن (٢١) سنة\n⭐ ألا يكون موظفاً في الحكومة أو أي مؤسسة رسمية عامة","qs":[{"q":"يشترط فيمن يرشح نفسه لعضوية مجلس إدارة شركة مساهمة عامة ألا يقل عمره عن:","o":["واحد وعشرين سنة","ثماني عشرة سنة","خمس وعشرين سنة","ثلاثين سنة"],"a":0},{"q":"أي من الأشخاص التاليين لا يجوز له ترشيح نفسه لعضوية مجلس إدارة شركة مساهمة عامة؟","o":["موظف في مؤسسة رسمية عامة عمره (٣٥) سنة","محام عمره (٢٢) سنة","تاجر عمره (٤٠) سنة","موظف في شركة خاصة عمره (٣٠) سنة"],"a":0}]},{"n":"148","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - لا يجوز لمن يشغل وظيفة عامة ان يكون عضواً في مجلس ادارة اي شركة مساهمة عامة الا اذا كان ممثلاً للحكومة او لاي مؤسسة رسمية عامة او لشخص اعتباري عام .\nب - لا يجوز لعضو مجلس ادارة الشركة او مديرها العام ان يكون عضواً في مجلس ادارة شركة مشابهة في اعمالها للشركة التي هو عضو مجلس ادارتها او مماثلة لها في غاياتها او تنافسها في اعمالها كما لا يجوز له ان يقوم باي عمل منافس لأعمالها .\nج - لا يجوز ان يكون لرئيس مجلس الادارة او أحد اعضائه او المدير العام او اي موظف يعمل في الشركة مصلحة مباشرة او غير مباشرة في العقود والمشاريع والارتباطات التي تعقد مع الشركة او لحسابها .\nد - يستثنى من احكام الفقرة ( ج ) من هذه المادة اعمال المقاولات والتعهدات والمناقصات العامة التي يسمح فيها لجميع المتنافسين الاشتراك في العروض على قدم المساواة فاذا كان العرض الأنسب مقدماً من احد المذكورين في الفقرة ( ج ) من هذه المادة فيجب ان يوافق ثلثا اعضاء مجلس الادارة على عرضه دون ان يكون له حق حضور جلسة المداولة في الموضوع المتعلق به ، وتجدد هذه الموافقة سنوياً من مجلس الادارة اذا كانت تلك العقود والارتباطات ذات طبيعة دورية ومتجددة .\nهـ - كل من يخالف احكام هذه المادة من الاشخاص المشار اليهم في الفقرة ( ج ) من هذه المادة يعزل منصبه او وظيفته في الشركة التي هو فيها .","title":"المحظورات على أعضاء المجلس","memo":"⭐ لا يكون شاغل الوظيفة العامة عضواً إلا ممثلاً للحكومة أو مؤسسة رسمية أو شخص اعتباري عام\n⭐ لا يكون العضو أو المدير العام عضواً في شركة مشابهة أو منافسة ولا يقوم بعمل منافس\n⭐ لا مصلحة مباشرة أو غير مباشرة للرئيس أو الأعضاء أو المدير العام أو أي موظف في عقود الشركة، باستثناء المناقصات العامة المتساوية بموافقة ثلثي الأعضاء دون حضور صاحب العلاقة، وتجدد سنوياً للعقود الدورية\n⭐ جزاء المخالفة: العزل من المنصب أو الوظيفة","qs":[{"q":"يجوز لمن يشغل وظيفة عامة أن يكون عضواً في مجلس إدارة شركة مساهمة عامة إذا كان:","o":["ممثلاً للحكومة أو لمؤسسة رسمية عامة أو لشخص اعتباري عام","مالكاً لأسهم التأهيل المطلوبة","حاصلاً على موافقة المراقب","متفرغاً لأعمال الشركة"],"a":0},{"q":"إذا كان العرض الأنسب في مناقصة عامة مقدماً من عضو في مجلس الإدارة، فيجب لقبوله موافقة:","o":["ثلثي أعضاء مجلس الإدارة دون حضوره جلسة المداولة","الأكثرية المطلقة لأعضاء المجلس بحضوره","الهيئة العامة غير العادية","المراقب"],"a":0},{"q":"جزاء مخالفة عضو مجلس الإدارة لحظر المصلحة في عقود الشركة وفق هذه المادة هو:","o":["العزل من منصبه أو وظيفته في الشركة","غرامة يحددها المراقب","الحبس مدة لا تقل عن سنة","الحرمان من المكافأة السنوية فقط"],"a":0},{"q":"موافقة مجلس الإدارة على العقود ذات الطبيعة الدورية والمتجددة مع أحد أعضائه وفق الاستثناء الوارد في النص:","o":["تجدد سنوياً","تكون لمرة واحدة طوال مدة المجلس","تجدد كل ستة أشهر","تجدد كل أربع سنوات"],"a":0}]},{"n":"149","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"اذا انتخب اي شخص عضواً في مجلس ادارة اي شركة مساهمة عامة وكان غائباً عند انتخابه فعليه ان يعلن عن قبوله بتلك العضوية او رفضها خلال عشرة ايام من تاريخ تبليغه نتيجة الانتخاب ويعتبر سكوته قبولاً منه بالعضوية .","title":"قبول العضو الغائب للعضوية","memo":"⭐ العضو المنتخب الغائب عند انتخابه يعلن قبوله أو رفضه خلال (١٠) أيام من تاريخ تبليغه النتيجة\n⭐ يعتبر سكوته قبولاً بالعضوية","qs":[{"q":"على الشخص المنتخب عضواً في مجلس الإدارة وهو غائب أن يعلن قبوله أو رفضه للعضوية خلال:","o":["عشرة أيام من تاريخ تبليغه نتيجة الانتخاب","سبعة أيام من تاريخ الانتخاب","ثلاثين يوماً من تاريخ تبليغه","خمسة عشر يوماً من تاريخ الانتخاب"],"a":0},{"q":"انتخب شخص غائب عضواً في مجلس الإدارة ولم يعلن موقفه خلال المدة المقررة بعد تبليغه، فإن سكوته يعتبر:","o":["قبولاً بالعضوية","رفضاً للعضوية","استقالة حكمية","موقوفاً على قرار الهيئة العامة"],"a":0}]},{"n":"150","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - ١. اذا شغر مركز عضو في مجلس الادارة لاي سبب من الأسباب فيخلفه عضو ينتخبه مجلس الادارة من المساهمين الحائزين على مؤهلات العضوية ويشترك الشخص المعنوي في هذا الانتخاب ويتبع هذا الاجراء كلما شغر مركز في مجلس الادارة ، ويبقى تعيين العضو بموجبه مؤقتا حتى يعرض على الهيئة العامة للشركة في اول اجتماع تعقده لتقوم باقراره او انتخاب من يملأ المركز الشاغر بمقتضى احكام هذا القانون وفي هذه الحالة يكمل العضو الجديد مدة سلفه في عضوية مجلس الادارة .\n.٢اذا لم يتم اقرار تعيين العضو الموقت او انتخاب غيره من قبل الهيئة العامة في اول اجتماع تعقده ، فتعتبر العضوية المؤقتة لذلك الشخص منتهية ، وعلى مجلس الادارة تعيين عضوا اخر على ان يعرض تعيينه على الهيئة العامة للشركة في اول اجتماع لاحق تعقده ووفق الاحكام المبينة في هذه الفقرة.\nب - لا يجوز ان يزيد عدد الاعضاء الذين يعينون في مجلس الادارة بمقتضى هذه المادة على نصف عدد اعضاء المجلس فاذا شغر مركز في المجلس بعد ذلك فتدعى الهيئة العامة لانتخاب مجلس ادارة جديد .","title":"شغور مركز في مجلس الإدارة","memo":"⭐ يملأ الشاغر بعضو ينتخبه المجلس من المساهمين الحائزين مؤهلات العضوية، ويشترك الشخص المعنوي في الانتخاب\n⭐ التعيين مؤقت حتى يعرض على الهيئة العامة في أول اجتماع لإقراره أو انتخاب غيره، ويكمل العضو مدة سلفه\n⭐ إذا لم يقر تنتهي العضوية المؤقتة ويعين المجلس عضواً آخر\n⭐ لا يزيد المعينون بموجب المادة على نصف عدد أعضاء المجلس، وبعدها تدعى الهيئة العامة لانتخاب مجلس جديد","qs":[{"q":"إذا شغر مركز عضو في مجلس إدارة الشركة المساهمة العامة، فإن من يملؤه مؤقتاً هو عضو:","o":["ينتخبه مجلس الإدارة من المساهمين الحائزين على مؤهلات العضوية","يعينه المراقب","تنتخبه الهيئة العامة غير العادية فوراً","يعينه رئيس المجلس منفرداً"],"a":0},{"q":"الحد الأقصى لعدد الأعضاء الذين يجوز تعيينهم في مجلس الإدارة لملء المراكز الشاغرة هو:","o":["نصف عدد أعضاء المجلس","ثلث عدد أعضاء المجلس","ربع عدد أعضاء المجلس","ثلثا عدد أعضاء المجلس"],"a":0},{"q":"مجلس إدارة من (٨) أعضاء عين فيه (٤) أعضاء لملء شواغر، ثم شغر مركز آخر، فإن الإجراء الواجب هو:","o":["دعوة الهيئة العامة لانتخاب مجلس إدارة جديد","تعيين عضو خامس من قبل المجلس","ترك المركز شاغراً حتى نهاية مدة المجلس","تعيين عضو من قبل المراقب"],"a":0}]},{"n":"151","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"مـع مراعـاة التشريعات الخاصـة وقواعـد الحوكمـة الصادرة بموجبها:-\nأ- تلتزم الشركات المساهمة العامة بتطبيق تعليمات قواعد الحوكمة الصادرة عن الوزير بناء على تنسيب المراقب بمـا فـي ذلـك تمثيـل المـرأة فـي مجـالس إدارة الشركات وفقاً للنسبة المحـددة فـي التعليمـات.\nب- تنظم الأمور المالية والمحاسبية والإدارية للشركة المساهمة العامة بموجب أنظمة داخلية خاصة يعدها مجلس إدارة الشركة، ويحدد فيها بصورة مفصلة واجبات المجلس وصلاحياته ومسؤولياته وعلاقته بالإدارة التنفيذية، ويبين اللجان الواجب تأليفها وبما يتماشى ودليل قواعد الحوكمة المشار إليه في الفقرة (أ) من هذه المادة .\nج - تحتفظ الشركة بنسخة من الأنظمـة الداخليـة وعلـى الشـركة تزويد المراقب بها عند طلبه.","title":"قواعد الحوكمة والأنظمة الداخلية","memo":"⭐ تلتزم الشركات المساهمة العامة بتعليمات قواعد الحوكمة الصادرة عن الوزير بتنسيب المراقب، بما فيها تمثيل المرأة في مجالس الإدارة وفق النسبة المحددة\n⭐ الأمور المالية والمحاسبية والإدارية تنظم بأنظمة داخلية يعدها مجلس الإدارة وتحدد واجباته وصلاحياته وعلاقته بالإدارة التنفيذية واللجان\n⭐ تحتفظ الشركة بنسخة منها وتزود المراقب بها عند طلبه","qs":[{"q":"تصدر تعليمات قواعد الحوكمة التي تلتزم بها الشركات المساهمة العامة عن:","o":["الوزير بناءً على تنسيب المراقب","المراقب منفرداً","مجلس الوزراء","الهيئة العامة للشركة"],"a":0},{"q":"الجهة التي تعد الأنظمة الداخلية الخاصة بالأمور المالية والمحاسبية والإدارية للشركة المساهمة العامة هي:","o":["مجلس إدارة الشركة","الهيئة العامة غير العادية","المراقب","مدقق الحسابات"],"a":0},{"q":"ما التزام الشركة المساهمة العامة تجاه المراقب فيما يتعلق بأنظمتها الداخلية؟","o":["تزويده بها عند طلبه","إيداعها لديه خلال (٧) أيام من إعدادها","الحصول على موافقته المسبقة عليها","نشرها في صحيفتين يوميتين"],"a":0}]},{"n":"152","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠١٧-١٠-١٧"],"source":"أ - يعتبر رئيس مجلس الادارة رئيسا للشركة المساهمة العامة ويمثلها لدى الغير وامام جميع الجهات بما في ذلك الجهات القضائية المختصة وله ان يفوض من يمثله امام هذه الجهات ويمارس رئيس المجلس الصلاحيات المخولة له بموجب احكام هذا القانون والانظمة الصادرة بمقتضاه والانظمة الاخرى المعمول بها في الشركة ويتولى تنفيذ قرارات مجلس الادارة بالتعاون مع الجهاز التنفيذي في الشركة .\nب - يجوز ان يكون رئيس مجلس الادارة متفرغاً لاعمال الشركة بموافقة ثلثي اعضاء المجلس ويحدد مجلس الادارة في هذه الحالة الصلاحيات والمسؤوليات التي يحق له ممارستها بوضوح كما يحدد اتعابه والعلاوات التي يستحقها ويشترط في ذلك ان لا يكون رئيسا متفرغا لمجلس ادارة شركة مساهمة عامة اخرى او مديرا عاما لاي شركة مساهمة عامة اخرى .\nج - يجوز تعيين عضو مجلس إدارة الشركة المساهمة العامة من غير الرئيس مديراً عاماً للشركة او مساعداً او نائباً له بقرار يصدر عن اكثرية ثلثي اصوات اعضاء المجلس في اي حالة من هذه الحالات على ان لا يشترك صاحب العلاقة في التصويت .","title":"صلاحيات رئيس مجلس الإدارة","memo":"⭐ رئيس المجلس رئيس للشركة ويمثلها أمام الغير وجميع الجهات بما فيها القضائية، وله تفويض من يمثله\n⭐ يجوز أن يكون متفرغاً بموافقة ثلثي أعضاء المجلس، بشرط ألا يكون رئيساً متفرغاً أو مديراً عاماً لشركة مساهمة عامة أخرى\n⭐ يجوز تعيين عضو (غير الرئيس) مديراً عاماً أو مساعداً أو نائباً له بأكثرية ثلثي أصوات الأعضاء دون مشاركة صاحب العلاقة","qs":[{"q":"من يمثل الشركة المساهمة العامة لدى الغير وأمام الجهات القضائية؟","o":["رئيس مجلس الإدارة","المدير العام","أمين سر المجلس","نائب رئيس المجلس دائماً"],"a":0},{"q":"يجوز أن يكون رئيس مجلس الإدارة متفرغاً لأعمال الشركة بموافقة:","o":["ثلثي أعضاء المجلس","الأكثرية المطلقة لأعضاء المجلس","الهيئة العامة العادية","المراقب"],"a":0},{"q":"قرر مجلس الإدارة تعيين أحد أعضائه (من غير الرئيس) مديراً عاماً للشركة، فإن ذلك يتطلب:","o":["أكثرية ثلثي أصوات أعضاء المجلس دون مشاركة صاحب العلاقة في التصويت","الأكثرية المطلقة للأعضاء الحاضرين بمشاركة صاحب العلاقة","موافقة الهيئة العامة غير العادية","إجماع أعضاء المجلس"],"a":0}]},{"n":"153","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يعين مجلس الادارة مديراً عاماً للشركة المساهمة العامة من ذوي الكفاءة ويحدد صلاحياته ومسؤولياته بموجب تعليمات يصدرها المجلس لهذه الغاية، ويفوضه بالادارة العامة لها بالتعاون مع مجلس الادارة وتحت اشرافه ويحدد المجلس راتب المدير العام ويشترط في ذلك ان لا يكون مديرا عاما لاكثر من شركة مساهمة عامة واحدة .\nب - لمجلس ادارة الشركة المساهمة العامة انهاء خدمات المدير العام على ان يعلم المراقب باي قرار يتخذ بشأن تعيين المدير العام للشركة او انهاء خدماته وذلك حال اتخاذ القرار .\nج - اذا كانت الاوراق المالية للشركة مدرجة في السوق المالي فيتم اعلام السوق المالي باي قرار يتخذ بشأن تعيين المدير العام للشركة او انهاء خدماته وذلك حال اتخاذ القرار .\nد - لا يجوز لرئيس مجلس ادارة الشركة المساهمة العامة او لاي عضو من اعضائه ان يتولى اي عمل او وظيفة في الشركة مقابل اجر او تعويض او مكافأة باستثناء ما نص عليه في هذا القانون الا في الحالات التي تقتضيها طبيعة عمل الشركة ويوافق عليها مجلس الادارة باغلبية ثلثي اعضاؤه على ان لا يشارك الشخص المعني في التصويت .","title":"المدير العام","memo":"⭐ يعين المجلس مديراً عاماً من ذوي الكفاءة ويحدد صلاحياته وراتبه، بشرط ألا يكون مديراً عاماً لأكثر من شركة مساهمة عامة واحدة\n⭐ للمجلس إنهاء خدماته، ويعلم المراقب (والسوق المالي إن كانت الأوراق مدرجة) بقرار التعيين أو الإنهاء حال اتخاذه\n⭐ لا يتولى الرئيس أو العضو عملاً بأجر في الشركة إلا لطبيعة العمل وبموافقة ثلثي أعضاء المجلس دون مشاركة الشخص المعني","qs":[{"q":"الجهة التي تعين المدير العام للشركة المساهمة العامة وتحدد راتبه هي:","o":["مجلس الإدارة","الهيئة العامة","المراقب","رئيس مجلس الإدارة منفرداً"],"a":0},{"q":"متى يجب إعلام المراقب بقرار تعيين المدير العام للشركة المساهمة العامة أو إنهاء خدماته؟","o":["حال اتخاذ القرار","خلال سبعة أيام من اتخاذ القرار","خلال ثلاثين يوماً من اتخاذ القرار","في أول اجتماع للهيئة العامة"],"a":0},{"q":"يجوز لعضو مجلس الإدارة أن يتولى وظيفة في الشركة مقابل أجر في الحالات التي تقتضيها طبيعة عمل الشركة بموافقة:","o":["ثلثي أعضاء المجلس دون مشاركة الشخص المعني في التصويت","الأكثرية المطلقة لأعضاء المجلس بمن فيهم الشخص المعني","الهيئة العامة غير العادية","المراقب"],"a":0}]},{"n":"154","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يعين مجلس الادارة من بين موظفي الشركة امين سر للمجلس ويحدد مكافاته ، يتولى تنظيم اجتماعاته واعداد جداول اعماله وتدوين محاضر اجتماعاته وقراراته في سجل خاص وفي صفحات متتالية مرقمة بالتسلسل وتوقع من رئيس واعضاء المجلس الذين حضروا الاجتماع وتختم كل صفحة بخاتم الشركة .","title":"أمين سر مجلس الإدارة","memo":"⭐ يعين المجلس أمين السر من بين موظفي الشركة ويحدد مكافأته\n⭐ ينظم الاجتماعات ويعد جداول الأعمال ويدون المحاضر في سجل خاص بصفحات متتالية مرقمة\n⭐ توقع المحاضر من الرئيس والأعضاء الحاضرين وتختم كل صفحة بخاتم الشركة","qs":[{"q":"يعين أمين سر مجلس إدارة الشركة المساهمة العامة:","o":["من قبل مجلس الإدارة من بين موظفي الشركة","من قبل الهيئة العامة من بين المساهمين","من قبل المراقب","من قبل المدير العام من خارج الشركة"],"a":0},{"q":"توقع محاضر اجتماعات مجلس الإدارة من قبل:","o":["رئيس وأعضاء المجلس الذين حضروا الاجتماع","أمين السر وحده","رئيس المجلس وحده","المدير العام ومدقق الحسابات"],"a":0}]},{"n":"155","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يجتمع مجلس ادارة الشركة المساهمة العامة بدعوة خطية من رئيسه او نائبه في حالة غيابه او بناء على طلب خطي يقدمه الى رئيس المجلس ربع اعضائه على الاقل يبينون فيه الاسباب الداعية لعقد الاجتماع فاذا لم يوجه رئيس المجلس او نائبه الدعوة للمجلس الى الاجتماع خلال سبعة ايام من تاريخ تسلمه الطلب فللأعضاء الذين قدموا الطلب دعوته للإنعقاد .\nب - يعقد مجلس ادارة الشركة المساهمة العامة اجتماعاته بحضور الاكثرية المطلقة لاعضاء المجلس في مركز الشركة الرئيسي او في اي مكان آخر داخل المملكة اذا تعذر عقده في مركزها الا انه يحق للشركات التي لها فروع خارج المملكة او كانت طبيعة عمل الشركة تتطلب ذلك ، عقد اجتماعين على الاكثر لمجلس ادارتها في السنة خارج المملكة ، وتصدر قرارات المجلس بالأكثرية المطلقة للأعضاء الذين حضروا الاجتماع واذا تساوت الاصوات يرجح الجانب الذي صوت معه رئيس الاجتماع .\nج - يكون التصويت على قرارات مجلس ادارة الشركة شخصياً ويقوم به العضو بنفسه ولا يجوز التوكيل فيه كما لا يجوز ان يتم بالمراسلة او بصورة غير مباشرة اخرى .\nد - يجب ان لا يقل عدد اجتماعات مجلس ادارة الشركة المساهمة العامة عن ستة اجتماعات خلال السنة المالية للشركة ، وان لا ينقضي اكثر من شهرين دون عقد اجتماع للمجلس ويبلغ المراقب نسخة من الدعوة للإجتماع .","title":"اجتماعات مجلس الإدارة","memo":"⭐ يجتمع بدعوة خطية من الرئيس أو نائبه، أو بطلب خطي من ربع الأعضاء على الأقل؛ وإذا لم يدع خلال (٧) أيام فللطالبين دعوته\n⭐ النصاب: الأكثرية المطلقة للأعضاء؛ القرارات بالأكثرية المطلقة للحاضرين، وعند التساوي يرجح جانب رئيس الاجتماع\n⭐ يجوز عقد اجتماعين على الأكثر سنوياً خارج المملكة للشركات ذات الفروع الخارجية أو لطبيعة العمل\n⭐ التصويت شخصي دون توكيل أو مراسلة؛ لا تقل الاجتماعات عن (٦) سنوياً ولا يمضي أكثر من شهرين دون اجتماع","qs":[{"q":"الحد الأدنى لعدد اجتماعات مجلس إدارة الشركة المساهمة العامة خلال السنة المالية هو:","o":["ستة اجتماعات","أربعة اجتماعات","اثنا عشر اجتماعاً","ثلاثة اجتماعات"],"a":0},{"q":"يجتمع مجلس الإدارة بناءً على طلب خطي يقدمه إلى رئيس المجلس عدد من الأعضاء لا يقل عن:","o":["ربع أعضائه","ثلث أعضائه","نصف أعضائه","عضوين"],"a":0},{"q":"تساوت الأصوات في اجتماع مجلس إدارة شركة مساهمة عامة، فإن القرار:","o":["يرجح فيه الجانب الذي صوت معه رئيس الاجتماع","يعتبر مرفوضاً","يحال إلى الهيئة العامة","يعاد التصويت عليه في اجتماع لاحق"],"a":0},{"q":"أي مما يلي جائز بالنسبة للتصويت على قرارات مجلس إدارة الشركة المساهمة العامة؟","o":["أن يقوم به العضو بنفسه شخصياً","التوكيل فيه لعضو آخر","التصويت بالمراسلة","التصويت بصورة غير مباشرة"],"a":0}]},{"n":"156","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يكون لمجلس ادارة الشركة المساهمة العامة او مديرها العام الصلاحيات الكاملة في ادارة الشركة في الحدود التي بينها نظامها وتعتبر الاعمال والتصرفات التي يقوم بها ويمارسها المجلس او مدير الشركة باسمها ملزمة لها في مواجهة الغير الذي يتعامل مع الشركة بحسن نية ولها الرجوع عليه بقيمة التعويض عن الضرر الذي لحق بها وذلك بغض النظر عن اي قيد يرد في نظام الشركة او عقد تأسيسها .\nب - يعتبر الغير الذي يتعامل مع الشركة حسن النية ما لم يثبت غير ذلك على انه لا يلزم ذلك الغير بالتحقق من وجود اي قيد على صلاحيات مجلس الادارة او مدير الشركة او على سلطتهم في الزام الشركة بموجب عقدها في نظامها .\nج. على مجلس ادارة الشركة وضع جدول يبين فيه صلاحيات التوقيع عن الشركة في مختلف الامور على الانموذج الذي يعتمده الوزير بناء على تنسيب المراقب ، وكذلك الصلاحيات والسلطات الاخرى المخولة لكل من الرئيس والمدير العام وخاصة اذا كان الرئيس متفرغا لاعمال الشركة ، كما يبين ذلك الجدول أي امور يراها المجلس ضرورية لتسيير اعمال الشركة وتعاملها مع الغير .","title":"صلاحيات مجلس ادارة الشركة المساهمة العامة","memo":"⭐ لمجلس الإدارة أو المدير العام الصلاحيات الكاملة في إدارة الشركة في حدود نظامها، وتصرفاتهم ملزمة للشركة تجاه الغير حسن النية بغض النظر عن أي قيد في النظام أو العقد\n⭐ الغير يعتبر حسن النية ما لم يثبت غير ذلك، ولا يلزم بالتحقق من القيود على الصلاحيات\n⭐ جدول صلاحيات التوقيع يضعه المجلس على الأنموذج الذي يعتمده الوزير بتنسيب المراقب","qs":[{"q":"تعتبر تصرفات مجلس إدارة الشركة المساهمة العامة باسم الشركة ملزمة لها في مواجهة الغير الذي يتعامل معها:","o":["بحسن نية بغض النظر عن أي قيد في نظام الشركة أو عقد تأسيسها","فقط إذا كانت ضمن القيود الواردة في عقد التأسيس","فقط بعد موافقة الهيئة العامة عليها","فقط إذا تحقق الغير من صلاحيات المجلس قبل التعامل"],"a":0},{"q":"بالنسبة للغير الذي يتعامل مع الشركة المساهمة العامة، فإن القاعدة هي:","o":["يعتبر حسن النية ما لم يثبت غير ذلك ولا يلزم بالتحقق من القيود على صلاحيات المجلس","يعتبر سيئ النية حتى يثبت العكس","يلزم بالتحقق من القيود على صلاحيات المجلس قبل التعامل","يعتبر حسن النية فقط إذا كان مساهماً في الشركة"],"a":0},{"q":"يضع مجلس الإدارة جدول صلاحيات التوقيع عن الشركة على الأنموذج الذي يعتمده:","o":["الوزير بناء على تنسيب المراقب","المراقب بناء على تنسيب الوزير","الهيئة العامة للشركة","هيئة الأوراق المالية"],"a":0}]},{"n":"157","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - رئيس واعضاء مجلس ادارة الشركة المساهمة العامة مسؤولون تجاه الشركة والمساهمين والغير عن كل مخالفة ارتكبها اي منهم او جميعهم للقوانين والانظمة المعمول بها ولنظام الشركة وعن اي خطأ في ادارة الشركة ولا تحول موافقة الهيئة العامة على ابراء ذمة مجلس الادارة دون الملاحقة القانونية لرئيس واعضاء المجلس .\nب - تكون المسؤولية المنصوص عليها في الفقرة ( أ ) من هذه المادة أما شخصية تترتب على عضو او اكثر من اعضاء مجلس ادارة الشركة او مشتركة بين رئيس واعضاء المجلس ويكونون جميعهم في هذه الحالة الاخيرة مسؤولين بالتضامن والتكافل عن التعويض عن الضرر الذي نتج عن المخالفة او الخطأ ، على ان لا تشمل هذه المسؤولية اي عضو اثبت اعتراضه خطياً في محضر للاجتماع على القرار الذي تضمن المخالفة او الخطأ وفي جميع الاحوال لا تسمع الدعوى بهذه المسؤولية بعد مرور خمس سنوات على تاريخ اجتماع الهيئة العامة الذي صادقت فيه على الميزانية السنوية والحسابات الختامية للشركة .","title":"مخالفة رئيس واعضاء مجلس الادارة لانظمة الشركة","memo":"⭐ الرئيس والأعضاء مسؤولون تجاه الشركة والمساهمين والغير عن أي مخالفة أو خطأ في الإدارة\n⭐ إبراء ذمة المجلس من الهيئة العامة لا يحول دون الملاحقة القانونية\n⭐ المسؤولية شخصية أو مشتركة (بالتضامن والتكافل)، ولا تشمل العضو الذي أثبت اعتراضه خطياً في المحضر\n⭐ لا تسمع الدعوى بعد مرور (٥) سنوات على اجتماع الهيئة العامة الذي صادق على الميزانية والحسابات الختامية","qs":[{"q":"لا تسمع دعوى مسؤولية رئيس وأعضاء مجلس الإدارة عن المخالفات بعد مرور:","o":["خمس سنوات على تاريخ اجتماع الهيئة العامة الذي صادقت فيه على الميزانية السنوية","ثلاث سنوات على تاريخ وقوع المخالفة","سنتين على تاريخ اجتماع الهيئة العامة","عشر سنوات على تاريخ وقوع المخالفة"],"a":0},{"q":"في حالة المسؤولية المشتركة عن قرار تضمن مخالفة، لا تشمل المسؤولية العضو الذي:","o":["أثبت اعتراضه خطياً في محضر الاجتماع على القرار","تغيب عن الاجتماع بعذر مقبول","امتنع عن التصويت دون تسجيل اعتراض","يمثل شخصاً اعتبارياً خاصاً"],"a":0},{"q":"وافقت الهيئة العامة على إبراء ذمة مجلس الإدارة، ثم تبين وجود مخالفة للقانون ارتكبها المجلس. ما الحكم؟","o":["لا تحول موافقة الهيئة العامة على الإبراء دون الملاحقة القانونية للرئيس والأعضاء","يسقط حق الملاحقة بموافقة الهيئة العامة على الإبراء","لا تجوز الملاحقة إلا بموافقة الوزير","تقتصر الملاحقة على المدير العام دون أعضاء المجلس"],"a":0}]},{"n":"158","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يحظر على رئيس واعضاء مجلس ادارة الشركة المساهمة العامة ومديرها العام أو اي موظف يعمل فيها ان يفشي الى اي مساهم في الشركة او الى غيره اي معلومات او بيانات تتعلق بالشركة وتعتبر ذات طبيعة سرية بالنسبة لها وكان قد حصل عليها بحكم منصبه في الشركة او قيامه باي عمل لها او فيها وذلك تحت طائلة العزل والمطالبة بالتعويض عن الاضرار التي لحقت بالشركة .\nويستثنى من ذلك المعلومات التي تجيز القوانين والانظمة المعمول بها نشرها ولا تحول موافقة الهيئة العامة على ابراء رئيس واعضاء مجلس الإدارة من هذه المسؤولية .","title":"افشاء المعلومات السرية","memo":"⭐ يحظر على الرئيس والأعضاء والمدير العام وأي موظف إفشاء المعلومات السرية التي حصل عليها بحكم منصبه\n⭐ الجزاء: العزل والمطالبة بالتعويض\n⭐ يستثنى ما تجيز القوانين والأنظمة نشره، ولا يحول إبراء الهيئة العامة دون هذه المسؤولية","qs":[{"q":"جزاء قيام عضو مجلس إدارة بإفشاء معلومات سرية عن الشركة حصل عليها بحكم منصبه هو:","o":["العزل والمطالبة بالتعويض عن الأضرار التي لحقت بالشركة","غرامة تحددها الهيئة العامة فقط","الإنذار الخطي من المراقب","الحرمان من المكافأة السنوية فقط"],"a":0},{"q":"يستثنى من حظر إفشاء المعلومات المتعلقة بالشركة:","o":["المعلومات التي تجيز القوانين والأنظمة المعمول بها نشرها","المعلومات التي يطلبها أي مساهم في الشركة","المعلومات التي يوافق المدير العام على إفشائها","المعلومات التي مضى عليها أكثر من سنة"],"a":0},{"q":"يشمل حظر إفشاء المعلومات السرية للشركة المساهمة العامة جميع ما يلي باستثناء:","o":["المراقب العام للشركات","رئيس مجلس الإدارة","المدير العام","أي موظف يعمل في الشركة"],"a":0}]},{"n":"159","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"رئيس واعضاء مجلس ادارة الشركة المساهمة العامة مسؤولون بالتضامن والتكافل تجاه المساهمين عن تقصيرهم او إهمالهم في ادارة الشركة غير انه في حالة تصفية الشركة وظهور عجز في موجوداتها بحيث لا تستطيع الوفاء بالتزاماتها وكان سبب هذا العجز او التقصير او الاهمال من رئيس واعضاء المجلس او المدير العام في ادارة الشركة او مدققي الحسابات للمحكمة ان تقرر تحميل كل مسؤول عن هذا العجز ديون الشركة كلها او بعضها حسب مقتضى الحال ، وتحدد المحكمة المبالغ الواجب اداؤها وما اذا كان المسببون للخسارة متضامنين في المسؤولية او لا .","title":"مسؤولية رئيس واعضاء مجلس الادارة عن تقصيرهم واهمالهم في ادارة الشركة","memo":"⭐ الرئيس والأعضاء مسؤولون بالتضامن والتكافل تجاه المساهمين عن التقصير أو الإهمال\n⭐ عند التصفية وظهور عجز سببه تقصير الرئيس أو الأعضاء أو المدير العام أو مدققي الحسابات: للمحكمة تحميل المسؤول ديون الشركة كلها أو بعضها\n⭐ المحكمة تحدد المبالغ وما إذا كان المسببون متضامنين","qs":[{"q":"في حالة تصفية الشركة وظهور عجز في موجوداتها بسبب تقصير مجلس الإدارة، فإن الجهة التي تقرر تحميل المسؤول ديون الشركة هي:","o":["المحكمة","المراقب","الوزير","الهيئة العامة"],"a":0},{"q":"يجوز تحميل المسؤول عن العجز في موجودات الشركة عند تصفيتها:","o":["ديون الشركة كلها أو بعضها حسب مقتضى الحال","نصف ديون الشركة كحد أقصى","قيمة أسهمه في الشركة فقط","مقدار المكافآت التي تقاضاها فقط"],"a":0},{"q":"من الذين يجوز تحميلهم ديون الشركة عند ظهور عجز في موجوداتها بسبب تقصيرهم، وفقاً للمادة، ما يلي باستثناء:","o":["المساهمين غير الأعضاء في مجلس الإدارة","المدير العام","مدققي الحسابات","أعضاء مجلس الإدارة"],"a":0}]},{"n":"160","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ-يحق للمراقب وللشركة ولاي مساهم فيها اقامة الدعوى بمقتضى احكام المواد ( ١٥٧ و ١٥٨ و ١٥٩ ) من هذا القانون.\nب- تتمتع أقلية المساهمين بحقوق وضمانات في الشركة على أن تحدد نسبتهم وحقوقهم بموجب تعليمات تصدرها الهيئة لهذه الغاية.","title":"الحق في اقامة الدعوى","memo":"⭐ يحق للمراقب وللشركة ولأي مساهم إقامة الدعوى بموجب المواد (١٥٧ و١٥٨ و١٥٩)\n⭐ تتمتع أقلية المساهمين بحقوق وضمانات، وتحدد نسبتهم وحقوقهم بتعليمات تصدرها الهيئة","qs":[{"q":"يحق إقامة دعوى المسؤولية على أعضاء مجلس الإدارة بموجب المواد (١٥٧ و١٥٨ و١٥٩) لكل من:","o":["المراقب والشركة وأي مساهم فيها","المراقب فقط","الشركة فقط من خلال الهيئة العامة","المساهمين الذين يملكون ١٠٪ من الأسهم فقط"],"a":0},{"q":"تحدد نسبة أقلية المساهمين وحقوقهم بموجب:","o":["تعليمات تصدرها الهيئة","نظام الشركة الأساسي","قرار من الهيئة العامة للشركة","قرار من مجلس الوزراء"],"a":0}]},{"n":"161","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - لا يمكن الاحتجاج بالابراء الصادر عن الهيئة العامة الا اذا سبقه بيان حسابات الشركة السنوية واعلان تقرير مدققي الحسابات .\nب - لا يشمل هذا الابراء الا الامور التي تمكنت الهيئة العامة من معرفتها .","title":"احتجاج رئيس و اعضاء مجلس الادارة بالابراء الصادر عن الهيئة العامة","memo":"⭐ لا يحتج بالإبراء الصادر عن الهيئة العامة إلا إذا سبقه بيان حسابات الشركة السنوية وإعلان تقرير مدققي الحسابات\n⭐ لا يشمل الإبراء إلا الأمور التي تمكنت الهيئة العامة من معرفتها","qs":[{"q":"لا يمكن الاحتجاج بالإبراء الصادر عن الهيئة العامة إلا إذا سبقه:","o":["بيان حسابات الشركة السنوية وإعلان تقرير مدققي الحسابات","موافقة المراقب الخطية","مرور ستة أشهر على انتهاء السنة المالية","قرار من الوزير بالمصادقة عليه"],"a":0},{"q":"يشمل الإبراء الصادر عن الهيئة العامة لمجلس الإدارة:","o":["الأمور التي تمكنت الهيئة العامة من معرفتها فقط","جميع أعمال المجلس خلال السنة المالية","جميع أعمال المجلس منذ تأسيس الشركة","الأمور الواردة في تقرير المدير العام فقط"],"a":0}]},{"n":"162","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تحدد مكافأة رئيس واعضاء مجلس الادارة في الشركة المساهمة العامة بنسبة ( %١٠ ) من الربح الصافي القابل للتوزيع على المساهمين بعد تنزيل جميع الضرائب والإحتياطات وبحد اقصى ( ٥٠٠٠ ) خمسة الاف دينار لكل منهم في السنة ، وتوزع المكافأة عليهم بنسبة عدد الجلسات التي حضرها كل منهم ، وتعتبر الجلسات التي لم يحضرها العضو لسبب مشروع يوافق عليه المجلس من الجلسات التي حضرها العضو .\nب - اذا كانت الشركة في مرحلة التأسيس ولم تحقق بعد ارباحاً يجوز توزيع مكافأة سنوية لرئيس واعضاء مجلس الإدارة بمعدل لا يتجاوز الف دينار لكل عضو الى ان تبدأ الشركة بتحقيق الارباح وعندها تخضع لإحكام الفقرة ( أ ) من هذه المادة .\nج - اما اذا لحقت بالشركة خسائر بعد تحقيق الارباح او لم تكن قد حققت ارباحاً بعد فيعطى لكل من رئيس واعضاء مجلس الادارة تعويضاً عن جهدهم في ادارة الشركة بمعدل ( ٢٠ ) ديناراً عن كل جلسة من جلسات مجلس الإدارة او اي اجتماع للجان المنبثقة عنه على ان لا تتجاوز هذه المكافآت مبلغ ( ٦٠٠ ) دينار ستمائة دينار في السنة لكل عضو .\nد - تحدد بدلات الانتقال والسفر لرئيس واعضاء مجلس الادارة بموجب نظام خاص تصدره الشركة لهذه الغاية .","title":"مكافأة رئيس واعضاء مجلس الادارة في الشركة","memo":"⭐ المكافأة: (١٠٪) من الربح الصافي القابل للتوزيع بعد الضرائب والاحتياطيات، بحد أقصى (٥٠٠٠) دينار لكل عضو سنوياً، وتوزع بنسبة الجلسات المحضورة\n⭐ مرحلة التأسيس دون أرباح: مكافأة لا تتجاوز (١٠٠٠) دينار لكل عضو\n⭐ عند الخسارة أو عدم تحقيق أرباح: (٢٠) ديناراً عن كل جلسة وبحد أقصى (٦٠٠) دينار سنوياً\n⭐ بدلات الانتقال والسفر بنظام خاص تصدره الشركة","qs":[{"q":"تحدد مكافأة رئيس وأعضاء مجلس إدارة الشركة المساهمة العامة بنسبة:","o":["١٠٪ من الربح الصافي القابل للتوزيع وبحد أقصى ٥٠٠٠ دينار لكل منهم سنوياً","٥٪ من الربح الصافي وبحد أقصى ١٠٠٠٠ دينار","١٠٪ من الربح الإجمالي وبحد أقصى ٣٠٠٠ دينار","٢٠٪ من الربح الصافي وبحد أقصى ٥٠٠٠ دينار"],"a":0},{"q":"شركة مساهمة عامة في مرحلة التأسيس لم تحقق أرباحاً بعد، يجوز أن توزع مكافأة سنوية لكل عضو مجلس إدارة لا تتجاوز:","o":["ألف دينار","ستمائة دينار","خمسة آلاف دينار","ألفي دينار"],"a":0},{"q":"إذا لحقت بالشركة خسائر بعد تحقيق الأرباح، يعطى العضو تعويضاً عن كل جلسة بمعدل ... وبحد أقصى سنوي ...:","o":["٢٠ ديناراً للجلسة، و٦٠٠ دينار في السنة","٥٠ ديناراً للجلسة، و١٠٠٠ دينار في السنة","٢٠ ديناراً للجلسة، و١٠٠٠ دينار في السنة","٣٠ ديناراً للجلسة، و٦٠٠ دينار في السنة"],"a":0},{"q":"تعتبر الجلسة التي لم يحضرها العضو من الجلسات التي حضرها لغايات توزيع المكافأة إذا كان التغيب:","o":["لسبب مشروع يوافق عليه المجلس","بسبب السفر خارج المملكة مطلقاً","بعذر يقبله المراقب","لأي سبب كان"],"a":0}]},{"n":"163","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لعضو مجلس ادارة الشركة المساهمة العامة من غير ممثل الشخص الاعتباري العام ان يقدم استقالته من المجلس على ان تكون هذه الاستقالة خطية وتعتبر نافذة المفعول من تاريخ تقديمها الى المجلس ولا يجوز الرجوع عنها .","title":"استقالة عضو مجلس الادارة","memo":"⭐ لعضو المجلس (من غير ممثل الشخص الاعتباري العام) تقديم استقالته\n⭐ يجب أن تكون خطية، ونافذة من تاريخ تقديمها للمجلس، ولا يجوز الرجوع عنها","qs":[{"q":"تعتبر استقالة عضو مجلس إدارة الشركة المساهمة العامة نافذة المفعول:","o":["من تاريخ تقديمها إلى المجلس","من تاريخ موافقة المجلس عليها","من تاريخ موافقة المراقب عليها","بعد مرور شهر على تقديمها"],"a":0},{"q":"أي مما يلي صحيح بشأن استقالة عضو مجلس الإدارة في الشركة المساهمة العامة؟","o":["يجب أن تكون خطية ولا يجوز الرجوع عنها","يجوز أن تكون شفوية في اجتماع المجلس","يجوز الرجوع عنها خلال عشرة أيام","تحتاج لموافقة الهيئة العامة لتصبح نافذة"],"a":0}]},{"n":"164","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يفقد رئيس مجلس ادارة الشركة المساهمة العامة واي من اعضائه عضويته من المجلس اذا تغيب عن حضور اربع اجتماعات متتالية للمجلس دون عذر يقبله المجلس او اذا تغيب عن حضور اجتماعات المجلس لمدة ستة اشهر متتالية ولو كان هذا التغيب بعذر مقبول ، ويبلغ المراقب القرار الذي يصدره المجلس بمقتضى احكام هذه الفقرة .\nب - لا يفقد الشخص الاعتباري الخاص عضويته من مجلس ادارة الشركة المساهمة العامة بسبب تغيب ممثله في اي من الحالتين المنصوص عليهما في الفقرة ( أ ) من هذه المادة ولكن يجب عليه ان يعين شخصاً آخر بدلاً عنه بعد تبليغه قرار المجلس خلال شهر من تبليغه عن تغيب ممثله ويعتبر فاقدا للعضوية اذا لم يعمد لتسمية ممثل جديد خلال تلك المدة .","title":"فقدان عضوية رئيس واعضاء مجلس الادارة","memo":"⭐ يفقد العضو عضويته إذا تغيب (٤) اجتماعات متتالية دون عذر يقبله المجلس، أو (٦) أشهر متتالية ولو بعذر مقبول\n⭐ يبلغ المراقب بقرار المجلس\n⭐ الشخص الاعتباري الخاص لا يفقد العضوية بتغيب ممثله، لكن عليه تعيين بديل خلال شهر من تبليغه وإلا فقد العضوية","qs":[{"q":"يفقد عضو مجلس إدارة الشركة المساهمة العامة عضويته إذا تغيب دون عذر يقبله المجلس عن حضور:","o":["أربعة اجتماعات متتالية","ثلاثة اجتماعات متتالية","ستة اجتماعات متتالية","اجتماعين متتاليين"],"a":0},{"q":"يفقد العضو عضويته إذا تغيب عن حضور اجتماعات المجلس ولو بعذر مقبول لمدة:","o":["ستة أشهر متتالية","ثلاثة أشهر متتالية","سنة كاملة","أربعة أشهر متتالية"],"a":0},{"q":"تغيب ممثل شخص اعتباري خاص عن أربعة اجتماعات متتالية دون عذر. ما الحكم؟","o":["لا يفقد الشخص الاعتباري عضويته، وعليه تعيين بديل خلال شهر من تبليغه وإلا اعتبر فاقداً للعضوية","يفقد الشخص الاعتباري عضويته فوراً","لا يترتب أي أثر لأن العضوية للشخص الاعتباري","على الشخص الاعتباري تعيين بديل خلال ستة أشهر"],"a":0}]},{"n":"165","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يحق للهيئة العامة للشركة المساهمة العامة في اجتماع غير عادي تعقده اقالة رئيس مجلس الادارة او اي عضو من اعضائه باستثناء الاعضاء الممثلين لاسهم الحكومة او اي شخص اعتباري عام وذلك بناء على طلب موقع من مساهمين يملكون ما لا يقل عن ( %٣٠ ) ثلاثين بالمائة من اسهم الشركة ، ويقدم طلب الاقالة الى مجلس الادارة وتبلغ نسخه منه الى المراقب ، وعلى مجلس الاداره دعوة الهيئة العامة لعقد اجتماع غير عادي لها خلال عشرة ايام من تاريخ تقديم الطلب اليه لتنظر الهيئة العامة فيه واصدار القرار الذي تراه مناسباً بشأنه ، واذا لم يقم مجلس الادارة بدعوة الهيئة العامة الى الاجتماع يتولى المراقب دعوتها على نفقة الشركة .\nب - تتولى الهيئة العامة مناقشة طلب اقالة اي عضو ولها سماع اقواله شفاهاً او كتابة ، ويجري بعد ذلك التصويت على الطلب بالاقتراع السري فاذا قررت الهيئة العامة اقالته فعليها انتخاب بديل له وفقا لقواعد انتخاب اعضاء مجلس الادارة المقررة .\nج - اذا لم تتم الاقالة وفقا لاحكام هذه المادة فلا يجوز طلب مناقشة الاقالة للسبب ذاته قبل مرور ستة اشهر من تاريخ اجتماع الهيئة العامة التي تمت فيه مناقشة طلب الاقالة .","title":"حق الهيئة العامة في اقالة رئيس واعضاء مجلس الادارة","memo":"⭐ للهيئة العامة في اجتماع غير عادي إقالة الرئيس أو أي عضو (باستثناء ممثلي الحكومة أو أي شخص اعتباري عام)\n⭐ بطلب موقع من مساهمين يملكون ما لا يقل عن (٣٠٪) من الأسهم، يقدم للمجلس وتبلغ نسخة للمراقب\n⭐ على المجلس الدعوة خلال (١٠) أيام، وإلا يدعو المراقب على نفقة الشركة؛ التصويت بالاقتراع السري\n⭐ إذا لم تتم الإقالة لا تطلب للسبب ذاته قبل (٦) أشهر","qs":[{"q":"يقدم طلب إقالة عضو مجلس إدارة الشركة المساهمة العامة بطلب موقع من مساهمين يملكون ما لا يقل عن:","o":["٣٠٪ من أسهم الشركة","٢٥٪ من أسهم الشركة","١٥٪ من أسهم الشركة","٥٠٪ من أسهم الشركة"],"a":0},{"q":"على مجلس الإدارة دعوة الهيئة العامة لاجتماع غير عادي للنظر في طلب الإقالة خلال:","o":["عشرة أيام من تاريخ تقديم الطلب","خمسة عشر يوماً من تاريخ تقديم الطلب","شهر من تاريخ تقديم الطلب","سبعة أيام من تاريخ تقديم الطلب"],"a":0},{"q":"لم توافق الهيئة العامة على إقالة أحد الأعضاء، فلا يجوز طلب مناقشة إقالته للسبب ذاته قبل مرور:","o":["ستة أشهر من تاريخ اجتماع الهيئة العامة","ثلاثة أشهر من تاريخ الاجتماع","سنة من تاريخ الاجتماع","شهر من تاريخ الاجتماع"],"a":0},{"q":"يجوز للهيئة العامة إقالة أي من الأعضاء التاليين باستثناء:","o":["العضو الممثل لأسهم الحكومة","رئيس مجلس الإدارة","العضو الممثل لشخص اعتباري خاص","العضو المنتخب بصفته الشخصية"],"a":0}]},{"n":"166","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يحظر على رئيس واعضاء مجلس ادارة الشركة المساهمة العامة والمدير العام للشركة واي موظف فيها ان يتعامل بأسهم الشركة بصورة مباشرة او غير مباشرة بناء على معلومات اطلع عليها بحكم منصبه او عمله في الشركة كما لا يجوز ان ينقل هذه المعلومات لاي شخص اخر بقصد احداث تأثير في اسعار اسهم هذه الشركة أو اي شركة تابعة او قابضة حليفة للشركة التي هو عضو او موظف فيها او اذا كان من شأن النقل احداث ذلك التأثير ، ويقع باطلاً كل تعامل او معاملة تنطبق عليها أحكام هذه المادة ويعتبر الشخص الذي قام بذلك مسؤولاً عن الضرر الذي احدثه بالشركة او بمساهميها او بالغير اذا اثير بشأنها قضية .","title":"منع رئيس واعضاء مجلس الادارة والمدير العام","memo":"⭐ يحظر على الرئيس والأعضاء والمدير العام وأي موظف التعامل بأسهم الشركة مباشرة أو غير مباشرة بناء على معلومات اطلع عليها بحكم منصبه\n⭐ ولا يجوز نقل هذه المعلومات بقصد التأثير في أسعار أسهم الشركة أو الشركات التابعة أو القابضة أو الحليفة\n⭐ يقع باطلاً كل تعامل مخالف، ويسأل الفاعل عن الضرر","qs":[{"q":"ما حكم تعامل المدير العام بأسهم الشركة بناء على معلومات اطلع عليها بحكم منصبه؟","o":["يقع التعامل باطلاً ويكون مسؤولاً عن الضرر","يكون التعامل صحيحاً مع فرض غرامة","يكون التعامل موقوفاً على إجازة الهيئة العامة","يكون التعامل صحيحاً إذا تم بصورة غير مباشرة"],"a":0},{"q":"يحظر نقل المعلومات التي اطلع عليها العضو بحكم منصبه إلى أي شخص آخر بقصد إحداث تأثير في أسعار أسهم:","o":["الشركة أو أي شركة تابعة أو قابضة أو حليفة لها","الشركة نفسها فقط","الشركات المنافسة فقط","الشركات المدرجة في السوق المالي فقط"],"a":0}]},{"n":"167","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - اذا قدم رئيس واعضاء مجلس ادارة الشركة المساهمة العامة استقالاتهم او فقد المجلس نصابه القانوني بسبب استقالة عدد من اعضائه او اذا لم تتمكن الهيئة العامة من انتخاب مجلس ادارة للشركة فعلى الوزير بناء على تنسب المراقب تشكيل لجنة مؤقتة من ذوي الخبرة والاختصاص بالعدد الذي يراه مناسباً ويعين لها رئيساً ونائباً له من بين اعضائها لتتولى ادارة الشركة ، ودعوة الهيئة العامة لها للإجتماع خلال مدة لا تزيد على ستة اشهر من تاريخ تشكيلها لانتخاب مجلس ادارة جديد للشركة ، ويمنح رئيس اللجنة واعضاؤها مكافأة على حساب الشركة وفقاً لما يقرره الوزير .\nب - تطبق احكام الفقرة ( أ ) من هذه المادة على البنوك وشركات الخدمات المالية وشركات التامين ، بعد الاستئناس براي محافظ البنك المركزي ، وهيئة الاوراق المالية وهيئة تنظيم قطاع التامين حسب مقتضى الحال .","title":"حق الوزير في تشكيل لجنة لادارة الشركة عند استقالة رئيس واعضاء مجلس الادارة","memo":"⭐ عند استقالة المجلس أو فقده النصاب أو تعذر انتخابه: يشكل الوزير بتنسيب المراقب لجنة مؤقتة من ذوي الخبرة\n⭐ تدعو اللجنة الهيئة العامة خلال مدة لا تزيد على (٦) أشهر من تشكيلها لانتخاب مجلس جديد\n⭐ مكافأة اللجنة على حساب الشركة وفق ما يقرره الوزير\n⭐ تطبق على البنوك وشركات الخدمات المالية والتأمين بعد الاستئناس برأي البنك المركزي/هيئة الأوراق المالية/هيئة تنظيم قطاع التأمين","qs":[{"q":"إذا قدم رئيس وأعضاء مجلس إدارة الشركة المساهمة العامة استقالاتهم، فإن الذي يشكل لجنة مؤقتة لإدارة الشركة هو:","o":["الوزير بناء على تنسيب المراقب","المراقب بناء على تنسيب الوزير","الهيئة العامة في اجتماع غير عادي","المحكمة بناء على طلب المساهمين"],"a":0},{"q":"على اللجنة المؤقتة دعوة الهيئة العامة للاجتماع لانتخاب مجلس إدارة جديد خلال مدة لا تزيد على:","o":["ستة أشهر من تاريخ تشكيلها","ثلاثة أشهر من تاريخ تشكيلها","سنة من تاريخ تشكيلها","شهر من تاريخ تشكيلها"],"a":0},{"q":"تمنح رئيس وأعضاء اللجنة المؤقتة مكافأة:","o":["على حساب الشركة وفقاً لما يقرره الوزير","على حساب دائرة مراقبة الشركات","وفقاً لما تقرره الهيئة العامة","بنسبة ١٠٪ من الربح الصافي"],"a":0}]},{"n":"168","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - اذا تعرضت الشركة لأوضاع مالية أو إدارية سيئة او تعرضت لخسائر جسيمة تؤثر في حقوق المساهمين او في حقوق دائنيها او قيام مجلس ادارتها او أي من اعضاء المجلس او مديرها العام باستغلال صلاحياته ومركزه باي صورة كانت لتحقق له او لغيره أي منفعة بطريقة غير مشروعة ويسري هذا الحكم في حال امتناع اي منهم عن عمل يستوجب القانون القيام به او قيامه باي عمل ينطوي على تلاعب او يعتبر اختلاسا او احتيالا او تزويرا او اساءة ائتمان وبشكل يؤدي الى المساس بحقوق الشركة او مساهميها او الغير فعلى رئيس مجلس ادارتها او احد اعضائها او مديرها العام او مدقق حساباتها تبليغ المراقب بذلك وذلك تحت طائلة المسؤولية التقصيرية في حالة عدم التبليغ عن ذلك .\nب - يقوم الوزير في اي من هذه الحالات بناء على تنسيب المراقب بعد التحقق من صحة ما ورد في التبليغ بحل مجلس ادارة الشركة وتشكيل لجنة من ذوي الخبرة والاختصاص لادارة الشركة بالعدد الذي يراه مناسباً لمدة ستة شهور قابلة للتمديد لمرتين على الاكثر ويعين رئيساً لها ونائباً للرئيس من بين اعضائها وعليها في هذه الحالة دعوة الهيئة العامة خلال تلك المدة لانتخاب مجلس ادارة جديد للشركة ويمنح رئيس اللجنة وأعضائها مكافأة على حساب الشركة وفقاً لما يقرره الوزير .\nج - تسري احكام هذه المادة على الشركات ذات المسؤولية المحدودة والشركات المساهمة الخاصة في أي حالة يوافق عليها مجلس الوزراء بناء على تنسيب الوزير .","title":"وجوب تبليغ المراقب عند تعرض الشركة لخسارة جسيمة وحق الوزير في حل المجلس","memo":"⭐ عند الأوضاع المالية أو الإدارية السيئة أو الخسائر الجسيمة أو استغلال الصلاحيات أو التلاعب والاختلاس: على الرئيس أو أحد الأعضاء أو المدير العام أو المدقق تبليغ المراقب تحت طائلة المسؤولية التقصيرية\n⭐ يحل الوزير المجلس بتنسيب المراقب ويشكل لجنة لمدة (٦) شهور قابلة للتمديد لمرتين على الأكثر\n⭐ تسري على ذات المسؤولية المحدودة والمساهمة الخاصة في أي حالة يوافق عليها مجلس الوزراء بتنسيب الوزير","qs":[{"q":"تعرضت شركة مساهمة عامة لخسائر جسيمة تؤثر في حقوق المساهمين، فإن الجهة الواجب تبليغها بذلك هي:","o":["المراقب","الوزير مباشرة","المحكمة","هيئة الأوراق المالية"],"a":0},{"q":"في حالة حل مجلس الإدارة بموجب المادة (١٦٨)، تشكل لجنة لإدارة الشركة لمدة:","o":["ستة شهور قابلة للتمديد لمرتين على الأكثر","ستة شهور غير قابلة للتمديد","سنة قابلة للتمديد مرة واحدة","ثلاثة شهور قابلة للتمديد لثلاث مرات"],"a":0},{"q":"يترتب على عدم قيام المدير العام أو المدقق بتبليغ المراقب عن الحالات الواردة في المادة (١٦٨):","o":["المسؤولية التقصيرية","بطلان قرارات المجلس","العزل الفوري من المنصب","غرامة يومية عن التأخير"],"a":0},{"q":"تسري أحكام حل المجلس الواردة في المادة (١٦٨) على الشركات ذات المسؤولية المحدودة والمساهمة الخاصة في أي حالة يوافق عليها:","o":["مجلس الوزراء بناء على تنسيب الوزير","الوزير بناء على تنسيب المراقب","المراقب","الهيئة العامة للشركة"],"a":0}]},{"n":"169","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تعقد الهيئة العامة للشركة المساهمة العامة اجتماعاً عادياً داخل المملكة مرة واحدة كل سنة على الأقل بدعوة من مجلس ادارة الشركة في التاريخ الذي يحدده المجلس بالاتفاق مع المراقب على أن يعقد هذا الاجتماع خلال الأشهر الأربعة التالية لانتهاء السنة المالية للشركة .","title":"اجتماع الهيئة العامة العادي","memo":"⭐ تعقد الهيئة العامة اجتماعاً عادياً داخل المملكة مرة واحدة كل سنة على الأقل\n⭐ بدعوة من مجلس الإدارة في تاريخ يحدده المجلس بالاتفاق مع المراقب\n⭐ خلال الأشهر الأربعة التالية لانتهاء السنة المالية","qs":[{"q":"يجب أن يعقد الاجتماع العادي للهيئة العامة للشركة المساهمة العامة خلال:","o":["الأشهر الأربعة التالية لانتهاء السنة المالية","الأشهر الثلاثة التالية لانتهاء السنة المالية","الأشهر الستة التالية لانتهاء السنة المالية","الشهرين التاليين لانتهاء السنة المالية"],"a":0},{"q":"يحدد تاريخ الاجتماع العادي للهيئة العامة للشركة المساهمة العامة من قبل:","o":["مجلس الإدارة بالاتفاق مع المراقب","المراقب منفرداً","الوزير بناء على تنسيب المراقب","المساهمين الذين يملكون ربع الأسهم"],"a":0}]},{"n":"170","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يعتبر الاجتماع العادي للهيئة العامة للشركة المساهمة العامة قانونياً اذا حضره مساهمون يمثلون اكثر من نصف اسهم الشركة المكتتب بها، واذا لم يتوفر هذا النصاب بمضي ساعة من الموعد المحدد للاجتماع، يوجه رئيس مجلس الادارة الدعوة الى الهيئة العامة بعقد اجتماع ثان يعقد خلال عشرة ايام من تاريخ الاجتماع الأول بإعلان ينشر في صحيفتين يوميتين محليتين وقبل موعد الاجتماع بثلاثة ايام على الأقل ويعتبر الاجتماع الثاني قانونياً مهما كان عدد الأسهم الممثلة فيه .","title":"نصاب اجتماع الهيئة العامة العادي","memo":"⭐ نصاب الاجتماع العادي: حضور مساهمين يمثلون أكثر من نصف الأسهم المكتتب بها\n⭐ إذا لم يتوفر بمضي ساعة: يدعى لاجتماع ثانٍ خلال (١٠) أيام بإعلان في صحيفتين يوميتين محليتين قبل (٣) أيام على الأقل\n⭐ الاجتماع الثاني قانوني مهما كان عدد الأسهم الممثلة","qs":[{"q":"يعتبر الاجتماع العادي الأول للهيئة العامة للشركة المساهمة العامة قانونياً إذا حضره مساهمون يمثلون:","o":["أكثر من نصف أسهم الشركة المكتتب بها","ثلثي أسهم الشركة المكتتب بها","٤٠٪ من أسهم الشركة المكتتب بها","ربع أسهم الشركة المكتتب بها"],"a":0},{"q":"لم يتوفر نصاب الاجتماع العادي الأول بمضي ساعة، فيعقد اجتماع ثانٍ خلال:","o":["عشرة أيام من تاريخ الاجتماع الأول","خمسة عشر يوماً من تاريخ الاجتماع الأول","سبعة أيام من تاريخ الاجتماع الأول","شهر من تاريخ الاجتماع الأول"],"a":0},{"q":"نصاب الاجتماع العادي الثاني (المؤجل) للهيئة العامة للشركة المساهمة العامة:","o":["يعتبر قانونياً مهما كان عدد الأسهم الممثلة فيه","٤٠٪ من الأسهم المكتتب بها","ربع الأسهم المكتتب بها","أكثر من نصف الأسهم المكتتب بها"],"a":0}]},{"n":"171","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تشمل صلاحية الهيئة العامة للشركة المساهمة العامة في اجتماعها العادي النظر في جميع الأمور المتعلقة بالشركة ومناقشتها واتخاذ القرارات المناسبة بشأنها وبخاصة ما يلي :-\n١ - تلاوة وقائع الاجتماع العادي السابق للهيئة العامة .\n٢ - تقرير مجلس الادارة عن أعمال الشركة خلال السنة والخطة المستقبلية لها.\n٣ - تقرير مدققي حسابات الشركة عن ميزانيتها وحساباتها الختامية الاخرى واحوالها واوضاعها المالية .\n٤ - الميزانية السنوية وحساب الأرباح والخسائر وتحديد الأرباح التي يقترح مجلس الادارة توزيعها بما في ذلك الاحتياطات والمخصصات التي نص عليها القانون ونظام الشركة على اقتطاعها .\n٥ - انتخاب اعضاء مجلس الادارة .\n٦ - انتخاب مدققي حسابات الشركة للسنة المالية المقبلة وتحديد اتعابهم او تفويض مجلس الادارة بتحديدها .\n٧. اقتراحات الاستدانة والرهن واعادة الكفالات وكافة التزامات الشركات التابعة او الحليفة للشركة اذا اقتضى ذلك نظام الشركة .\n٨ - أي موضوع اخر أدرجه مجلس الادارة في جدول اعمال الشركة .\n٩ - أي أمور اخرى تقترح الهيئة العامة إدراجها في جدول الأعمال ويدخل في نطاق أعمال الاجتماع العادي للهيئة العامة على أن يقترن ادراج هذا الاقتراح في جدول الأعمال بموافقة عدد من المساهمين يمثلون ما لا يقل عن ( %١٠ ) من الأسهم الممثلة في الاجتماع .\nب - يجب أن تتضمن دعوة الهيئة العامة الى الاجتماع جدول الأعمال بالأمور التي سيتم عرضها عليها لمناقشتها بنسخة من أي وثائق أو بيانات تتعلق بتلك الأمور .","title":"صلاحيلت الهيئة العامة وجدول اعمالها","memo":"⭐ صلاحيات الاجتماع العادي: تلاوة وقائع الاجتماع السابق، تقرير المجلس، تقرير المدققين، الميزانية والأرباح، انتخاب المجلس، انتخاب المدققين وتحديد أتعابهم أو تفويض المجلس، الاستدانة والرهن...\n⭐ إدراج أمور جديدة باقتراح الهيئة العامة يتطلب موافقة مساهمين يمثلون ما لا يقل عن (١٠٪) من الأسهم الممثلة في الاجتماع\n⭐ يجب أن تتضمن الدعوة جدول الأعمال مع نسخة من الوثائق المتعلقة به","qs":[{"q":"يقترن إدراج اقتراح الهيئة العامة لأمر جديد في جدول أعمال الاجتماع العادي بموافقة عدد من المساهمين يمثلون ما لا يقل عن:","o":["١٠٪ من الأسهم الممثلة في الاجتماع","٢٥٪ من الأسهم المكتتب بها","١٥٪ من الأسهم الممثلة في الاجتماع","٣٠٪ من الأسهم المكتتب بها"],"a":0},{"q":"جميع ما يلي من صلاحيات الهيئة العامة في اجتماعها العادي باستثناء:","o":["تعديل عقد الشركة ونظامها الأساسي","انتخاب أعضاء مجلس الإدارة","انتخاب مدققي الحسابات وتحديد أتعابهم","مناقشة تقرير مجلس الإدارة والخطة المستقبلية"],"a":0},{"q":"تحديد أتعاب مدققي الحسابات للسنة المالية المقبلة في الاجتماع العادي يتم من قبل:","o":["الهيئة العامة أو تفويض مجلس الإدارة بتحديدها","المراقب","هيئة الأوراق المالية","المدير العام للشركة"],"a":0}]},{"n":"172","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تعقد الهيئة العامة للشركة المساهمة العامة اجتماعاً غير عادي داخل المملكة بدعوة من مجلس الادارة أو بناء على طلب خطي يقدم الى المجلس من مساهمين يملكون ما لا يقل عن ربع اسهم الشركة المكتتب بها أو بطلب خطي من مدققي حسابات الشركة أو المراقب اذا طلب ذلك مساهمون يملكون اصالة ما لا يقل عن ( %١٥ ) من اسهم الشركة المكتتب بها .\nب - على مجلس الادارة دعوة الهيئة العامة للاجتماع غير العادي الذي طلب المساهمون أو مدقق الحسابات أو المراقب عقده بمقتضى احكام الفقرة ( أ ) من هذه المادة خلال مدة لا تتجاوز خمسة عشر يوماً من تاريخ تبليغ المجلس الطلب لعقد هذا الاجتماع فاذا تخلف عن ذلك أو رفض الاستجابة للطلب يقوم المراقب بدعوة الهيئة العامة للاجتماع على نفقة الشركة .","title":"اجتماع الهيئة العامة غير العادي","memo":"⭐ يعقد الاجتماع غير العادي داخل المملكة بدعوة من المجلس، أو بطلب خطي من مساهمين يملكون ما لا يقل عن ربع الأسهم المكتتب بها، أو بطلب من المدققين أو المراقب إذا طلب ذلك مساهمون يملكون أصالة (١٥٪)\n⭐ على المجلس الدعوة خلال مدة لا تتجاوز (١٥) يوماً من تبليغه الطلب، وإلا يدعو المراقب على نفقة الشركة","qs":[{"q":"يجوز للمساهمين أن يطلبوا مباشرة من مجلس الإدارة عقد اجتماع غير عادي للهيئة العامة إذا كانوا يملكون ما لا يقل عن:","o":["ربع أسهم الشركة المكتتب بها","١٥٪ من أسهم الشركة المكتتب بها","١٠٪ من أسهم الشركة المكتتب بها","نصف أسهم الشركة المكتتب بها"],"a":0},{"q":"يحق للمراقب طلب عقد اجتماع غير عادي للهيئة العامة إذا طلب ذلك مساهمون يملكون أصالة ما لا يقل عن:","o":["١٥٪ من أسهم الشركة المكتتب بها","٢٥٪ من أسهم الشركة المكتتب بها","٣٠٪ من أسهم الشركة المكتتب بها","١٠٪ من أسهم الشركة المكتتب بها"],"a":0},{"q":"على مجلس الإدارة دعوة الهيئة العامة للاجتماع غير العادي المطلوب عقده خلال مدة لا تتجاوز:","o":["خمسة عشر يوماً من تاريخ تبليغ المجلس الطلب","عشرة أيام من تاريخ تبليغ المجلس الطلب","ثلاثين يوماً من تاريخ تبليغ المجلس الطلب","سبعة أيام من تاريخ تبليغ المجلس الطلب"],"a":0}]},{"n":"173","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - مع مراعاة احكام الفقرة ( ب ) من هذه المادة يكون اجتماع الهيئة العامة غير العادي للشركة المساهمة العامه قانونياً بحضور مساهمين يمثلون أكثر من نصف أسهم الشركة المكتتب بها، واذا لم يتوفر هذا النصاب بمضي ساعة من الموعد المحدد للاجتماع، فيؤجل الاجتماع الى موعد اخر يعقد خلال عشرة ايام من تاريخ الاجتماع الأول ويعلن ذلك من قبل رئيس مجلس الادارة في صحيفتين محليتين يوميتين على الأقل وقبل موعد الاجتماع بثلاثة أيام على الأقل، ويعتبر الاجتماع الثاني قانونياً بحضور مساهمين يمثلون ( %٤٠ ) من أسهم الشركة المكتتب بها على الأقل، فاذا لم يتوفر هذا النصاب في الاجتماع الثاني يلغى الاجتماع مهما كانت اسباب الدعوة اليه .\nب - يجب أن لا يقل النصاب القانوني للاجتماع غير العادي للهيئة العامة للشركة في حالتي تصفيتها أو إندماجها بغيرها من الشركات عن ثلثي اسهم الشركة المكتتب بها بما في ذلك الاجتماع المؤجل للمرة الاولى واذا لم يكتمل النصاب القانوني فيه فيتم الغاء اجتماع الهيئة العامة مهما كانت اسباب الدعوة اليه .","title":"نصاب اجتماع الهيئة العامة غير العادي","memo":"⭐ نصاب الاجتماع غير العادي الأول: أكثر من نصف الأسهم المكتتب بها؛ وإلا يؤجل لاجتماع خلال (١٠) أيام يعلن في صحيفتين قبل (٣) أيام\n⭐ نصاب الاجتماع الثاني: (٤٠٪) من الأسهم المكتتب بها على الأقل، وإلا يلغى الاجتماع\n⭐ في حالتي التصفية أو الاندماج: النصاب لا يقل عن ثلثي الأسهم المكتتب بها بما فيه الاجتماع المؤجل، وإلا يلغى","qs":[{"q":"يعتبر الاجتماع غير العادي الثاني (المؤجل) للهيئة العامة قانونياً بحضور مساهمين يمثلون على الأقل:","o":["٤٠٪ من أسهم الشركة المكتتب بها","أكثر من نصف أسهم الشركة المكتتب بها","ثلث أسهم الشركة المكتتب بها","مهما كان عدد الأسهم الممثلة"],"a":0},{"q":"دعيت الهيئة العامة لاجتماع غير عادي لتصفية الشركة، فإن النصاب القانوني يجب ألا يقل عن:","o":["ثلثي أسهم الشركة المكتتب بها بما في ذلك الاجتماع المؤجل للمرة الأولى","أكثر من نصف الأسهم في الأول و٤٠٪ في المؤجل","٧٥٪ من أسهم الشركة المكتتب بها","نصف الأسهم المكتتب بها في الاجتماعين"],"a":0},{"q":"إذا لم يتوفر النصاب في الاجتماع غير العادي الثاني (المؤجل)، فإن الحكم هو:","o":["يلغى الاجتماع مهما كانت أسباب الدعوة إليه","يعقد اجتماع ثالث خلال عشرة أيام","يعتبر قانونياً مهما كان عدد الأسهم الممثلة","يحيل المراقب الموضوع إلى الوزير"],"a":0}]},{"n":"174","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجب أن تتضمن دعوة الهيئة العامة لاجتماع غير عادي المواضيع التي سيتم عرضها ومناقشتها بالاجتماع، واذا تضمن جدول الأعمال تعديل عقد تأسيس الشركة ونظامها الأساسي فيجب ارفاق التعديلات المقترحة مع الدعوة الى الاجتماع .","title":"جدول اعمال اجتماع الهيئة العامة غير العادي","memo":"⭐ يجب أن تتضمن دعوة الاجتماع غير العادي المواضيع التي ستعرض وتناقش\n⭐ إذا تضمن جدول الأعمال تعديل عقد التأسيس والنظام الأساسي يجب إرفاق التعديلات المقترحة مع الدعوة","qs":[{"q":"إذا تضمن جدول أعمال الاجتماع غير العادي تعديل عقد تأسيس الشركة ونظامها الأساسي، فيجب:","o":["إرفاق التعديلات المقترحة مع الدعوة إلى الاجتماع","الحصول على موافقة الوزير المسبقة على الدعوة","نشر التعديلات في الجريدة الرسمية قبل الاجتماع","عرض التعديلات على المحكمة قبل الاجتماع"],"a":0},{"q":"يجب أن تتضمن دعوة الهيئة العامة لاجتماع غير عادي:","o":["المواضيع التي سيتم عرضها ومناقشتها بالاجتماع","أسماء المساهمين الحاضرين مسبقاً","تقرير مدقق الحسابات السنوي فقط","موافقة المراقب على كل بند"],"a":0}]},{"n":"175","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠١٧-١٠-١٧"],"source":"أ - تختص الهيئة العامة للشركة المساهمة العامة في اجتماعها غير العادي النظر في مناقشة الأمور التالية واتخاذ القرارات المناسبة بشأنها :-\n١ - تعديل عقد الشركة ونظامها الأساسي .\n٢ - دمج الشركة او اندماجها.\n٣ - تصفية الشركة وفسخها .\n٤ - اقالة مجلس الادارة او رئيسه او احد اعضائه ..\n٥ - بيع الشركة أو تملك شركة اخرى كلياً أو بيع موجودات الشركة أو أي جزء منها وبما يؤثر على تحقيق غاياتها.\n٦ - زيادة رأس مال الشركة المصرح به او تخفيض رأس المال .\n٧ - اصدار اسناد القرض القابلة للتحويل الى اسهم .\n٨ - تمليك العاملين في الشركة لاسهم في راسمالها .\n٩ - شراء الشركة لاسهمها وبيع تلك الاسهم وفقا لاحكام هذا القانون والتشريعات النافذة ذات العلاقة .\nب - تصدر القرارات في الاجتماع غير العادي للهيئة العامة بأكثرية ( %٧٥ ) من مجموع الأسهم الممثلة في الاجتماع .\nج - تخضع قرارات الهيئة العامة في اجتماعها غير العادي لإجراءات الموافقة والتسجيل والنشر المقررة بمقتضى هذا القانون باستثناء ما ورد في البندين ( ٤ ) و ( ٧ ) من الفقرة ( أ ) من هذه المادة .","title":"صلاحيات الهيئة العامة في اجتماعها غير العادي","memo":"⭐ صلاحيات الاجتماع غير العادي: تعديل العقد والنظام، الدمج، التصفية والفسخ، إقالة المجلس أو أعضائه، بيع الشركة أو موجوداتها، زيادة رأس المال المصرح به أو تخفيضه، إسناد القرض القابلة للتحويل، تمليك العاملين أسهماً، شراء الشركة لأسهمها\n⭐ القرارات بأكثرية (٧٥٪) من الأسهم الممثلة في الاجتماع\n⭐ تخضع للموافقة والتسجيل والنشر باستثناء البندين (٤) الإقالة و(٧) إسناد القرض القابلة للتحويل","qs":[{"q":"تصدر القرارات في الاجتماع غير العادي للهيئة العامة للشركة المساهمة العامة بأكثرية:","o":["٧٥٪ من مجموع الأسهم الممثلة في الاجتماع","الأغلبية المطلقة للأسهم الممثلة في الاجتماع","ثلثي الأسهم المكتتب بها","٧٥٪ من الأسهم المكتتب بها"],"a":0},{"q":"جميع ما يلي من اختصاص الهيئة العامة في اجتماعها غير العادي باستثناء:","o":["انتخاب مدققي حسابات الشركة للسنة المالية المقبلة","زيادة رأس مال الشركة المصرح به","إصدار إسناد القرض القابلة للتحويل إلى أسهم","تمليك العاملين في الشركة لأسهم في رأسمالها"],"a":0},{"q":"من قرارات الاجتماع غير العادي التي لا تخضع لإجراءات الموافقة والتسجيل والنشر:","o":["إقالة مجلس الإدارة أو رئيسه أو أحد أعضائه","تعديل عقد الشركة ونظامها الأساسي","تخفيض رأس مال الشركة","دمج الشركة"],"a":0}]},{"n":"176","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز أن تبحث الهيئة العامة للشركة المساهمة العامة في اجتماعها غير العادي الأمور الداخلة ضمن صلاحيتها في الاجتماع العادي وتصدر قراراتها في هذه الحالة بالأغلبية المطلقة للأسهم الممثلة في الاجتماع .","title":"تمتع الهيئة العامة في اجتماعها غير العادي بصلاحيتها في الاجتماع العادي","memo":"⭐ يجوز للهيئة العامة في الاجتماع غير العادي بحث أمور الاجتماع العادي\n⭐ وتصدر قراراتها فيها بالأغلبية المطلقة للأسهم الممثلة في الاجتماع","qs":[{"q":"إذا بحثت الهيئة العامة في اجتماعها غير العادي أموراً داخلة ضمن صلاحيتها في الاجتماع العادي، فإن قراراتها تصدر بـ:","o":["الأغلبية المطلقة للأسهم الممثلة في الاجتماع","أكثرية ٧٥٪ من الأسهم الممثلة في الاجتماع","أكثرية ثلثي الأسهم المكتتب بها","الإجماع"],"a":0},{"q":"هل يجوز للهيئة العامة في اجتماعها غير العادي أن تبحث أموراً من صلاحيات الاجتماع العادي؟","o":["نعم، يجوز ذلك","لا، يجب عقد اجتماع عادي مستقل","نعم، بشرط موافقة الوزير","نعم، بشرط موافقة المراقب المسبقة"],"a":0}]},{"n":"177","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يرأ س اجتماع الهيئة العامة للشركة المساهمة العامة رئيس مجلس الادارة او نائبه في حالة غيابه او من ينتدبه المجلس في حالة غيابهما .\nب - على مجلس الادارة حضور اجتماع الهيئة العامة بعدد لا يقل عن العدد الواجب توافره لصحة انعقاد مجلس الادارة ولا يجوز التخلف عن الحضور بغير عذر مقبول .","title":"رئاسة اجتماع الهيئة العامة","memo":"⭐ يرأس اجتماع الهيئة العامة رئيس المجلس، أو نائبه في غيابه، أو من ينتدبه المجلس في غيابهما\n⭐ على المجلس الحضور بعدد لا يقل عن نصاب صحة انعقاد المجلس، ولا يجوز التخلف بغير عذر مقبول","qs":[{"q":"في حال غياب رئيس مجلس الإدارة ونائبه، يرأس اجتماع الهيئة العامة للشركة المساهمة العامة:","o":["من ينتدبه مجلس الإدارة","المراقب أو مندوبه","أكبر المساهمين سناً","المدير العام للشركة حكماً"],"a":0},{"q":"يجب أن يحضر اجتماع الهيئة العامة من أعضاء مجلس الإدارة عدد لا يقل عن:","o":["العدد الواجب توافره لصحة انعقاد مجلس الإدارة","جميع أعضاء المجلس دون استثناء","ثلثي أعضاء المجلس","رئيس المجلس ونائبه فقط"],"a":0}]},{"n":"178","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠١٧-١٠-١٧"],"source":"لكل مساهم في الشركة المساهمة العامة كان مسجلاً في سجلات الشركة قبل يوم من الموعد المحدد لاي اجتماع ستعقده الهيئة العامة الاشتراك في مناقشة الامور المعروضة عليها والتصويت على قراراتها بشأنها بعدد الاصوات يساوي عدد الاسهم التي يملكها اصالة ووكالة في الاجتماع .","title":"حق المناقشة والتصويت على القرارات","memo":"⭐ لكل مساهم مسجل في سجلات الشركة قبل يوم من موعد الاجتماع حق المناقشة والتصويت\n⭐ عدد الأصوات يساوي عدد الأسهم التي يملكها أصالة ووكالة","qs":[{"q":"يحق للمساهم الاشتراك في مناقشة أمور الهيئة العامة والتصويت عليها إذا كان مسجلاً في سجلات الشركة قبل:","o":["يوم من الموعد المحدد للاجتماع","ثلاثة أيام من الموعد المحدد للاجتماع","أسبوع من الموعد المحدد للاجتماع","خمسة عشر يوماً من الموعد المحدد للاجتماع"],"a":0},{"q":"يكون للمساهم في اجتماع الهيئة العامة عدد من الأصوات يساوي:","o":["عدد الأسهم التي يملكها أصالة ووكالة","صوتاً واحداً بغض النظر عن عدد أسهمه","عدد الأسهم التي يملكها أصالة فقط","نصف عدد الأسهم التي يمثلها وكالة"],"a":0}]},{"n":"179","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - للمساهم في الشركة المساهمة العامة ان يوكل عنه مساهماً اخر لحضور اي اجتماع تعقده الهيئة العامة للشركة بالنيابة عنه بموجب وكالة خطية على القسيمة المعدة لهذا الغرض من قبل مجلس ادارة الشركة وبموافقة المراقب على ان تودع القسيمة في مركز الشركة قبل ثلاثة ايام على الاقل من التاريخ المحدد لاجتماع الهيئة العامة ويتولى المراقب او من ينتدبه تدقيقها ، كما يجوز للمساهم توكيل اي شخص بموجب وكالة عدلية لحضور الاجتماع نيابة عنه .\nب - تكون الوكالة صالحة لحضور الوكيل لاي اجتماع اخر يؤجل اليه اجتماع الهيئة العامة .\nج - يكون حضور ولي او وصي او وكيل المساهم في الشركة او ممثل الشخص الاعتباري المساهم فيها بمثابة حضور قانوني للمساهم الاصيل لاجتماع الهيئة العامة ولو كان ذلك الولي او الوصي او ممثل الشخص الاعتباري غير مساهم في الشركة .","title":"التوكيل في حضور الاجتماع","memo":"⭐ للمساهم توكيل مساهم آخر بوكالة خطية على القسيمة المعدة من المجلس وبموافقة المراقب، تودع في مركز الشركة قبل (٣) أيام على الأقل من الاجتماع\n⭐ يجوز توكيل أي شخص (ولو غير مساهم) بموجب وكالة عدلية\n⭐ الوكالة صالحة لأي اجتماع مؤجل؛ وحضور الولي أو الوصي أو ممثل الشخص الاعتباري حضور قانوني ولو كان غير مساهم","qs":[{"q":"تودع قسيمة التوكيل لحضور اجتماع الهيئة العامة في مركز الشركة قبل:","o":["ثلاثة أيام على الأقل من التاريخ المحدد للاجتماع","يوم واحد على الأقل من التاريخ المحدد للاجتماع","سبعة أيام على الأقل من التاريخ المحدد للاجتماع","عشرة أيام على الأقل من التاريخ المحدد للاجتماع"],"a":0},{"q":"أراد مساهم توكيل شخص غير مساهم في الشركة لحضور اجتماع الهيئة العامة، فإن ذلك يتم بموجب:","o":["وكالة عدلية","وكالة خطية على القسيمة المعدة من مجلس الإدارة","كتاب موقع من المساهم فقط","موافقة شفوية من رئيس الاجتماع"],"a":0},{"q":"تكون الوكالة المعطاة لحضور اجتماع الهيئة العامة:","o":["صالحة لحضور الوكيل أي اجتماع آخر يؤجل إليه الاجتماع","صالحة للاجتماع الأول فقط","صالحة لجميع اجتماعات السنة المالية","صالحة لمدة شهر من تاريخ إيداعها"],"a":0}]},{"n":"180","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يتولى المراقب او من ينتدبه خطيا من موظفي الدائرة الاشراف على تنفيذ الاجراءات الخاصة بعقد اجتماع الهيئة العامة للشركة المساهمة العامة وفقا للتعليمات التي يصدرها الوزير لهذه الغاية .\nب - تحدد بنظام خاص الاتعاب التي يتوجب على الشركات دفعها وتودع هذه الاتعاب في صندوق خاص بالدائرة كما يحدد النظام كيفية الصرف من هذا الصندوق بما فيها مقدار المكافأة التي تدفع للمراقب وموظفي الدائرة الذين يشتركون في اجتماعات الهيئات العامة.","title":"الاشراف على تنفيذ الاجراءات الخاصة بعقد الاجتماع","memo":"⭐ يشرف المراقب أو من ينتدبه خطياً من موظفي الدائرة على إجراءات عقد اجتماع الهيئة العامة وفق تعليمات يصدرها الوزير\n⭐ الأتعاب التي تدفعها الشركات تحدد بنظام خاص وتودع في صندوق خاص بالدائرة، ويحدد النظام مكافأة المراقب والموظفين","qs":[{"q":"يتولى الإشراف على تنفيذ الإجراءات الخاصة بعقد اجتماع الهيئة العامة للشركة المساهمة العامة:","o":["المراقب أو من ينتدبه خطياً من موظفي الدائرة","رئيس مجلس الإدارة","مدقق حسابات الشركة","هيئة الأوراق المالية"],"a":0},{"q":"تحدد الأتعاب التي يتوجب على الشركات دفعها مقابل حضور اجتماعات الهيئات العامة بموجب:","o":["نظام خاص","تعليمات يصدرها المراقب","قرار من مجلس إدارة الشركة","النظام الأساسي للشركة"],"a":0}]},{"n":"181","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يعين رئيس اجتماع الهيئة العامة للشركة المساهمة العامة كاتباً من بين المساهمين او من موظفي الشركة لتدوين محضر بوقائع اجتماع الهيئة العامة والقرارات التي اتخذت فيه كما يعين عدداً من المراقبين لا يقل عن اثنين لجمع الاصوات وفرزها ويتولى المراقب او من يمثله اعلان النتائج التي يسفر عنها التصويت .\nب - يدرج في محضر اجتماع الهيئة العامة النصاب القانوني للاجتماع والأمور التي عرضت فيه والقرارات التي اتخذت بشأنها وعدد الاصوات المؤيدة لكل قرار، والمعارضة له والاصوات التي لم تظهر ومداولات الهيئة العامة التي يطلب المساهمون اثباتها في المحضر ، ويوقع هذا المحضر من رئيس الاجتماع والمراقب والكاتب،ويجب توثيق هذا المحضر في سجل خاص يعد في الشركة لهذه الغاية ويرسل مجلس الادارة نسخة موقعة منه للمراقب خلال عشرة ايام من تاريخ عقد اجتماع الهيئة العامةتحت طائلـة فـرض غرامـة عـن كـل يـوم تـأخير تحدد بموجـب نظام الشركات .\nج - للمراقب اعطاء صورة مصدقة عن محضر اجتماع الهيئة العامة لاي مساهم مقابل الرسوم المقررة بموجب احكام هذا القانون .","title":"محضر الاجتماع","memo":"⭐ يعين رئيس الاجتماع كاتباً (من المساهمين أو الموظفين) وعدداً من المراقبين لا يقل عن اثنين لجمع الأصوات وفرزها؛ ويعلن المراقب أو من يمثله النتائج\n⭐ يوقع المحضر رئيس الاجتماع والمراقب والكاتب، ويوثق في سجل خاص\n⭐ يرسل المجلس نسخة موقعة للمراقب خلال (١٠) أيام تحت طائلة غرامة عن كل يوم تأخير تحدد بنظام الشركات","qs":[{"q":"يرسل مجلس الإدارة نسخة موقعة من محضر اجتماع الهيئة العامة للمراقب خلال:","o":["عشرة أيام من تاريخ عقد الاجتماع","خمسة عشر يوماً من تاريخ عقد الاجتماع","ثلاثين يوماً من تاريخ عقد الاجتماع","سبعة أيام من تاريخ عقد الاجتماع"],"a":0},{"q":"يعين رئيس اجتماع الهيئة العامة لجمع الأصوات وفرزها عدداً من المراقبين لا يقل عن:","o":["اثنين","ثلاثة","واحد","خمسة"],"a":0},{"q":"يوقع محضر اجتماع الهيئة العامة للشركة المساهمة العامة من قبل:","o":["رئيس الاجتماع والمراقب والكاتب","رئيس الاجتماع ومدقق الحسابات","جميع أعضاء مجلس الإدارة الحاضرين","رئيس الاجتماع والمدير العام"],"a":0}]},{"n":"182","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"على مجلس الادارة توجيه الدعوة لاجتماع الهيئة العامة لكل من المراقب وهيئة الاوراق المالية ومدققي حسابات الشركة قبل خمسة عشر يوماً على الأقل من موعد انعقاد اجتماعها وعلى المدقق الحضور او ارسال مندوب عنه تحت طائلة المسؤولية، ويرفق بالدعوة جدول اعمال الاجتماع وجميع البيانات والمرفقات التي نص على ارسالها للمساهم مع الدعوة ويعتبر اي اجتماع تعقده الهيئة العامة باطلاً اذا لم يحضره المراقب او من ينتدبه خطيا من موظفي الدائرة .","title":"دعوة المراقب ومدققي الحسابات لحضور الاجتماع","memo":"⭐ يدعو المجلس المراقب وهيئة الأوراق المالية ومدققي الحسابات قبل (١٥) يوماً على الأقل من الاجتماع\n⭐ على المدقق الحضور أو إرسال مندوب تحت طائلة المسؤولية\n⭐ يعتبر اجتماع الهيئة العامة باطلاً إذا لم يحضره المراقب أو من ينتدبه خطياً","qs":[{"q":"على مجلس الإدارة توجيه الدعوة لاجتماع الهيئة العامة إلى المراقب وهيئة الأوراق المالية ومدققي الحسابات قبل:","o":["خمسة عشر يوماً على الأقل من موعد الاجتماع","عشرة أيام على الأقل من موعد الاجتماع","ثلاثة أيام على الأقل من موعد الاجتماع","شهر على الأقل من موعد الاجتماع"],"a":0},{"q":"عقدت الهيئة العامة اجتماعها دون حضور المراقب أو من ينتدبه خطياً من موظفي الدائرة. ما حكم الاجتماع؟","o":["يعتبر الاجتماع باطلاً","يعتبر صحيحاً إذا توفر النصاب","يعتبر صحيحاً إذا حضر مدقق الحسابات","موقوف على مصادقة الوزير"],"a":0}]},{"n":"183","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تعتبر القرارات التي تصدرها الهيئة العامة للشركة للمساهمة العامة في اي اجتماع تعقده بنصاب قانوني ملزمة لمجلس الادارة ولجميع المساهمين الذين حضروا الاجتماع والذين لم يحضرون، شريطة ان تكون تلك القرارات قد اتخذت وفقاً لاحكام هذا القانون والانظمة الصادرة بمقتضاه .\nب - تختص المحكمة بالنظر والفصل في أي دعاوى قد تقدم للطعن في قانونية أي اجتماع عقدته الهيئة العامة او الطعن في القرارات التي اتخذتها فيه على ان لا يوقف الطعن تنفيذ أي قرار من قرارات الهيئة العامة الا اذا قررت المحكمة خلاف ذلك ولا تسمع الدعوى بذلك بعد مضي ثلاثة اشهر على عقد الاجتماع .","title":"الزامية القرارات الصادرة عن الهيئة العامة والطعن فيها","memo":"⭐ قرارات الهيئة العامة المتخذة بنصاب قانوني ووفقاً للقانون ملزمة للمجلس ولجميع المساهمين الحاضرين والغائبين\n⭐ تختص المحكمة بالطعن في قانونية الاجتماع أو قراراته، ولا يوقف الطعن التنفيذ إلا إذا قررت المحكمة خلاف ذلك\n⭐ لا تسمع الدعوى بعد مضي (٣) أشهر على عقد الاجتماع","qs":[{"q":"لا تسمع دعوى الطعن في قرارات الهيئة العامة للشركة المساهمة العامة بعد مضي:","o":["ثلاثة أشهر على عقد الاجتماع","ستة أشهر على عقد الاجتماع","سنة على عقد الاجتماع","شهر على عقد الاجتماع"],"a":0},{"q":"طعن مساهم أمام المحكمة في قرار للهيئة العامة، فإن أثر الطعن على تنفيذ القرار:","o":["لا يوقف التنفيذ إلا إذا قررت المحكمة خلاف ذلك","يوقف التنفيذ حكماً لحين صدور الحكم","يوقف التنفيذ إذا وافق المراقب","يوقف التنفيذ إذا كان الطاعن يملك ١٠٪ من الأسهم"],"a":0},{"q":"تكون قرارات الهيئة العامة المتخذة بنصاب قانوني ووفقاً لأحكام القانون ملزمة لـ:","o":["مجلس الإدارة وجميع المساهمين الذين حضروا الاجتماع والذين لم يحضروا","المساهمين الذين حضروا الاجتماع فقط","المساهمين الذين صوتوا لصالح القرار فقط","مجلس الإدارة فقط"],"a":0}]},{"n":"184","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . يترتب على الشركة المساهمة العامة تنظيم حساباتها وحفظ سجلاتها ودفاترها وفق معايير المحاسبة والتدقيق الدولية المعتمدة .\nب. يصدر الوزير بالتنسيق مع الجهات المهنية المختصة التعليمات اللازمة لضمان تطبيق معايير المحاسبة الدولية واصولها المتعارف عليها بما يحقق اهداف هذا القانون ويضمن حقوق الشركة ومساهميها .\nج. ١. تطبق معايير وقواعد المحاسبة والتدقيق الدولية المتعارف عليها والمعتمدة من الجهات المهنية المختصة .\n٢. لمقاصد هذا القانون ينصرف معنى عبارة ( معايير وقواعد المحاسبة والتدقيق الدولية المتعارف عليها ) على أي عبارة تشير صراحة او دلالة على اعتماد اصول ومعايير وقواعد المحاسبة والتدقيق او ما يرتبط بها .","title":"اتباع الاصول المحاسبية","memo":"⭐ تنظم الشركة المساهمة العامة حساباتها وتحفظ سجلاتها ودفاترها وفق معايير المحاسبة والتدقيق الدولية المعتمدة\n⭐ يصدر الوزير بالتنسيق مع الجهات المهنية المختصة التعليمات اللازمة لضمان تطبيق معايير المحاسبة الدولية","qs":[{"q":"يترتب على الشركة المساهمة العامة تنظيم حساباتها وحفظ سجلاتها ودفاترها وفق:","o":["معايير المحاسبة والتدقيق الدولية المعتمدة","تعليمات البنك المركزي","المعايير التي تقرها الهيئة العامة للشركة","نظام محاسبي يضعه مجلس الإدارة"],"a":0},{"q":"يصدر التعليمات اللازمة لضمان تطبيق معايير المحاسبة الدولية في الشركات المساهمة العامة:","o":["الوزير بالتنسيق مع الجهات المهنية المختصة","المراقب منفرداً","مجلس الوزراء","مدقق حسابات الشركة"],"a":0}]},{"n":"185","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تبدا السنة المالية للشركة المساهمة العامة في اليوم الاول من شهر كانون الثاني من السنة وتنتهي في الحادي والثلاثين من شهر كانون الاول من السنة نفسها مالم ينص نظام الشركة على غير ذلك .\nب - اذا بدأت الشركة عملها خلال النصف الاول من السنة فتنتهي سنتها المالية في الحادي والثلاثين من شهر كانون الاول من السنة نفسها اما اذا بدأت العمل خلال النصف الثاني من السنة فتنتهي سنتها المالية الاولى في الحادي والثلاثين من شهر كانون الاول من السنة التالية .","title":"السنة المالية للشركة المساهمة العامة","memo":"⭐ تبدأ السنة المالية في ١ كانون الثاني وتنتهي في ٣١ كانون الأول ما لم ينص النظام على غير ذلك\n⭐ إذا بدأت الشركة عملها في النصف الأول: تنتهي سنتها الأولى في ٣١ كانون الأول من السنة نفسها\n⭐ إذا بدأت في النصف الثاني: تنتهي سنتها الأولى في ٣١ كانون الأول من السنة التالية","qs":[{"q":"بدأت شركة مساهمة عامة عملها في شهر أيلول (النصف الثاني من السنة)، فتنتهي سنتها المالية الأولى في:","o":["٣١ كانون الأول من السنة التالية","٣١ كانون الأول من السنة نفسها","٣٠ حزيران من السنة التالية","نهاية اثني عشر شهراً من بدء العمل"],"a":0},{"q":"بدأت شركة مساهمة عامة عملها في شهر آذار، فتنتهي سنتها المالية الأولى في:","o":["٣١ كانون الأول من السنة نفسها","٣١ كانون الأول من السنة التالية","٣١ آذار من السنة التالية","٣٠ حزيران من السنة نفسها"],"a":0},{"q":"تبدأ السنة المالية للشركة المساهمة العامة:","o":["في الأول من كانون الثاني ما لم ينص نظام الشركة على غير ذلك","في الأول من كانون الثاني دون أي استثناء","من تاريخ تسجيل الشركة دائماً","في الأول من تموز ما لم يقرر المجلس غير ذلك"],"a":0}]},{"n":"186","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - لا يجوز للشركة المساهمة العامة توزيع اي عوائد على المساهمين فيها الا من ارباحها بعد تسوية الخسائر المدورة من سنوات سابقة وعليها ان تقتطع ما نسبته ( %١٠ ) من ارباحها السنوية الصافية لحساب الاحتياطي الاجباري ولا يجوز توزيع اي ارباح على المساهمين الا بعد اجراء هذا الاقتطاع ولا يجوز وقفه قبل ان يبلغ حساب الاحتياطي الاجباري المتجمع ما يعادل ربع رأسمال الشركة المصرح به الا انه يجوز بموافقة الهيئة العامة للشركة الاستمرار في اقتطاع هذه النسبة السنوية الى ان يبلغ هذا الاحتياطي ما يعادل مقدار رأس مال الشركة المصرح به .\nب - لا يجوز توزيع الاحتياطي الاجباري للشركة المساهمة العامة على المساهمين فيها ولكن يجوز استعماله لتأمين الحد الادنى للربح المقرر في اتفاقيات الشركات ذات الامتياز في اي سنة لا تسمح فيها ارباح هذه الشركات بتأمين ذلك الحد، وعلى مجلس ادارة الشركة ان يعيد الى هذا الاحتياطي ما اخذ منه عندما تسمح بذلك ارباح الشركة في السنين التالية كما يجوز للمجلس اذا استدعت الضرورة استعمال رصيد الاحتياطي الاجباري المتكون لدى الشركة ، بصورة جزئية وحسب مقتضى الحال ، لتغطية مدفوعاتها لمقاصد تسوية الارباح الزائدة المتحققة للحكومة زيادة عن نسبة الربح المحدد بموجب اتفاقية الامتياز المعقودة معها على ان يعاد بناء هذا الاحتياطي وفقا لاحكام الفقرة (أ) من هذه المادة .\nج- للهيئة العامة وبعد استنفاد الاحتياطيات الأخرى ان تقرر في اجتماع غير عادي إطفاء خسائرها من المبالغ المتجمعة في حساب الاحتياطي الإجباري على ان يعاد بناؤه وفقاً لأحكام الفقرة (أ) من هذه المادة.\nد - علـى الـرغم ممـا ورد في النظام الأساسي للشركة، للهيئـة العامـة تفويض مجلس الإدارة بتوزيع الأرباح كل ثلاثة أشهر على أن يكون التفويض محدداً بسنوات معينة شريطة وجود تقرير من المحاسب القانوني للشـركة يؤكـد تـوافر الشـروط والقيـود الـواردة في الفقرتين (أ) و(ب) من هذه المادة.","title":"توزيح الارباح و الاحتياطي الاجباري","memo":"⭐ لا توزع عوائد إلا من الأرباح بعد تسوية الخسائر المدورة\n⭐ يقتطع (١٠٪) من الأرباح السنوية الصافية للاحتياطي الإجباري، ولا يوقف قبل أن يبلغ ربع رأس المال المصرح به، ويجوز بموافقة الهيئة العامة الاستمرار حتى يعادل رأس المال المصرح به\n⭐ الاحتياطي الإجباري لا يوزع؛ وللهيئة العامة في اجتماع غير عادي إطفاء الخسائر منه بعد استنفاد الاحتياطيات الأخرى\n⭐ للهيئة العامة تفويض المجلس بتوزيع الأرباح كل (٣) أشهر لسنوات معينة بشرط تقرير المحاسب القانوني","qs":[{"q":"تقتطع الشركة المساهمة العامة لحساب الاحتياطي الإجباري ما نسبته:","o":["١٠٪ من أرباحها السنوية الصافية","٢٠٪ من أرباحها السنوية الصافية","١٠٪ من أرباحها الإجمالية","٢٥٪ من أرباحها السنوية الصافية"],"a":0},{"q":"لا يجوز وقف الاقتطاع للاحتياطي الإجباري قبل أن يبلغ رصيده المتجمع ما يعادل:","o":["ربع رأس مال الشركة المصرح به","نصف رأس مال الشركة المصرح به","ربع رأس مال الشركة المكتتب به","كامل رأس مال الشركة المصرح به"],"a":0},{"q":"يجوز إطفاء خسائر الشركة المساهمة العامة من المبالغ المتجمعة في حساب الاحتياطي الإجباري بقرار من:","o":["الهيئة العامة في اجتماع غير عادي بعد استنفاد الاحتياطيات الأخرى","مجلس الإدارة دون الحاجة لموافقة الهيئة العامة","الهيئة العامة في اجتماع عادي دون أي شرط","المراقب بناء على طلب المجلس"],"a":0},{"q":"يجوز للهيئة العامة تفويض مجلس الإدارة بتوزيع الأرباح:","o":["كل ثلاثة أشهر لسنوات معينة بشرط تقرير من المحاسب القانوني","كل شهر دون قيد","كل ستة أشهر بموافقة المراقب","مرة واحدة سنوياً فقط"],"a":0}]},{"n":"187","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - للهيئة العامة للشركة المساهمة العامة ، بناء على اقتراح مجلس ادارتها ، ان تقرر سنوياً اقتطاع ما لا يزيد على ( %٢٠ ) من ارباحها الصافية عن تلك السنة لحساب الاحتياطي الاختياري .\nب - يستعمل الاحتياطي الاختياري للشركة المساهمة العامة في الاغراض التي يقررها مجلس ادارتها ويحق للهيئة العامة توزيعه ، كله او اي جزء منه، كأرباح على المساهمين اذا لم يستعمل في تلك الاغراض .\nج - كما ان للهيئة العامة للشركة المساهمة العامة بناء على اقتراح مجلس ادارتها ان تقرر سنوياً اقتطاع ما لا يزيد على ( %٢٠ ) من ارباحها الصافية عن تلك السنة احتياطاً خاص لاستعماله لاغراض الطوارئ او التوسع او لتقوية مركز الشركة المالي ومواجهة المخاطر التي قد تتعرض لها .","title":"الاحتياطي الاختياري واستعمالاته والاحتياطي الخاص","memo":"⭐ للهيئة العامة بناء على اقتراح المجلس اقتطاع ما لا يزيد على (٢٠٪) من الأرباح الصافية للاحتياطي الاختياري\n⭐ يستعمل الاختياري في الأغراض التي يقررها المجلس، ويحق للهيئة العامة توزيعه كأرباح إذا لم يستعمل\n⭐ ويجوز اقتطاع ما لا يزيد على (٢٠٪) احتياطياً خاصاً للطوارئ أو التوسع أو تقوية المركز المالي","qs":[{"q":"يجوز للهيئة العامة اقتطاع نسبة من الأرباح الصافية سنوياً لحساب الاحتياطي الاختياري لا تزيد على:","o":["٢٠٪","١٠٪","٢٥٪","١٥٪"],"a":0},{"q":"أي مما يلي صحيح بشأن الاحتياطي الاختياري للشركة المساهمة العامة؟","o":["يحق للهيئة العامة توزيعه كله أو جزء منه كأرباح إذا لم يستعمل في الأغراض المقررة","لا يجوز توزيعه على المساهمين مطلقاً","يقرر المراقب أغراض استعماله","يجب أن يستمر الاقتطاع له حتى يبلغ ربع رأس المال"],"a":0},{"q":"يستعمل الاحتياطي الخاص المنصوص عليه في المادة (١٨٧) لأغراض:","o":["الطوارئ أو التوسع أو تقوية مركز الشركة المالي ومواجهة المخاطر","توزيع أرباح على المساهمين سنوياً","دفع مكافآت أعضاء مجلس الإدارة","تأمين الحد الأدنى للربح في شركات الامتياز"],"a":0}]},{"n":"188","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"ملغاه","title":"مادة ملغاة","memo":"⭐ المادة ملغاة","qs":[]},{"n":"189","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تحقيقاً للغايات المتوخاة من المواد ( ١٨٦ و ١٨٧ و ١٨٨ ) من هذا القانون يقصد بالأرباح الصافية للشركة المساهمة العامة الفرق بين مجموع الايرادات المتحققة في اي سنة مالية من جانب ومجموع المصروفات والاستهلاك في تلك السنة من جانب اخر قبل تنزيل المخصص لضريبتي الدخل والخدمات الاجتماعية .","title":"احتساب الربح الصافي","memo":"⭐ الأرباح الصافية (لغايات المواد ١٨٦ و١٨٧ و١٨٨) = مجموع الإيرادات المتحققة في السنة − مجموع المصروفات والاستهلاك\n⭐ قبل تنزيل المخصص لضريبتي الدخل والخدمات الاجتماعية","qs":[{"q":"يقصد بالأرباح الصافية للشركة المساهمة العامة لغايات احتساب الاحتياطيات:","o":["الفرق بين مجموع الإيرادات المتحققة ومجموع المصروفات والاستهلاك قبل تنزيل مخصص ضريبتي الدخل والخدمات الاجتماعية","الفرق بين الإيرادات والمصروفات بعد تنزيل ضريبة الدخل","مجموع الإيرادات المتحققة قبل تنزيل الاستهلاك","الأرباح القابلة للتوزيع بعد تنزيل جميع الاحتياطيات"],"a":0},{"q":"حققت شركة مساهمة عامة إيرادات ١٠٠٠٠٠٠ دينار، ومصروفات واستهلاك ٦٠٠٠٠٠ دينار، ومخصص ضريبة دخل ٨٠٠٠٠ دينار. فإن الربح الصافي لغايات المادة (١٨٩) يساوي:","o":["٤٠٠٠٠٠ دينار","٣٢٠٠٠٠ دينار","١٠٠٠٠٠٠ دينار","٤٨٠٠٠٠ دينار"],"a":0}]},{"n":"190","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"للشركة ان تنشئ صندوق ادخار لمستخدميها يتمتع بالشخصية الاعتبارية المستقلة وذلك بموجب نظام خاص يصدره مجلس ادارة الشركة ويتم اعتماده من الجهات الرسمية المختصة بموجب احكام التشريعات السارية المفعول ، وعلى ان يتضمن هذا النظام ما يكفل استقلال هذا الصندوق من الناحية الادارية والمالية عن ادارة الشركة .","title":"صندوق ادخار المستخدمين","memo":"⭐ للشركة إنشاء صندوق ادخار لمستخدميها يتمتع بالشخصية الاعتبارية المستقلة\n⭐ بنظام خاص يصدره مجلس الإدارة ويعتمد من الجهات الرسمية المختصة، ويكفل استقلاله إدارياً ومالياً عن إدارة الشركة","qs":[{"q":"يصدر النظام الخاص بصندوق ادخار مستخدمي الشركة من قبل:","o":["مجلس إدارة الشركة ويعتمد من الجهات الرسمية المختصة","الهيئة العامة للشركة","الوزير بناء على تنسيب المراقب","المستخدمين المشتركين في الصندوق"],"a":0},{"q":"أي مما يلي صحيح بشأن صندوق ادخار المستخدمين في الشركة؟","o":["يتمتع بالشخصية الاعتبارية المستقلة ويكون مستقلاً إدارياً ومالياً عن إدارة الشركة","يكون جزءاً من موجودات الشركة","يخضع لإدارة المدير العام مباشرة","إنشاؤه إلزامي على كل شركة مساهمة عامة"],"a":0}]},{"n":"191","chapter":"الباب السادس - الشركات المساهمة العامة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - ينشأ حق المساهم في الارباح السنوية للشركة المساهمة العامة بصدور قرار الهيئة العامة بتوزيعها .\nب - يكون الحق في استيفاء الربح تجاه الشركة لمالك السهم بتاريخ اجتماع الهيئة العامة الذي تقرر فيه توزيع الارباح وعلى مجلس ادارة الشركة ان يعلن عن ذلك في صحيفتين يوميتين محليتين على الاقل وبوسائل الاعلام الاخرى خلال اسبوع على الاكثر من تاريخ قرار الهيئة ، وتقوم الشركة بتبليغ المراقب والسوق المالي بهذا القرار .\nج - تلتزم الشركة بدفع الارباح المقرر توزيعها على المساهمين خلال خمسة واربعين يوما من تاريخ اجتماع الهيئة العامة وفي حال الاخلال بذلك تلتزم الشركة بدفع فائدة للمساهم بمعدل سعر الفائدة السائد على الودائع لأجل خلال فترة التأخير ، على ان لا تتجاوز مدة تأخير دفع الارباح ستة اشهر من تاريخ استحقاقها .\nد - للوزير بالتعاون مع الجهات المختصة اصدار النماذج اللازمة لاعداد وعرض البيانات الحسابية واصدار السياسات المحاسبية الخاصة بالشركات المساهمة العامة باستثناء البنوك والشركات المالية وشركات التامين التي يتم اعداد بياناتها المالية بالتنسيق مع البنك المركزي وهيئة الاوراق المالية وهيئة تنظيم قطاع التامين حسب مقتضى الحال .","title":"الارباح وتوزيعها والنماذج اللازمة لاعداد وعرض البيانات الحسابية","memo":"⭐ ينشأ حق المساهم في الأرباح بصدور قرار الهيئة العامة بتوزيعها، ويكون لمالك السهم بتاريخ اجتماع الهيئة الذي قرر التوزيع\n⭐ يعلن المجلس في صحيفتين يوميتين خلال أسبوع على الأكثر، ويبلغ المراقب والسوق المالي\n⭐ تدفع الأرباح خلال (٤٥) يوماً، وعند التأخير فائدة بسعر الودائع لأجل، ولا يتجاوز التأخير (٦) أشهر\n⭐ يصدر الوزير النماذج والسياسات المحاسبية (باستثناء البنوك والشركات المالية وشركات التأمين)","qs":[{"q":"تلتزم الشركة المساهمة العامة بدفع الأرباح المقرر توزيعها على المساهمين خلال:","o":["خمسة وأربعين يوماً من تاريخ اجتماع الهيئة العامة","ثلاثين يوماً من تاريخ اجتماع الهيئة العامة","ستين يوماً من تاريخ اجتماع الهيئة العامة","ستة أشهر من تاريخ اجتماع الهيئة العامة"],"a":0},{"q":"يكون الحق في استيفاء الربح تجاه الشركة لـ:","o":["مالك السهم بتاريخ اجتماع الهيئة العامة الذي تقرر فيه توزيع الأرباح","مالك السهم في نهاية السنة المالية","مالك السهم بتاريخ دفع الأرباح فعلياً","المساهم المؤسس للشركة"],"a":0},{"q":"تأخرت الشركة عن دفع الأرباح المقررة في الموعد القانوني، فإنها تلتزم بـ:","o":["دفع فائدة للمساهم بمعدل سعر الفائدة السائد على الودائع لأجل خلال فترة التأخير","دفع غرامة مقطوعة تحددها الهيئة العامة","دفع ضعف الأرباح المقررة","دفع فائدة بنسبة ١٠٪ سنوياً"],"a":0},{"q":"يعلن مجلس الإدارة قرار توزيع الأرباح في صحيفتين يوميتين محليتين على الأقل خلال:","o":["أسبوع على الأكثر من تاريخ قرار الهيئة","عشرة أيام من تاريخ قرار الهيئة","خمسة عشر يوماً من تاريخ قرار الهيئة","ثلاثة أيام من تاريخ قرار الهيئة"],"a":0}]},{"n":"192","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - تنتخب الهيئة العامة لكل من الشركة المساهمة العامة والشركة المحدودة المسؤولية والشركة المساهمة الخاصة مدققاً او اكثر من بين مدققي الحسابات المرخص لهم بمزاولة المهنة لمدة سنة واحدة قابلة للتجديد وتقرر بدل اتعابهم ،او تفويض مجلس الادارة بتحديد الاتعاب ويتوجب على الشركة تبليغ المدقق المنتخب خطيا بذلك خلال اربعة عشر يوما من تاريخ انتخابه .\nب - اذا تخلفت الهيئة العامة للشركة عن انتخاب مدقق الحسابات او اعتذر المدقق الذي انتخبته عن العمل او امتنع عن القيام به لاي سبب من الاسباب او توفي فعلى مجلس الادارة ان ينسب للمراقب ثلاثة من مدققي الحسابات على الاقل وذلك خلال اربعة عشر يوماً من تاريخ شغور هذا المركز ليختار احدهم .","title":"انتخاب مدققوا الحسابات للشركات","memo":"⭐ تنتخب الهيئة العامة (للمساهمة العامة والمحدودة المسؤولية والمساهمة الخاصة) مدققاً أو أكثر لمدة سنة واحدة قابلة للتجديد وتقرر أتعابه أو تفوض المجلس\n⭐ تبلغ الشركة المدقق المنتخب خطياً خلال (١٤) يوماً من انتخابه\n⭐ عند تخلف الهيئة عن الانتخاب أو اعتذار المدقق أو وفاته: ينسب المجلس للمراقب ثلاثة مدققين على الأقل خلال (١٤) يوماً من الشغور ليختار أحدهم","qs":[{"q":"تنتخب الهيئة العامة مدقق حسابات الشركة لمدة:","o":["سنة واحدة قابلة للتجديد","ثلاث سنوات قابلة للتجديد","سنتين غير قابلة للتجديد","خمس سنوات كحد أقصى"],"a":0},{"q":"توفي مدقق حسابات شركة مساهمة عامة أثناء السنة، فعلى مجلس الإدارة:","o":["أن ينسب للمراقب ثلاثة مدققين على الأقل خلال أربعة عشر يوماً من الشغور ليختار أحدهم","أن يعين مدققاً بديلاً مباشرة دون الرجوع لأحد","أن يدعو الهيئة العامة لاجتماع غير عادي خلال شهر","أن ينسب للوزير مدققين اثنين خلال عشرة أيام"],"a":0},{"q":"يتوجب على الشركة تبليغ مدقق الحسابات المنتخب خطياً خلال:","o":["أربعة عشر يوماً من تاريخ انتخابه","سبعة أيام من تاريخ انتخابه","ثلاثين يوماً من تاريخ انتخابه","عشرة أيام من تاريخ انتخابه"],"a":0}]},{"n":"193","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يتولى مدققو الحسابات مجتمعين او منفردين القيام بما يلي :-\nأ - مراقبة اعمال الشركة .\nب - تدقيق حساباتها وفقاً لقواعد التدقيق المعتمدة ومتطلبات المهنة واصولها العلمية والفنية .\nج - فحص الانظمة المالية والادارية للشركة وانظمة المراقبة المالية الداخلية لها والتأكد من ملاءمتها لحسن سير اعمال الشركة والمحافظة على اموالها .\nد - التحقق من موجودات الشركة وملكيتها لها والتأكد من قانونية الالتزامات المترتبة على الشركة وصحتها .\nهـ. الاطلاع على قرارات مجلس الادارة والهيئة العامة والتعليمات الصادرة عن الشركة واي بيانات يتطلب عملهم ضرورة الحصول عليها والتحقق منها .\nو. أي واجبات اخرى يترتب على مدقق الحسابات القيام بها بموجب هذا القانون وقانون مهنة تدقيق الحسابات والانظمة الاخرى ذات العلاقة .\nز - يقدم مدققو الحسابات تقريراً خطياً موجهاً للهيئة العامة وعليهم او من ينتدبونه ان يتلو التقرير امام الهيئة العامة .","title":"مهام مدققوا الحسابات","memo":"⭐ مهام المدقق: مراقبة أعمال الشركة، تدقيق حساباتها وفق قواعد التدقيق المعتمدة، فحص الأنظمة المالية والإدارية والرقابة الداخلية، التحقق من الموجودات وملكيتها وقانونية الالتزامات، الاطلاع على قرارات المجلس والهيئة العامة\n⭐ يقدم تقريراً خطياً موجهاً للهيئة العامة ويتلوه أمامها هو أو من ينتدبه","qs":[{"q":"يوجه مدقق الحسابات تقريره الخطي إلى:","o":["الهيئة العامة","مجلس الإدارة","المراقب","المدير العام"],"a":0},{"q":"جميع ما يلي من مهام مدقق الحسابات وفقاً للمادة (١٩٣) باستثناء:","o":["إعداد الخطة المستقبلية للشركة","فحص أنظمة المراقبة المالية الداخلية للشركة","التحقق من موجودات الشركة وملكيتها لها","الاطلاع على قرارات مجلس الإدارة والهيئة العامة"],"a":0},{"q":"يقوم مدققو حسابات الشركة بمهامهم:","o":["مجتمعين أو منفردين","مجتمعين فقط","منفردين فقط بموافقة المجلس","تحت إشراف المدير العام"],"a":0}]},{"n":"194","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"اذا تعذر على مدقق حسابات الشركة القيام بالمهام والواجبات الموكلة اليه بموجب احكام هذا القانون لاي سبب من الاسباب فعليه قبل الاعتذار عن القيام بتدقيق الحسابات ان يقدم تقريراً خطياً للمراقب ونسخة منه لمجلس الادارة يتضمن الاسباب التي تعرقل اعماله او تحول دون قيامه بها وعلى المراقب معالجة هذه الاسباب مع مجلس الادارة واذا تعذر عليه ذلك يعرض المراقب الامر على الهيئة العامة في اول اجتماع تعقده .","title":"عرقلة اعمال مدقق الحسابات","memo":"⭐ إذا تعذر على المدقق القيام بمهامه: عليه قبل الاعتذار تقديم تقرير خطي للمراقب ونسخة لمجلس الإدارة بالأسباب\n⭐ يعالج المراقب الأسباب مع المجلس، فإن تعذر يعرض الأمر على الهيئة العامة في أول اجتماع","qs":[{"q":"إذا تعذر على مدقق الحسابات القيام بمهامه، فعليه قبل الاعتذار أن يقدم تقريراً خطياً بالأسباب إلى:","o":["المراقب ونسخة منه لمجلس الإدارة","الهيئة العامة مباشرة","مجلس الإدارة فقط","الوزير ونسخة منه للمراقب"],"a":0},{"q":"إذا تعذر على المراقب معالجة الأسباب التي تعرقل عمل المدقق مع مجلس الإدارة، فإنه:","o":["يعرض الأمر على الهيئة العامة في أول اجتماع تعقده","يحيل الأمر إلى المحكمة","يعين مدققاً بديلاً فوراً","يحل مجلس إدارة الشركة"],"a":0}]},{"n":"195","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - مع مراعاة احكام قانون مهنة تدقيق الحسابات المعمول به واي قانون او نظام اخر له علاقة بهذه المهنة يجب ان يتضمن تقرير مدقق الحسابات مايلي :\n١ - انه قد حصل على المعلومات والبيانات والايضاحات التي رآها ضرورية لاداء عمله .\n٢- ان الشركة تمسك حسابات وسجلات ومستندات منظمة وان بياناتها المالية معدة وفقا لمعايير المحاسبة الدولية المعتمدة ، تمكن من اظهار المركز المالي للشركة ونتائج اعمالها وتدفقاتها النقدية بصورة عادلة ، وان الميزانية وبيان الارباح والخسائر متفقة مع القيود والدفاتر .\n٣ - ان إجراءات التدقيق التي قام بها لحسابات الشركة تعتبر كافية برأيه لتشكل اساساً معقولاً لإبداء رأيه حول المركز المالي ونتائج الأعمال والتدفقات النقدية للشركة وفقاً لقواعد التدقيق المتعارف عليها عالمياً .\n٤ - ان البيانات المالية الواردة في تقرير مجلس الادارة الموجه للهيئة العامة تتفق مع قيود الشركة وسجلاتها .\n٥ - المخالفات لأحكام هذا القانون أو لنظام الشركة الواقعة خلال السنة موضوع التدقيق ولها أثر جوهري على نتائج أعمال الشركة ووضعها المالي وما اذا كانت هذه المخالفات لا تزال قائمة، وذلك في حدود المعلومات التي توفرت لديه او التي يتوجب عليه معرفتها بحكم واجباته المهنية .\nب - على مدقق الحسابات أن يبدي رأيه النهائي في الميزانية وحساب الأرباح والخسائر للشركة باحدى التوصيات التالية :-\n١ - المصادقة على ميزانية الشركة وحساب ارباحها وخسائرها وتدفقاتها النقدية بصورة مطلقة .\n٢ - المصادقة على الميزانية وحساب الأرباح والخسائر وتدفقاتها النقدية مع التحفظ مع بيان اسباب هذا التحفظ وآثره المالي على الشركة .\n٣ - عدم المصادقة على الميزانية وحساب الأرباح والخسائر وتدفقاتها النقدية، وردها الى مجلس الادارة وبيان الأسباب الموجبة لرفضه التوصية على الميزانية .","title":"مشتملات تقرير مدقق الحسابات","memo":"⭐ يتضمن تقرير المدقق: حصوله على المعلومات اللازمة، انتظام الحسابات وإعداد البيانات وفق معايير المحاسبة الدولية، كفاية إجراءات التدقيق، اتفاق البيانات في تقرير المجلس مع القيود، المخالفات ذات الأثر الجوهري\n⭐ الرأي النهائي بإحدى ثلاث توصيات: المصادقة المطلقة، المصادقة مع التحفظ (مع بيان أسبابه وأثره المالي)، عدم المصادقة وردها للمجلس مع بيان الأسباب","qs":[{"q":"إذا أوصى مدقق الحسابات بالمصادقة على الميزانية مع التحفظ، فيجب عليه:","o":["بيان أسباب التحفظ وأثره المالي على الشركة","رد الميزانية إلى مجلس الإدارة","إبلاغ الوزير فوراً","الاعتذار عن التدقيق"],"a":0},{"q":"جميع ما يلي من التوصيات التي يبدي بها مدقق الحسابات رأيه النهائي في الميزانية باستثناء:","o":["تعديل الميزانية بنفسه واعتمادها","المصادقة بصورة مطلقة","المصادقة مع التحفظ","عدم المصادقة وردها إلى مجلس الإدارة"],"a":0},{"q":"يجب أن يتضمن تقرير المدقق المخالفات لأحكام القانون أو نظام الشركة الواقعة خلال السنة إذا كانت:","o":["ذات أثر جوهري على نتائج أعمال الشركة ووضعها المالي","مرتكبة من المدير العام فقط","تتجاوز قيمتها ١٠٠٠٠ دينار","قد أبلغ عنها المراقب مسبقاً"],"a":0}]},{"n":"196","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"للهيئة العامة للشركة في حالة توصية المدقق بعدم المصادقة على البيانات المالية وردها للمجلس أن تقرر ما يلي :-\nأ- اما الطلب الى المجلس تصحيح الميزانية وحساب الأرباح والخسائر وفقاً لملاحظات مدقق الحسابات ، واعتبارها مصدقة بعد هذا التعديل .\nب- أو احالة الموضوع الى المراقب لتعيين لجنة خبراء من مدققي حسابات قانونيين للفصل في موضوع الخلاف بين مجلس ادارة الشركة ومدققي حساباتها ، ويكون قرار اللجنة ملزماً بعد عرضه مرة اخرى على الهيئة العامة لإقراره ويتم تعديل الميزانية وحساب الأرباح والخسائر تبعاً لذلك .\nج- تحقيقا لغايات الفقرة (ب) من هذه المادة ، يمارس المراقب صلاحياته بالتنسيق مع البنك المركزي وهيئة الاوراق المالية وهيئة قطاع التامين حسب مقتضى الحال .","title":"توصية المدقق بعدم المصادقة على البيانات المالية لمجلس الادارة","memo":"⭐ عند توصية المدقق بعدم المصادقة: للهيئة العامة إما الطلب للمجلس تصحيح الميزانية وفق ملاحظات المدقق واعتبارها مصدقة\n⭐ أو إحالة الموضوع للمراقب لتعيين لجنة خبراء من مدققي الحسابات القانونيين، وقرارها ملزم بعد عرضه على الهيئة العامة لإقراره\n⭐ يمارس المراقب ذلك بالتنسيق مع البنك المركزي وهيئة الأوراق المالية وهيئة التأمين حسب الحال","qs":[{"q":"في حالة توصية المدقق بعدم المصادقة على البيانات المالية، يجوز للهيئة العامة إحالة الموضوع إلى المراقب ليقوم بـ:","o":["تعيين لجنة خبراء من مدققي حسابات قانونيين للفصل في الخلاف","حل مجلس الإدارة","عزل مدقق الحسابات","إحالة الموضوع إلى المحكمة"],"a":0},{"q":"يكون قرار لجنة الخبراء المعينة للفصل في الخلاف بين مجلس الإدارة ومدقق الحسابات:","o":["ملزماً بعد عرضه مرة أخرى على الهيئة العامة لإقراره","ملزماً فور صدوره دون عرضه على أحد","استشارياً غير ملزم","ملزماً بعد مصادقة الوزير عليه"],"a":0}]},{"n":"197","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز لمدقق الحسابات أن يشترك في تأسيس الشركة المساهمة العامة التي يدقق حساباتها أو أن يكون عضواً في مجالس ادارتها أو الاشتغال بصفة دائمة في أي عمل فني أو اداري أو استشاري فيها، ولا يجوز أن يكون شريكاً لأي عضو من اعضاء مجلس ادارتها أو أن يكون موظفاً لديه وذلك تحت طائلة بطلان أي اجراء أو تصرف يقع بصورة تخالف أحكام هذه المادة .","title":"القيود الواردة على مدققوا الحسابات","memo":"⭐ لا يجوز للمدقق: الاشتراك في تأسيس الشركة التي يدققها، أو عضوية مجلس إدارتها، أو الاشتغال بصفة دائمة في أي عمل فني أو إداري أو استشاري فيها\n⭐ ولا أن يكون شريكاً لأي عضو مجلس إدارة أو موظفاً لديه\n⭐ الجزاء: بطلان أي إجراء أو تصرف مخالف","qs":[{"q":"ما حكم التصرف الذي يقع من مدقق حسابات يعمل بصفة دائمة مستشاراً في الشركة التي يدقق حساباتها؟","o":["البطلان","صحيح مع فرض غرامة","موقوف على إجازة الهيئة العامة","صحيح إذا وافق المراقب"],"a":0},{"q":"جميع ما يلي محظور على مدقق حسابات الشركة المساهمة العامة باستثناء:","o":["تقديم تقرير خطي للهيئة العامة","الاشتراك في تأسيس الشركة التي يدقق حساباتها","العضوية في مجلس إدارة الشركة","أن يكون شريكاً لأحد أعضاء مجلس إدارتها"],"a":0}]},{"n":"198","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"على مجلس ادارة الشركة أن يزود مدقق الحسابات بنسخة عن التقارير والبيانات التي يرسلها المجلس للمساهمين بما في ذلك الدعوة لحضور اجتماع الهيئة العامة للشركة وعلى المدقق أو من يمثله حضور هذا الاجتماع .","title":"حضور المدقق اجتماع الهيئة العامة","memo":"⭐ يزود المجلس المدقق بنسخة عن التقارير والبيانات التي يرسلها للمساهمين، بما فيها دعوة اجتماع الهيئة العامة\n⭐ على المدقق أو من يمثله حضور الاجتماع","qs":[{"q":"على مجلس إدارة الشركة أن يزود مدقق الحسابات بـ:","o":["نسخة عن التقارير والبيانات التي يرسلها للمساهمين بما فيها دعوة اجتماع الهيئة العامة","محاضر جميع اجتماعات الموظفين","نسخة عن العقود الشخصية لأعضاء المجلس","سجل المساهمين فقط"],"a":0},{"q":"يحضر اجتماع الهيئة العامة عن جانب التدقيق:","o":["المدقق أو من يمثله","المدقق شخصياً فقط دون جواز الإنابة","أحد موظفي الشركة نيابة عن المدقق","لا يلزم حضور المدقق"],"a":0}]},{"n":"199","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يعتبر مدقق حسابات الشركة وكيلاً عن المساهمين فيها وذلك في حدود المهمة الموكلة اليه .\nب - لكل مساهم اثناء انعقاد الهيئة العامة أن يستوضح مدقق الحسابات عما ورد في تقريره ويناقشه فيه .","title":"مدقق الحسابات وكيل عن المساهمين وحقهم في مناقشته","memo":"⭐ يعتبر مدقق حسابات الشركة وكيلاً عن المساهمين في حدود المهمة الموكلة إليه\n⭐ لكل مساهم أثناء انعقاد الهيئة العامة أن يستوضح المدقق عما ورد في تقريره ويناقشه فيه","qs":[{"q":"يعتبر مدقق حسابات الشركة من الناحية القانونية:","o":["وكيلاً عن المساهمين في حدود المهمة الموكلة إليه","موظفاً لدى مجلس الإدارة","وكيلاً عن المراقب","ممثلاً عن هيئة الأوراق المالية"],"a":0},{"q":"يحق لكل مساهم مناقشة مدقق الحسابات في تقريره:","o":["أثناء انعقاد الهيئة العامة","بموجب طلب خطي للمراقب فقط","إذا كان يملك ١٠٪ من الأسهم","بعد موافقة مجلس الإدارة"],"a":0}]},{"n":"200","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"اذا اطلع مدقق الحسابات على أي مخالفة ارتكبتها الشركة لهذا القانون أو نظام الشركة أو على أي أمور مالية ذات أثر سلبي على أوضاع الشركة المالية أو الادارية فعليه أن يبلغ ذلك خطياً الى كل من رئيس مجلس الادارة والمراقب والهيئة والسوق المالي حال اطلاعه أو اكتشافه لتلك الأمور. على أن تعامل هذه المعلومات من جميع الأطراف بسرية تامة لحين البت في المخالفات .","title":"تبليغ المدقق عن اي مخالفة ترتكبها الشركة","memo":"⭐ إذا اطلع المدقق على أي مخالفة للقانون أو نظام الشركة أو أمور مالية ذات أثر سلبي: يبلغ خطياً كلاً من رئيس مجلس الإدارة والمراقب والهيئة والسوق المالي حال اطلاعه\n⭐ تعامل هذه المعلومات بسرية تامة لحين البت في المخالفات","qs":[{"q":"إذا اطلع مدقق الحسابات على مخالفة ارتكبتها الشركة لأحكام القانون، فعليه أن يبلغ ذلك خطياً إلى:","o":["رئيس مجلس الإدارة والمراقب والهيئة والسوق المالي","الهيئة العامة في اجتماعها السنوي فقط","المدير العام فقط","النيابة العامة"],"a":0},{"q":"يجب على مدقق الحسابات إبلاغ الجهات المختصة بالمخالفات التي يكتشفها:","o":["حال اطلاعه أو اكتشافه لتلك الأمور","خلال ثلاثين يوماً من اكتشافها","عند إعداد التقرير السنوي","بعد موافقة مجلس الإدارة"],"a":0},{"q":"تعامل المعلومات التي يبلغ عنها المدقق بشأن مخالفات الشركة:","o":["بسرية تامة من جميع الأطراف لحين البت في المخالفات","بالنشر الفوري في صحيفتين يوميتين","بإطلاع جميع المساهمين عليها فوراً","بالإفصاح عنها في الموقع الإلكتروني للشركة"],"a":0}]},{"n":"201","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يكون مدقق الحسابات مسؤولا تجاه كل من الشركة التي يقوم بتدقيق حساباتها ومساهميها ومستخدمي بياناتها المالية عن تعويض الضرر المتحقق والربح الفائت بسبب الاخطاء التي ارتكبها في تنفيذ عمله او نتيجة لاخفاقه في القيام بواجباته المحددة له وفقا لاحكام هذا القانون واحكام أي تشريعات اخرى سارية المفعول او واجباته التي تقتضيها معايير المحاسبة والتدقيق الدولية المعتمدة او بسبب اصدار بيانات مالية غير مطابقة للواقع بشكل جوهري او عن مصادقته على هذه البيانات ويسال المدقق عن تعويض الضرر الذي يلحقه بالمساهم او الغير حسن النية بسب الخطا الذي ارتكبه ، واذا كان للشركة اكثر من مدقق حسابات ، واشتركوا في الخطا كانوا مسؤولين بالتضامن وفق احكام هذه المادة ، وتسقط دعوى المسؤولية المدنية في أي من هذه الحالات بمضي ثلاث سنوات من تاريخ انعقاد اجتماع الهيئة العامة للشركة الذي تلي فيه تقرير المدقق ، واذا كان الفعل المنسوب لمدقق الحسابات يشكل جريمة فلا تسقط دعوى المسؤولية المدنية الا بسقوط دعوى الحق العام .","title":"مسؤولية المدقق عن التعويض","memo":"⭐ المدقق مسؤول تجاه الشركة ومساهميها ومستخدمي بياناتها المالية عن تعويض الضرر المتحقق والربح الفائت\n⭐ تعدد المدققين واشتراكهم في الخطأ = مسؤولية بالتضامن\n⭐ تسقط دعوى المسؤولية المدنية بمضي ثلاث سنوات من تاريخ اجتماع الهيئة العامة الذي تلي فيه تقرير المدقق\n⭐ إذا شكل الفعل جريمة لا تسقط الدعوى المدنية إلا بسقوط دعوى الحق العام","qs":[{"q":"تسقط دعوى المسؤولية المدنية على مدقق الحسابات بمضي:","o":["ثلاث سنوات من تاريخ اجتماع الهيئة العامة الذي تلي فيه تقرير المدقق","خمس سنوات من تاريخ اجتماع الهيئة العامة الذي تلي فيه تقرير المدقق","سنة واحدة من تاريخ إصدار تقرير المدقق","ثلاث سنوات من تاريخ انتهاء السنة المالية للشركة"],"a":0},{"q":"إذا كان للشركة أكثر من مدقق حسابات واشتركوا في الخطأ فإنهم يكونون مسؤولين:","o":["بالتضامن","كل بنسبة أتعابه","بالتساوي دون تضامن","المدقق الأول فقط"],"a":0},{"q":"حالة عملية: ارتكب مدقق حسابات فعلاً يشكل جريمة وألحق ضرراً بالشركة، فإن دعوى المسؤولية المدنية عليه:","o":["لا تسقط إلا بسقوط دعوى الحق العام","تسقط بمضي ثلاث سنوات من تاريخ اجتماع الهيئة العامة","تسقط بمضي سنة من تاريخ اكتشاف الجريمة","لا تسقط أبداً"],"a":0},{"q":"يكون المدقق مسؤولاً عن تعويض الضرر المتحقق والربح الفائت تجاه كل مما يلي باستثناء:","o":["دائني المساهمين الشخصيين","الشركة التي يدقق حساباتها","مساهمي الشركة","مستخدمي بياناتها المالية"],"a":0}]},{"n":"202","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"مع مراعاة عدم الإخلاء بالتزامات مدقق الحسابات الأساسية لا يجوز له أن يذيع للمساهمين في مقر اجتماع الهيئة العامة للشركة المساهمة أو في غيره من الأمكنة والأوقات او الى غير المساهمين ما وقف عليه من اسرار الشركة بسبب قيامه بعمله لديها ، والا وجب عزله ومطالبته بالتعويض .","title":"حظر إفشاء المدقق أسرار الشركة","memo":"⭐ لا يجوز للمدقق أن يذيع للمساهمين في اجتماع الهيئة العامة أو غيره أو لغير المساهمين ما وقف عليه من أسرار الشركة بسبب عمله\n⭐ جزاء المخالفة: وجوب عزله ومطالبته بالتعويض\n⭐ مع مراعاة عدم الإخلال بالتزاماته الأساسية","qs":[{"q":"جزاء إذاعة مدقق الحسابات أسرار الشركة التي وقف عليها بسبب عمله:","o":["وجوب عزله ومطالبته بالتعويض","إنذاره خطياً من المراقب","غرامة يحددها الوزير فقط","حرمانه من أتعاب السنة المالية"],"a":0},{"q":"وفقاً لقانون الشركات، فإن حظر إذاعة المدقق أسرار الشركة يشمل إذاعتها:","o":["للمساهمين في مقر اجتماع الهيئة العامة ولغير المساهمين","لغير المساهمين فقط","خارج اجتماع الهيئة العامة فقط","للمنافسين فقط"],"a":0}]},{"n":"203","chapter":"الباب السابع - مدققوا الحسابات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يحظر على مدقق الحسابات وعلى موظفيه المضاربة بأسهم الشركة التي يدقق حساباتها سواء جرى هذا التعامل بالأسهم بصورة مباشرة أو غير مباشرة وذلك تحت طائلة عزله من العمل في تدقيق حسابات الشركة وتضمينه التعويض عن أي ضرر ترتب على مخالفته لأحكام هذه المادة .","title":"حظر مضاربة المدقق بأسهم الشركة","memo":"⭐ يحظر على المدقق وموظفيه المضاربة بأسهم الشركة التي يدقق حساباتها بصورة مباشرة أو غير مباشرة\n⭐ الجزاء: عزله من تدقيق حسابات الشركة وتضمينه التعويض عن أي ضرر","qs":[{"q":"يحظر على مدقق الحسابات وموظفيه المضاربة بأسهم الشركة التي يدقق حساباتها:","o":["بصورة مباشرة أو غير مباشرة","بصورة مباشرة فقط","خلال فترة إعداد البيانات المالية فقط","إذا تجاوزت المضاربة (٥%) من أسهم الشركة"],"a":0},{"q":"جزاء مخالفة المدقق حظر المضاربة بأسهم الشركة التي يدقق حساباتها:","o":["عزله من تدقيق حسابات الشركة وتضمينه التعويض عن الضرر","شطب اسمه من سجل المدققين نهائياً","مصادرة الأسهم لصالح الشركة","تنبيهه من قبل مجلس الإدارة"],"a":0}]},{"n":"204","chapter":"الباب الثامن - الشركة القابضة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - الشركة القابضة هي شركة مساهمة عامة تقوم بالسيطرة المالية والادارية على شركة أو شركات اخرى تدعى الشركات التابعة بواحدة من الطرق التالية :-\n١ - ان تمتلك أكثر من نصف رأسمالها و / أو .\n٢ - أن يكون لها السيطرة على تأليف مجلس ادارتها .\nب - لا يجوز للشركة القابضة تملك حصص في شركات التضامن أو في شركات التوصية البسيطة .\nج - يحظر على الشركة التابعة تملك أي سهم أو حصة في الشركة القابضة .\nد - تقوم الشركة القابضة بتعيين ممثليها في مجالس ادارة الشركة التابعة بنسبة مساهمتها ، ولا يحق لها الاشتراك في انتخاب بقية اعضاء المجلس أو هيئة المديرين حسب مقتضى الأحوال .","title":"تعريف الشركة القابضة","memo":"⭐ الشركة القابضة: شركة مساهمة عامة تسيطر مالياً وإدارياً على شركات تابعة بتملك أكثر من نصف رأسمالها و/أو السيطرة على تأليف مجلس إدارتها\n⭐ لا يجوز لها تملك حصص في شركات التضامن أو التوصية البسيطة\n⭐ يحظر على الشركة التابعة تملك أي سهم أو حصة في القابضة\n⭐ تعين ممثليها في مجالس إدارة التابعة بنسبة مساهمتها ولا تشترك في انتخاب بقية الأعضاء","qs":[{"q":"الشكل القانوني للشركة القابضة وفقاً لقانون الشركات:","o":["شركة مساهمة عامة","شركة ذات مسؤولية محدودة","شركة مساهمة خاصة","شركة توصية بالأسهم"],"a":0},{"q":"تعد الشركة قابضة إذا امتلكت في الشركة الأخرى:","o":["أكثر من نصف رأسمالها","ربع رأسمالها على الأقل","ثلث رأسمالها على الأقل","(٢٠%) من رأسمالها"],"a":0},{"q":"لا يجوز للشركة القابضة تملك حصص في:","o":["شركات التضامن وشركات التوصية البسيطة","الشركات المساهمة العامة","الشركات ذات المسؤولية المحدودة","شركات التوصية بالأسهم"],"a":0},{"q":"حالة عملية: شركة قابضة تملك (٦٠%) من أسهم شركة تابعة، فإن تمثيلها في مجلس إدارة الشركة التابعة يكون:","o":["بتعيين ممثليها بنسبة مساهمتها دون الاشتراك في انتخاب بقية الأعضاء","بانتخاب جميع أعضاء المجلس","بتعيين نصف الأعضاء والاشتراك في انتخاب الباقين","بتعيين الرئيس فقط"],"a":0}]},{"n":"205","chapter":"الباب الثامن - الشركة القابضة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تكون غايات الشركة القابضة ما يلي :-\nأ - ادارة الشركات التابعة لها أو المشاركة في ادارة الشركات الاخرى التي تساهم فيها .\nب - استثمار اموالها في الأسهم والسندات والأوراق المالية .\nج - تقديم القروض والكفالات والتمويل للشركات التابعة لها .\nد - تملك براءات الاختراع والعلامات التجارية وحقوق الامتياز وغيرها من الحقوق المعنوية واستغلالها وتأجيرها للشركات التابعة لها أو لغيرها .","title":"غايات الشركة القابضة","memo":"⭐ غاياتها: إدارة الشركات التابعة أو المشاركة في إدارة غيرها\n⭐ استثمار أموالها في الأسهم والسندات والأوراق المالية\n⭐ تقديم القروض والكفالات والتمويل للشركات التابعة\n⭐ تملك براءات الاختراع والعلامات التجارية وحقوق الامتياز واستغلالها وتأجيرها للتابعة أو لغيرها","qs":[{"q":"جميع ما يلي من غايات الشركة القابضة باستثناء:","o":["قبول الودائع من الجمهور","إدارة الشركات التابعة لها","استثمار أموالها في الأسهم والسندات والأوراق المالية","تقديم القروض والكفالات والتمويل للشركات التابعة لها"],"a":0},{"q":"يجوز للشركة القابضة تأجير براءات الاختراع والعلامات التجارية التي تملكها:","o":["للشركات التابعة لها أو لغيرها","للشركات التابعة لها فقط","للشركات المساهمة العامة فقط","بموافقة الوزير فقط"],"a":0}]},{"n":"206","chapter":"الباب الثامن - الشركة القابضة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تؤسس الشركة القابضة باحدى الطرق التالية :-\n١ - بتأسيس شركة مساهمة عامة تنحصر غاياتها في الأعمال المنصوص عليها في المادة ( ٢٠٥ ) من هذا القانون ، أو في أي منها ، وفي تأسيس شركات تابعة لها أو تملك اسهم أو حصص في شركات مساهمة عامة اخرى أو شركات محدودة المسؤولية أو شركات توصية بالأسهم للقيام بتلك الغايات .\n٢ - بتعديل غايات شركة مساهمة عامة قائمة الى شركة قابضة وفقاً لأحكام هذا القانون .\nب - تحدد الاحكام التنظيمية للشركات القابضة والشركات التابعة لها بنظام خاص يصدر لهذه الغاية .","title":"طرق تأسيس الشركة القابضة","memo":"⭐ تؤسس بتأسيس شركة مساهمة عامة تنحصر غاياتها في غايات المادة (٢٠٥) وتأسيس شركات تابعة أو تملك أسهم/حصص في مساهمة عامة أو محدودة المسؤولية أو توصية بالأسهم\n⭐ أو بتعديل غايات شركة مساهمة عامة قائمة إلى شركة قابضة\n⭐ أحكامها التنظيمية بنظام خاص","qs":[{"q":"تؤسس الشركة القابضة بإحدى طريقتين هما:","o":["تأسيس شركة مساهمة عامة جديدة أو تعديل غايات شركة مساهمة عامة قائمة","تأسيس شركة محدودة المسؤولية أو تحويل شركة تضامن","اندماج شركتين أو تملك شركة أجنبية","قرار من الوزير أو قرار من المراقب"],"a":0},{"q":"تحدد الأحكام التنظيمية للشركات القابضة والشركات التابعة لها بموجب:","o":["نظام خاص يصدر لهذه الغاية","تعليمات يصدرها المراقب","قرار من مجلس الوزراء","النظام الأساسي لكل شركة"],"a":0}]},{"n":"207","chapter":"الباب الثامن - الشركة القابضة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تطبق أحكام هذا القانون على الشركات القابضة التي تؤسس في المملكة بموجب اتفاقيات تبرمها حكومة المملكة الأردنية الهاشمية مع الحكومات الاخرى أو المنظمات العربية أو الدولية وذلك في الحالات غير المنصوص عليها في اتفاقيات تأسيسها أو في عقودها وانظمتها التأسيسية .","title":"سريان القانون على القابضة المؤسسة باتفاقيات","memo":"⭐ يطبق قانون الشركات على الشركات القابضة المؤسسة بموجب اتفاقيات بين الحكومة والحكومات الأخرى أو المنظمات العربية أو الدولية\n⭐ وذلك في الحالات غير المنصوص عليها في اتفاقيات تأسيسها أو عقودها وأنظمتها","qs":[{"q":"تطبق أحكام قانون الشركات على الشركات القابضة المؤسسة بموجب اتفاقيات حكومية مع حكومات أو منظمات أخرى:","o":["في الحالات غير المنصوص عليها في اتفاقيات تأسيسها أو عقودها وأنظمتها","في جميع الحالات وتلغى الاتفاقيات المخالفة","لا تطبق عليها مطلقاً","فقط عند تصفيتها"],"a":0},{"q":"الجهات التي تبرم معها الحكومة الأردنية اتفاقيات تأسيس الشركات القابضة المشار إليها هي:","o":["الحكومات الأخرى أو المنظمات العربية أو الدولية","الشركات الأجنبية العاملة فقط","البنوك المركزية فقط","المستثمرون الأفراد"],"a":0}]},{"n":"208","chapter":"الباب الثامن - الشركة القابضة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"على الشركة القابضة ان تعد في نهاية كل سنة مالية ميزانية مجمعة وبيانات الارباح والخسائر والتدفقات النقدية لها ولجميع الشركات التابعة لها وان تعرضها على الهيئة العامة مع الايضاحات والبيانات المتعلقة بها وفقا لما تتطلبه معايير واصول المحاسبة والتدقيق الدولية المعتمدة .","title":"البيانات المالية المجمعة للقابضة","memo":"⭐ تعد الشركة القابضة في نهاية كل سنة مالية ميزانية مجمعة وبيانات الأرباح والخسائر والتدفقات النقدية لها ولجميع شركاتها التابعة\n⭐ تعرضها على الهيئة العامة وفق معايير المحاسبة والتدقيق الدولية المعتمدة","qs":[{"q":"على الشركة القابضة أن تعد في نهاية كل سنة مالية:","o":["ميزانية مجمعة وبيانات أرباح وخسائر وتدفقات نقدية لها ولجميع شركاتها التابعة","ميزانية خاصة بها فقط","ميزانية لكل شركة تابعة دون تجميع","بيان التدفقات النقدية فقط"],"a":0},{"q":"تعرض الشركة القابضة بياناتها المالية المجمعة على:","o":["الهيئة العامة","الوزير","المحكمة","مجالس إدارة الشركات التابعة"],"a":0}]},{"n":"209","chapter":"الباب التاسع - شركة الاستثمار المشترك","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تسجل شركة الاستثمار المشتركة كشركة مساهمة عامة لدى مراقب الشركات في سجل منفصل وتقتصر غاياتها على استثمار اموالها وأموال الغير في الأوراق المالية على اختلاف انواعها وتنظيم أعمالها وفق أحكام قانون الأوراق المالية .\nب - تطبق على شركة الاستثمار المشترك كافة احكام هذا القانون بما يخص الشركة المساهمة العامة مع مراعاة مايلي :-\n١ - يجب أن يتضمن عقد تأسيس الشركة ونظامها الأساسي اسم مستشار استثماري مرخص حسب القوانين المرعية يقوم بادارة استثمارات الشركة .\n٢ - اذا كانت شركة الاستثمار المشترك ذات رأس مال متغير فلا تطبق عليها أحكام الفقرتين ( أ ) و ( ب ) من المادة ( ٩٥ ) من هذا القانون من حيث ضرورة أن يكون الحد الأدنى لرأس مال الشركة المصرح به خمسمائة الف ( ٥٠٠,٠٠٠ ) دينار ومن حيث ضرورة تسديده في خلال ثلاث سنوات .\n٣ - يحق لمجلس الادارة وحده دون الحاجة للحصول على موافقة الهيئة العامة لشركة الاستثمار المشترك ذات رأس المال المتغير رفع أو تخفيض رأسمالها المصرح به حسب ما يراه مجلس الادارة مناسباً شريطة إبلاغ المراقب بذلك خلال عشرة ايام من تاريخ القرار بالرفع أو التخفيض .\n٤ - يحق للمساهم في شركة الاستثمار المشترك ذات رأس المال المتغير الطلب الى الشركة أن يسترد اسهمه بسعر يمثل صافي قيمة الأسهم محسوباً بتاريخ الاسترداد وناقصاً قيمة أي رسوم أو عمولات تحدد في النظام الأساسي للشركة .\n٥ - لا يلتزم مجلس ادارة شركة الاستثمار المشترك بدعوة الهيئة العامة للانعقاد الا في السنوات التي يتوجب فيها انتخاب مجلس ادارة جديد ما لم ينص النظام الأساسي للشركة على غير ذلك .\n٦ - على الرغم مما ورد في المادة ( ٢٧٤ ) من هذا القانون لا يجوز للمساهم في شركة الاستثمار المشترك ذات رأس المال المتغير أن يطلع على سجلات المساهمين في الشركة ما لم ينص النظام الأساسي للشركة على غير ذلك .\n٧ - في حال اندماج شركة الاستثمار المشترك ذات رأس المال المتغير مع شركة اخرى، فليس للمساهمين في شركة الاستثمار المشترك ذات رأس المال المتغير الذين اعترضوا في اجتماع الهيئة العامة على الاندماج المطالبة بقيمة اسهمهم بالطريقة الواردة في المادة (\n٢٣٥ ) من هذا القانون، الا انهم يحتفظون بحقهم في مطالبة الشركة باسترداد اسهمهم حسب ما ينص عليه البند ( ٤ ) من الفقرة ( ب ) من هذه المادة .","title":"تسجيل شركة الاستثمار المشترك وأحكامها","memo":"⭐ تسجل كشركة مساهمة عامة في سجل منفصل وتقتصر غاياتها على استثمار أموالها وأموال الغير في الأوراق المالية\n⭐ يتضمن عقدها ونظامها اسم مستشار استثماري مرخص\n⭐ ذات رأس المال المتغير: لا يطبق عليها حد (٥٠٠,٠٠٠) دينار ولا تسديده خلال ثلاث سنوات؛ يرفع مجلس الإدارة رأسمالها أو يخفضه ويبلغ المراقب خلال عشرة أيام\n⭐ لا تدعى الهيئة العامة إلا في سنوات انتخاب مجلس إدارة جديد ما لم ينص النظام على خلافه","qs":[{"q":"تسجل شركة الاستثمار المشترك لدى المراقب كـ:","o":["شركة مساهمة عامة في سجل منفصل","شركة محدودة المسؤولية","شركة مساهمة خاصة","شركة معفاة"],"a":0},{"q":"يحق لمجلس إدارة شركة الاستثمار المشترك ذات رأس المال المتغير رفع أو تخفيض رأسمالها المصرح به دون موافقة الهيئة العامة شريطة إبلاغ المراقب خلال:","o":["عشرة أيام من تاريخ القرار","خمسة عشر يوماً من تاريخ القرار","ثلاثين يوماً من تاريخ القرار","سبعة أيام من تاريخ القرار"],"a":0},{"q":"يجب أن يتضمن عقد تأسيس شركة الاستثمار المشترك ونظامها الأساسي اسم:","o":["مستشار استثماري مرخص يدير استثماراتها","مدقق حسابات قانوني","أمين الاستثمار المعين من الهيئة","المصفي المحتمل"],"a":0},{"q":"لا يلتزم مجلس إدارة شركة الاستثمار المشترك بدعوة الهيئة العامة للانعقاد إلا:","o":["في السنوات التي يتوجب فيها انتخاب مجلس إدارة جديد ما لم ينص النظام على غير ذلك","مرة كل سنة","مرة كل سنتين","بطلب من المراقب فقط"],"a":0}]},{"n":"210","chapter":"الباب التاسع - شركة الاستثمار المشترك","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"تتخذ شركة الاستثمار المشترك أحد الشكلين التاليين :\nأ - شركة ذات رأسمال متغير وهي التي تصدر اسهماً قابلة للاسترداد من قبل الشركة ذاتها بسعر يتجدد وفقاً لقيمة صافي موجوداتها المتداولة ، وتلتزم الشركة في أي وقت باسترداد هذه الأسهم بناء على طلب المساهم وحسب الأسعار التي يجب على الشركة أن تعلنها كل اسبوع بمعرفة السوق المالي .\nب - شركة ذات رأسمال ثابت وهي التي تصدر اسهما غير قابلة للاسترداد ويتم تداولها في السوق المالي وفقاً لأسعارها التي تتحدد في السوق المالي .\nج - لا تخضع زيادة المال وتخفيضه في الشركة ذات رأس المال المتغير للاجراءات المنصوص عليها في هذا القانون ما لم ينص عقد تأسيسها أو نظامها على غير ذلك، ويجب أن تظل قيمة أسهم الشركة اسمية حتى بعد سداد قيمتها .","title":"شكلا شركة الاستثمار المشترك","memo":"⭐ ذات رأسمال متغير: تصدر أسهماً قابلة للاسترداد بسعر يتجدد وفق صافي موجوداتها وتعلن الأسعار كل أسبوع بمعرفة السوق المالي\n⭐ ذات رأسمال ثابت: أسهم غير قابلة للاسترداد وتتداول في السوق المالي\n⭐ زيادة وتخفيض رأس المال المتغير لا تخضع لإجراءات القانون ما لم ينص العقد أو النظام، وتظل الأسهم اسمية","qs":[{"q":"الشركة ذات رأس المال المتغير تعلن أسعار استرداد أسهمها بمعرفة السوق المالي:","o":["كل أسبوع","كل يوم","كل شهر","كل ثلاثة أشهر"],"a":0},{"q":"شركة الاستثمار المشترك التي تصدر أسهماً غير قابلة للاسترداد وتتداول في السوق المالي هي:","o":["شركة ذات رأسمال ثابت","شركة ذات رأسمال متغير","شركة قابضة","شركة معفاة"],"a":0},{"q":"وفقاً للمادة، يجب أن تظل قيمة أسهم الشركة ذات رأس المال المتغير:","o":["اسمية حتى بعد سداد قيمتها","لحاملها بعد سداد قيمتها","قابلة للتحويل إلى سندات","مرتبطة بسعر السوق المالي"],"a":0}]},{"n":"211","chapter":"الباب العاشر - الشركة المعفاة","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - الشركة المعفاة هي شركة مساهمة عامة أو شركة محدودة المسؤولية او الشركات المساهمة الخاصة تسجل في المملكة وتزاول أعمالها خارجها ويضاف الى اسمها عبارة ( شركة معفاة ) .\nب - يحظر على الشركة المعفاة أن تطرح أسهمها للاكتتاب في المملكة .","title":"تعريف الشركة المعفاة","memo":"⭐ الشركة المعفاة: مساهمة عامة أو محدودة المسؤولية أو مساهمة خاصة تسجل في المملكة وتزاول أعمالها خارجها\n⭐ يضاف إلى اسمها عبارة (شركة معفاة)\n⭐ يحظر عليها طرح أسهمها للاكتتاب في المملكة","qs":[{"q":"الشركة المعفاة هي شركة تسجل في المملكة و:","o":["تزاول أعمالها خارج المملكة","تزاول أعمالها داخل المملكة فقط","تعفى من التسجيل لدى المراقب","تزاول أعمال الوساطة المالية فقط"],"a":0},{"q":"أي مما يلي يحظر على الشركة المعفاة:","o":["طرح أسهمها للاكتتاب في المملكة","إضافة عبارة (شركة معفاة) إلى اسمها","التسجيل لدى المراقب","مزاولة أعمالها خارج المملكة"],"a":0},{"q":"يجوز أن تكون الشركة المعفاة أياً مما يلي باستثناء:","o":["شركة تضامن","شركة مساهمة عامة","شركة محدودة المسؤولية","شركة مساهمة خاصة"],"a":0}]},{"n":"212","chapter":"الباب العاشر - الشركة المعفاة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"تسجل الشركة المعفاة لدى المراقب في سجل خاص بالشركات الأردنية العاملة خارج حدود المملكة. ويجب أن لا يقل رأسمالها عن الحد الادنى المقرر في التشريعات ذات العلاقة إذا كان نشاطها في مجال التأمين أو اعادة التأمين أو البنوك أو الشركات المالية .","title":"تسجيل الشركة المعفاة ورأسمالها","memo":"⭐ تسجل لدى المراقب في سجل خاص بالشركات الأردنية العاملة خارج حدود المملكة\n⭐ لا يقل رأسمالها عن الحد الأدنى المقرر في التشريعات ذات العلاقة إذا كان نشاطها تأميناً أو إعادة تأمين أو بنوكاً أو شركات مالية","qs":[{"q":"تسجل الشركة المعفاة لدى المراقب في:","o":["سجل خاص بالشركات الأردنية العاملة خارج حدود المملكة","سجل الشركات الأجنبية","سجل الشركات المساهمة العامة","سجل منفصل لدى هيئة الأوراق المالية"],"a":0},{"q":"يجب ألا يقل رأسمال الشركة المعفاة عن الحد الأدنى المقرر في التشريعات ذات العلاقة إذا كان نشاطها في مجال:","o":["التأمين أو إعادة التأمين أو البنوك أو الشركات المالية","التجارة العامة","الخدمات الاستشارية","الصناعة"],"a":0}]},{"n":"213","chapter":"الباب العاشر - الشركة المعفاة","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"ملغاه","title":"مادة ملغاة","memo":"⭐ المادة (٢١٣) ملغاة","qs":[]},{"n":"214","chapter":"الباب العاشر - الشركة المعفاة","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تحدد الأحكام والشروط الخاصة باجراءات تأسيس الشركة المعفاة وعملها والرسوم المتوجبة عليها ورقابتها بنظام يصدر بموجب هذا القانون .","title":"نظام تأسيس الشركة المعفاة ورقابتها","memo":"⭐ إجراءات تأسيس الشركة المعفاة وعملها والرسوم المتوجبة عليها ورقابتها تحدد بنظام يصدر بموجب القانون","qs":[{"q":"تحدد الأحكام الخاصة بإجراءات تأسيس الشركة المعفاة وعملها والرسوم المتوجبة عليها ورقابتها بموجب:","o":["نظام يصدر بموجب قانون الشركات","تعليمات يصدرها المراقب","قرار من الوزير","عقد تأسيس الشركة"],"a":0}]},{"n":"215","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز لشركة التضامن أن تتحول الى شركة توصية بسيطة كما يجوز لشركة التوصية البسيطة أن تتحول إلى شركة تضامن وذلك بموافقة جميع الشركاء وباتباع الاجراءات القانونية في تسجيل الشركة وتسجيل التغيرات الطارئة عليها .","title":"التحول بين التضامن والتوصية البسيطة","memo":"⭐ يجوز تحول شركة التضامن إلى توصية بسيطة والعكس\n⭐ بشرط موافقة جميع الشركاء واتباع إجراءات التسجيل وتسجيل التغيرات","qs":[{"q":"يشترط لتحول شركة التضامن إلى شركة توصية بسيطة:","o":["موافقة جميع الشركاء واتباع إجراءات التسجيل","موافقة أغلبية الشركاء","موافقة الشركاء الذين يملكون ثلثي رأس المال","موافقة الوزير بناء على تنسيب المراقب"],"a":0},{"q":"وفقاً للمادة، يجوز لشركة التوصية البسيطة أن تتحول إلى:","o":["شركة تضامن","شركة مساهمة عامة مباشرة","شركة قابضة","شركة معفاة"],"a":0}]},{"n":"216","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"للشركة أن تتحول الى شركة ذات مسؤولية محدودة او شركة مساهمة خاصة باتباع الاجراءات التالية :-\nأ - أن يقدم جميع الشركاء طلباً خطياً الى المراقب، أو أن يقدم قرار الهيئة العامة للشركة حسب واقع الحال، بالرغبة في تحويل الشركة مع بيان أسباب التحويل ومبرراته ونوع الشركة التي سيتم التحويل اليها ويرفق بالطلب ما يلي :-\n١ - ميزانية الشركة لكل من السنتين الاخيرتين السابقتين لطلب التحويل، مصدقة من مدقق حسابات قانوني أو ميزانية آخر سنة مالية للشركة إذا لم يكن قد مضى على تسجيلها أكثر من سنة .\n٢ - بيان بتقديرات الشركاء لموجودات الشركة ومطلوباتها .\nب. مع مراعاة احكام الفقرة ( أ ) من هذه المادة يشترط موافقة الشركاء او المساهمين حسب مقتضى الحال بالاجماع على تحويل الشركة الى شركة مساهمة خاصة .\nج - يعلن المراقب عن طلب التحويل في صحيفتين يوميتين على الأقل وعلى نفقة الشركة خلال خمسة عشر يوماً من تاريخ تقديم الطلب ويبين في الاعلان ما اذا كان هناك اعتراضات من الدائنين او الغير ولا يتم التحويل الا بموافقة خطية من الدائنين الذين يملكون اكثر من ثلثي الديون المترتبة على الشركة .\nد - للمراقب أن يتحقق من صحة تقديرات صافي حقوق الشركاء أو المساهمين حسب واقع الحال بالطريقة التي يراها مناسبة بما في ذلك تعيين خبير أو أكثر للتحقق من صحة هذه التقديرات وتتحمل الشركة بدل أتعاب الخبراء التي يحددها المراقب .\nه - للمراقب قبول التحويل أو رفضه، وفي حالة الرفض يخضع قراره لأصول الطعن المقررة، أما في حالة الموافقة فعندها تستكمل اجراءات التسجيل والنشر وفقاً لأحكام هذا القانون .","title":"التحول إلى محدودة المسؤولية أو مساهمة خاصة","memo":"⭐ يقدم جميع الشركاء طلباً خطياً أو قرار الهيئة العامة للمراقب مرفقاً بميزانية آخر سنتين مصدقة (أو آخر سنة إذا لم يمض على التسجيل أكثر من سنة) وبيان تقديرات الموجودات والمطلوبات\n⭐ التحول إلى مساهمة خاصة يشترط الإجماع\n⭐ يعلن المراقب في صحيفتين يوميتين خلال خمسة عشر يوماً، ولا يتم التحويل إلا بموافقة خطية من دائني أكثر من ثلثي الديون\n⭐ للمراقب قبول التحويل أو رفضه ورفضه قابل للطعن","qs":[{"q":"يعلن المراقب عن طلب تحويل الشركة إلى شركة ذات مسؤولية محدودة في صحيفتين يوميتين على الأقل خلال:","o":["خمسة عشر يوماً من تاريخ تقديم الطلب","عشرة أيام من تاريخ تقديم الطلب","ثلاثين يوماً من تاريخ تقديم الطلب","ستين يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"لا يتم تحويل الشركة إلى شركة ذات مسؤولية محدودة إلا بموافقة خطية من الدائنين الذين يملكون:","o":["أكثر من ثلثي الديون المترتبة على الشركة","أكثر من نصف الديون المترتبة على الشركة","ثلاثة أرباع الديون المترتبة على الشركة","جميع الديون المترتبة على الشركة"],"a":0},{"q":"يشترط لتحويل الشركة إلى شركة مساهمة خاصة موافقة الشركاء أو المساهمين:","o":["بالإجماع","بأغلبية (٧٥%)","بأغلبية الثلثين","بالأغلبية المطلقة"],"a":0},{"q":"حالة عملية: شركة مسجلة منذ ثمانية أشهر ترغب بالتحول إلى شركة ذات مسؤولية محدودة، فإنها ترفق بطلبها:","o":["ميزانية آخر سنة مالية للشركة","ميزانيات آخر ثلاث سنوات","ميزانيات آخر سنتين","لا يلزمها إرفاق أي ميزانية"],"a":0}]},{"n":"217","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"يجوز للشركة ذات المسؤولية المحدودة والشركة المساهمة الخاصة التحول إلى شركة مساهمة عامة وفقاً للأحكام المنصوص عليها في هذا القانون، ويقدم طلب التحويل في هذه الحالة إلى المراقب مرفقاً به ما يلي :-\nأ - قرار الهيئة العامة للشركة بالموافقة على التحويل .\nب - أسباب ومبررات التحويل مبنية على دراسة اقتصادية ومالية عن أوضاع الشركة وما سيكون عليه بعد التحويل .\nج. الميزانية السنوية المدققة للسنتين الماليتين السابقتين على طلب التحويل شريطة ان تكون الشركة قد حققت ارباحا صافية خلال أي منهما .\nد - بيان بأن رأسمال الشركة مدفوع بالكامل .\nهـ - بيان من الشركة بالتقديرات الأولية لموجوداتها ومطلوباتها .","title":"التحول إلى مساهمة عامة ومرفقات الطلب","memo":"⭐ يجوز للمحدودة المسؤولية والمساهمة الخاصة التحول إلى مساهمة عامة بطلب للمراقب\n⭐ المرفقات: قرار الهيئة العامة، أسباب ومبررات مبنية على دراسة اقتصادية ومالية، الميزانية المدققة للسنتين السابقتين بشرط تحقيق أرباح صافية في أي منهما، بيان بأن رأس المال مدفوع بالكامل، تقديرات أولية للموجودات والمطلوبات","qs":[{"q":"يشترط في الميزانيات المرفقة بطلب تحويل الشركة ذات المسؤولية المحدودة إلى مساهمة عامة أن تكون الشركة قد حققت أرباحاً صافية خلال:","o":["أي من السنتين الماليتين السابقتين على الطلب","كل من السنتين الماليتين السابقتين","ثلاث سنوات متتالية","السنة المالية الأخيرة فقط"],"a":0},{"q":"جميع ما يلي من مرفقات طلب تحويل الشركة ذات المسؤولية المحدودة إلى مساهمة عامة باستثناء:","o":["موافقة جميع الدائنين على التحويل","قرار الهيئة العامة بالموافقة على التحويل","بيان بأن رأسمال الشركة مدفوع بالكامل","دراسة اقتصادية ومالية تبين أسباب التحويل ومبرراته"],"a":0},{"q":"يجب أن يرفق بطلب التحويل إلى شركة مساهمة عامة بيان بأن رأسمال الشركة:","o":["مدفوع بالكامل","مدفوع بنسبة (٥٠%) على الأقل","لا يقل عن (٥٠٠,٠٠٠) دينار","مدفوع بنسبة (٢٥%) على الأقل"],"a":0}]},{"n":"218","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"للوزير بناء على تنسيب المراقب الموافقة على تحويل الشركة ذات المسؤولية المحدودة او الشركة المساهمة الخاصة إلى شركة مساهمة عامة خلال ثلاثين يوماً من تاريخ تقديم الطلب المشار اليه في المادة ( ٢٢٥ ) من هذا القانون وبعد استكمال الاجراءات التالية :-\nأ - تقدير موجودات ومطلوبات الشركة الراغبة بالتحول من قبل لجنة من ذوي الخبرة والاختصاص يشكلها الوزير على أن يكون من بينها مدقق حسابات قانوني ويحدد الوزير أتعاب هذه اللجنة على نفقة الشركة .\nب - الموافقة الخطية على التحويل من الدائنين الذين يملكون اكثر من ثلثي الديون المترتبة على الشركة .","title":"موافقة الوزير على التحول لمساهمة عامة","memo":"⭐ يوافق الوزير بناء على تنسيب المراقب خلال ثلاثين يوماً من تاريخ تقديم الطلب\n⭐ بعد تقدير الموجودات والمطلوبات من لجنة خبراء يشكلها الوزير من بينها مدقق حسابات قانوني وأتعابها على نفقة الشركة\n⭐ وموافقة خطية من دائني أكثر من ثلثي الديون","qs":[{"q":"الجهة المختصة بالموافقة على تحويل الشركة ذات المسؤولية المحدودة إلى شركة مساهمة عامة:","o":["الوزير بناء على تنسيب المراقب","المراقب بناء على تنسيب الوزير","مجلس الوزراء","هيئة الأوراق المالية"],"a":0},{"q":"يوافق الوزير على تحويل الشركة إلى مساهمة عامة خلال:","o":["ثلاثين يوماً من تاريخ تقديم الطلب","خمسة عشر يوماً من تاريخ تقديم الطلب","ستين يوماً من تاريخ تقديم الطلب","تسعين يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"يشترط في لجنة تقدير موجودات ومطلوبات الشركة الراغبة بالتحول إلى مساهمة عامة أن يكون من بين أعضائها:","o":["مدقق حسابات قانوني","قاض منتدب","ممثل عن البنك المركزي","ممثل عن دائني الشركة"],"a":0}]},{"n":"219","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يعلن المراقب عن قرار الوزير بالموافقة على التحويل في صحيفتين يوميتين محليتين على الأقل ولمرتين متتاليتين على نفقة الشركة ويبلغ المراقب الهيئة والسوق المالي والمركز بهذا القرار .\nب - لكل ذي مصلحة الاعتراض لدى الوزير على قرار تحويل الشركة خلال ثلاثين يوماً من تاريخ نشر آخر إعلان عن التحويل مبينا فيه أسباب اعتراضه ومبرراته ، وإذا لم تتم تسوية الاعتراضات المقدمة أو أي منها خلال ثلاثين يوماً من تاريخ تقديم آخر اعتراض ، فلكل من المعترضين الطعن في قرار الوزير لدى المحكمة الإدارية خلال ثلاثين يوماً من انتهاء تلك المدة ، على أن لا يوقف الطعن اجراءات التحويل إلا إذا قررت المحكمة غير ذلك .","title":"إعلان قرار التحويل والاعتراض عليه","memo":"⭐ يعلن المراقب قرار الوزير في صحيفتين يوميتين محليتين على الأقل لمرتين متتاليتين على نفقة الشركة ويبلغ الهيئة والسوق والمركز\n⭐ الاعتراض لدى الوزير خلال ثلاثين يوماً من آخر إعلان\n⭐ إذا لم تسوّ الاعتراضات خلال ثلاثين يوماً فالطعن لدى المحكمة الإدارية خلال ثلاثين يوماً\n⭐ الطعن لا يوقف إجراءات التحويل إلا إذا قررت المحكمة غير ذلك","qs":[{"q":"لكل ذي مصلحة الاعتراض لدى الوزير على قرار تحويل الشركة إلى مساهمة عامة خلال:","o":["ثلاثين يوماً من تاريخ نشر آخر إعلان عن التحويل","خمسة عشر يوماً من تاريخ نشر أول إعلان","ستين يوماً من تاريخ صدور القرار","عشرة أيام من تاريخ نشر آخر إعلان"],"a":0},{"q":"الجهة التي يطعن لديها المعترض في قرار الوزير بالتحويل إذا لم تتم تسوية اعتراضه:","o":["المحكمة الإدارية","محكمة البداية","محكمة الاستئناف","مجلس الوزراء"],"a":0},{"q":"أثر الطعن في قرار الوزير بالتحويل على إجراءات التحويل:","o":["لا يوقفها إلا إذا قررت المحكمة غير ذلك","يوقفها حكماً","يوقفها لمدة ثلاثين يوماً","يلغيها حكماً"],"a":0}]},{"n":"220","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يتم تحويل الشركة إلا بعد اتمام اجراءات التسجيل والنشر المقررة بموجب هذا القانون. وإذا كان رأس المال الناتج عن إعادة التقدير يقل عن الحد الأدنى لرأسمال الشركة المساهمة العامة المقررة بمقتضى هذا القانون فتتبع الاجراءات القانونية الخاصة برفع رأس مال الشركة المساهمة العامة المنصوص عليها في هذا القانون .","title":"اشتراط التسجيل والنشر لإتمام التحويل","memo":"⭐ لا يتم التحويل إلا بعد إتمام إجراءات التسجيل والنشر\n⭐ إذا قل رأس المال الناتج عن إعادة التقدير عن الحد الأدنى لرأسمال المساهمة العامة تتبع إجراءات رفع رأس المال","qs":[{"q":"لا يتم تحويل الشركة إلا بعد:","o":["إتمام إجراءات التسجيل والنشر المقررة","موافقة جميع المساهمين","صدور حكم قضائي","انقضاء سنة على تقديم الطلب"],"a":0},{"q":"حالة عملية: نتج عن إعادة تقدير شركة متحولة إلى مساهمة عامة رأس مال يقل عن الحد الأدنى المقرر، فإن الإجراء الواجب:","o":["اتباع الإجراءات القانونية الخاصة برفع رأس مال الشركة المساهمة العامة","رفض التحويل حكماً","تصفية الشركة","تحويلها إلى شركة معفاة"],"a":0}]},{"n":"221","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يترتب على تحويل أية شركة إلى أية شركة أخرى لا يترتب عليه نشوء شخص اعتباري جديد بل تبقى للشركة شخصيتها الاعتبارية السابقة وتحتفظ الشركة بجميع حقوقها وتكون مسؤولة عن التزاماتها السابقة على التحويل ، وتبقى مسؤولية الشريك المتضامن بأمواله الشخصية عن ديون الشركة والتزاماتها السابقة على تاريخ التحويل قائمة .","title":"استمرار الشخصية الاعتبارية بعد التحول","memo":"⭐ لا يترتب على التحويل نشوء شخص اعتباري جديد بل تبقى للشركة شخصيتها السابقة\n⭐ تحتفظ بجميع حقوقها وتسأل عن التزاماتها السابقة\n⭐ تبقى مسؤولية الشريك المتضامن بأمواله الشخصية عن الديون السابقة على التحويل","qs":[{"q":"يترتب على تحويل الشركة إلى شركة أخرى:","o":["بقاء شخصيتها الاعتبارية السابقة دون نشوء شخص اعتباري جديد","نشوء شخص اعتباري جديد","انقضاء الشركة وتصفيتها","سقوط التزاماتها السابقة"],"a":0},{"q":"حالة عملية: تحولت شركة تضامن إلى شركة ذات مسؤولية محدودة، فإن مسؤولية الشريك المتضامن عن ديون الشركة السابقة على التحويل:","o":["تبقى قائمة بأمواله الشخصية","تنقضي بالتحويل","تقتصر على حصته في رأس المال","تنتقل إلى المدير العام"],"a":0}]},{"n":"222","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . يتم اندماج الشركات المنصوص عليها في هذا القانون باي من الطرق التالية على ان تكون غايات أي من الشركة الراغبة في الاندماج متماثلة او متكاملة :\n١. باندماج شركة او اكثر مع شركة او شركات اخرى تسمى ( الشركة الدامجة ) وتنقضي الشركة او الشركات الاخرى المندمجة فيها وتزول الشخصية الاعتبارية لكل منها وتنتقل جميع حقوق والتزامات الشركة المندمجة الى الشركة الدامجة بعد شطب تسجيل الشركة المندمجة وذلك وفقا للاجراءات التالية :\n- صدور قرار من الشركة المندمجة بضمها الى الشركة الدامجة .\n- اجراء تقييم صافي اصول وخصوم الشركة المندمجة طبقا لاحكام التقييم المنصوص عليها في هذا القانون والانظمة والتعليمات الصادرة بموجبه .\n- اتخاذ الشركة الدامجة قرارا بزيادة راسمالها بما لا يقل عن قيمة التقييم .\n- توزيع زيادة راسمال الشركة الدامجة على الشركاء او المساهمين في الشركة المندمجة بنسبة حصصهم او اسهمهم فيها . - جواز تداول اسهمها بمجرد اصدارها اذا كانت الشركة الدامجة شركة مساهمة عامة وانقضى على تاسيسها المدة المحددة في قانون الاوراق المالية .\n- استكمال اجراءات الموافقة والتسجيل والنشر المقرر في هذا القانون .\n٢. باندماج شركتين او اكثر لتاسيس شركة جديدة تكون هي الشركة الناتجة عن الاندماج ، وتنقضي الشركات التي اندمجت بالشركة الجديدة وتزول الشخصية الاعتبارية لكل منها .\n٣. باندماج فروع ووكالات الشركات الاجنبية العاملة في المملكة في شركة اردنية قائمة او جديدة تؤسس لهذه الغاية وتنقضي تلك الفروع والوكالات وتزول الشخصية الاعتبارية لكل منها .\nب. يحق للشركة تملك شركة اخرى وفقا لاحكام هذا القانون باتباع الاجراءات التالية :\n١. صدور قرار من الهيئة العامة غير العادية من الشركة الراغبة في الشراء بالموافقة على تملك اسهم مساهمي شركة اخرى .\n٢. صدور قرار من الهيئة العامة غير العادية للشركة الراغبة في البيع بالموافقة على بيع اسهم مساهميها الى شركة اخرى .\n٣. استكمال اجراءات الموافقة والتسجيل والنشر المقررة بتحويل اسهم مساهمي الشركة التي تقرر بيعها الى الشركة المشترية ولا يعتد بهذا التملك الا بعد قيده وتوثيقه بموجب احكام هذا القانون وقانون الاوراق المالية .\n٤. على الشركة المشترية دفع قيمة الاسهم المتفق عليها الى الشركة البائعة لوضعها في حساب خاص لتوزيعها على مساهميها المسجلين لديها بتاريخ قرار الهيئة العامة الذي يتضمن بيع اسهمهم .\n٥. على الشركة التي تم تملك اسهمها دعوة الهيئة العامة وفقا لاحكام هذا القانون لاجراء التعديلات اللازمة على عقد تاسيسها ونظامها الاساسي وانتخاب مجلس ادارة جديد .","title":"طرق الاندماج وتملك الشركات","memo":"⭐ يشترط أن تكون غايات الشركات الراغبة بالاندماج متماثلة أو متكاملة\n⭐ طرق الاندماج: الضم (دامجة ومندمجة)، المزج لتأسيس شركة جديدة، اندماج فروع الشركات الأجنبية في شركة أردنية\n⭐ تزيد الدامجة رأسمالها بما لا يقل عن قيمة التقييم وتوزع الزيادة على شركاء المندمجة بنسبة حصصهم\n⭐ التملك: قرار الهيئة العامة غير العادية للمشترية وللبائعة، ولا يعتد بالتملك إلا بعد قيده وتوثيقه","qs":[{"q":"يشترط في الشركات الراغبة في الاندماج أن تكون غاياتها:","o":["متماثلة أو متكاملة","متطابقة تماماً","مختلفة","من نوع واحد من الشركات"],"a":0},{"q":"في الاندماج بطريق الضم تتخذ الشركة الدامجة قراراً بزيادة رأسمالها:","o":["بما لا يقل عن قيمة التقييم","بما لا يزيد على قيمة التقييم","بنسبة (٥٠%) من رأسمالها","بقيمة رأسمال الشركة المندمجة الاسمي"],"a":0},{"q":"يتطلب تملك شركة لأسهم مساهمي شركة أخرى صدور قرار بالموافقة من:","o":["الهيئة العامة غير العادية لكل من الشركة المشترية والشركة البائعة","مجلس إدارة الشركة المشترية فقط","الهيئة العامة العادية للشركة البائعة فقط","الوزير فقط"],"a":0},{"q":"جميع ما يلي من طرق الاندماج المنصوص عليها في المادة باستثناء:","o":["اندماج شركة أردنية في شركة أجنبية خارج المملكة","اندماج شركة أو أكثر مع شركة دامجة","اندماج شركتين أو أكثر لتأسيس شركة جديدة","اندماج فروع الشركات الأجنبية العاملة في المملكة في شركة أردنية"],"a":0}]},{"n":"223","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"إذا اندمجت شركتان أو أكثر من نوع واحد في إحدى الشركات القائمة أو لتأسيس شركة جديدة ، فتكون الشركة الدامجة أو الشركة الجديدة الناتجة عن الدمج من ذلك النوع. على أنه يجوز للشركة المحدودة المسؤولية او الشركة المساهمة الخاصة الاندماج في شركة مساهمة عامة قائمة أو تأسيس شركة مساهمة عامة جديدة .","title":"نوع الشركة الناتجة عن الاندماج","memo":"⭐ اندماج شركات من نوع واحد: الشركة الدامجة أو الجديدة من ذلك النوع\n⭐ يجوز للمحدودة المسؤولية أو المساهمة الخاصة الاندماج في مساهمة عامة قائمة أو تأسيس مساهمة عامة جديدة","qs":[{"q":"إذا اندمجت شركتان أو أكثر من نوع واحد فإن الشركة الناتجة عن الدمج تكون:","o":["من ذلك النوع","شركة مساهمة عامة حكماً","من النوع الذي يختاره الوزير","شركة محدودة المسؤولية حكماً"],"a":0},{"q":"يجوز للشركة ذات المسؤولية المحدودة أو المساهمة الخاصة الاندماج في:","o":["شركة مساهمة عامة قائمة أو تأسيس شركة مساهمة عامة جديدة","شركة تضامن قائمة فقط","شركة توصية بسيطة فقط","شركة أجنبية غير عاملة"],"a":0}]},{"n":"224","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"تعفى الشركة المندمجة ومساهموها او الشركاء فيها والشركة الدامجة او الشركة الناتجة عن الاندماج ومساهموها او الشركاء فيها من جميع الضرائب والرسوم بما في ذلك رسوم نقل الملكية التي تترتب على الاندماج او بسببه .","title":"إعفاء الاندماج من الضرائب والرسوم","memo":"⭐ تعفى الشركة المندمجة والدامجة أو الناتجة ومساهموها أو الشركاء من جميع الضرائب والرسوم بما فيها رسوم نقل الملكية المترتبة على الاندماج أو بسببه","qs":[{"q":"تعفى الشركة المندمجة والدامجة ومساهموها من الضرائب والرسوم المترتبة على الاندماج أو بسببه:","o":["جميعها بما في ذلك رسوم نقل الملكية","باستثناء رسوم نقل الملكية","بنسبة (٥٠%) منها","لمدة خمس سنوات فقط"],"a":0},{"q":"يشمل الإعفاء من الضرائب والرسوم المترتبة على الاندماج:","o":["الشركة المندمجة والدامجة أو الناتجة ومساهميها أو الشركاء فيها","الشركة الدامجة فقط","مساهمي الشركة المندمجة فقط","الشركة الناتجة عن الاندماج فقط"],"a":0}]},{"n":"225","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يقدم طلب الاندماج مرفقا بالبيانات والوثائق التالية :\nأ - قرار الهيئة العامة غير العادية لكل من الشركات الراغبة في الاندماج أو قرار جميع الشركاء حسب مقتضى الحال بالموافقة على الاندماج وفقاً للشروط والبيانات المحددة في عقد الاندماج بما في ذلك التاريخ المحدد للدمج النهائي .\nب - عقد الاندماج المبرم بين الشركات الراغبة في الاندماج موقعاً من المفوضين بالتوقيع عن تلك الشركات .\nج - قائمة المركز المالي للشركات الراغبة بالاندماج لأقرب تاريخ لقرار الهيئة العامة لكل من الشركات أو قرار الشركاء بالاندماج مصدقة من مدققي حسابات الشركة .\nد - البيانات المالية لآخر سنتين ماليتين للشركات الراغبة بالاندماج مصادقاً عليها من مدققي الحسابات .\nهـ - التقدير الأولي لموجودات ومطلوبات الشركات الراغبة بالاندماج بالقيمة الفعلية أو السوقية .\nو - أي بيانات أخرى تتطلبها التشريعات السارية المفعول او يراها المراقب ضرورية .","title":"مرفقات طلب الاندماج","memo":"⭐ قرار الهيئة العامة غير العادية لكل شركة أو قرار جميع الشركاء بما فيه تاريخ الدمج النهائي\n⭐ عقد الاندماج موقعاً من المفوضين بالتوقيع\n⭐ قائمة المركز المالي لأقرب تاريخ لقرار الاندماج مصدقة، والبيانات المالية لآخر سنتين ماليتين\n⭐ التقدير الأولي للموجودات والمطلوبات بالقيمة الفعلية أو السوقية","qs":[{"q":"يرفق بطلب الاندماج البيانات المالية للشركات الراغبة بالاندماج لآخر:","o":["سنتين ماليتين مصادقاً عليها من مدققي الحسابات","ثلاث سنوات مالية","خمس سنوات مالية","سنة مالية واحدة"],"a":0},{"q":"يرفق بطلب الاندماج قرار الموافقة على الاندماج الصادر عن:","o":["الهيئة العامة غير العادية لكل شركة أو جميع الشركاء حسب مقتضى الحال","مجلس إدارة كل شركة","الهيئة العامة العادية للشركة الدامجة فقط","المدير العام لكل شركة"],"a":0},{"q":"يكون التقدير الأولي لموجودات ومطلوبات الشركات الراغبة بالاندماج المرفق بالطلب على أساس:","o":["القيمة الفعلية أو السوقية","القيمة الدفترية فقط","التكلفة التاريخية","القيمة الاسمية للأسهم"],"a":0}]},{"n":"226","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"على مجلس ادارة كل شركة من الشركات الراغبة في الاندماج تبليغ المراقب والهيئة والسوق المالي والمركز خلال عشرة ايام من تاريخ اتخاذ قرار الاندماج ، ويوقف تداول اسهمها اعتبارا من تاريخ تبليغ ذلك القرار ويعاد تداول اسهم الشركة الناتجة عن الدمج بعد انتهاء اجراءات الاندماج وتسجيلها ، وفي حالة العدول عن الدمج يعاد تداول اسهم تلك الشركات .","title":"وقف تداول أسهم الشركات الراغبة بالاندماج","memo":"⭐ يبلغ مجلس الإدارة المراقب والهيئة والسوق المالي والمركز خلال عشرة أيام من قرار الاندماج\n⭐ يوقف التداول من تاريخ تبليغ القرار ويعاد لأسهم الشركة الناتجة بعد انتهاء الإجراءات وتسجيلها\n⭐ عند العدول عن الدمج يعاد تداول الأسهم","qs":[{"q":"على مجلس إدارة الشركة الراغبة بالاندماج تبليغ المراقب والهيئة والسوق المالي والمركز خلال:","o":["عشرة أيام من تاريخ اتخاذ قرار الاندماج","سبعة أيام من تاريخ اتخاذ قرار الاندماج","ثلاثين يوماً من تاريخ اتخاذ قرار الاندماج","خمسة عشر يوماً من تاريخ اتخاذ قرار الاندماج"],"a":0},{"q":"يوقف تداول أسهم الشركة الراغبة بالاندماج اعتباراً من:","o":["تاريخ تبليغ قرار الاندماج","تاريخ موافقة الوزير","تاريخ تسجيل الشركة الناتجة","تاريخ تقديم طلب الاندماج"],"a":0},{"q":"حالة عملية: عدلت شركتان عن الدمج بعد وقف تداول أسهمهما، فإن الحكم:","o":["يعاد تداول أسهم تلك الشركات","يستمر وقف التداول لمدة سنة","تشطب الشركتان من السوق المالي","يتوقف التداول حتى موافقة الوزير"],"a":0}]},{"n":"227","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يقوم المراقب بدراسة طلب الاندماج ورفع توصياته إلى الوزير إذا كان الاندماج يتعلق بشركة مساهمة عامة ، أو ينتج شركة مساهمة عامة خلال ثلاثين يوما من تاريخ تقديم الطلب .","title":"دراسة المراقب لطلب الاندماج","memo":"⭐ يدرس المراقب طلب الاندماج ويرفع توصياته إلى الوزير خلال ثلاثين يوماً من تقديم الطلب\n⭐ إذا كان الاندماج يتعلق بشركة مساهمة عامة أو ينتج شركة مساهمة عامة","qs":[{"q":"يرفع المراقب توصياته بشأن طلب الاندماج إلى الوزير إذا كان الاندماج يتعلق بشركة مساهمة عامة أو ينتجها خلال:","o":["ثلاثين يوماً من تاريخ تقديم الطلب","عشرة أيام من تاريخ تقديم الطلب","ستين يوماً من تاريخ تقديم الطلب","تسعين يوماً من تاريخ تقديم الطلب"],"a":0},{"q":"يرفع المراقب توصياته بطلب الاندماج إلى الوزير في حالة:","o":["تعلق الاندماج بشركة مساهمة عامة أو إنتاجه شركة مساهمة عامة","اندماج شركات التضامن فقط","اندماج الشركات المعفاة فقط","جميع حالات الاندماج دون تمييز"],"a":0}]},{"n":"228","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"إذا وافق الوزير على طلب الاندماج يشكل ( لجنة تقدير ) يشترك في عضويتها المراقب أو من يمثله ومدققو حسابات الشركات الراغبة بالاندماج وممثل عن كل شركة وعدد مناسب من الخبراء والمختصين وتتولى اللجنة تقدير جميع موجودات الشركات الراغبة بالاندماج ومطلوباتها لبيان صافي حقوق المساهمين أو الشركاء حسب مقتضى الحال في التاريخ المحدد للدمج وعلى اللجنة تقديم تقريرها للوزير مع الميزانية الافتتاحية للشركة الناتجة عن الاندماج خلال مدة لا تزيد على تسعين يوماً من تاريخ إحالة الأمر إليها ، وللوزير تمديد هذه المدة لمدة مماثلة إذا اقتضت الضرورة ذلك وتحدد أتعاب وأجور اللجنة بقرار من الوزير وتتحملها الشركات الراغبة في الاندماج بالتساوي .","title":"لجنة تقدير موجودات الشركات المندمجة","memo":"⭐ يشكلها الوزير عند موافقته: المراقب أو من يمثله، مدققو حسابات الشركات، ممثل عن كل شركة، خبراء ومختصون\n⭐ تقدم تقريرها والميزانية الافتتاحية خلال مدة لا تزيد على تسعين يوماً قابلة للتمديد لمدة مماثلة\n⭐ أتعابها بقرار من الوزير وتتحملها الشركات بالتساوي","qs":[{"q":"تقدم لجنة التقدير تقريرها للوزير مع الميزانية الافتتاحية للشركة الناتجة عن الاندماج خلال مدة لا تزيد على:","o":["تسعين يوماً من تاريخ إحالة الأمر إليها","ستين يوماً من تاريخ إحالة الأمر إليها","ثلاثين يوماً من تاريخ إحالة الأمر إليها","مئة وعشرين يوماً من تاريخ إحالة الأمر إليها"],"a":0},{"q":"تتحمل الشركات الراغبة في الاندماج أتعاب وأجور لجنة التقدير:","o":["بالتساوي","بنسبة رؤوس أموالها","بنسبة صافي موجوداتها","الشركة الدامجة وحدها"],"a":0},{"q":"يتولى تشكيل لجنة التقدير في الاندماج:","o":["الوزير","المراقب","الهيئة العامة غير العادية","المحكمة"],"a":0},{"q":"جميع ما يلي يشترك في عضوية لجنة التقدير باستثناء:","o":["ممثل عن دائني الشركات","المراقب أو من يمثله","مدققو حسابات الشركات الراغبة بالاندماج","ممثل عن كل شركة"],"a":0}]},{"n":"229","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"على الشركات التي قررت الاندماج اعداد حسابات مستقلة عن اعمالها باشراف مدققي حساباتها من تاريخ صدور قرار الهيئة العامة للشركة بالموافقة على الاندماج وحتى تاريخ صدور قرار الهيئة العامة للشركة بالموافقة على الاندماج النهائي وتعرض نتائج اعمال هذه الشركات للفترة المذكورة على الهيئة العامة المشار اليها في المادة (٢٣٢) من هذا القانون او الشركاء فيها حسب مقتضى الحال وذلك بتقرير مصدق من مدققي حساباتها لاقرارها .","title":"الحسابات المستقلة خلال فترة الاندماج","memo":"⭐ تعد الشركات حسابات مستقلة بإشراف مدققيها من تاريخ قرار الهيئة العامة بالموافقة على الاندماج حتى قرار الموافقة على الاندماج النهائي\n⭐ تعرض النتائج على الهيئة العامة أو الشركاء بتقرير مصدق من المدققين لإقرارها","qs":[{"q":"تعد الشركات التي قررت الاندماج حسابات مستقلة عن أعمالها بإشراف:","o":["مدققي حساباتها","المراقب","لجنة التقدير","الوزير"],"a":0},{"q":"تبدأ فترة الحسابات المستقلة للشركات التي قررت الاندماج من تاريخ:","o":["صدور قرار الهيئة العامة بالموافقة على الاندماج","موافقة الوزير على الاندماج","تسجيل الشركة الدامجة","تقديم طلب الاندماج للمراقب"],"a":0}]},{"n":"230","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"يشكل الوزير لجنة تنفيذية من رؤساء وأعضاء مجالس ادارات الشركات الراغبة بالاندماج أو مديريها حسب مقتضى الحال ومدققي حسابات الشركات للقيام بالاجراءات التنفيذية للاندماج و بخاصة ما يلي :-\nأ - تحديد أسهم المساهمين أو حصص الشركاء في الشركات الداخلة في الاندماج من خلال تقديرات ( لجنة التقدير ) المنصوص عليها في المادة ( ٢٢٨ ) من هذا القانون .\nب - تعديل عقد التأسيس والنظام الأساسي للشركة الدامجة إذا كانت قائمة أو إعداد عقد التأسيس والنظام الأساسي للشركة الجديدة الناتجة عن الاندماج .\nج - دعوة الهيئة العامة غير العادية للمساهمين لكل شركة من الشركات الداخلة في الاندماج لاقرار ما يلي على أن يتم اقرارها بأغلبية ( ٧٥ % ) من الأسهم الممثلة في الاجتماع لكل شركة على حدة :\n١ - عقد تأسيس الشركة الجديدة ونظامها الأساسي أو العقد والنظام المعدلين للشركة الدامجة .\n٢ - نتائج إعادة تقدير موجودات الشركات ومطلوباتها والميزانية الافتتاحية للشركة الجديدة الناتجة عن الاندماج .\n٣ - الموافقة النهائية على الاندماج .\nد - تزود اللجنة التنفيذية المشار إليها في هذه المادة المراقب بمحضر اجتماع الهيئة العامة لكل شركة وذلك خلال سبعة أيام من تاريخ انعقاده .","title":"اللجنة التنفيذية للاندماج","memo":"⭐ يشكلها الوزير من رؤساء وأعضاء مجالس الإدارات أو المديرين ومدققي الحسابات\n⭐ تحدد الأسهم والحصص وفق تقديرات لجنة التقدير وتعدل/تعد عقد التأسيس والنظام\n⭐ تدعو الهيئة العامة غير العادية لكل شركة لإقرار العقد والنظام ونتائج التقدير والموافقة النهائية بأغلبية (٧٥%) من الأسهم الممثلة لكل شركة على حدة\n⭐ تزود المراقب بمحضر الاجتماع خلال سبعة أيام","qs":[{"q":"تقر الهيئة العامة غير العادية لكل شركة داخلة في الاندماج الموافقة النهائية على الاندماج بأغلبية:","o":["(٧٥%) من الأسهم الممثلة في الاجتماع لكل شركة على حدة","(٧٥%) من مجموع أسهم الشركات مجتمعة","ثلثي الأسهم الممثلة في الاجتماع","الأغلبية المطلقة للأسهم الممثلة في الاجتماع"],"a":0},{"q":"تزود اللجنة التنفيذية المراقب بمحضر اجتماع الهيئة العامة لكل شركة خلال:","o":["سبعة أيام من تاريخ انعقاده","عشرة أيام من تاريخ انعقاده","ثلاثين يوماً من تاريخ انعقاده","خمسة عشر يوماً من تاريخ انعقاده"],"a":0},{"q":"يشكل الوزير اللجنة التنفيذية للاندماج من:","o":["رؤساء وأعضاء مجالس الإدارات أو المديرين ومدققي حسابات الشركات","الخبراء والمختصين فقط","موظفي دائرة مراقبة الشركات","ممثلي الدائنين والمساهمين"],"a":0}]},{"n":"231","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تتبع اجراءات الموافقة والتسجيل والنشر المقررة بمقتضى هذا القانون لتسجل الشركة الدامجة أو الناتجة عن الاندماج وشطب تسجيل الشركات المندمجة .\nب - يعلن المراقب في الجريدة الرسمية وفي صحيفتين يوميتين محليتين لمرتين متتاليتين موجزاً عن عقد اندماج ونتائج إعادة التقدير والميزانية الافتتاحية للشركة الدامجة أو الناتجة عن الاندماج وعلى نفقة الشركة .","title":"تسجيل الدامجة وشطب المندمجة والإعلان","memo":"⭐ تتبع إجراءات الموافقة والتسجيل والنشر لتسجيل الدامجة أو الناتجة وشطب المندمجة\n⭐ يعلن المراقب في الجريدة الرسمية وفي صحيفتين يوميتين محليتين لمرتين متتاليتين موجزاً عن عقد الاندماج ونتائج التقدير والميزانية الافتتاحية على نفقة الشركة","qs":[{"q":"يعلن المراقب موجزاً عن عقد الاندماج ونتائج إعادة التقدير والميزانية الافتتاحية في:","o":["الجريدة الرسمية وفي صحيفتين يوميتين محليتين لمرتين متتاليتين","الجريدة الرسمية فقط","صحيفة يومية واحدة لمرة واحدة","الموقع الإلكتروني للوزارة فقط"],"a":0},{"q":"تكون نفقات إعلان المراقب عن الاندماج على حساب:","o":["الشركة","دائرة مراقبة الشركات","الوزارة","مساهمي الشركة المندمجة"],"a":0}]},{"n":"232","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"تستمر مجالس إدارة الشركات التي قررت الاندماج قائمة إلى أن يتم تسجيل الشركة الدامجة أو الناتجة عن الاندماج واقرار الحسابات المستقلة وعندها تقوم اللجنة التنفيذية المشار إليها في المادة ( ٢٣٠ ) بتولي إدارة الشركة لمدة لا تزيد على ثلاثين يوماً تدعو خلالها الهيئة العامة للشركة الدامجة أو الناتجة عن الاندماج لانتخاب مجلس إدارة جديد بعد توزيع الأسهم الناتجة عن الاندماج وتنتخب مدققي حسابات الشركة .","title":"استمرار مجالس الإدارة حتى التسجيل","memo":"⭐ تستمر مجالس إدارة الشركات المندمجة حتى تسجيل الدامجة أو الناتجة وإقرار الحسابات المستقلة\n⭐ ثم تتولى اللجنة التنفيذية الإدارة مدة لا تزيد على ثلاثين يوماً تدعو خلالها الهيئة العامة لانتخاب مجلس إدارة جديد ومدققي الحسابات","qs":[{"q":"تتولى اللجنة التنفيذية إدارة الشركة الدامجة أو الناتجة عن الاندماج لمدة لا تزيد على:","o":["ثلاثين يوماً","تسعين يوماً","ستين يوماً","سبعة أيام"],"a":0},{"q":"تستمر مجالس إدارة الشركات التي قررت الاندماج قائمة إلى أن:","o":["يتم تسجيل الشركة الدامجة أو الناتجة وإقرار الحسابات المستقلة","يوافق الوزير على طلب الاندماج","تقدم لجنة التقدير تقريرها","يصدر قرار الهيئة العامة بالموافقة على الاندماج"],"a":0},{"q":"خلال فترة إدارة اللجنة التنفيذية، تدعو الهيئة العامة للشركة الدامجة أو الناتجة من أجل:","o":["انتخاب مجلس إدارة جديد وانتخاب مدققي الحسابات","إعادة تقدير الموجودات","تصفية الشركة المندمجة","الموافقة المبدئية على الاندماج"],"a":0}]},{"n":"233","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يصدر الوزير التعليمات الخاصة باجراءات الاندماج وتسوية الاعتراضات المقدمة عليه .","title":"تعليمات إجراءات الاندماج","memo":"⭐ يصدر الوزير التعليمات الخاصة بإجراءات الاندماج وتسوية الاعتراضات المقدمة عليه","qs":[{"q":"الجهة التي تصدر التعليمات الخاصة بإجراءات الاندماج وتسوية الاعتراضات عليه:","o":["الوزير","المراقب","مجلس الوزراء","هيئة الأوراق المالية"],"a":0}]},{"n":"234","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - يجوز لحملة أسناد القرض ودائني الشركات المندمجة أو الدامجة ولكل ذي مصلحة من المساهمين أو الشركاء الاعتراض إلى الوزير خلال ثلاثين يوما من تاريخ الإعلان في الصحف المحلية بمقتضى أحكام المادة ( ٢٣١ ) على أن يبين المعترض موضوع اعتراضه والأسباب التي يستند إليها والأضرار التي يدعي أن الاندماج ألحقها به على وجه التحديد .\nب - يحيل الوزير الاعتراضات إلى المراقب للبت فيها وإذا لم يتمكن من تسويتها لأي سبب من الأسباب خلال ثلاثين يوما من إحالتها إليه يحق للمعترض اللجوء إلى المحكمة ، ولا توقف هذه الاعتراضات أو الدعوى التي تقام لدى المحكمة قرار الاندماج .","title":"الاعتراض على الاندماج","memo":"⭐ لحملة أسناد القرض والدائنين وكل ذي مصلحة من المساهمين أو الشركاء الاعتراض إلى الوزير خلال ثلاثين يوماً من تاريخ الإعلان في الصحف\n⭐ يحيلها الوزير للمراقب، وإن لم تسوّ خلال ثلاثين يوماً من إحالتها فللمعترض اللجوء إلى المحكمة\n⭐ الاعتراضات والدعوى لا توقف قرار الاندماج","qs":[{"q":"يقدم الاعتراض على الاندماج إلى الوزير خلال:","o":["ثلاثين يوماً من تاريخ الإعلان في الصحف المحلية","ستين يوماً من تاريخ الإعلان في الصحف المحلية","خمسة عشر يوماً من تاريخ قرار الهيئة العامة","عشرة أيام من تاريخ موافقة الوزير"],"a":0},{"q":"يحيل الوزير الاعتراضات على الاندماج للبت فيها إلى:","o":["المراقب","لجنة التقدير","اللجنة التنفيذية","المحكمة مباشرة"],"a":0},{"q":"حالة عملية: لم يتمكن المراقب من تسوية اعتراض أحد الدائنين على الاندماج خلال ثلاثين يوماً من إحالته إليه وأقام الدائن دعوى لدى المحكمة، فإن قرار الاندماج:","o":["لا يتوقف بالاعتراض أو الدعوى","يتوقف حتى صدور حكم قطعي","يلغى حكماً","يتوقف لمدة ستين يوماً"],"a":0}]},{"n":"235","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"إذا لم يراع في الاندماج أي حكم من أحكام هذا القانون أو جاء مخالفاً للنظام العام فلكل ذي مصلحة رفع الدعوى لدى المحكمة للطعن في الاندماج والمطالبة ببطلانه وذلك خلال ستين يوماً من تاريخ الإعلان عن الاندماج النهائي على أن يبين المدعي الأسباب التي يستند إليها في دعواه وبخاصة مايلي :-\nأ - إذا تبين أن هناك عيوباً تبطل عقد الاندماج أو كان هناك نقص جوهري واضح في تقدير حقوق المساهمين .\nب - إذا كان الاندماج ينطوي على التعسف في استعمال الحق أو أن هدفه كان تحقيق مصلحة شخصية مباشرة لمجلس إدارة أي من الشركات الداخلة في الاندماج أو لأغلبية الشركاء في أي منها على حساب حقوق الأقلية .\nج - إذا قام الاندماج على التضليل والاحتيال أو ترتب على الاندماج أضرار بالدائنين .\nد - إذا أدى الاندماج إلى احتكار أو سبقه احتكار وتبين أنه يلحق أضراراً بالمصلحة الاقتصادية العامة .","title":"الطعن ببطلان الاندماج","memo":"⭐ لكل ذي مصلحة رفع دعوى البطلان لدى المحكمة خلال ستين يوماً من تاريخ الإعلان عن الاندماج النهائي\n⭐ أسباب: عيوب تبطل العقد أو نقص جوهري في تقدير الحقوق، التعسف أو المصلحة الشخصية للمجلس أو الأغلبية على حساب الأقلية، التضليل والاحتيال أو الإضرار بالدائنين، الاحتكار المضر بالمصلحة الاقتصادية العامة","qs":[{"q":"لكل ذي مصلحة رفع دعوى لدى المحكمة للطعن في الاندماج والمطالبة ببطلانه خلال:","o":["ستين يوماً من تاريخ الإعلان عن الاندماج النهائي","ثلاثين يوماً من تاريخ الإعلان عن الاندماج النهائي","تسعين يوماً من تاريخ قرار الهيئة العامة","سنة من تاريخ تسجيل الشركة الدامجة"],"a":0},{"q":"جميع ما يلي من أسباب الطعن ببطلان الاندماج باستثناء:","o":["انخفاض أسعار أسهم الشركة الدامجة بعد الاندماج","وجود نقص جوهري واضح في تقدير حقوق المساهمين","قيام الاندماج على التضليل والاحتيال","أداء الاندماج إلى احتكار يضر بالمصلحة الاقتصادية العامة"],"a":0},{"q":"حالة عملية: تبين أن هدف الاندماج تحقيق مصلحة شخصية مباشرة لمجلس إدارة إحدى الشركات على حساب حقوق الأقلية، فإن ذلك يعد:","o":["سبباً للطعن ببطلان الاندماج","سبباً لإعادة التقدير فقط","مخالفة إدارية لا تؤثر على الاندماج","سبباً لوقف التداول فقط"],"a":0}]},{"n":"236","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"لا يوقف الطعن ببطلان الاندماج استمرار العمل به إلى أن يصدر قرار قضائي قطعي بالبطلان ويجوز للمحكمة عند النظر في دعوى البطلان أن تحدد من تلقاء ذاتها مهلة لاتخاذ اجراءات معينة لتصحيح الأسباب التي أدت إلى الطعن بالبطلان ، ولها رد الدعوى بطلب البطلان إذا قامت الجهة المعنية بتصحيح الأوضاع قبل النطق بالحكم .","title":"أثر الطعن ببطلان الاندماج","memo":"⭐ الطعن بالبطلان لا يوقف استمرار العمل بالاندماج حتى صدور قرار قضائي قطعي بالبطلان\n⭐ للمحكمة من تلقاء ذاتها تحديد مهلة لتصحيح الأسباب\n⭐ لها رد الدعوى إذا صححت الجهة المعنية الأوضاع قبل النطق بالحكم","qs":[{"q":"الطعن ببطلان الاندماج:","o":["لا يوقف استمرار العمل به إلى أن يصدر قرار قضائي قطعي بالبطلان","يوقف العمل به فور تسجيل الدعوى","يوقف العمل به لمدة ستين يوماً","يوقف العمل به إذا طلب ذلك الوزير"],"a":0},{"q":"للمحكمة رد دعوى بطلان الاندماج إذا:","o":["قامت الجهة المعنية بتصحيح الأوضاع قبل النطق بالحكم","وافق الوزير على الاندماج","مضى ثلاثون يوماً على رفع الدعوى","اعترض المراقب على الدعوى"],"a":0},{"q":"يجوز للمحكمة عند النظر في دعوى بطلان الاندماج أن تحدد مهلة لتصحيح الأسباب:","o":["من تلقاء ذاتها","بناء على طلب الوزير فقط","بناء على طلب المدعي فقط","بعد موافقة المراقب"],"a":0}]},{"n":"237","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"رئيس وأعضاء مجلس الإدارة والمدير العام ومدققو الحسابات لكل من الشركات المندمجة أو الدامجة مسؤولون بصفة شخصية تجاه الغير عن أي مطالبات أو التزامات أو ادعاءات يدعي بها على الشركة ولم تكن مسجلة أو لم يتم الاعلان عنها قبل تاريخ الدمج النهائي وللمحكمة اعفاء أولئك الأشخاص من هذه المسؤولية إذا ثبت لها أنهم لم يكونوا مسؤولين عن تلك الالتزامات والمطالبات أو لم يكونوا يعلمون بها .","title":"المسؤولية الشخصية عن الالتزامات غير المعلنة","memo":"⭐ رئيس وأعضاء مجلس الإدارة والمدير العام ومدققو الحسابات للشركات المندمجة أو الدامجة مسؤولون شخصياً تجاه الغير عن المطالبات غير المسجلة أو غير المعلنة قبل الدمج النهائي\n⭐ للمحكمة إعفاؤهم إذا ثبت أنهم لم يكونوا مسؤولين عنها أو لم يكونوا يعلمون بها","qs":[{"q":"يسأل بصفة شخصية تجاه الغير عن الالتزامات غير المسجلة أو غير المعلنة قبل تاريخ الدمج النهائي جميع ما يلي باستثناء:","o":["المساهمون","رئيس وأعضاء مجلس الإدارة","المدير العام","مدققو الحسابات"],"a":0},{"q":"الجهة التي لها إعفاء رئيس وأعضاء مجلس الإدارة والمدير العام والمدققين من المسؤولية عن الالتزامات غير المعلنة قبل الدمج:","o":["المحكمة","الوزير","المراقب","الهيئة العامة"],"a":0},{"q":"يشترط لإعفاء المذكورين في المادة من المسؤولية عن الالتزامات غير المعلنة أن يثبت:","o":["أنهم لم يكونوا مسؤولين عنها أو لم يكونوا يعلمون بها","مضي سنة على الدمج النهائي","موافقة الدائنين","تسديد نصف قيمة الالتزامات"],"a":0}]},{"n":"238","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج حكما بعد انتهاء اجراءات الدمج وتسجيل الشركة وفقاً لأحكام هذا القانون ، وتعتبر الشركة الدامجة أو الناتجة عن الاندماج خلفاً قانونياً للشركات المندمجة وتحل محلها في جميع حقوقها والتزاماتها .","title":"الدامجة خلف قانوني للمندمجة","memo":"⭐ تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الدامجة أو الناتجة حكماً بعد انتهاء إجراءات الدمج وتسجيل الشركة\n⭐ تعتبر الدامجة أو الناتجة خلفاً قانونياً للمندمجة","qs":[{"q":"تعتبر الشركة الدامجة أو الناتجة عن الاندماج بالنسبة للشركات المندمجة:","o":["خلفاً قانونياً تحل محلها في جميع حقوقها والتزاماتها","كفيلاً متضامناً عن ديونها فقط","شخصاً من الغير لا يسأل عن التزاماتها","مسؤولة عن حقوقها دون التزاماتها"],"a":0},{"q":"تنتقل حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة:","o":["حكماً بعد انتهاء إجراءات الدمج وتسجيل الشركة","فور صدور قرار الهيئة العامة بالموافقة على الاندماج","بعد موافقة كل دائن على حدة","فور تقديم طلب الاندماج"],"a":0}]},{"n":"239","chapter":"الباب الحادي عشر - تحول الشركات واندماجها وتملكها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"إذا ظهرت التزامات أو ادعاءات على احدى الشركات المندمجة بعد الدمج النهائي وكانت قد أخفيت من بعض المسؤولين أو العاملين في الشركة فتدفع لأصحابها من قبل الشركة الدامجة أو الناتجة عن الدمج ، ولها حق الرجوع بما دفعته على أولئك المسؤولين او العاملين وتحت طائلة العقوبات المقررة لذلك العمل بموجب القوانين المعمول بها .","title":"رجوع الدامجة بالالتزامات المخفاة","memo":"⭐ الالتزامات المخفاة من بعض المسؤولين أو العاملين والظاهرة بعد الدمج النهائي تدفعها الشركة الدامجة أو الناتجة لأصحابها\n⭐ للدامجة حق الرجوع بما دفعته على أولئك المسؤولين أو العاملين مع العقوبات المقررة","qs":[{"q":"حالة عملية: ظهرت بعد الدمج النهائي التزامات على إحدى الشركات المندمجة أخفاها بعض العاملين فيها، فإن هذه الالتزامات:","o":["تدفعها الشركة الدامجة لأصحابها ولها حق الرجوع على من أخفاها","تسقط لعدم الإعلان عنها","يتحملها مساهمو الشركة المندمجة","تدفعها دائرة مراقبة الشركات"],"a":0},{"q":"يحق للشركة الدامجة الرجوع بما دفعته من التزامات مخفاة على:","o":["المسؤولين أو العاملين الذين أخفوها","مساهمي الشركة الدامجة","دائني الشركة المندمجة","لجنة التقدير"],"a":0}]},{"n":"240","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ- لغايات هذا القانون يقصد بالشركة الأجنبية العاملة ، الشركة أو الهيئة المسجلة خارج المملكة ويقع مركزها الرئيسي في دولة أخرى جنسيتها غير أردنية ، وتقسم من حيث طبيعة عملها إلى نوعين :-\n١- شركات تعمل لمدة محدودة ، وهي الشركات التي تحال عليها عطاءات لتنفيذ أعمالها في المملكة لمدة محدودة ينتهي تسجيلها بانتهاء تلك الأعمال ما لم تحصل على عقود جديدة ، وعندها يمتد تسجيلها لتنفيذ تلك الأعمال ، ويتم شطب تسجيلها بعد تنفيذ كامل أعمالها في المملكة وتصفية حقوقها والتزاماتها .\n٢- شركات تعمل بصفة دائمة في المملكة بترخيص من الجهات الرسمية المختصة .\nب - لا يجوز لأي شركة أو هيئة أجنبية أن تمارس أي عمل تجاري في المملكة ما لم تكن مسجلة بمقتضى أحكام هذا القانون بعد الحصول على تصريح بالعمل بمقتضى القوانين والأنظمة المعمول بها .","title":"تعريف الشركة الأجنبية العاملة","memo":"⭐ الشركة الأجنبية العاملة: مسجلة خارج المملكة ومركزها الرئيسي في دولة أخرى جنسيتها غير أردنية\n⭐ نوعان: تعمل لمدة محدودة (عطاءات، ينتهي تسجيلها بانتهاء الأعمال ما لم تحصل على عقود جديدة) أو تعمل بصفة دائمة بترخيص\n⭐ لا يجوز لأي شركة أجنبية ممارسة عمل تجاري في المملكة ما لم تسجل بعد الحصول على تصريح بالعمل","qs":[{"q":"تقسم الشركة الأجنبية العاملة من حيث طبيعة عملها إلى:","o":["شركات تعمل لمدة محدودة وشركات تعمل بصفة دائمة","شركات عاملة وشركات غير عاملة","شركات قابضة وشركات تابعة","شركات معفاة وشركات غير معفاة"],"a":0},{"q":"ينتهي تسجيل الشركة الأجنبية التي تعمل لمدة محدودة:","o":["بانتهاء الأعمال المحالة عليها ما لم تحصل على عقود جديدة","بمضي سنة على تسجيلها","بقرار من الوزير في جميع الأحوال","بمضي خمس سنوات على تسجيلها"],"a":0},{"q":"حالة عملية: شركة أجنبية ترغب بممارسة عمل تجاري في المملكة، فإنه يشترط لذلك:","o":["تسجيلها بمقتضى قانون الشركات بعد الحصول على تصريح بالعمل","تأسيس شركة أردنية تابعة لها فقط","الحصول على موافقة الهيئة العامة لمساهميها فقط","تعيين وكيل تجاري دون تسجيل"],"a":0}]},{"n":"241","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يقدم طلب تسجيل الشركة أو الهيئة الأجنبية إلى المراقب مرفقا بالبيانات والوثائق التالية مترجمة إلى اللغة العربية على أن تكون ترجمتها مصدقة لدى الكاتب العدل في المملكة :\n١ - نسخة من عقد تأسيسها ونظامها الأساسي أو أي مستند آخر تألفت بموجبه وبيان كيفية تأسيسها .\n٢ - الوثائق الخطية الرسمية التي تثبت حصولها على موافقة الجهات المختصة في المملكة لممارسة العمل واستثمار رؤوس الأموال الأجنبية فيها بمقتضى التشريعات المعمول بها .\n٣ - قائمة بأسماء أعضاء مجلس إدارة الشركة أو هيئة المديرين أو الشركاء حسب مقتضى الحال ، وجنسية كل منهم ، وأسماء الأشخاص المفوضين بالتوقيع عن الشركة .\n٤ - نسخة عن الوكالة التي تفوض الشركة الأجنبية بموجبها شخصا مقيما في المملكة لتولي اعمالها والتبلغ نيابة عنها .\n٥ - البيانات المالية لآخر سنة مالية للشركة في مركزها الرئيسي مصدقة من مدقق حسابات قانوني .\n٦ - أية بيانات أو معلومات أخرى يرى المراقب ضرورة تقديمها .\nب - يوقع طلب التسجيل أمام المراقب أو من يفوضه خطياً أو أمام الكاتب العدل أو أحـد المحامين المزاولين من قبل الشخص المفوض بتسجيل الشركة ويجب أن يتضمن الطلب المعلومات الرئيسية عن الشركة وبخاصة ما يلي :-\n١ - اسم الشركة ونوعها ورأسمالها .\n٢ - غايات الشركة التي ستقوم بها في المملكة .\n٣ - بيانات تفصيلية عن المؤسسين أو الشركاء أو مجلس الإدارة وحصة كل منهم .\n٤ - أية بيانات أو معلومات يرى المراقب تقديمها .","title":"وثائق تسجيل الشركة الأجنبية","memo":"⭐ يقدم الطلب للمراقب مع وثائق مترجمة للعربية ومصدقة لدى الكاتب العدل في المملكة\n⭐ منها: عقد التأسيس والنظام، موافقات الجهات المختصة، أسماء أعضاء المجلس والمفوضين، الوكالة لشخص مقيم في المملكة، البيانات المالية لآخر سنة مصدقة\n⭐ يوقع الطلب أمام المراقب أو من يفوضه خطياً أو الكاتب العدل أو أحد المحامين المزاولين","qs":[{"q":"يشترط في الوثائق المرفقة بطلب تسجيل الشركة الأجنبية أن تكون مترجمة إلى العربية وترجمتها مصدقة لدى:","o":["الكاتب العدل في المملكة","سفارة دولة الشركة","وزارة الخارجية في بلد الشركة","المراقب"],"a":0},{"q":"يرفق بطلب تسجيل الشركة الأجنبية البيانات المالية لمركزها الرئيسي عن:","o":["آخر سنة مالية مصدقة من مدقق حسابات قانوني","آخر سنتين ماليتين","آخر ثلاث سنوات مالية","آخر خمس سنوات مالية"],"a":0},{"q":"يرفق بطلب تسجيل الشركة الأجنبية نسخة عن الوكالة التي تفوض بموجبها:","o":["شخصاً مقيماً في المملكة لتولي أعمالها والتبلغ نيابة عنها","محامياً أجنبياً لتمثيلها","مدقق حسابات أردنياً","البنك المركزي"],"a":0},{"q":"يجوز توقيع طلب تسجيل الشركة الأجنبية أمام أي مما يلي باستثناء:","o":["سفير دولة الشركة","المراقب أو من يفوضه خطياً","الكاتب العدل","أحد المحامين المزاولين"],"a":0}]},{"n":"242","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - للمراقب الموافقة على تسجيل الشركة أو الهيئة الأجنبية أو رفض التسجيل وفي حالة الموافقة تستكمل الاجراءات القانونية لتسجيل الشركة أو الهيئة في سجل الشركات الأجنبية والاعلان على تسجيلها في الجريدة الرسمية بعد استيفاء الرسوم القانونية .\nب - تتبع الاجراءات المنصوص عليها في الفقرة ( أ ) من هذه المادة عند اجراء أي تغيير يطرأ على بيانات الشركة المقدمة عند تسجيلها ، وعليها تقديم هذه التغييرات خلال ثلاثين يوماً من تاريخ وقوعها .\nج - على فرع الشركة الاجنبية العامل في المملكة ان يعلن في وثائقه الرسمية ومراسلاته عن اسم الشركة الاجنبية الام وجنسيتها وشكلها القانوني وعنوانها وراسمالها في بلدها وفي المملكة وكذلك عن رقم تسجيل فرعه لدى المراقب .","title":"قرار تسجيل الشركة الأجنبية والتغييرات","memo":"⭐ للمراقب الموافقة على تسجيل الشركة الأجنبية أو رفضه، ويعلن التسجيل في الجريدة الرسمية بعد استيفاء الرسوم\n⭐ تقدم التغييرات على بياناتها خلال ثلاثين يوماً من وقوعها\n⭐ يعلن الفرع في وثائقه اسم الشركة الأم وجنسيتها وشكلها وعنوانها ورأسمالها ورقم تسجيل الفرع","qs":[{"q":"الجهة المختصة بالموافقة على تسجيل الشركة الأجنبية أو رفضه:","o":["المراقب","الوزير","مجلس الوزراء","هيئة الاستثمار"],"a":0},{"q":"على الشركة الأجنبية تقديم أي تغيير يطرأ على بياناتها المقدمة عند التسجيل خلال:","o":["ثلاثين يوماً من تاريخ وقوعه","عشرة أيام من تاريخ وقوعه","ستين يوماً من تاريخ وقوعه","ثلاثة أشهر من تاريخ وقوعه"],"a":0},{"q":"على فرع الشركة الأجنبية أن يعلن في وثائقه ومراسلاته جميع ما يلي باستثناء:","o":["أسماء مساهمي الشركة الأم","اسم الشركة الأم وجنسيتها","الشكل القانوني للشركة الأم وعنوانها","رقم تسجيل الفرع لدى المراقب"],"a":0}]},{"n":"243","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - على الشركة أو الهيئة الأجنبية المسجلة وفقا لأحكام هذا القانون القيام بما يلي :-\n١ - أن تقدم إلى المراقب خلال ثلاثة أشهر من نهاية كل سنة مالية ميزانيتها وحساب الأرباح والخسائر عن أعمالها في المملكة مصدقة من مدقق حسابات قانوني أردني .\n٢ - أن تنشر الميزانية وحساب الأرباح والخسائر عن أعمالها في المملكة في صحيفتين يوميتين محليتين على الأقل وذلك خلال ستين يوماً من تاريخ تقديم هذه البيانات للمراقب .\n٣ - للوزير استثناء أي شركة من أحكام البندين ( ١ ) و ( ٢ ) بناء على تنسيب مراقب الشركات .\nب - للمراقب أو من ينتدبه الاطلاع على دفاتر الشركة ومستنداتها وعلى الشركة أن تضع تحت تصرفه تلك الدفاتر والمستندات .","title":"واجبات الشركة الأجنبية المسجلة","memo":"⭐ تقدم للمراقب خلال ثلاثة أشهر من نهاية السنة المالية ميزانيتها وحساب الأرباح والخسائر عن أعمالها في المملكة مصدقة من مدقق حسابات قانوني أردني\n⭐ تنشرها في صحيفتين يوميتين محليتين خلال ستين يوماً من تقديمها للمراقب\n⭐ للوزير استثناء أي شركة بتنسيب المراقب\n⭐ للمراقب أو من ينتدبه الاطلاع على دفاترها","qs":[{"q":"تقدم الشركة الأجنبية المسجلة إلى المراقب ميزانيتها وحساب الأرباح والخسائر عن أعمالها في المملكة خلال:","o":["ثلاثة أشهر من نهاية كل سنة مالية","شهر من نهاية كل سنة مالية","ستة أشهر من نهاية كل سنة مالية","ستين يوماً من نهاية كل سنة مالية"],"a":0},{"q":"يشترط في ميزانية الشركة الأجنبية عن أعمالها في المملكة أن تكون مصدقة من:","o":["مدقق حسابات قانوني أردني","مدقق حسابات الشركة الأم","المراقب","الكاتب العدل"],"a":0},{"q":"تنشر الشركة الأجنبية ميزانيتها وحساب الأرباح والخسائر في صحيفتين يوميتين محليتين على الأقل خلال:","o":["ستين يوماً من تاريخ تقديم هذه البيانات للمراقب","ثلاثين يوماً من تاريخ تقديمها للمراقب","ثلاثة أشهر من نهاية السنة المالية","تسعين يوماً من تاريخ تقديمها للمراقب"],"a":0},{"q":"صلاحية استثناء الشركة الأجنبية من تقديم ميزانيتها ونشرها تعود إلى:","o":["الوزير بناء على تنسيب المراقب","المراقب بناء على تنسيب الوزير","مجلس الوزراء","هيئة الأوراق المالية"],"a":0}]},{"n":"244","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - على الشركة أو الهيئة الأجنببة تبليغ المراقب خطياً عن التاريخ الذي تتوقع فيه انتهاء عملها في المملكة أو التاريخ المحدد لانتهائه وذلك قبل ثلاثين يوماً على الأقل من ذلك التاريخ ، وأن تثبت للمراقب تسوية جميع ما عليها من التزامات ترتبت على عملها في المملكة قبل الموافقة على شطب تسجيلها .\nب - تسري الأحكام العامة للتصفية المنصوص عليها في هذا القانون على فروع الشركات الأجنبية العاملة في المملكة التي يقع مركز ادارتها في الخارج .","title":"شطب تسجيل الشركة الأجنبية","memo":"⭐ تبلغ الشركة الأجنبية المراقب خطياً بتاريخ انتهاء عملها قبل ثلاثين يوماً على الأقل\n⭐ تثبت تسوية جميع التزاماتها في المملكة قبل الموافقة على الشطب\n⭐ تسري الأحكام العامة للتصفية على فروع الشركات الأجنبية التي يقع مركز إدارتها في الخارج","qs":[{"q":"على الشركة الأجنبية تبليغ المراقب خطياً عن التاريخ المتوقع لانتهاء عملها في المملكة قبل ذلك التاريخ بـ:","o":["ثلاثين يوماً على الأقل","خمسة عشر يوماً على الأقل","ستين يوماً على الأقل","تسعين يوماً على الأقل"],"a":0},{"q":"يشترط قبل الموافقة على شطب تسجيل الشركة الأجنبية أن تثبت للمراقب:","o":["تسوية جميع ما عليها من التزامات ترتبت على عملها في المملكة","تحويل أرباحها إلى الخارج","موافقة الوزير على الشطب","تعيين مصفٍ أردني"],"a":0},{"q":"تسري على فروع الشركات الأجنبية العاملة في المملكة التي يقع مركز إدارتها في الخارج:","o":["الأحكام العامة للتصفية المنصوص عليها في قانون الشركات","أحكام التصفية في قانون بلد الشركة الأم","أحكام الشركات المعفاة","أحكام الإعسار الخاصة بالبنوك"],"a":0}]},{"n":"245","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - لغايات هذا القانون يقصد بالشركة الأجنبية غير العاملة في المملكة الشركة أو الهيئة التي تتخذ من المملكة مقراً أو مكتب تمثيل لأعمالها التي تقوم بها خارج المملكة وذلك بقصد استخدام مقرهاً أو مكتبها لتوجيه أعمالها تلك وتنسيقها مع مركزها الرئيسي .\nب - يحظر على الشركة الأجنبية غير العاملة أن تزاول أي عمل أو نشاط تجاري داخل المملكة بما في ذلك أعمال الوكلاء والوسطاء وذلك تحت طائلة شطب تسجيلها وتحميلها مسؤولية التعويض عن أي خسارة أو ضرر ألحقته بالغير .\nج - يجوز تسجيل الشركة الأجنبية غير العاملة في المملكة وفقاً لأحكام هذا القانون لانشاء مقر لها أو مكاتب تمثيل أو ايصال خدمات أو مكاتب فنية أو علمية ، وتعتبر مدينة عمان موطناً لها لغايات التقاضي .","title":"الشركة الأجنبية غير العاملة","memo":"⭐ الشركة الأجنبية غير العاملة: تتخذ من المملكة مقراً أو مكتب تمثيل لأعمالها خارج المملكة لتوجيهها وتنسيقها\n⭐ يحظر عليها مزاولة أي عمل تجاري داخل المملكة بما فيه أعمال الوكلاء والوسطاء تحت طائلة شطب تسجيلها والتعويض\n⭐ تعتبر مدينة عمان موطناً لها لغايات التقاضي","qs":[{"q":"تعتبر مدينة عمان موطناً للشركة الأجنبية غير العاملة لغايات:","o":["التقاضي","فرض الضرائب","تسجيل العلامات التجارية","انعقاد الهيئة العامة"],"a":0},{"q":"جزاء مزاولة الشركة الأجنبية غير العاملة عملاً تجارياً داخل المملكة:","o":["شطب تسجيلها وتحميلها مسؤولية التعويض عن أي ضرر ألحقته بالغير","غرامة مالية فقط","تحويلها حكماً إلى شركة عاملة","إنذارها لمرة واحدة"],"a":0},{"q":"حالة عملية: شركة أجنبية غير عاملة مسجلة في المملكة قامت بأعمال الوساطة التجارية داخل المملكة، فإن ذلك:","o":["محظور عليها تحت طائلة شطب تسجيلها","جائز إذا أبلغت المراقب","جائز بموافقة الوزير","جائز إذا كانت الأعمال لمدة محدودة"],"a":0}]},{"n":"246","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يقدم طلب تسجيل الشركة الأجنبية غير العاملة إلى المراقب مرفقاً بالوثائق والمستندات التالية مترجمة إلى اللغة العربية ومصدقة ترجمتها لدى الكاتب العدل في المملكة :\n١- شهادة تسجيل الشركة في مركزها الرئيسي .\n٢- عقد تأسيسها ونظامها اللذين يبينان غاياتها ورأسمالها ونوعها .\n٣- الوكالة التي تفوض بموجبها شخصا مقيما في المملكة للقيام بأعمالها وتسجيلها لأغراض هذا القانون .\n٤- البيانات المالية لآخر سنتين ماليتين للشركة في بلد مركزها الرئيسي مصدقة من مدقق حسابات قانوني وللوزير بناء على تنسيب مبرر من المراقب اعفاء الشركة من تقديم هذه البيانات.\nب - يوقع طلب التسجيل أمام المراقب أو من يفوضه خطيا او أمام الكاتب العدل أو أحـد المحامين المزاولين على ان يتضمن المعلومات الرئيسية عن الشركة وبخاصة ما يلي :-\n١- اسم الشركة الاجنبية ومركزها الرئيسي وتاريخ تسجيلها وغاياتها .\n٢- نوع الشركة وجنسيتها وعنوانها في بلد تسجيلها .\n٣- رأسمال الشركة وأسماء المؤسسين أو الشركاء وجنسية كل منهم وحصته ومعلومات عن مجلس ادارتها .\n٤- اي معلومات أخرى يرى المراقب ضرورة تقديمها .","title":"طلب تسجيل الشركة الأجنبية غير العاملة","memo":"⭐ يقدم الطلب إلى المراقب مع وثائق مترجمة إلى العربية ومصدقة ترجمتها لدى الكاتب العدل\n⭐ الوثائق: شهادة التسجيل، عقد التأسيس والنظام، الوكالة لشخص مقيم في المملكة، البيانات المالية لآخر سنتين ماليتين مصدقة من مدقق حسابات قانوني\n⭐ للوزير بناء على تنسيب مبرر من المراقب إعفاء الشركة من تقديم البيانات المالية\n⭐ يوقع الطلب أمام المراقب أو من يفوضه خطياً أو الكاتب العدل أو أحد المحامين المزاولين","qs":[{"q":"البيانات المالية المطلوب إرفاقها بطلب تسجيل الشركة الأجنبية غير العاملة هي بيانات:","o":["آخر سنتين ماليتين مصدقة من مدقق حسابات قانوني","آخر سنة مالية واحدة مصدقة من المراقب","آخر ثلاث سنوات مالية مصدقة من مدقق حسابات قانوني","آخر خمس سنوات مالية مصدقة من الكاتب العدل"],"a":0},{"q":"الجهة التي تملك إعفاء الشركة الأجنبية غير العاملة من تقديم البيانات المالية هي:","o":["الوزير بناء على تنسيب مبرر من المراقب","المراقب بقرار منفرد","مجلس الوزراء بناء على تنسيب الوزير","المحكمة المختصة بناء على طلب الشركة"],"a":0},{"q":"يجوز توقيع طلب تسجيل الشركة الأجنبية غير العاملة أمام أي مما يلي باستثناء:","o":["مدقق حسابات الشركة","المراقب أو من يفوضه خطياً","الكاتب العدل","أحد المحامين المزاولين"],"a":0}]},{"n":"247","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - للمراقب الموافقة على تسجيل الشركة أو الهيئة الأجنبية غير العاملة أو رفض التسجيل وفي حالة الموافقة تستكمل الإجراءات القانونية لتسجيل الشركة أو الهيئة في سجل الشركات الأجنبية غير العاملة والاعلان عن تسجيلها في الجريدة الرسمية على ان تقدم الى المراقب ما يثبت وجود مقر فعلي لها داخل المملكة .\nب - تتبع اجراءات الموافقة والتسجيل والنشر على أي تغييرات تطرأ على البيانات الرئيسية عن الشركة وعن ممثلها في المملكة ويجب تبليغ المراقب بهذه التغييرات خلال ثلاثين يوماً من وقوعها .","title":"الموافقة على تسجيل الشركة الأجنبية غير العاملة","memo":"⭐ للمراقب الموافقة على التسجيل أو رفضه، ويعلن عن التسجيل في الجريدة الرسمية\n⭐ شرط التسجيل: تقديم ما يثبت وجود مقر فعلي لها داخل المملكة\n⭐ يجب تبليغ المراقب بأي تغيير على البيانات الرئيسية خلال ثلاثين يوماً من وقوعه","qs":[{"q":"الجهة المختصة بالموافقة على تسجيل الشركة الأجنبية غير العاملة أو رفضه هي:","o":["المراقب","الوزير","مجلس الوزراء","المحكمة المختصة"],"a":0},{"q":"يجب تبليغ المراقب بالتغييرات التي تطرأ على البيانات الرئيسية للشركة الأجنبية غير العاملة خلال:","o":["ثلاثين يوماً من وقوعها","سبعة أيام من وقوعها","خمسة عشر يوماً من وقوعها","ستين يوماً من وقوعها"],"a":0},{"q":"يشترط لاستكمال تسجيل الشركة الأجنبية غير العاملة أن تقدم إلى المراقب ما يثبت:","o":["وجود مقر فعلي لها داخل المملكة","إيداع رأسمالها في بنك أردني","تعيين مدقق حسابات أردني","تسجيلها لدى غرفة التجارة"],"a":0}]},{"n":"248","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"تتمتع الشركة الأجنبية غير العاملة بما يلي :-\nأ - الاعفاء من رسوم التسجيل والنشر المقررة على الشركات الأجنبية العاملة .\nب - اعفاء الأرباح الواردة إليها عن أعمالها في الخارج من ضريبتي الدخل والخدمات الاجتماعية .\nج - الاعفاء من التسجيل لدى الغرف التجارية والصناعية والنقابات المهنية ومن رسوم التسجيل لديها ومن أي التزامات تجاهها بما في ذلك رخصة المهن التجارية .\nد - اعفاء الرواتب والأجور التي تدفعها الشركة الأجنبية غير العاملة لمستخدميها غير الأردنيين العاملين في مقرها في المملكة من ضريبتي الدخل والخدمات الاجتماعية .\nهـ - السماح لها بإدخال العينات والنماذج التجارية معفاة من الرسوم الجمركية ورسوم الاستيراد .\nو - اعفاء الأثاث والتجهيزات التي تستوردها الشركة واللازمة لتجهيز مكاتبها من الرسوم الجمركية والرسوم والعوائد الأخرى .\nز - السماح للشركة باستيراد سيارة واحدة تحت وضع الإدخال المؤقت كل خمس سنوات لاستعمال مستخدميها من غير الأردنيين .\nح - للوزير بناء على تنسيب المراقب في حالات مبررة السماح للشركة بإدخال سيارة أخرى تحت وضع الإدخال المؤقت .\nط - تحدد بنظام خاص الشروط التي تمنح بموجبها الاعفاءات المذكورة في هذه المادة .","title":"مزايا الشركة الأجنبية غير العاملة","memo":"⭐ إعفاء من رسوم التسجيل والنشر، ومن التسجيل لدى الغرف التجارية والصناعية والنقابات المهنية ورخصة المهن\n⭐ إعفاء أرباحها عن أعمالها في الخارج ورواتب مستخدميها غير الأردنيين في مقرها من ضريبتي الدخل والخدمات الاجتماعية\n⭐ إدخال العينات معفاة من الجمارك، وإعفاء الأثاث والتجهيزات اللازمة لمكاتبها\n⭐ سيارة واحدة إدخال مؤقت كل خمس سنوات لمستخدميها غير الأردنيين، وللوزير بتنسيب المراقب السماح بسيارة أخرى","qs":[{"q":"يسمح للشركة الأجنبية غير العاملة باستيراد سيارة واحدة تحت وضع الإدخال المؤقت لاستعمال مستخدميها غير الأردنيين كل:","o":["خمس سنوات","سنتين","ثلاث سنوات","عشر سنوات"],"a":0},{"q":"تتمتع الشركة الأجنبية غير العاملة بجميع المزايا التالية باستثناء:","o":["إعفاء رواتب مستخدميها الأردنيين من ضريبة الدخل","إعفاء أرباحها الواردة عن أعمالها في الخارج من ضريبتي الدخل والخدمات الاجتماعية","الإعفاء من التسجيل لدى الغرف التجارية والصناعية","إدخال العينات والنماذج التجارية معفاة من الرسوم الجمركية"],"a":0},{"q":"طلبت شركة أجنبية غير عاملة إدخال سيارة ثانية تحت وضع الإدخال المؤقت لحالة مبررة، فإن الجهة التي تملك السماح بذلك:","o":["الوزير بناء على تنسيب المراقب","المراقب بقرار منفرد","مدير عام الجمارك","مجلس الوزراء"],"a":0}]},{"n":"249","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لا يجوز أن يقل عدد المستخدمين الأردنيين في الشركة الأجنبية غير العاملة في المملكة عن نصف مجموع المستخدمين لديها .","title":"نسبة المستخدمين الأردنيين","memo":"⭐ لا يجوز أن يقل عدد المستخدمين الأردنيين في الشركة الأجنبية غير العاملة عن نصف مجموع المستخدمين لديها","qs":[{"q":"الحد الأدنى لعدد المستخدمين الأردنيين في الشركة الأجنبية غير العاملة في المملكة هو:","o":["نصف مجموع المستخدمين","ربع مجموع المستخدمين","ثلث مجموع المستخدمين","ثلاثة أرباع مجموع المستخدمين"],"a":0},{"q":"شركة أجنبية غير عاملة لديها (٤٠) مستخدماً، فإن أقل عدد من المستخدمين الأردنيين يجب أن يعمل لديها هو:","o":["٢٠ مستخدماً","١٠ مستخدمين","٣٠ مستخدماً","٤٠ مستخدماً"],"a":0}]},{"n":"250","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يسمح للشركة الأجنبية غير العاملة أن تفتح لها حسابا غير مقيم في البنوك التجارية المرخصة بالدينار الأردني أو بالعملات الأجنبية شريطة أن تكون هذه الأموال محولة إليها من الخارج عن طريق البنك .","title":"حساب غير مقيم للشركة غير العاملة","memo":"⭐ يسمح لها بفتح حساب غير مقيم في البنوك التجارية المرخصة بالدينار أو بالعملات الأجنبية\n⭐ شرط: أن تكون الأموال محولة إليها من الخارج عن طريق البنك","qs":[{"q":"يسمح للشركة الأجنبية غير العاملة أن تفتح حساباً غير مقيم في البنوك التجارية المرخصة بشرط أن تكون الأموال:","o":["محولة إليها من الخارج عن طريق البنك","ناتجة عن أعمالها داخل المملكة","مودعة نقداً من ممثلها في المملكة","بالدينار الأردني حصراً"],"a":0},{"q":"يجوز أن يكون الحساب غير المقيم للشركة الأجنبية غير العاملة:","o":["بالدينار الأردني أو بالعملات الأجنبية","بالعملات الأجنبية فقط","بالدينار الأردني فقط","بالدولار الأمريكي فقط"],"a":0}]},{"n":"251","chapter":"الباب الثاني عشر - الشركات الأجنبية","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"للوزير بناء على تنسيب المراقب شطب تسجيل الشركة الأجنبية غير العاملة في المملكة إذا تبين له إنها تمارس أي عمل تجاري في المملكة او لم يعد لها مقر فعلي فيها أو خالفت أحكام هذا القانون أو أية أنظمة أو تعليمات صادرة بموجبه .","title":"شطب تسجيل الشركة غير العاملة","memo":"⭐ للوزير بناء على تنسيب المراقب شطب التسجيل إذا: مارست أي عمل تجاري في المملكة، أو لم يعد لها مقر فعلي، أو خالفت القانون أو الأنظمة أو التعليمات","qs":[{"q":"الجهة التي تملك شطب تسجيل الشركة الأجنبية غير العاملة هي:","o":["الوزير بناء على تنسيب المراقب","المراقب بقرار منفرد","المحكمة المختصة","مجلس الوزراء بناء على تنسيب الوزير"],"a":0},{"q":"يجوز شطب تسجيل الشركة الأجنبية غير العاملة في أي من الحالات التالية باستثناء:","o":["تحقيقها أرباحاً من أعمالها في الخارج","ممارستها أي عمل تجاري في المملكة","عدم وجود مقر فعلي لها في المملكة","مخالفتها أحكام القانون أو الأنظمة الصادرة بموجبه"],"a":0}]},{"n":"252","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تصفى الشركة المساهمة العامة أما تصفية اختيارية من هيئتها العامة غير العادية أو تصفية اجبارية بقرار قطعي من المحكمة ولا تفسخ الشركة إلا بعد استكمال اجراءات تصفيتها بمقتضى أحكام هذا القانون .\nب- تحدد اجراءات التصفية وتنظيمها وتنفيذها وعمل المصفي بما في ذلك التقارير التي يتوجب عليه تقديمها بموجب نظام خاص يصدر لهذه الغاية .","title":"نوعا تصفية الشركة المساهمة العامة","memo":"⭐ التصفية إما اختيارية من الهيئة العامة غير العادية أو إجبارية بقرار قطعي من المحكمة\n⭐ لا تفسخ الشركة إلا بعد استكمال إجراءات تصفيتها\n⭐ تنظم إجراءات التصفية وعمل المصفي وتقاريره بموجب نظام خاص","qs":[{"q":"تقرر التصفية الاختيارية للشركة المساهمة العامة من قبل:","o":["الهيئة العامة غير العادية","الهيئة العامة العادية","مجلس الإدارة","المراقب"],"a":0},{"q":"تكون التصفية الإجبارية للشركة المساهمة العامة بموجب:","o":["قرار قطعي من المحكمة","قرار من الوزير","قرار من المراقب","قرار من مجلس الإدارة"],"a":0},{"q":"لا تفسخ الشركة المساهمة العامة إلا:","o":["بعد استكمال إجراءات تصفيتها","بعد صدور قرار التصفية مباشرة","بعد مرور سنة على قرار التصفية","بعد موافقة مجلس الوزراء"],"a":0}]},{"n":"253","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"إذا صدر قرار بتصفية الشركة المساهمة العامة وتعيين مصف لها ، يتولى المصفي الاشراف على أعمال الشركة المعتادة والمحافظة على أموالها وموجوداتها .","title":"مهمة المصفي عند صدور قرار التصفية","memo":"⭐ يتولى المصفي الإشراف على أعمال الشركة المعتادة والمحافظة على أموالها وموجوداتها","qs":[{"q":"إذا صدر قرار بتصفية الشركة المساهمة العامة وتعيين مصفٍ لها، فإن الإشراف على أعمال الشركة المعتادة والمحافظة على أموالها يتولاه:","o":["المصفي","مجلس الإدارة","المراقب","الهيئة العامة"],"a":0}]},{"n":"254","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - تتوقف الشركة التي تقرر تصفيتها عن ممارسة أعمالها من تاريخ صدور قرار الهيئة العامة في حالة التصفية الاختيارية ومن تاريخ صدور قرار المحكمة في حالة التصفية الاجبارية وتستمر الشخصية الاعتبارية للشركة ويمثلها المصفي لحين فسخها بعد الانتهاء من تصفيتها .\nب - على الجهة التي قررت تصفية الشركة تزويد المراقب والهيئة والسوق المالي والمركز بنسخة من قرارها خلال ثلاثة أيام من صدوره وعلى المراقب نشره في الجريدة الرسمية وفي صحيفتين يوميتين محليتين على الأقل خلال مدة لا تزيد على سبعة أيام من تاريخ تبلغه للقرار .\nج - على المصفي إضافة عبارة ( تحت التصفية ) إلى اسم الشركة في جميع أوراقها ومراسلاتها .","title":"آثار قرار التصفية وإعلانه","memo":"⭐ تتوقف الشركة عن أعمالها من تاريخ قرار الهيئة العامة (اختيارية) أو قرار المحكمة (إجبارية)، وتستمر شخصيتها الاعتبارية ويمثلها المصفي لحين فسخها\n⭐ تزود الجهة المقررة المراقب والهيئة والسوق المالي والمركز بنسخة من القرار خلال ثلاثة أيام\n⭐ ينشره المراقب في الجريدة الرسمية وصحيفتين يوميتين محليتين خلال مدة لا تزيد على سبعة أيام من تبلغه\n⭐ يضيف المصفي عبارة (تحت التصفية) إلى اسم الشركة في جميع أوراقها","qs":[{"q":"على الجهة التي قررت تصفية الشركة تزويد المراقب والهيئة والسوق المالي والمركز بنسخة من قرارها خلال:","o":["ثلاثة أيام من صدوره","سبعة أيام من صدوره","عشرة أيام من صدوره","ثلاثين يوماً من صدوره"],"a":0},{"q":"ينشر المراقب قرار التصفية في الجريدة الرسمية وفي صحيفتين يوميتين محليتين على الأقل خلال مدة لا تزيد على:","o":["سبعة أيام من تاريخ تبلغه للقرار","ثلاثة أيام من تاريخ تبلغه للقرار","أربعة عشر يوماً من تاريخ تبلغه للقرار","ثلاثين يوماً من تاريخ تبلغه للقرار"],"a":0},{"q":"في التصفية الاختيارية تتوقف الشركة عن ممارسة أعمالها من تاريخ:","o":["صدور قرار الهيئة العامة","تعيين المصفي","نشر القرار في الجريدة الرسمية","تبلغ المراقب للقرار"],"a":0},{"q":"أي العبارات التالية صحيحة بشأن الشركة التي تقرر تصفيتها؟","o":["تستمر شخصيتها الاعتبارية ويمثلها المصفي لحين فسخها","تنقضي شخصيتها الاعتبارية فور صدور قرار التصفية","يستمر مجلس إدارتها في تمثيلها لحين فسخها","يمثلها المراقب لحين انتهاء التصفية"],"a":0}]},{"n":"255","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يعتبر باطلا :-\n١ - كل تصرف بأموال الشركة المساهمة العامة الموجودة تحت التصفية وحقوقها وأي تداول بأسهمها ونقل ملكيتها .\n٢ - أي تغيير أو تعديل في التزامات رئيس وأعضاء مجلس إدارة الشركة الموجودة تحت التصفية أو في التزامات الغير تجاهها .\n٣ - أي حجز على أموال الشركة ، وموجوداتها وأي تصرف آخر أو تنفيذ يجري على تلك الأموال والموجودات بعد صدور القرار بتصفية الشركة .\n٤ - جميع عقود الرهن أو التأمين على أموال الشركة وموجوداتها ، والعقود أو الاجراءات الأخرى التي ترتب التزامات أو امتيازات على أموال الشركة وموجوداتها إذا تمت خلال الأشهر الثلاثة السابقة على قرار تصفية الشركة ، إلا إذا ثبت أن الشركة قادرة على الوفاء بجميع ديونها بعد انتهاء التصفية ، ولا يسري هذا البطلان إلا على المبلغ الذي يزيد على ما دفع للشركة بموجب تلك العقود وقت انشائها أو بعد ذلك مع الفوائد القانونية عليها .\n٥ - كل تحويل لأموال الشركة تحت التصفية وموجوداتها أو التنازل عنها أو اجراء أي تصرف بها بطريق التدليس لتفضيل بعض دائني الشركة على غيرهم .\nب - يفقد المحكوم له على الشركة حقه بما أوقعه من حجز على أموال الشركة وموجوداتها وفي أي اجراء آخر اتخذه بشأنها إلا إذا كان الحجز أو الاجراء قد تم قبل بدء اجراءات تصفية الشركة .\nج - إذا تبلغ مأمور الاجراء اشعاراً بصدور قرار تصفية الشركة المساهمة العامة قبل بيع أموالها وموجوداتها المحجوزة أو قبل اتمام معاملة التنفيذ عليها فيترتب عليه أن يسلم تلك الأموال والموجودات للمصفي بما في ذلك ما تسلمه منها من الشركة ، وتكون النفقات الاجرائية ورسومها دينا ممتازاً على تلك الأموال والموجودات .\nد - للمحكمة أن تأذن للمصفي ببيع موجودات الشركة المساهمة العامة الموجودة تحت التصفية سواء أكانت تصفية اختيارية أو اجبارية إذا تبين لها أن مصلحة الشركة تستدعي ذلك .","title":"التصرفات الباطلة أثناء التصفية","memo":"⭐ باطل: كل تصرف بأموال الشركة تحت التصفية وأي تداول بأسهمها، وأي حجز على أموالها بعد قرار التصفية\n⭐ باطلة عقود الرهن والتأمين والامتيازات التي تمت خلال الأشهر الثلاثة السابقة على قرار التصفية، إلا إذا ثبت قدرة الشركة على الوفاء بجميع ديونها\n⭐ يسلم مأمور الإجراء الأموال المحجوزة للمصفي، والنفقات الإجرائية دين ممتاز عليها\n⭐ للمحكمة أن تأذن للمصفي ببيع الموجودات في التصفية الاختيارية أو الإجبارية","qs":[{"q":"تعتبر باطلة عقود الرهن أو التأمين على أموال الشركة إذا تمت خلال:","o":["الأشهر الثلاثة السابقة على قرار تصفية الشركة","الأشهر الستة السابقة على قرار تصفية الشركة","السنة السابقة على قرار تصفية الشركة","الشهر السابق على قرار تصفية الشركة"],"a":0},{"q":"لا يسري بطلان عقود الرهن المبرمة قبل التصفية إذا ثبت أن:","o":["الشركة قادرة على الوفاء بجميع ديونها بعد انتهاء التصفية","العقد موثق لدى الكاتب العدل","الدائن المرتهن من مساهمي الشركة","مجلس الإدارة وافق على العقد بالإجماع"],"a":0},{"q":"تبلغ مأمور الإجراء إشعاراً بصدور قرار تصفية شركة مساهمة عامة قبل بيع أموالها المحجوزة، فإن عليه:","o":["تسليم تلك الأموال للمصفي وتكون النفقات الإجرائية ورسومها ديناً ممتازاً عليها","إتمام البيع وتسليم الثمن للدائن الحاجز","إعادة الأموال لمجلس إدارة الشركة","وقف الإجراءات لحين صدور قرار فسخ الشركة"],"a":0},{"q":"الجهة التي تأذن للمصفي ببيع موجودات الشركة المساهمة العامة تحت التصفية هي:","o":["المحكمة","المراقب","الهيئة العامة","الوزير"],"a":0}]},{"n":"256","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يسدد المصفي ديون الشركة وفق الترتيب التالي بعد حسم نفقات التصفية بما في ذلك أتعاب المصفي وتحت طائلة البطلان في حالة المخالفة لهذا الترتيب :-\nأ - المبالغ المستحقة للعاملين في الشركة .\nب - المبالغ المستحقة للخزينة العامة والبلديات .\nج - بدلات الايجار المستحقة لمالك أي عقار مؤجر للشركة .\nد - المبالغ الأخرى المستحقة حسب ترتيب امتيازاتها وفق القوانين المعمول بها .","title":"ترتيب تسديد ديون الشركة تحت التصفية","memo":"⭐ تحسم أولاً نفقات التصفية بما فيها أتعاب المصفي\n⭐ الترتيب: ١- مستحقات العاملين ٢- الخزينة العامة والبلديات ٣- بدلات إيجار العقار المؤجر للشركة ٤- المبالغ الأخرى حسب امتيازاتها\n⭐ مخالفة الترتيب تحت طائلة البطلان","qs":[{"q":"أول ما يسدده المصفي من ديون الشركة بعد حسم نفقات التصفية هو:","o":["المبالغ المستحقة للعاملين في الشركة","المبالغ المستحقة للخزينة العامة والبلديات","بدلات الإيجار المستحقة لمالك العقار المؤجر للشركة","الديون المضمونة برهن"],"a":0},{"q":"تأتي المبالغ المستحقة للخزينة العامة والبلديات في ترتيب سداد ديون الشركة تحت التصفية:","o":["بعد مستحقات العاملين وقبل بدلات الإيجار","قبل مستحقات العاملين","بعد بدلات الإيجار","في المرتبة الأخيرة"],"a":0},{"q":"يترتب على مخالفة المصفي لترتيب سداد الديون المنصوص عليه في القانون:","o":["البطلان","غرامة عشرة دنانير عن كل يوم","عزل المصفي حكماً","لا يترتب أي أثر قانوني"],"a":0}]},{"n":"257","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - إذا أساء أي مؤسس للشركة المساهمة العامة أو رئيس أو عضو مجلس إدارتها أو أي مدير أو موظف فيها استعمال أي أموال تخص الشركة تحت التصفية أو أبقاها لديه أو أصبح ملزماً بدفعها أو مسؤولاً عنها ، فيلزم بإعادتها للشركة مع الفائدة القانونية وضمان التعويض عن أي ضرر ألحقه بالشركة أو بالغير ، بالإضافة إلى تحمله أي مسؤولية جزائية ترتبها عليه التشريعات المعمول بها .\nب - إذا ظهر أثناء التصفية أن بعض أعمال الشركة قد أجريت بقصد الاحتيال على دائنيها ، فيعتبر رئيس وأعضاء مجلس إدارة الشركة القائم ورئيس وأعضاء أي مجلس ادارة سابق للشركة اشترك في تلك الأعمال ملزما شخصياً عن ديون الشركة والتزاماتها أو عن أي منها حسب مقتضى الحال .\nج - تسري أحكام الباب الثاني من قانون التجارة المتعلقة بالإفلاس على الشركات والأشخاص وآعضاء مجالس الإدارة أو من في حكمهم الوارد ذكرهم في هذا القانون .","title":"مسؤولية المؤسسين والإدارة عند التصفية","memo":"⭐ من أساء استعمال أموال الشركة تحت التصفية يلزم بإعادتها مع الفائدة القانونية والتعويض، إضافة إلى المسؤولية الجزائية\n⭐ إذا ظهرت أعمال بقصد الاحتيال على الدائنين يُلزم رئيس وأعضاء المجلس القائم وأي مجلس سابق اشترك فيها شخصياً عن ديون الشركة\n⭐ تسري أحكام الباب الثاني من قانون التجارة المتعلقة بالإفلاس","qs":[{"q":"إذا ظهر أثناء التصفية أن بعض أعمال الشركة أجريت بقصد الاحتيال على دائنيها، فإن رئيس وأعضاء مجلس الإدارة الذين اشتركوا فيها:","o":["يلزمون شخصياً عن ديون الشركة والتزاماتها أو أي منها حسب مقتضى الحال","يسألون فقط بقدر مساهمتهم في رأس المال","لا يسألون لأن الشركة شخص اعتباري مستقل","يسألون تأديبياً أمام المراقب فقط"],"a":0},{"q":"أساء مدير في شركة مساهمة عامة تحت التصفية استعمال أموال تخصها، فإنه يلزم بـ:","o":["إعادتها للشركة مع الفائدة القانونية وضمان التعويض إضافة لأي مسؤولية جزائية","إعادتها للشركة دون فائدة","دفع غرامة مقدارها ألف دينار فقط","إعادة نصفها للشركة"],"a":0},{"q":"تسري على الشركات وأعضاء مجالس إدارتها أحكام الإفلاس الواردة في:","o":["الباب الثاني من قانون التجارة","قانون الإعسار حصراً","الباب الأول من القانون المدني","قانون أصول المحاكمات المدنية"],"a":0}]},{"n":"258","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - إذا لم تنته التصفية خلال سنة من بدء اجراءتها ، فعلى المصفي أن يرسل إلى المراقب بياناً يتضمن التفاصيل المتعلقة بالتصفية والمرحلة التي وصلت إليها ، ويشترط في جميع الأحوال أن لا تزيد مدة التصفية على ثلاث سنوات إلا في الحالات الاستثنائية التي يقدرها المراقب في حالة التصفية الاختيارية والمحكمة في حالة التصفية الاجبارية .\nب - يحق لكل دائن أو مدين للشركة أن يطلع على البيان المنصوص عليه في الفقرة ( أ ) من هذه المادة وإذا ظهر من هذا البيان أن لدى المصفي أي مبلغ من أموال الشركة لم يدع به أحد أو لم يوزع بعد مضي ستة أشهر على تسلمه ، فعلى المصفي أن يودع ذلك المبلغ حالاً باسم الشركة تحت التصفية لدى البنك الذي يعينه المراقب .","title":"مدة التصفية وإيداع المبالغ غير الموزعة","memo":"⭐ إذا لم تنته التصفية خلال سنة يرسل المصفي بياناً إلى المراقب\n⭐ لا تزيد مدة التصفية على ثلاث سنوات إلا استثناءً يقدره المراقب (اختيارية) أو المحكمة (إجبارية)\n⭐ المبلغ الذي لم يدع به أحد أو لم يوزع بعد ستة أشهر يودع باسم الشركة لدى البنك الذي يعينه المراقب","qs":[{"q":"الحد الأقصى لمدة تصفية الشركة المساهمة العامة في غير الحالات الاستثنائية هو:","o":["ثلاث سنوات","سنة واحدة","سنتان","خمس سنوات"],"a":0},{"q":"يرسل المصفي إلى المراقب بياناً بتفاصيل التصفية والمرحلة التي وصلت إليها إذا لم تنته التصفية خلال:","o":["سنة من بدء إجراءاتها","ستة أشهر من بدء إجراءاتها","ثلاث سنوات من بدء إجراءاتها","سنتين من بدء إجراءاتها"],"a":0},{"q":"إذا بقي لدى المصفي مبلغ من أموال الشركة لم يدع به أحد بعد مضي ستة أشهر على تسلمه، فعليه إيداعه لدى:","o":["البنك الذي يعينه المراقب","البنك الذي تعينه الهيئة العامة","خزينة المحكمة","البنك المركزي الأردني"],"a":0},{"q":"الجهة التي تقدر الحالات الاستثنائية لتجاوز مدة التصفية في التصفية الاختيارية هي:","o":["المراقب","المحكمة","الوزير","الهيئة العامة"],"a":0}]},{"n":"259","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"تصفى الشركة المساهمة العامة تصفية اختيارية في أي من الحالات التالية :\nأ - بانتهاء المدة المعينة للشركة ما لم تقرر الهيئة العامة تمديدها .\nب - بإتمام أو انتقاء الغاية التي تأسست الشركة من أجلها أو باستحالة اتمام هذه الغاية أو انتفاءها .\nج - بصدور قرار من الهيئة العامة للشركة بفسخها وتصفيتها .\nد - في الحالات الأخرى التي ينص عليها نظام الشركة .","title":"حالات التصفية الاختيارية","memo":"⭐ انتهاء مدة الشركة ما لم تقرر الهيئة العامة تمديدها\n⭐ إتمام الغاية أو استحالة إتمامها أو انتفاؤها\n⭐ قرار الهيئة العامة بفسخها وتصفيتها، أو الحالات التي ينص عليها نظامها","qs":[{"q":"تصفى الشركة المساهمة العامة تصفية اختيارية في جميع الحالات التالية باستثناء:","o":["زيادة خسائرها عن (٧٥%) من رأسمالها المكتتب به","انتهاء المدة المعينة لها ما لم تقرر الهيئة العامة تمديدها","إتمام الغاية التي تأسست من أجلها","صدور قرار من الهيئة العامة بفسخها وتصفيتها"],"a":0},{"q":"انتهت المدة المعينة لشركة مساهمة عامة في نظامها، فإنها تصفى تصفية اختيارية ما لم:","o":["تقرر الهيئة العامة تمديدها","يقرر مجلس الإدارة تمديدها","يوافق المراقب على استمرارها","تكن رابحة"],"a":0}]},{"n":"260","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تعين الهيئة العامة للشركة المساهمة العامة عند اصدار قرارها بتصفية الشركة مصفيا أو أكثر وإذا لم تعين المصفي يتولى المراقب تعيينه وتحديد أتعابه .\nب - تبدأ اجراءات تصفية الشركة من تاريخ صدور قرار الهيئة العامة بذلك أو من تاريخ تعيين المصفي إذا تم تعيينه بعد صدور قرار التصفية .","title":"تعيين المصفي في التصفية الاختيارية","memo":"⭐ تعين الهيئة العامة مصفياً أو أكثر عند قرار التصفية، وإن لم تعين يتولى المراقب تعيينه وتحديد أتعابه\n⭐ تبدأ التصفية من تاريخ قرار الهيئة العامة أو من تاريخ تعيين المصفي إذا عين بعد قرار التصفية","qs":[{"q":"إذا لم تعين الهيئة العامة مصفياً عند إصدار قرارها بتصفية الشركة، فإن تعيينه وتحديد أتعابه يتولاه:","o":["المراقب","المحكمة","الوزير","مجلس الإدارة"],"a":0},{"q":"قررت الهيئة العامة تصفية الشركة في ١/٣ وعين المصفي لاحقاً في ١٥/٣، فإن إجراءات التصفية تبدأ من:","o":["١٥/٣ تاريخ تعيين المصفي","١/٣ تاريخ قرار الهيئة العامة","تاريخ نشر القرار في الجريدة الرسمية","تاريخ تبلغ المراقب للقرار"],"a":0}]},{"n":"261","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يتولى المصفي تسوية حقوق الشركة المساهمة العامة والتزاماتها وتصفية موجوداتها وفقا للاجراءات التالية :-\nأ - يمارس الصلاحيات التي يخولها القانون للمصفي في التصفية الإجبارية للشركة .\nب - ينظم قائمة بأسماء المدينين للشركة ويضع تقريرا بالأعمال والاجراءات التي قام بها للمطالبة بالديون المستحقة للشركة على مدينيها وتعتبر هذه القائمة بينة أولية على أن الأشخاص الواردة أسماؤهم فيها هم المدينون لها .\nج - يتولى دفع ديون الشركة ويسوى ما لها من حقوق وما عليها من التزامات .\nد - إذا عين أكثر من مصف واحد فتتخذ قراراتهم وفقا لما نص عليه في قرار تعيينهم وإذا لم ينص فيه على ذلك فتتخذ قراراتهم باجماعهم أو الاغلبية المطلقة لهم ويرجع للمحكمة للفصل بقراراتهم في حالة اختلافهم فيها .","title":"صلاحيات المصفي في التصفية الاختيارية","memo":"⭐ يمارس المصفي الصلاحيات المخولة له في التصفية الإجبارية\n⭐ قائمة المدينين التي ينظمها تعتبر بينة أولية على مديونيتهم\n⭐ تعدد المصفين: القرارات حسب قرار التعيين وإلا بالإجماع أو الأغلبية المطلقة، وعند الاختلاف يرجع للمحكمة","qs":[{"q":"تعتبر قائمة المدينين التي ينظمها المصفي:","o":["بينة أولية على أن الواردة أسماؤهم فيها هم المدينون للشركة","بينة قاطعة على مديونيتهم","سنداً تنفيذياً لدى دوائر الإجراء","مجرد وثيقة إدارية لا قيمة إثباتية لها"],"a":0},{"q":"إذا عين أكثر من مصفٍ ولم ينص قرار تعيينهم على طريقة اتخاذ القرارات، فإنها تتخذ:","o":["بإجماعهم أو بالأغلبية المطلقة لهم","بقرار أقدمهم","بقرار المراقب","بأغلبية الثلثين"],"a":0},{"q":"في حال اختلاف المصفين في قراراتهم، يرجع للفصل فيها إلى:","o":["المحكمة","المراقب","الهيئة العامة","الوزير"],"a":0}]},{"n":"262","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - كل اتفاق يتم بين المصفي ودائني الشركة المساهمة العامة يعتبر ملزما لها إذا اقترن بموافقة هيئتها العامة كما يكون ملزما لدائني الشركة إذا قبله عدد منهم يبلغ مجموع ديونهم ثلاثة أرباع الديون المستحقة عليها ولا يجوز اشتراك الدائنين المضمونة ديونهم برهن أو امتياز أو تأمين في التصويت على هذا القرار. على أن يتم الإعلان عن هذا الاتفاق المبرم بموجب هذه الفقرة في صحيفتين يوميتين وذلك خلال مدة لا تزيد على سبعة أيام من تاريخ إبرامه .\nب - يجوز لأي دائن أو مدين أن يطعن في الاتفاق المنصوص عليه في الفقرة ( أ ) من هذه المادة أمام المحكمة خلال خمسة عشر يوما من تاريخ الاعلان .","title":"الاتفاق بين المصفي والدائنين","memo":"⭐ يلزم الشركة إذا اقترن بموافقة هيئتها العامة، ويلزم الدائنين إذا قبله من يبلغ مجموع ديونهم ثلاثة أرباع الديون\n⭐ لا يشترك الدائنون المضمونة ديونهم برهن أو امتياز أو تأمين في التصويت\n⭐ يعلن في صحيفتين يوميتين خلال مدة لا تزيد على سبعة أيام من إبرامه\n⭐ الطعن أمام المحكمة خلال خمسة عشر يوماً من تاريخ الإعلان","qs":[{"q":"يكون الاتفاق بين المصفي ودائني الشركة ملزماً للدائنين إذا قبله عدد منهم يبلغ مجموع ديونهم:","o":["ثلاثة أرباع الديون المستحقة عليها","نصف الديون المستحقة عليها","ثلثي الديون المستحقة عليها","جميع الديون المستحقة عليها"],"a":0},{"q":"يجوز لأي دائن أو مدين الطعن في الاتفاق المبرم بين المصفي والدائنين أمام المحكمة خلال:","o":["خمسة عشر يوماً من تاريخ الإعلان","سبعة أيام من تاريخ الإعلان","ثلاثين يوماً من تاريخ الإبرام","ثلاثة أشهر من تاريخ الإبرام"],"a":0},{"q":"لا يجوز أن يشترك في التصويت على الاتفاق بين المصفي ودائني الشركة:","o":["الدائنون المضمونة ديونهم برهن أو امتياز أو تأمين","الدائنون المقيمون خارج المملكة","الدائنون من العاملين في الشركة","الدائنون الذين تقل ديونهم عن ألف دينار"],"a":0}]},{"n":"263","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"للمصفي ولأي مدين أو دائن للشركة المساهمة العامة ولكل ذي مصلحة أن يطلب من المحكمة أن تفصل في أي مسألة تنشأ في اجراءات التصفية الاختيارية وفقا للطريقة التي تم فيها الفصل في المسائل التي تنشأ في اجراءات التصفية الاجبارية بمقتضى أحكام هذا القانون .","title":"فصل المحكمة في مسائل التصفية الاختيارية","memo":"⭐ للمصفي ولأي مدين أو دائن ولكل ذي مصلحة طلب فصل المحكمة في أي مسألة في التصفية الاختيارية بطريقة الفصل في التصفية الإجبارية","qs":[{"q":"تفصل المحكمة في المسائل الناشئة في إجراءات التصفية الاختيارية وفقاً للطريقة المتبعة في:","o":["التصفية الإجبارية","قانون أصول المحاكمات الجزائية","قانون التحكيم","تعليمات المراقب"],"a":0},{"q":"الجهة التي يطلب منها الفصل في أي مسألة تنشأ في إجراءات التصفية الاختيارية هي:","o":["المحكمة","المراقب","الهيئة العامة","الوزير"],"a":0}]},{"n":"264","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ . يجوز للمصفي اثناء سير التصفية الاختيارية ان يدعو الهيئة العامة للشركة للحصول على موافقتها على أي امر يراه ضروريا بما في ذلك العدول عن تصفيتها ، ويجوز للمراقب دعوة الهيئة العامة بناء على طلب مقدم اليه من مساهمين او شركاء ممن يملكوا اكثر من (٢٥%) من راسمال الشركة المكتتب به من اجل مناقشة اجراءات التصفية او عزل المصفي وانتخاب غيره .\nب. ١. على المصفي خلال ثلاثين يوما من تاريخ صدور قرار التصفية نشر اعلان التصفية في مكان ظاهر في صحيفتين محليتين يوميتين على الاقل لاشعار الدائنين بلزوم تقديم مطالباتهم تجاه الشركة سواء اكانت مستحقة الوفاء ام لا خلال شهرين اذا كانوا مقيمين في المملكة وثلاثة اشهر اذا كانوا مقيمين خارجها .\n٢. يعاد نشر هذا الاعلان بالطريقة ذاتها فور انقضاء اربعة عشر يوما على تاريخ نشر الاعلان الاول ، وتحتسب مدة تقديم المطالبات من تاريخ نشر الاعلان الاول .\n٣. اذا اقتنع المصفي او المحكمة المختصة بوجود عذر مشروع للدائن لعدم تمكنه من تقديم مطالبته خلال المدة المحددة في البند (١) من هذه الفقرة فتمدد ثلاثة اشهر اخرى حدا اعلى .\nج. على الرغم مما ورد النص عليه في الفقرة (ب) من هذه المادة اذا لم يقدم الدائن مطالبته خلال المدد المحددة فيها فيجوز له تقديم مطالبته في أي مرحلة لاحقة على ان تصبح مطالبته في هذه الحالة في مرتبة تالية لمطالبات الدائنين المقدمة ضمن المدد المحددة في هذه المادة .","title":"دعوة الهيئة العامة ومطالبات الدائنين في التصفية الاختيارية","memo":"⭐ للمصفي دعوة الهيئة العامة لأي أمر بما في ذلك العدول عن التصفية؛ وللمراقب دعوتها بطلب من يملكون أكثر من (٢٥%) من رأس المال المكتتب به\n⭐ ينشر المصفي إعلان التصفية خلال ثلاثين يوماً في صحيفتين؛ تقدم المطالبات خلال شهرين للمقيم وثلاثة أشهر لغير المقيم\n⭐ يعاد النشر بعد أربعة عشر يوماً، وتحسب المدة من النشر الأول؛ وتمدد ثلاثة أشهر أخرى حداً أعلى للعذر المشروع\n⭐ المطالبة المتأخرة تقبل في أي مرحلة لاحقة في مرتبة تالية","qs":[{"q":"للمراقب دعوة الهيئة العامة أثناء التصفية الاختيارية بناءً على طلب مساهمين يملكون:","o":["أكثر من (٢٥%) من رأسمال الشركة المكتتب به","أكثر من (١٠%) من رأسمال الشركة المكتتب به","أكثر من (٥٠%) من رأسمال الشركة المكتتب به","أكثر من (١٥%) من رأسمال الشركة المكتتب به"],"a":0},{"q":"دائن مقيم خارج المملكة لشركة تحت التصفية الاختيارية، فإن مدة تقديم مطالبته هي:","o":["ثلاثة أشهر من تاريخ نشر الإعلان الأول","شهران من تاريخ نشر الإعلان الثاني","شهران من تاريخ نشر الإعلان الأول","ستة أشهر من تاريخ نشر الإعلان الأول"],"a":0},{"q":"يعاد نشر إعلان التصفية الاختيارية فور انقضاء:","o":["أربعة عشر يوماً على تاريخ نشر الإعلان الأول","سبعة أيام على تاريخ نشر الإعلان الأول","ثلاثين يوماً على تاريخ نشر الإعلان الأول","شهرين على تاريخ نشر الإعلان الأول"],"a":0},{"q":"دائن لم يقدم مطالبته خلال المدد المحددة ودون عذر مشروع، فإن حكم مطالبته:","o":["يجوز تقديمها في أي مرحلة لاحقة في مرتبة تالية لمطالبات الدائنين المقدمة ضمن المدد","تسقط نهائياً","تقبل بالمرتبة ذاتها مع غرامة تأخير","تقبل فقط بقرار من الوزير"],"a":0}]},{"n":"265","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"للمحكمة ، استناداً لطلب يقدم إليها من المصفي أو المحامي المدني أو المراقب أو من أي من ذي مصلحة ، أن تقرر تحويل التصفية الاختيارية للشركة المساهمة العامة إلى تصفية اجبارية أو الاستمرار في التصفية الاختيارية شريطة أن تجري تحت اشرافها ووفق الشروط والقيود التي تقررها .","title":"تحويل التصفية الاختيارية إلى إجبارية","memo":"⭐ للمحكمة بطلب من المصفي أو المحامي المدني أو المراقب أو أي ذي مصلحة تحويل التصفية الاختيارية إلى إجبارية\n⭐ أو الاستمرار في التصفية الاختيارية تحت إشرافها ووفق الشروط والقيود التي تقررها","qs":[{"q":"الجهة المختصة بتحويل التصفية الاختيارية للشركة المساهمة العامة إلى تصفية إجبارية هي:","o":["المحكمة","المراقب","الوزير","الهيئة العامة غير العادية"],"a":0},{"q":"يجوز تقديم طلب تحويل التصفية الاختيارية إلى إجبارية من أي مما يلي باستثناء:","o":["مجلس إدارة الشركة","المصفي","المحامي المدني","المراقب"],"a":0}]},{"n":"266","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ- مـع مراعاة أحكـام قـانـون الإعسار يقـدم طلـب التصفية الإجباريـة إلى المحكمـة بلائحـة دعـوى مـن وكيـل عـام إدارة قضايا الدولـة أو المراقــب أو مـن ينيبـه وللمحكمـة أن تقرر التصـفيـة في أي من الحالات التالية:-\n١ - إذا ارتكبت الشركة مخالفات جسيمة للقانون أو لنظامها الأساسي .\n٢ - إذا عجزت الشركة عن الوفاء بالتزاماتها .\n٣ - إذا توقفت عن أعمالها مدة سنة دون سبب مبرر أو مشروع .\n٤ - إذا زاد مجموع خسائر الشركة عن (٧٥ %) من رأسمالها المكتتب به ما لم تقرر هيئتها العامة زيادة رأسمالها .\nب - للوزير الطلب من المراقب او من وكيل عام إدارة قضايا الدولة ايقاف تصفية الشركة اذا قامت بتوفيق اوضاعها قبل صدور القرار بتصفيتها .\nج- ١- ينشأ لدى الدائرة حساب خاص لتغطية الرسوم والمصاريف القضائية أو أي نفقات ضرورية تقدرها المحكمة وتقرر صرفها تترتب على اعمال واجراءات التصفية الاجبارية .\n٢- يتم تمويل الحساب مما يخصص له في موازنة الدائرة ويستخدم في حال عدم توافر سيولة لدى الشركة ويتم اعادة المبالغ للحساب عند توافر السيولة لدى الشركة في أي وقت أثناء اجراءات التصفية .\n٣- تنظم احكام وشروط الانفاق من الحساب بموجب نظام يصدر لهذه الغاية .","title":"حالات التصفية الإجبارية","memo":"⭐ يقدم طلب التصفية الإجبارية بلائحة دعوى من وكيل عام إدارة قضايا الدولة أو المراقب أو من ينيبه، مع مراعاة قانون الإعسار\n⭐ الحالات: مخالفات جسيمة، العجز عن الوفاء، التوقف سنة دون مبرر، خسائر تزيد على (٧٥%) من رأس المال المكتتب به ما لم تقرر الهيئة زيادته\n⭐ للوزير طلب إيقاف التصفية إذا وفقت الشركة أوضاعها قبل صدور القرار\n⭐ ينشأ لدى الدائرة حساب خاص لتغطية رسوم ونفقات التصفية الإجبارية عند عدم توافر سيولة","qs":[{"q":"للمحكمة تقرير التصفية الإجبارية للشركة المساهمة العامة إذا زاد مجموع خسائرها عن:","o":["(٧٥%) من رأسمالها المكتتب به","(٥٠%) من رأسمالها المكتتب به","(٢٥%) من رأسمالها المكتتب به","(١٠٠%) من رأسمالها المكتتب به"],"a":0},{"q":"يقدم طلب التصفية الإجبارية إلى المحكمة بلائحة دعوى من:","o":["وكيل عام إدارة قضايا الدولة أو المراقب أو من ينيبه","الهيئة العامة غير العادية","أي مساهم في الشركة","مجلس إدارة الشركة"],"a":0},{"q":"توقفت شركة مساهمة عامة عن أعمالها دون سبب مبرر، فيجوز طلب تصفيتها إجبارياً إذا استمر التوقف مدة:","o":["سنة","ستة أشهر","سنتين","ثلاث سنوات"],"a":0},{"q":"الجهة التي لها أن تطلب إيقاف تصفية الشركة إذا قامت بتوفيق أوضاعها قبل صدور القرار بتصفيتها هي:","o":["الوزير","الهيئة العامة","مجلس الإدارة","المصفي"],"a":0}]},{"n":"267","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - تعتبر المحكمة قد بدأت في تصفية الشركة المساهمة العامة من تاريخ تقديم لائحة دعوى التصفية لها وللمحكمة تأجيل الدعوى أو ردها أو الحكم بالتصفية وبالمصاريف والنفقات على الأشخاص المسؤولين عن أسباب التصفية .\nب - للمحكمة عند النظر في دعوى تصفية الشركة وقبل صدور القرار بالتصفية أن تعين مصفياً ,وتحدد صلاحياته مع الزامه بتقديم كفالة للمحكمة ، ولها تعيين أكثر من مصف واحد ولها عزل المصفي أو استبدال غيره به وتتولى المحكمة تبليغ هذه القرارات إلى المراقب .\nج - للمحكمة بناء على طلب المدعي بالتصفية أن توقف السير في أي دعوى أقيمت أو اجراءات اتخذت ضد الشركة المطالب بتصفيتها أمام المحاكم ويشترط في ذلك أنه لا يجوز سماع أي دعوى أو اجراءات قضائية جديدة إذا أقيمت على الشركة أو اتخذت بحقها بعد تقديم دعوى التصفية .\nد. يترتب على صدور قرار التصفية الاجبارية ما يلي :\n١. وقف العمل باي تفويض او صلاحية توقيع صادرة عن أي جهة في الشركة ويختص المصفي حصرا بمنح أي تفويض او صلاحية توقيع تتطلبه اجراءات التصفية .\n٢. وقف احتساب أي فوائد على الديون المترتبة على الشركة الا اذا كانت فوائد هذه الديون مؤمنة برهون او بضمانات صحيحة .\n٣. وقف احتساب مرور الزمن المانع من سماع الدعوى بشان أي حقوق او مطالبات مستحقة او قائمة لصالح الشركة لمدة ستة اشهر من تاريخ صدور قرار التصفية .\n٤. وقف السير في الدعاوى والاجراءات القضائية المقامة من الشركة او ضدها لمدة ثلاثة اشهر ، الا اذا قرر المصفي متابعة السير فيها قبل انتهاء هذه المدة ، وذلك مع مراعاة احكام الفقرة (ج) من هذه المادة .\n٥. وقف السير في أي معاملات اجرائية او تنفيذية ضد الشركة الا اذا كانت بناء على طلب دائن مرتهن ومتعلقة بالمال المرهون نفسه ، ففي هذه الحالة توقف تلك المعاملات او يمنع قبولها لمدة ثلاثة اشهر من تاريخ صدور قرار التصفية.\n٦. سقوط الاجال المتفق عليها مع مديني الشركة لتسديد الالتزامات المترتبة عليهم .","title":"بدء التصفية الإجبارية وآثار قرارها","memo":"⭐ تعتبر التصفية قد بدأت من تاريخ تقديم لائحة دعوى التصفية\n⭐ للمحكمة تعيين مصفٍ قبل القرار مع إلزامه بكفالة، ولها عزله أو استبداله\n⭐ آثار القرار: وقف التفويضات، وقف الفوائد إلا المؤمنة برهون، وقف مرور الزمن لصالح الشركة ستة أشهر، وقف الدعاوى ثلاثة أشهر، سقوط آجال المدينين\n⭐ معاملات الدائن المرتهن على المال المرهون توقف أو يمنع قبولها لمدة ثلاثة أشهر","qs":[{"q":"تعتبر المحكمة قد بدأت في تصفية الشركة المساهمة العامة إجبارياً من تاريخ:","o":["تقديم لائحة دعوى التصفية","صدور قرار التصفية","تعيين المصفي","نشر القرار في الجريدة الرسمية"],"a":0},{"q":"يترتب على صدور قرار التصفية الإجبارية وقف احتساب مرور الزمن المانع من سماع الدعوى بشأن حقوق الشركة لمدة:","o":["ستة أشهر من تاريخ صدور القرار","ثلاثة أشهر من تاريخ صدور القرار","سنة من تاريخ صدور القرار","شهرين من تاريخ صدور القرار"],"a":0},{"q":"يترتب على صدور قرار التصفية الإجبارية كل مما يلي باستثناء:","o":["استمرار احتساب الفوائد على جميع ديون الشركة","وقف العمل بأي تفويض أو صلاحية توقيع صادرة عن أي جهة في الشركة","سقوط الآجال المتفق عليها مع مديني الشركة","وقف السير في الدعاوى المقامة من الشركة أو ضدها لمدة ثلاثة أشهر"],"a":0},{"q":"عند تعيين المحكمة مصفياً قبل صدور قرار التصفية، فإنها تلزمه بـ:","o":["تقديم كفالة للمحكمة","إيداع مبلغ نقدي لدى المراقب","الحصول على موافقة الهيئة العامة","تقديم إقرار ذمة مالية للوزير"],"a":0}]},{"n":"268","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - للمحكمة بناء على طلب المصفي أن تصدر قراراً يخول للمصفي وضع يده على جميع أموال وموجودات الشركة المساهمة العامة وتسليمها إلى المصفي ولها بعد صدور قرارها بتصفية الشركة أن تأمر أي مدين لها أو وكيل عنها أو بنك أو مندوب أو موظف بأن يدفع إلى المصفي أو يسلمه أو يحول له على الفور جميع الأموال والسجلات والدفاتر والأوراق الموجودة لديه والعائدة للشركة .\nب - يعتبر القرار الصادر عن المحكمة على أي مدين للشركة بينة قاطعة على أن الذي حكمت به مستحق للشركة مع مراعاة حق المحكوم عليه باستئناف القرار .","title":"وضع المصفي يده على أموال الشركة","memo":"⭐ للمحكمة بطلب المصفي تخويله وضع يده على أموال الشركة، ولها أن تأمر أي مدين أو وكيل أو بنك أو موظف بتسليمه الأموال والسجلات فوراً\n⭐ قرار المحكمة على أي مدين بينة قاطعة على استحقاق المبلغ للشركة، مع حق الاستئناف","qs":[{"q":"يعتبر القرار الصادر عن المحكمة على أي مدين للشركة تحت التصفية:","o":["بينة قاطعة على أن الذي حكمت به مستحق للشركة مع مراعاة حق الاستئناف","بينة أولية قابلة لإثبات العكس","قراراً غير قابل للاستئناف","قراراً يحتاج لمصادقة المراقب"],"a":0},{"q":"يصدر القرار الذي يخول المصفي وضع يده على جميع أموال وموجودات الشركة المساهمة العامة من:","o":["المحكمة بناء على طلب المصفي","المراقب بناء على طلب المصفي","الهيئة العامة","الوزير بناء على تنسيب المراقب"],"a":0}]},{"n":"269","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - للمصفي اتخاذ جميع القرارات والاجراءات التي يراها لازمة لاتمام اعمال التصفية بما في ذلك :\n١. ادارة اعمال الشركة في حدود ما تتطلبه اجراءات التصفية بما في ذلك تنفيذ العقود القائمة قبل التصفية .\n٢. جرد اصول الشركة وموجوداتها وحصر مطلوباتها .\n٣. تعيين أي من الخبراء والاشخاص لمساعدته على اتمام اجراءات التصفية او تعيين لجان خاصة وتفويضها باي من المهام والصلاحيات المنوطة به تحت اشرافه .\n٤. اقامة أي دعاوى او اتخاذ أي اجراءات قانونية باسم الشركة او نيابة عنها لتحصيل ديونها والمحافظة على حقوقها بما في ذلك تعيين محام لتمثيل الشركة في أي من هذه الدعاوى او الاجراءات .\n٥. التدخل في الدعاوى والاجراءات القضائية المتعلقة باموال الشركة ومصالحها .\nب - يجوز لأي دائن أو مدين أن يرجع للمحكمة بشأن الطريقة التي يمارس فيها المصفي للصلاحيات الواردة في الفقرة السابقة ويكون قرارها بذلك قطعيا .","title":"صلاحيات المصفي لإتمام التصفية","memo":"⭐ للمصفي: إدارة الأعمال في حدود التصفية وتنفيذ العقود القائمة، جرد الأصول وحصر المطلوبات، تعيين خبراء ولجان، إقامة الدعاوى وتعيين محام، التدخل في الدعاوى\n⭐ لأي دائن أو مدين الرجوع للمحكمة بشأن طريقة ممارسة المصفي لصلاحياته، وقرارها قطعي","qs":[{"q":"يجوز لأي دائن أو مدين أن يرجع بشأن الطريقة التي يمارس فيها المصفي صلاحياته إلى:","o":["المحكمة ويكون قرارها قطعياً","المراقب ويكون قراره قطعياً","الوزير ويكون قراره قابلاً للطعن","الهيئة العامة للشركة"],"a":0},{"q":"تشمل صلاحيات المصفي لإتمام أعمال التصفية جميع ما يلي باستثناء:","o":["مزاولة أعمال جديدة للشركة خارج حدود ما تتطلبه التصفية","تنفيذ العقود القائمة قبل التصفية","جرد أصول الشركة وحصر مطلوباتها","تعيين محام لتمثيل الشركة في الدعاوى"],"a":0}]},{"n":"270","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يلتزم المصفي للشركة المساهمة العامة التقيد بالأمور التالية :-\n١ - ايداع الأموال التي تسلمها باسم الشركة في البنك الذي تعينه المحكمة لهذه الغاية .\n٢ - تزويد المحكمة والمراقب في المواعيد المقررة بحساب مصدق من مدقق حسابات التصفية عما تسلمه من مبالغ او دفعها ولا يعتبر هذا الحساب نهائيا إلا تصديقه من قبل المحكمة .\n٣ - حفظ سجلات ودفاتر حسابية منظمة وفق الأصول المرعية لأعمال التصفية ويجوز لأي دائن أو مدين للشركة الاطلاع عليها بموافقة المحكمة .\n٤ - دعوة الدائنين أو المدينين إلى اجتماعات عامة للتحقق من مطالباتهم وسماع اقتراحاتهم .\n٥ - مراعاة تعليمات المحكمة وقراراتها المتعلقة بالدائنين والمدينين قي اشرافه على أموال الشركة وموجوداتها وتوزيعها على دائنينها .\nب - يجوز لأي متضرر من أعمال المصفي واجراءاته أن يطعن فيها لدى المحكمة التي لها أن تؤيدها أو تبطلها أو تعدلها ، ويكون قرارها في ذلك قطعياً .","title":"التزامات المصفي والطعن في أعماله","memo":"⭐ يودع المصفي الأموال باسم الشركة في البنك الذي تعينه المحكمة\n⭐ يزود المحكمة والمراقب بحساب مصدق من مدقق حسابات التصفية، ولا يعتبر نهائياً إلا بتصديق المحكمة\n⭐ اطلاع الدائن أو المدين على سجلات التصفية بموافقة المحكمة\n⭐ الطعن في أعمال المصفي لدى المحكمة التي تؤيدها أو تبطلها أو تعدلها بقرار قطعي","qs":[{"q":"يودع المصفي الأموال التي تسلمها باسم الشركة في البنك الذي يعينه:","o":["المحكمة","المراقب","الهيئة العامة","البنك المركزي"],"a":0},{"q":"لا يعتبر حساب المصفي عما تسلمه من مبالغ أو دفعه نهائياً إلا بعد تصديقه من قبل:","o":["المحكمة","المراقب","مدقق حسابات الشركة","الهيئة العامة"],"a":0},{"q":"طعن أحد المتضررين في إجراءات المصفي لدى المحكمة، فإن للمحكمة:","o":["أن تؤيدها أو تبطلها أو تعدلها ويكون قرارها قطعياً","أن تحيلها إلى المراقب للبت فيها","أن تؤيدها أو تبطلها فقط ويكون قرارها قابلاً للاستئناف","رد الطعن لعدم الاختصاص"],"a":0}]},{"n":"271","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يجوز استئناف قرار المحكمة الذي تصدره بتصفية الشركة المساهمة العامة أو أي قرار تصدره أثناء التصفية إلى محكمة الاستئناف وفقاً لأصول المحاكمات المدنية المعمول بها وذلك دون الاخلال بأحكام هذا القانون الخاصة بالقرارات القطعية التي تصدرها المحكمة .","title":"استئناف قرارات المحكمة في التصفية","memo":"⭐ يجوز استئناف قرار التصفية أو أي قرار أثناء التصفية إلى محكمة الاستئناف وفق أصول المحاكمات المدنية\n⭐ دون الإخلال بالقرارات القطعية المنصوص عليها في القانون","qs":[{"q":"يجوز استئناف قرار المحكمة بتصفية الشركة المساهمة العامة إلى:","o":["محكمة الاستئناف وفقاً لأصول المحاكمات المدنية","محكمة التمييز مباشرة","المراقب","الوزير"],"a":0},{"q":"يجوز استئناف قرارات المحكمة الصادرة أثناء تصفية الشركة المساهمة العامة دون الإخلال بأحكام القانون الخاصة بـ:","o":["القرارات القطعية التي تصدرها المحكمة","قرارات المراقب","قرارات الهيئة العامة","التصفية الاختيارية"],"a":0}]},{"n":"272","chapter":"الباب الثالث عشر - تصفية الشركة المساهمة العامة وفسخها","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - بعد اتمام تصفية الشركة المساهمة العامة تصدر المحكمة قراراً بفسخها وتعتبر الشركة منقضية من تاريخ صدور هذا القرار ، ويتولى المصفي تبليغه إلى المراقب لنشره في الجريدة الرسمية وفي صحيفتين يوميتين محليتين على الأقل وذلك على نفقة المصفي وإذا تحلف المصفي عن تنفيذ هذا الاجراء خلال أربعة عشر يوماً من تاريخ صدور القرار ، يغرم مبلغ عشرة دنانير عن كل يوم يستمر فيه تقصيره .\nب - اذا تبين ان هناك أي موجودات منقولة او غير منقولة او حقوق للشركة بعد فسخها وشطب تسجيلها فيجوز للمراقب احالة هذه المسالة الى المحكمة لتعيين مصف قانوني او تكليف المصفي السابق لغايات التصرف بتلك الموجودات او تحصيل تلك الحقوق وتسويتها وفق احكام التصفية المنصوص عليها في هذا القانون .","title":"فسخ الشركة بعد التصفية","memo":"⭐ بعد إتمام التصفية تصدر المحكمة قراراً بفسخ الشركة وتعتبر منقضية من تاريخه\n⭐ يبلغه المصفي للمراقب لنشره في الجريدة الرسمية وصحيفتين يوميتين على نفقة المصفي\n⭐ تخلف المصفي خلال أربعة عشر يوماً: غرامة عشرة دنانير عن كل يوم\n⭐ للمراقب إحالة موجودات أو حقوق تظهر بعد الشطب للمحكمة لتعيين مصفٍ أو تكليف السابق","qs":[{"q":"تعتبر الشركة المساهمة العامة منقضية من تاريخ:","o":["صدور قرار المحكمة بفسخها","انتهاء أعمال المصفي","نشر قرار الفسخ في الجريدة الرسمية","قرار الهيئة العامة بالتصفية"],"a":0},{"q":"إذا تخلف المصفي عن تبليغ قرار الفسخ للمراقب خلال المدة المحددة، يغرم عن كل يوم يستمر فيه تقصيره مبلغ:","o":["عشرة دنانير","دينار واحد","مائة دينار","خمسين ديناراً"],"a":0},{"q":"المدة التي يجب على المصفي خلالها تبليغ قرار فسخ الشركة إلى المراقب لنشره هي:","o":["أربعة عشر يوماً من تاريخ صدور القرار","سبعة أيام من تاريخ صدور القرار","ثلاثون يوماً من تاريخ صدور القرار","ثلاثة أيام من تاريخ صدور القرار"],"a":0}]},{"n":"273","chapter":"الباب الرابع عشر - الرقابة على الشركات","notes":["تاريخ السريان ٢٠٢١-١٠-١٦"],"source":"يترتب على جميع الشركات التقيد بأحكام هذا القانون ومراعاة عقود تأسيسها وأنظمتها الأساسية ونشرة الإصدار وتطبيق القرارات التي تتخذها هيئاتها العامة وللوزير والمراقب اتخاذ الاجراءات التي يريانها مناسبة لمراقبة الشركات للتحقق من تقيدها بتلك الأحكام والعقود والأنظمة والقرارات وتشمل الرقابة بشكل خاص ما يلي :\nأ - فحص حسابات الشركة وقيودها .\nب - التأكد من التزام الشركة بالغايات التي أسست من أجلها .\nنص المادة مكرر\nالمادة (٢٧٣ مكرر): أ- للغايات المقصودة في قانون مكافحة غسل الاموال وتمويل الارهاب تلتزم الشركة المسجلة بما يلي:- ١- الاحتفاظ بسجل يتضمن معلومات المستفيد الحقيقي، والافصاح عنه وعن أي تغيير يطرأ على بياناته خلال ثلاثين يوم عمل من حصول التغيير أو توثيق التغيير لدى الدائرة ، وللمراقب طلب أي من الوثائق والمعلومات اللازمة التي تمكنه من التحقق من صحة المعلومات المقدمة من الشركة . ٢- تصويب أوضاعها وفقاً لما ورد في البند (١) من هذه الفقرة خلال ثلاثة اشهر من تاريخ نفاذ احكام هذا القانون المعدل. ٣- تحديث بياناتها ومعلوماتها الأساسية وفقاً للتعليمات الصادرة لهذه الغاية . ب- على المراقب تثبيت المستفيد الحقيقي في سجل الكتروني يتضمن البيانات والمعلومات التي يجب الاحتفاظ بها في هذا السجل وله اتاحة هذه البيانات والمعلومات أو أي جزء منها للعموم ، أو ربطها على قواعد بيانات الجهات المختصة. ج- على المراقب التعاون مع الجهات الدولية النظيرة ومتابعة نوعية المساعدة المقدمة استجابة لطلبات التعاون الدولي بشأن المعلومات الأساسية للشركات المسجلة ومعلومات المستفيدين الحقيقيين وتحديد أماكن تواجد المقيمين منهم في الخارج، وفقا للتشريعات النافذة أو عملا بمبدأ المعاملة بالمثل. د. يتم تنفيذ احكام هذه المادة بموجب نظام يصدر لهذه الغاية.","title":"الرقابة على الشركات والمستفيد الحقيقي","memo":"⭐ للوزير والمراقب اتخاذ الإجراءات لمراقبة الشركات، وتشمل خصوصاً: فحص الحسابات والقيود، والتأكد من الالتزام بالغايات\n⭐ (٢٧٣ مكرر) تحتفظ الشركة بسجل المستفيد الحقيقي وتفصح عن أي تغيير خلال ثلاثين يوم عمل\n⭐ تصويب الأوضاع خلال ثلاثة أشهر من نفاذ القانون المعدل؛ ويثبت المراقب المستفيد الحقيقي في سجل إلكتروني","qs":[{"q":"تشمل رقابة الوزير والمراقب على الشركات بشكل خاص:","o":["فحص حسابات الشركة وقيودها والتأكد من التزامها بغاياتها","تعيين أعضاء مجلس الإدارة","تحديد أسعار منتجات الشركة","إقرار توزيع الأرباح بدلاً من الهيئة العامة"],"a":0},{"q":"تلتزم الشركة المسجلة بالإفصاح عن أي تغيير يطرأ على بيانات المستفيد الحقيقي خلال:","o":["ثلاثين يوم عمل من حصول التغيير","سبعة أيام من حصول التغيير","ستين يوماً من حصول التغيير","ثلاثة أشهر من حصول التغيير"],"a":0},{"q":"يتم تثبيت المستفيد الحقيقي للشركات من قبل المراقب في:","o":["سجل إلكتروني","الجريدة الرسمية","سجل الشركات الموقوفة","سجل المساهمين لدى مركز الإيداع"],"a":0}]},{"n":"274","chapter":"الباب الرابع عشر - الرقابة على الشركات","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ- لكل مساهم ولكل شريك في الشركات المسجلة بمقتضى أحكام هذا القانون الاطلاع على المعلومات والوثائق المنشورة المتعلقة بالشركة والخاصة بها المحفوظة لدى المراقب والحصول بموافقة المراقب على صورة مصدقة منها ، وأن يحصل بطلب من المحكمة على صورة مصدقة عن أي بيانات غير منشورة مقابل الرسم المنصوص عليه في الأنظمة الصادرة بمقتضى أحكام هذا القانون .\nب- لكل شخص الاطلاع على المعلومات المتعلقة بالشركات المسجلة . اما الاطلاع على ملف الشركة المحفوظ لدى المراقب والحصول على صورة مصدقة من أي وثيقة منه فلا يتم الا بموافقة من المحكمة المختصة وتحت اشراف المراقب مقابل الرسم المقرر .","title":"حق الاطلاع على وثائق الشركة","memo":"⭐ للمساهم والشريك الاطلاع على المعلومات والوثائق المنشورة لدى المراقب والحصول على صورة مصدقة بموافقة المراقب\n⭐ الصورة المصدقة عن البيانات غير المنشورة: بطلب من المحكمة مقابل الرسم\n⭐ لكل شخص الاطلاع على معلومات الشركات المسجلة، أما ملف الشركة فبموافقة المحكمة المختصة وتحت إشراف المراقب","qs":[{"q":"يحصل المساهم على صورة مصدقة عن بيانات غير منشورة متعلقة بالشركة:","o":["بطلب من المحكمة مقابل الرسم المقرر","بموافقة المراقب دون رسوم","بموافقة مجلس إدارة الشركة","بموافقة الوزير"],"a":0},{"q":"أراد شخص ليس مساهماً الاطلاع على ملف شركة محفوظ لدى المراقب، فإن ذلك لا يتم إلا:","o":["بموافقة المحكمة المختصة وتحت إشراف المراقب مقابل الرسم المقرر","بموافقة المراقب فقط","بموافقة مجلس إدارة الشركة","بموافقة الهيئة العامة للشركة"],"a":0},{"q":"يحصل المساهم على صورة مصدقة من المعلومات والوثائق المنشورة المحفوظة لدى المراقب بموافقة:","o":["المراقب","المحكمة","الوزير","مجلس الإدارة"],"a":0}]},{"n":"275","chapter":"الباب الرابع عشر - الرقابة على الشركات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يجوز لمساهمين يملكون ما لا يقل عن (%١٠) من راسمال الشركة المساهمة العامة او الشركة المساهمة الخاصة او الشركة ذات المسؤولية المحدودة او ربع اعضاء مجلس ادارة او هيئة مديري أي منها على الاقل ، حسب مقتضى الحال ، الطلب من المراقب اجراء تدقيق على اعمال الشركة ودفاترها وللمراقب اذا اقتنع بمبررات هذا الطلب انتداب خبير او اكثر لهذه الغاية ، فاذا اظهر التدقيق وجود أي مخالفة تستوجب التحقيق فللوزير احالة الموضوع الى لجنة تحقيق من موظفي الدائرة للتحقق من تلك المخالفة ودراسة التقرير الذي اعده الخبير ولها في سياق ذلك الاطلاع على الاوراق والوثائق التي تراها ، او التدقيق مجددا في بعض الامور التي ترى ضرورة التدقيق فيها ولها حق التنسيب للمراقب في توجيه الشركة لتطبيق التوصيات الصادرة عنها او احالة الامر الى المحكمة المختصة ، حسب مقتضى الحال .\nب - ١. على طالبي التدقيق على اعمال الشركة تقديم كفالة بنكية لصالح الوزارة بالقيمة التي يحددها المراقب وذلك لتغطية نفقات التدقيق فيما اذا تبين في نتيجته ان طالبي التدقيق لم يكونوا محقين بطلبهم .\n٢. اذا كان من يطلب التدقيق محقا في طلبه فتتحمل الشركة نفقات التدقيق ، ويعتبر قرار المراقب بتحديد اتعاب لجان التدقيق في هذه الحالة قابلا للتنفيذ في دوائر الاجراء ويحق للشركة ان تعود بما دفعته من نفقات التدقيق وبقيمة الضرر على من يثبت ارتكابه لاي مخالفة مبينة في تقرير اللجنة .","title":"طلب التدقيق على أعمال الشركة","memo":"⭐ لمساهمين يملكون (١٠%) على الأقل من رأس المال أو ربع أعضاء مجلس الإدارة/هيئة المديرين طلب التدقيق من المراقب\n⭐ للمراقب انتداب خبير أو أكثر؛ وللوزير إحالة المخالفة إلى لجنة تحقيق من موظفي الدائرة\n⭐ على الطالبين تقديم كفالة بنكية لصالح الوزارة بقيمة يحددها المراقب\n⭐ إن كانوا محقين تتحمل الشركة النفقات، ولها الرجوع على مرتكب المخالفة","qs":[{"q":"يجوز للمساهمين طلب إجراء تدقيق على أعمال الشركة من المراقب إذا كانوا يملكون ما لا يقل عن:","o":["(١٠%) من رأسمال الشركة","(٥%) من رأسمال الشركة","(٢٥%) من رأسمال الشركة","(١٥%) من رأسمال الشركة"],"a":0},{"q":"يحق طلب التدقيق على أعمال الشركة لعدد من أعضاء مجلس إدارتها لا يقل عن:","o":["ربع الأعضاء","نصف الأعضاء","ثلث الأعضاء","عضوين"],"a":0},{"q":"تبين نتيجة التدقيق أن طالبي التدقيق كانوا محقين في طلبهم، فإن نفقات التدقيق يتحملها:","o":["الشركة","طالبو التدقيق","الوزارة","المراقب"],"a":0},{"q":"الكفالة البنكية التي يقدمها طالبو التدقيق تكون لصالح:","o":["الوزارة بالقيمة التي يحددها المراقب","الشركة بالقيمة التي يحددها مجلس الإدارة","المحكمة بالقيمة التي تحددها","الخبير المنتدب بقيمة أتعابه"],"a":0}]},{"n":"276","chapter":"الباب الرابع عشر - الرقابة على الشركات","notes":["تاريخ السريان ٢٠٠٢-٠٧-١٦"],"source":"أ - للوزير بناء على تنسيب المراقب تكليف موظفي الدائرة او أي لجنة خاصة يشكلها القيام بتدقيق حسابات الشركة المساهمة العامة وأعمالها ولهم في سياق القيام بذلك الاطلاع على سجلات الشركة ودفاترها ومستنداتها وتدقيقها في مقر الشركة كما يحق له توجيه الاستيضاحات لموظفيها ومدققي حساباتها ، ويعتير تخلف الشركة عن الاستجابة لذلك مخالفة لأحكام هذا القانون .\nب - تستثنى البنوك وشركات التامين من احكام هذه المادة .","title":"تدقيق الوزير لحسابات الشركة المساهمة العامة","memo":"⭐ للوزير بناء على تنسيب المراقب تكليف موظفي الدائرة أو لجنة خاصة بتدقيق حسابات الشركة المساهمة العامة في مقرها\n⭐ تخلف الشركة عن الاستجابة يعتبر مخالفة لأحكام القانون\n⭐ تستثنى البنوك وشركات التأمين","qs":[{"q":"تستثنى من أحكام تدقيق الوزير لحسابات الشركة المساهمة العامة:","o":["البنوك وشركات التأمين","شركات الوساطة المالية","الشركات القابضة","شركات الاتصالات"],"a":0},{"q":"يكلف الوزير موظفي الدائرة أو لجنة خاصة بتدقيق حسابات الشركة المساهمة العامة:","o":["بناء على تنسيب المراقب","بناء على طلب الهيئة العامة","بناء على قرار مجلس الوزراء","بناء على طلب مدقق حسابات الشركة"],"a":0},{"q":"يترتب على تخلف الشركة عن الاستجابة لتدقيق موظفي الدائرة واستيضاحاتهم:","o":["اعتباره مخالفة لأحكام هذا القانون","تصفية الشركة إجبارياً","شطب تسجيل الشركة حكماً","عزل مجلس الإدارة حكماً"],"a":0}]},{"n":"277","chapter":"الباب الرابع عشر - الرقابة على الشركات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ . اذا لم تشرع أي شركة مساهمة عامة او شركة مساهمة خاصة او شركة ذات مسؤولية محدودة في اعمالها خلال سنة من تاريخ تسجيلها ، او توقفت عن العمل لمدة لا تقل عن سنة دون سبب او مبرر مشروع ، وثبت بعد اخطارها خطيا والاعلان من قبل المراقب بصحيفة يومية محلية لمرة واحدة عن توقفها عن العمل او عدم قيامها بتقديم أي بيانات تثبت قيامها بالعمل وتصويب اوضاعها خلال ثلاثين يوما من تاريخ نشر الاعلان ، يحق للوزير بناء على تنسيب المراقب شطب تسجيلها ويعلن عن هذا الشطب في الجريدة الرسمية وفي صحيفتين يوميتين محليتين لمرة واحدة ، وتبقى مسؤولية المؤسسين او الشركاء قائمة كان الشركة لم تشطب ، ولا يمس هذا الاجراء صلاحية المحكمة في تصفية الشركة التي تم شطب تسجيلها من السجل .\nب. لكل شخص ان يطعن في قرار الشطب خلال ثلاثة اشهر من تاريخ نشر الاعلان في الجريدة الرسمية لدى المحكمة المختصة ، واذا اقتنعت المحكمة بان الشركة كانت تمارس اعمالها او قامت بتوفيق اوضاعها وفقا لاحكام هذا القانون خلال المدة المشار اليها في الفقرة (أ) من هذه المادة فتصدر قرارا باعادة تسجيلها وتعتبر الشركة عندئذ كانها لم تشطب ويظل وجودها مستمرا بعد فرض الغرامة المقررة عليها بموجب احكام هذا القانون ودفع الرسوم والمصاريف المستحقة عليها ، وترسل المحكمة نسخة من هذا القرار الى المراقب لتنفيذه ونشر خلاصته في الجريدة الرسمية وصحيفة يومية محلية واحدة على الاقل على نفقة الشركة .","title":"شطب الشركة لعدم ممارسة أعمالها","memo":"⭐ إذا لم تشرع الشركة (مساهمة عامة/خاصة/محدودة) في أعمالها خلال سنة من تسجيلها أو توقفت سنة دون مبرر\n⭐ بعد إخطارها والإعلان مرة واحدة ومرور ثلاثين يوماً دون تصويب: للوزير بتنسيب المراقب شطبها\n⭐ تبقى مسؤولية المؤسسين أو الشركاء قائمة\n⭐ الطعن في قرار الشطب أمام المحكمة خلال ثلاثة أشهر من نشره في الجريدة الرسمية","qs":[{"q":"يحق للوزير شطب تسجيل الشركة ذات المسؤولية المحدودة إذا لم تشرع في أعمالها خلال:","o":["سنة من تاريخ تسجيلها","ستة أشهر من تاريخ تسجيلها","سنتين من تاريخ تسجيلها","ثلاث سنوات من تاريخ تسجيلها"],"a":0},{"q":"يجوز لكل شخص الطعن في قرار شطب الشركة لدى المحكمة المختصة خلال:","o":["ثلاثة أشهر من تاريخ نشر الإعلان في الجريدة الرسمية","ثلاثين يوماً من تاريخ نشر الإعلان","خمسة عشر يوماً من تاريخ التبليغ","سنة من تاريخ الشطب"],"a":0},{"q":"بعد شطب تسجيل الشركة لعدم ممارستها أعمالها، فإن مسؤولية المؤسسين أو الشركاء:","o":["تبقى قائمة كأن الشركة لم تشطب","تنقضي بالشطب","تنحصر في حدود مساهماتهم","تنتقل إلى المراقب"],"a":0},{"q":"المدة الممنوحة للشركة لتصويب أوضاعها بعد إعلان المراقب عن توقفها في صحيفة يومية هي:","o":["ثلاثون يوماً من تاريخ نشر الإعلان","أربعة عشر يوماً من تاريخ نشر الإعلان","ستون يوماً من تاريخ نشر الإعلان","ثلاثة أشهر من تاريخ نشر الإعلان"],"a":0}]},{"n":"278","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - يعاقب كل شخص يرتكب أيا من الأفعال التالية بالحبس من سنة إلى ثلاث سنوات وبغرامة لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار :\n١ - اصدار الأسهم أو شهاداتها أو القيام بتسليمها إلى أصحابها أو عرضها للتداول قبل تصديق النظام الأساسي للشركة والموافقة على تأسيسها أو السماح لها بزيادة رأسمالها المصرح به قبل الاعلان عن ذلك في الجريدة الرسمية .\n٢ - اجراء اكتتابات صورية للأسهم أو قبول الاكتتابات فيها بصورة وهمية أو غير حقيقية لشركات غير قائمة أو غير حقيقية .\n٣ - اصدار سندات القرض وعرضها للتداول قبل أوانها بصورة مخالفة لأحكام هذا القانون .\n٤ - تنظيم ميزانية أي شركة وحسابات أرباحها وخسائرها بصورة غير مطابقة للواقع أو تضمين تقرير مجلس ادارتها أو تقرير مدققي حساباتها بيانات غير صحيحة والأدلاء إلى هيئتها العامة بمعلومات غير صحيحة أو كتم معلومات وايضاحات يوجب القانون ذكرها وذلك بقصد اخفاء حالة الشركة الحقيقية عن المساهمين أو ذوي العلاقة .\n٥ - توزيع أرباح صورية أو غير مطابقة لحالة الشركة الحقيقية .\nب - تطبق العقوبات المنصوص عليها في الفقرة ( أ ) من هذه المادة على المتدخل في الجرائم المبينة فيها والمحرض عليها .","title":"جرائم التأسيس والبيانات المالية","memo":"⭐ العقوبة: الحبس من سنة إلى ثلاث سنوات وغرامة من ألف إلى عشرة آلاف دينار\n⭐ الأفعال: إصدار الأسهم قبل تصديق النظام، الاكتتابات الصورية، إصدار سندات القرض قبل أوانها، الميزانية غير المطابقة للواقع، توزيع أرباح صورية\n⭐ تطبق العقوبة نفسها على المتدخل والمحرض","qs":[{"q":"عقوبة توزيع أرباح صورية أو غير مطابقة لحالة الشركة الحقيقية هي:","o":["الحبس من سنة إلى ثلاث سنوات وغرامة من ألف إلى عشرة آلاف دينار","الحبس من شهر إلى سنة","غرامة من مائة إلى ألف دينار","الحبس من ستة أشهر إلى ثلاث سنوات أو غرامة لا تقل عن ألف دينار"],"a":0},{"q":"حرّض شخص رئيس مجلس إدارة على تنظيم ميزانية غير مطابقة للواقع بقصد إخفاء حالة الشركة، فإن المحرض:","o":["يعاقب بالعقوبات ذاتها المقررة للفاعل","يعاقب بنصف العقوبة","لا يعاقب لأنه ليس من إدارة الشركة","يعاقب بغرامة فقط"],"a":0},{"q":"يعاقب بالحبس من سنة إلى ثلاث سنوات وبالغرامة من ألف إلى عشرة آلاف دينار على جميع الأفعال التالية باستثناء:","o":["تخلف الشريك المتضامن عن إجراء تغيير طارئ على عقد الشركة","إجراء اكتتابات صورية للأسهم","إصدار سندات القرض وعرضها للتداول قبل أوانها","إصدار الأسهم قبل تصديق النظام الأساسي"],"a":0}]},{"n":"279","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - إذا ارتكبت الشركة المساهمة العامة أو الشركة المحدودة المسؤولية او المساهمة الخاصة مخالفة لأحكام هذا القانون تعاقب بغرامة لا تقل عن ألف دينار ولا تتجاوز عشرة آلاف دينار مع أبطال التصرف المخالف إذا رأت المحكمة وجهاً لذلك .\nب - إذا ظهر أن أياً من الشركات المنصوص عليها في الفقرة ( أ ) من هذه المادة لم تحفظ دفاتر حسابات منظمة قبل تصفيتها يعتبر مديرها ومدقق حساباتها قد ارتكب جرماً يعاقب عليه بالحبس مدة لا تقل عن شهر ولا تزيد على سنة .\nج - مع عدم الاخلال باي عقوبة اشد ينص عليها قانون اخر يعاقب بغرامة لا تقل عن الف دينار ولا تتجاوز عشرة الاف دينار كل من يمتنع عمدا عن تمكين مدققي الحسابات او الاشخاص المكلفين من قبل الوزير او المراقب ، بالقيام بواجباتهم المحددة بموجب هذا القانون او الاطلاع على دفاترها ووثائقها او يمتنع عن تقديم المعلومات والايضاحات اللازمة لهم .\nد- يعاقب كل من يخالف أحكام الفقرة (أ) من المادة ( ٢٧٣ مكرر) من هذا القانون بغرامة لا تقل عن ألفي دينار ولا تتجاوز عشرين ألف دينار أو بالحبس مدة لا تتجاوز سنة أو بكلتا هاتين العقوبتين .","title":"عقوبات مخالفات الشركات","memo":"⭐ الشركة المساهمة العامة أو المحدودة أو المساهمة الخاصة المخالفة: غرامة من ألف إلى عشرة آلاف دينار مع إبطال التصرف إن رأت المحكمة\n⭐ عدم حفظ دفاتر منظمة قبل التصفية: حبس المدير والمدقق من شهر إلى سنة\n⭐ الامتناع عمداً عن تمكين المدققين أو المكلفين من الوزير أو المراقب: غرامة من ألف إلى عشرة آلاف دينار\n⭐ مخالفة الفقرة (أ) من المادة (٢٧٣ مكرر): غرامة من ألفين إلى عشرين ألف دينار أو حبس لا يتجاوز سنة أو كلتاهما","qs":[{"q":"إذا ظهر أن شركة مساهمة عامة لم تحفظ دفاتر حسابات منظمة قبل تصفيتها، يعاقب مديرها ومدقق حساباتها بالحبس مدة:","o":["لا تقل عن شهر ولا تزيد على سنة","لا تقل عن سنة ولا تزيد على ثلاث سنوات","لا تقل عن ستة أشهر ولا تزيد على ثلاث سنوات","لا تزيد على ستة أشهر"],"a":0},{"q":"عقوبة مخالفة أحكام المستفيد الحقيقي الواردة في الفقرة (أ) من المادة (٢٧٣ مكرر) هي:","o":["غرامة من ألفي دينار إلى عشرين ألف دينار أو الحبس مدة لا تتجاوز سنة أو كلتاهما","غرامة من ألف إلى عشرة آلاف دينار","غرامة من مائة إلى ألف دينار","الحبس من سنة إلى ثلاث سنوات"],"a":0},{"q":"امتنعت شركة عمداً عن تمكين الأشخاص المكلفين من المراقب من الاطلاع على دفاترها، فإن العقوبة هي:","o":["غرامة لا تقل عن ألف دينار ولا تتجاوز عشرة آلاف دينار","غرامة لا تقل عن مائة دينار ولا تزيد على ألف دينار","غرامة دينار واحد عن كل يوم","شطب تسجيل الشركة"],"a":0}]},{"n":"280","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يعتبر مدقق الحسابات ، الذي يخالف أحكام هذا القانون بتقديم تقارير أو بيانات لا تتفق وواقع حسابات الشركة التي قام بتدقيقها أنه ارتكب جرما ويعاقب عليه بالحبس مدة لا تقل عن ستة أشهر ولا تزيد على ثلاث سنوات أو بغرامة لا تقل عن ألف دينار أو بكلتا العقوبتين ولا يحول ذلك دون تعرضه للعقوبات المسلكية المقررة في القوانين الخاصة بالمهنة المعمول بها .","title":"عقوبة مدقق الحسابات المخالف","memo":"⭐ المدقق الذي يقدم تقارير أو بيانات لا تتفق وواقع الحسابات: حبس من ستة أشهر إلى ثلاث سنوات أو غرامة لا تقل عن ألف دينار أو كلتاهما\n⭐ لا يحول ذلك دون العقوبات المسلكية في قوانين المهنة","qs":[{"q":"عقوبة مدقق الحسابات الذي يقدم تقارير لا تتفق وواقع حسابات الشركة هي الحبس مدة:","o":["لا تقل عن ستة أشهر ولا تزيد على ثلاث سنوات أو غرامة لا تقل عن ألف دينار أو كلتاهما","لا تقل عن شهر ولا تزيد على سنة","من سنة إلى ثلاث سنوات وغرامة من ألف إلى عشرة آلاف دينار","لا تزيد على ستة أشهر أو غرامة مائة دينار"],"a":0},{"q":"عوقب مدقق حسابات جزائياً لتقديمه بيانات غير مطابقة لواقع حسابات الشركة، فإن ذلك:","o":["لا يحول دون تعرضه للعقوبات المسلكية المقررة في قوانين المهنة","يمنع مساءلته مسلكياً","يوجب شطب الشركة","يعفي الشركة من المسؤولية تجاه الغير"],"a":0}]},{"n":"281","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يعاقب كل شريك متضامن في أي شركة تضامن أو شركة التوصية البسيطة تخلف عن اجراء أي تغيير طارىء على عقد الشركة بغرامة مقدارها دينار واحد عن كل يوم استمرت فيه المخالفة بعد انقضاء شهر من تاريخ حدوث هذا التغيير .","title":"غرامة عدم تسجيل تغيير عقد شركة الأشخاص","memo":"⭐ الشريك المتضامن في شركة التضامن أو التوصية البسيطة المتخلف عن إجراء تغيير طارئ على عقد الشركة: غرامة دينار واحد عن كل يوم\n⭐ تبدأ بعد انقضاء شهر من تاريخ حدوث التغيير","qs":[{"q":"يعاقب الشريك المتضامن الذي يتخلف عن إجراء أي تغيير طارئ على عقد شركة التضامن بغرامة مقدارها:","o":["دينار واحد عن كل يوم بعد انقضاء شهر من حدوث التغيير","عشرة دنانير عن كل يوم بعد انقضاء أسبوعين","مائة دينار عن كل شهر","ألف دينار لمرة واحدة"],"a":0},{"q":"حدث تغيير على عقد شركة توصية بسيطة في ١/٥ ولم يجرِ الشريك المتضامن التغيير حتى ١٠/٦، فإن الغرامة تحسب عن الأيام:","o":["التي تلي انقضاء شهر من ١/٥","التي تلي ١/٥ مباشرة","التي تلي انقضاء أسبوعين من ١/٥","لا غرامة لأن المدة لم تتجاوز ثلاثة أشهر"],"a":0}]},{"n":"282","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"كل مخالفة لأي حكم من أحكام هذا القانون أو أي نظام أو أمر صادر بمقتضاه لم ينص القانون على عقوبة خاصة لها ، يعاقب مرتكبها بغرامة لا تقل عن مائة دينار و لا تزيد على ألف دينار .","title":"العقوبة العامة للمخالفات","memo":"⭐ كل مخالفة لم ينص القانون على عقوبة خاصة لها: غرامة لا تقل عن مائة دينار ولا تزيد على ألف دينار","qs":[{"q":"العقوبة المقررة لمخالفة أي حكم من أحكام قانون الشركات لم ينص القانون على عقوبة خاصة لها هي:","o":["غرامة لا تقل عن مائة دينار ولا تزيد على ألف دينار","غرامة لا تقل عن ألف دينار ولا تزيد على عشرة آلاف دينار","الحبس مدة لا تزيد على سنة","غرامة دينار واحد عن كل يوم"],"a":0},{"q":"تطبق العقوبة العامة الواردة في قانون الشركات على مخالفة:","o":["أي حكم من القانون أو نظام أو أمر صادر بمقتضاه لم ينص على عقوبة خاصة له","أحكام المستفيد الحقيقي فقط","الجرائم المتعلقة بالميزانية فقط","التزامات مدقق الحسابات فقط"],"a":0}]},{"n":"283","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - يكون للمراقب ولموظفي الدائرة المفوضين خطيا من قبله حق الاطلاع على جميع سجلات الشركة ودفاترها ووثائقها ، كما يكون لهم حق الحصول على نسخ من تلك السجلات والدفاتر والوثائق لغايات تمكينهم من القيام باعمالهم وفق احكام هذا القانون ، وعلى السلطات الرسمية المختصة ومسؤولي وموظفي الشركات تقديم المساعدة اللازمة لهذه الغاية.\nب ـ يتولى وكيـل عـام إدارة قضايا الدولة تمثيـل الـوزير او المراقـب او الدائرة امام المحاكم في القضايا الحقوقية التي تنشأ عن تطبيق احكام هذا القانون والانظمة الصادرة بمقتضاه والتي يكون أي منهم طرفا فيها، كما يجوز للوزير بموافقة مجلس الوزراء تعيين محام لغايات هذه الفقرة.","title":"اطلاع المراقب وتمثيل الوزير أمام المحاكم","memo":"⭐ للمراقب وموظفي الدائرة المفوضين خطياً حق الاطلاع على سجلات الشركة والحصول على نسخ منها\n⭐ يمثل وكيل عام إدارة قضايا الدولة الوزير أو المراقب أو الدائرة في القضايا الحقوقية\n⭐ للوزير بموافقة مجلس الوزراء تعيين محام لهذه الغاية","qs":[{"q":"يتولى تمثيل الوزير أو المراقب أمام المحاكم في القضايا الحقوقية الناشئة عن تطبيق قانون الشركات:","o":["وكيل عام إدارة قضايا الدولة","النائب العام","المحامي المدني","مدير الدائرة القانونية في الوزارة"],"a":0},{"q":"يجوز للوزير تعيين محام لتمثيله أو تمثيل المراقب أمام المحاكم:","o":["بموافقة مجلس الوزراء","بتنسيب من المراقب فقط","بموافقة نقابة المحامين","بقرار منفرد منه"],"a":0},{"q":"يمارس حق الاطلاع على جميع سجلات الشركة ودفاترها ووثائقها والحصول على نسخ منها:","o":["المراقب وموظفو الدائرة المفوضون خطياً من قبله","أي مساهم في الشركة","أي دائن للشركة","مدقق حسابات أي شركة أخرى"],"a":0}]},{"n":"284","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أ - تعطى القضايا الحقوقية والجزائية المتعلقة بالشركات والناشئة عن تطبيق احكام هذا القانون صفة الاستعجال لدى المحاكم المختصة.\nب- يجري تبليغ أي كتاب او قرار او اشعار صادر عن الوزير او المراقب وفق هذا القانون والانظمة والتعليمات الصادرة بمقتضاه الى الشخص المعني اما بتسليمه له شخصيا او لمن يمثله قانونا او بارساله في البريد المسجل الى اخر عنوان له محفوظ في ملفات الدائرة أو بالوسائل الالكترونيـة عـلـى الـعنـوان المحفـوظ لـديها .\nج - يعتبر كل كتاب او قرار او اشعار ارسل بمقتضى هذه المادة انه قد سلم حسب الاصول الى الشخص المرسل له ويعتبر انه قد تم تبليغه فيما لو رفض ذلك الشخص تسلمه.\nد - اذا تم تبليغ الورقة الى الشخص المعني بواسطة البريد المسجل فيعتبر انه قد تم تبليغه بعد مرور خمسة عشر يوما على تاريخ ارسالها اذا كان هذا الشخص مقيما داخل المملكة او ثلاثين يوما على تاريخ ارسالها اذا كان الشخص مقيما خارج المملكة ، ويكفي لاثبات وقوع التبليغ ان يقام الدليل على ان الورقة المبلغة قد ارسلت في البريد على العنوان المشار اليه في الفقرة (ب) من هذه المادة.\nه- اذا تعذر التبليغ وفقا لاحكام الفقرات (ب) و (ج) و (د) من هذه المادة فيتم اجراء التبليغ بالنشر لمرتين على الاقل في صحيفتين محليتين يوميتين ، وتكون اجور النشر على نفقة الشخص المعني او الشركة ذات العلاقة وفقا لما يقرره المراقب ، ويعتبر هذا النشر تبليغا قانونيا من جميع الوجوه.","title":"الاستعجال وطرق التبليغ","memo":"⭐ القضايا الحقوقية والجزائية المتعلقة بالشركات تعطى صفة الاستعجال\n⭐ التبليغ: شخصياً أو لمن يمثله قانوناً أو بالبريد المسجل أو بالوسائل الإلكترونية؛ ورفض التسلم يعتبر تبليغاً\n⭐ البريد المسجل: يعتبر التبليغ بعد خمسة عشر يوماً للمقيم داخل المملكة وثلاثين يوماً لخارجها\n⭐ تعذر التبليغ: النشر مرتين على الأقل في صحيفتين محليتين يوميتين","qs":[{"q":"إذا تم التبليغ بالبريد المسجل لشخص مقيم داخل المملكة، يعتبر قد تبلغ بعد مرور:","o":["خمسة عشر يوماً على تاريخ الإرسال","سبعة أيام على تاريخ الإرسال","ثلاثين يوماً على تاريخ الإرسال","عشرة أيام على تاريخ الإرسال"],"a":0},{"q":"أرسل المراقب إشعاراً بالبريد المسجل لشريك مقيم خارج المملكة، فإنه يعتبر قد تبلغ بعد مرور:","o":["ثلاثين يوماً على تاريخ الإرسال","خمسة عشر يوماً على تاريخ الإرسال","ستين يوماً على تاريخ الإرسال","أربعة عشر يوماً على تاريخ الإرسال"],"a":0},{"q":"إذا تعذر التبليغ بالطرق المقررة، يتم التبليغ بالنشر:","o":["لمرتين على الأقل في صحيفتين محليتين يوميتين","لمرة واحدة في الجريدة الرسمية","لمرة واحدة في صحيفة يومية واحدة","على الموقع الإلكتروني للدائرة فقط"],"a":0},{"q":"رفض شخص تسلم قرار صادر عن المراقب أرسل إليه وفق القانون، فإنه:","o":["يعتبر قد تم تبليغه","يعاد تبليغه بالنشر","لا يعتبر مبلغاً حتى يوقع على التسلم","يبلغ عن طريق المحكمة"],"a":0}]},{"n":"285","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ٢٠٢٣-١١-١١"],"source":"أـ دون الإخـلال بأحكـام التصـفية الإجباريـة المنصـوص عليهـا في هذا القانون وقانون الإعسار، اذا تخلفت شركة عن توفيـق أوضاعها وفقا لأحكام القانون أو اذا تبين للمراقب انه لم يعد لها مقـر او أنـهـا قـد توقفـت عـن ممارسة أعمالهـا أو عـن قيامها بالواجبات المفروضة عليها بحكم هذا القانون او انقضت مدة تزيد على ستة أشهر دون ان تنتخب الهيئة العامة للشركة مديرا لها او هيئة مديرين او مجلس إدارة حسبما يقتضيه نظامها الداخلي فعلى المراقـب انـذار الشركة بالاعلان على الموقع الالكتروني للدائرة بقيـدهـا فـي سـجل الشركات الموقوفـة بـعـد مـرور شـهر على تاريخ الانذار، وفي هذه الحالة يمتنع على الشركة القيـام بـاي تصرفات أو أعمـال، كمـا يفقـد مـديرها أو هيئـة مـديريها او مجلس إدارتها جميع صلاحياتهم، إلا أن ذلك لا يمنع من تقرير استمرار عمـل الشـركة واستمرار تسجيلها لمصلحة الغيـر او من تقرير وقف عمل تلك الشركة وقيدها في سجل الشركات الموقوفة لمصلحة الغير ، وفي كل الأحوال يعتبر رئيس مجلس ادارة الشركة أو رئيس هيئة المديرين او مدير الشركة متضامنا مع الشركة في تحمل أي ضرر قد يلحق بالغير.\nب - يجوز للمراقب من اجل تمكين الشركة من متابعة اعمالها وانشطتها ان يقرر اعادة نقل الشركة من سجل الشركات الموقوفة الى سجل الشركات العاملة بناء على طلب الشركة اذا تبين له بانها قد قامت بتوفيق اوضاعها وفقا لاحكام هذا القانون .\nج - اذا استمر قيد الشركة في سجل الشركات الموقوفة لمدة تزيد على سنة دون ان تقوم الشركة او الشركاء فيها بالاعمال والاجراءات المطلوبة لاعادة قيدها في سجل الشركات العاملة وفقا لاحكام الفقرة (ب) من هذه المادة، فعلـى المراقـب شـطب تسجيلها على أن تبقى مسؤولية الشركاء والمساهمين وأعضاء هيئة المديرين ومجالس الإدارة قائمة ولا يمس هذا الاجراء صلاحية المحكمة في تصفية الشركة التي تم شطب تسجيلها من السجل.","title":"سجل الشركات الموقوفة","memo":"⭐ حالات الإنذار: عدم توفيق الأوضاع، عدم وجود مقر، التوقف عن الأعمال أو الواجبات، مرور أكثر من ستة أشهر دون انتخاب مدير أو مجلس\n⭐ ينذر المراقب الشركة على الموقع الإلكتروني للدائرة بقيدها في سجل الشركات الموقوفة بعد شهر من الإنذار\n⭐ يمتنع على الشركة أي تصرف وتفقد إدارتها صلاحياتها؛ ورئيس المجلس أو المدير متضامن مع الشركة في أي ضرر للغير\n⭐ استمرار القيد أكثر من سنة دون تصويب: يشطب المراقب التسجيل مع بقاء مسؤولية الشركاء والإدارة","qs":[{"q":"يتم إنذار الشركة بقيدها في سجل الشركات الموقوفة عن طريق:","o":["الإعلان على الموقع الإلكتروني للدائرة","النشر في الجريدة الرسمية","النشر في صحيفتين يوميتين","التبليغ بالبريد المسجل فقط"],"a":0},{"q":"على المراقب شطب تسجيل الشركة إذا استمر قيدها في سجل الشركات الموقوفة دون تصويب أوضاعها لمدة تزيد على:","o":["سنة","ستة أشهر","سنتين","ثلاثة أشهر"],"a":0},{"q":"من حالات قيد الشركة في سجل الشركات الموقوفة انقضاء مدة دون أن تنتخب الهيئة العامة مجلس إدارة أو مديراً تزيد على:","o":["ستة أشهر","ثلاثة أشهر","سنة","شهر"],"a":0},{"q":"قيدت شركة في سجل الشركات الموقوفة، فإن المسؤول بالتضامن مع الشركة عن أي ضرر يلحق بالغير هو:","o":["رئيس مجلس الإدارة أو رئيس هيئة المديرين أو مدير الشركة","المراقب","جميع المساهمين بالتضامن","مدقق حسابات الشركة"],"a":0}]},{"n":"286","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"أ - تعتبر جميع الشركات المسجلة بمقتضى القوانين المعمول بها قبل نفاذ هذا القانون قائمة وكأنها مسجلة وفق أحكامه .\nب - على الشركات القائمة بتاريخ نفاذ هذا القانون توفيق أوضاعها واجراء التعديلات اللازمة على عقود تأسيسها وأنظمتها الأساسية خلال مدة لا تتجاوز سنة واحدة من تاريخ نفاذ هذا القانون ، وذلك دون الحاجة إلى دعوة هيئاتها العامة لإقرار هذه التعديلات .","title":"الشركات القائمة قبل نفاذ القانون","memo":"⭐ تعتبر الشركات المسجلة قبل نفاذ القانون قائمة وكأنها مسجلة وفق أحكامه\n⭐ عليها توفيق أوضاعها خلال مدة لا تتجاوز سنة واحدة من نفاذ القانون دون الحاجة إلى دعوة هيئاتها العامة","qs":[{"q":"على الشركات القائمة بتاريخ نفاذ قانون الشركات توفيق أوضاعها خلال مدة لا تتجاوز:","o":["سنة واحدة من تاريخ نفاذ القانون","ستة أشهر من تاريخ نفاذ القانون","سنتين من تاريخ نفاذ القانون","ثلاث سنوات من تاريخ نفاذ القانون"],"a":0},{"q":"تجري الشركات القائمة التعديلات اللازمة على عقود تأسيسها وأنظمتها لتوفيق أوضاعها مع القانون:","o":["دون الحاجة إلى دعوة هيئاتها العامة لإقرارها","بعد موافقة الهيئة العامة غير العادية","بعد موافقة المحكمة المختصة","بعد موافقة مجلس الوزراء"],"a":0}]},{"n":"287","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"لمجلس الوزراء اصدار الأنظمة اللازمة لتنفيذ أحكام هذا القانون وخاصة ما يتعلق منها بما يلي :-\nأ - تحديد الرسوم التي يجب استيفاؤها في تطبيق أحكام هذا القانون .\nب - تنظيم النماذج الخاصة بعقد التأسيس والوثائق الأخرى المنصوص عليها في هذا القانون .\nج - للوزير تفويض بعض صلاحياته المنصوص عليها في هذا القانون إلى المراقب ، وللمراقب تفويض أي من صلاحياته إلى أي من موظفي مديرية مراقبة الشركات في الوزارة على أن تكون الصلاحية محددة بصورة خطية .","title":"إصدار الأنظمة وتفويض الصلاحيات","memo":"⭐ لمجلس الوزراء إصدار الأنظمة اللازمة، خاصة لتحديد الرسوم وتنظيم نماذج عقد التأسيس والوثائق\n⭐ للوزير تفويض بعض صلاحياته للمراقب، وللمراقب تفويض صلاحياته لموظفي مديرية مراقبة الشركات بصورة خطية محددة","qs":[{"q":"الجهة المختصة بإصدار الأنظمة اللازمة لتنفيذ أحكام قانون الشركات هي:","o":["مجلس الوزراء","الوزير","المراقب","مجلس الأمة"],"a":0},{"q":"يشترط في تفويض المراقب لأي من صلاحياته إلى موظفي مديرية مراقبة الشركات أن يكون:","o":["محدداً بصورة خطية","بموافقة مجلس الوزراء","منشوراً في الجريدة الرسمية","لمدة لا تزيد على سنة"],"a":0}]},{"n":"288","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"يلغى قانون الشركات رقم ( ١٢ ) لسنة ١٩٦٤ والتعديلات التي أدخلت عليه كما تلغى نصوص وأحكام أي تشريعات أخرى تتعارض مع أحكام القانون .","title":"الإلغاءات","memo":"⭐ يلغى قانون الشركات رقم (١٢) لسنة ١٩٦٤ وتعديلاته، وأي تشريعات تتعارض مع أحكام هذا القانون","qs":[{"q":"ألغى قانون الشركات رقم (٢٢) لسنة ١٩٩٧ قانون الشركات:","o":["رقم (١٢) لسنة ١٩٦٤","رقم (١) لسنة ١٩٨٩","رقم (٢٢) لسنة ١٩٦٤","رقم (١٢) لسنة ١٩٨٩"],"a":0},{"q":"نص قانون الشركات على أن نصوص وأحكام أي تشريعات أخرى تتعارض مع أحكامه:","o":["تلغى","تبقى سارية بالقدر الذي لا يتعارض مع النظام","تبقى سارية لمدة سنة","تعدل بقرار من مجلس الوزراء"],"a":0}]},{"n":"289","chapter":"الباب الخامس عشر - العقوبات","notes":["تاريخ السريان ١٩٩٧-٠٦-١٤"],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون .","title":"المكلفون بتنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون","qs":[{"q":"المكلفون بتنفيذ أحكام قانون الشركات هم:","o":["رئيس الوزراء والوزراء","وزير الصناعة والتجارة والمراقب","مراقب عام الشركات وحده","مجلس الأمة"],"a":0}]}]};
